impl InodeMode {
    /// File type mask
    pub const S_IFMT: u32 = 0o0170000;

    /// Regular file
    pub const S_IFREG: u32 = 0o0100000;
    /// Directory
    pub const S_IFDIR: u32 = 0o0040000;
    /// Character device
    pub const S_IFCHR: u32 = 0o0020000;
    /// Block device
    pub const S_IFBLK: u32 = 0o0060000;
    /// FIFO (named pipe)
    pub const S_IFIFO: u32 = 0o0010000;
    /// Symbolic link
    pub const S_IFLNK: u32 = 0o0120000;
    /// Socket
    pub const S_IFSOCK: u32 = 0o0140000;

    /// Permission bits
    pub const S_IRWXU: u32 = 0o0700;  // User permissions
    pub const S_IRUSR: u32 = 0o0400;  // User read
    pub const S_IWUSR: u32 = 0o0200;  // User write
    pub const S_IXUSR: u32 = 0o0100;  // User execute
    pub const S_IRWXG: u32 = 0o0070;  // Group permissions
    pub const S_IRGRP: u32 = 0o0040;  // Group read
    pub const S_IWGRP: u32 = 0o0020;  // Group write
    pub const S_IXGRP: u32 = 0o0010;  // Group execute
    pub const S_IRWXO: u32 = 0o0007;  // Others permissions
    pub const S_IROTH: u32 = 0o0004;  // Others read
    pub const S_IWOTH: u32 = 0o0002;  // Others write
    pub const S_IXOTH: u32 = 0o0001;  // Others execute

    pub fn new(mode: u32) -> Self {
        Self(mode)
    }

    pub fn is_regular_file(&self) -> bool {
        (self.0 & Self::S_IFMT) == Self::S_IFREG
    }

    pub fn is_directory(&self) -> bool {
        (self.0 & Self::S_IFMT) == Self::S_IFDIR
    }

    pub fn is_char_device(&self) -> bool {
        (self.0 & Self::S_IFMT) == Self::S_IFCHR
    }

    pub fn is_block_device(&self) -> bool {
        (self.0 & Self::S_IFMT) == Self::S_IFBLK
    }

    pub fn is_fifo(&self) -> bool {
        (self.0 & Self::S_IFMT) == Self::S_IFIFO
    }

    pub fn is_symlink(&self) -> bool {
        (self.0 & Self::S_IFMT) == Self::S_IFLNK
    }

    pub fn is_socket(&self) -> bool {
        (self.0 & Self::S_IFMT) == Self::S_IFSOCK
    }

    pub fn bits(&self) -> u32 {
        self.0
    }
}

/// INV-VFSOPS-1 (unsafe-slim rounds 3-4): every dispatch through an
/// INodeOps fn-pointer slot goes through one of the `call_*` methods
/// below (plus the `op_*` conveniences) — one place per op to read.
/// UNSAFE-SLIM L4 (2026-11-20): the pointer types are now SAFE `fn`
/// pointers, matching the FileOps precedent — every slot signature
/// carries only safe parameter types (`&Inode`, `&[u8]`, scalars,
/// `Result`), so no unsafe contract remains at the dispatch boundary.
/// The callee contract is "VFS callback with safe parameter types":
/// tables are built once at filesystem registration from in-tree
/// callbacks, the `&Inode` receiver is the shared Arc the caller
/// already holds, and every other argument is a plain
/// reference/scalar. Implementations that need raw access (ext4's
/// block edges, per-FS private_data views) keep narrow inner audited
/// blocks at their own bottoms — see fs/unsafe.rs.
/// `None` slots are mapped to the caller's
/// `unsupported` errno so each call site keeps its LTP-observed error
/// precedence (mkdir-family sites answer EROFS, mknod EOPNOTSUPP,
/// create EACCES — these differ on purpose).
impl INodeOps {
    #[inline]
    pub fn call_lookup(
        &self,
        dir: &Inode,
        name: &[u8],
        unsupported: Result<Ino, Errno>,
    ) -> Result<Ino, Errno> {
        match self.lookup {
            Some(f) => f(dir, name),
            None => unsupported,
        }
    }

    #[inline]
    pub fn call_create(
        &self,
        dir: &Inode,
        name: &[u8],
        mode: InodeMode,
        unsupported: Result<Arc<Inode>, Errno>,
    ) -> Result<Arc<Inode>, Errno> {
        match self.create {
            Some(f) => f(dir, name, mode),
            None => unsupported,
        }
    }

    #[inline]
    pub fn call_link(&self, dir: &Inode, name: &[u8], target: &Inode, unsupported: i32) -> i32 {
        match self.link {
            Some(f) => f(dir, name, target),
            None => unsupported,
        }
    }

    #[inline]
    pub fn call_unlink(&self, dir: &Inode, name: &[u8], unsupported: i32) -> i32 {
        match self.unlink {
            Some(f) => f(dir, name),
            None => unsupported,
        }
    }

    #[inline]
    pub fn call_symlink(
        &self,
        dir: &Inode,
        name: &[u8],
        target: &[u8],
        unsupported: Result<Arc<Inode>, Errno>,
    ) -> Result<Arc<Inode>, Errno> {
        match self.symlink {
            Some(f) => f(dir, name, target),
            None => unsupported,
        }
    }

    #[inline]
    pub fn call_mkdir(
        &self,
        dir: &Inode,
        name: &[u8],
        mode: InodeMode,
        unsupported: Result<Arc<Inode>, Errno>,
    ) -> Result<Arc<Inode>, Errno> {
        match self.mkdir {
            Some(f) => f(dir, name, mode),
            None => unsupported,
        }
    }

    #[inline]
    pub fn call_rmdir(&self, dir: &Inode, name: &[u8], unsupported: i32) -> i32 {
        match self.rmdir {
            Some(f) => f(dir, name),
            None => unsupported,
        }
    }

    #[inline]
    pub fn call_mknod(
        &self,
        dir: &Inode,
        name: &[u8],
        mode: InodeMode,
        dev: u64,
        unsupported: Result<Arc<Inode>, Errno>,
    ) -> Result<Arc<Inode>, Errno> {
        match self.mknod {
            Some(f) => f(dir, name, mode, dev),
            None => unsupported,
        }
    }

    #[inline]
    pub fn call_rename(
        &self,
        old_dir: &Inode,
        old_name: &[u8],
        new_dir: &Inode,
        new_name: &[u8],
        unsupported: i32,
    ) -> i32 {
        match self.rename {
            Some(f) => f(old_dir, old_name, new_dir, new_name),
            None => unsupported,
        }
    }

    #[inline]
    pub fn call_readlink(&self, inode: &Inode, buf: &mut [u8], unsupported: isize) -> isize {
        match self.readlink {
            Some(f) => f(inode, buf),
            None => unsupported,
        }
    }

    #[inline]
    pub fn call_get_file_ops(
        &self,
        inode: &Inode,
    ) -> Option<&'static super::types::FileOps> {
        // get_file_ops has no "unsupported errno" — every site treats
        // both None layers identically (keep the existing ops / skip).
        match self.get_file_ops {
            Some(f) => f(inode),
            None => None,
        }
    }

    #[inline]
    pub fn call_readdir(
        &self,
        dir: &Inode,
    ) -> Option<alloc::vec::Vec<VfsDirEntry>> {
        match self.readdir {
            Some(f) => f(dir),
            None => None,
        }
    }

    #[inline]
    pub fn call_readdir_fill(
        &self,
        dir: &Inode,
        pos: u64,
        buf: &mut [u8],
    ) -> Option<Result<(usize, u64), i32>> {
        match self.readdir_fill {
            Some(f) => Some(f(dir, pos, buf)),
            None => None,
        }
    }

    #[inline]
    pub fn call_open(&self, inode: &Inode, file: &super::types::File, unsupported: i32) -> i32 {
        match self.open {
            Some(f) => f(inode, file),
            None => unsupported,
        }
    }

    #[inline]
    pub fn call_permission(&self, inode: &Inode, mask: u32, unsupported: i32) -> i32 {
        match self.permission {
            Some(f) => f(inode, mask),
            None => unsupported,
        }
    }

    #[inline]
    pub fn call_getattr(&self, inode: &Inode, stat: &mut super::types::Stat, unsupported: i32) -> i32 {
        match self.getattr {
            Some(f) => f(inode, stat),
            None => unsupported,
        }
    }

    #[inline]
    pub fn call_setattr(
        &self,
        inode: &Inode,
        attr: u32,
        arg1: u64,
        arg2: u64,
        unsupported: i32,
    ) -> i32 {
        match self.setattr {
            Some(f) => f(inode, attr, arg1, arg2),
            None => unsupported,
        }
    }

    #[inline]
    pub fn call_iget(
        &self,
        parent: &Inode,
        name: &[u8],
        ino: Ino,
        unsupported: Result<Arc<Inode>, Errno>,
    ) -> Result<Arc<Inode>, Errno> {
        match self.iget {
            Some(f) => f(parent, name, ino),
            None => unsupported,
        }
    }

    /// Dispatch destroy_inode (used by Inode::drop). Returns true when a
    /// hook ran.
    #[inline]
    pub fn call_destroy_inode(&self, inode: &mut Inode) -> bool {
        match self.destroy_inode {
            Some(f) => {
                f(inode);
                true
            }
            None => false,
        }
    }
}

/// Index node
///
/// Each inode represents an object (file, directory, symlink, etc.) in a filesystem.
/// Inodes are cached in the inode cache (icache) and can be shared.
/// Filesystem identity tags for the inode cache: entries from different
/// filesystems must never collide on (ino, fs_id) — rootfs/procfs/devfs all
/// use small inode numbers that would otherwise alias each other
/// (review VFS-H8). ext4 uses its instance pointer, which never equals
/// these small constants.
pub const FS_ID_ROOTFS: u64 = 0x525F_4653_0001;
pub const FS_ID_PROCFS: u64 = 0x5052_4F43_0002;
pub const FS_ID_DEVFS: u64 = 0x4445_5646_0003;
/// cgroup2 (unified cgroup hierarchy) — "CGRP"
pub const FS_ID_CGROUPFS: u64 = 0x4347_5250_0004;
/// selinuxfs — "SLNX"
pub const FS_ID_SELINUXFS: u64 = 0x534C_4E58_0005;

// ============================================================================
// Anonymous device numbers (stat st_dev / statfs f_fsid source)
//
// Linux semantics: every filesystem INSTANCE (superblock) carries an
// s_dev, allocated from a global counter for anonymous filesystems
// (get_anon_bdev: MKDEV(0, n)) — each tmpfs/proc/mqueue mount gets a
// distinct number, bind/MS_MOVE mounts share the source's number, and
// stat(2) reports it as st_dev for every inode under the mount.
// Userspace depends on it: systemd/libmount's is-mounted check compares
// st_dev against the parent directory (equal → not mounted); with st_dev
// 0 everywhere every mountpoint looks unmounted (ub2404 dev-mqueue.mount
// chase). Rux maps each icache fs_id (the per-instance identity —
// tmpfs instances, ext4 instance pointers, the pseudo-fs constants) to
// one anonymous 0:n device, first-come-first-served.
//
// Readers are lock-free (Acquire snapshot load); the writer (first stat
// after a new fs_id appears) rebuilds + republishes under the write
// lock. Retired snapshots leak: mounts per boot are tens, each map a
// few hundred bytes — bounded, and freeing would race lock-free readers.
// ============================================================================

static ANON_DEV_NEXT: AtomicU32 = AtomicU32::new(1);
static ANON_DEV_MAP: core::sync::atomic::AtomicPtr<AnonDevMap> =
    core::sync::atomic::AtomicPtr::new(core::ptr::null_mut());
static ANON_DEV_WRITE: Spinlock<()> = Spinlock::new(());

/// The stat device (Linux s_dev) of a filesystem instance: kernel dev_t
/// shape (DevNo, typically major 0 = UNNAMED_MAJOR, minor from the
/// global counter). Deterministic per fs_id for the whole boot.
pub fn stat_dev_for_fs(fs_id: u64) -> super::types::DevNo {
    // Fast path: immutable published snapshot.
    let p = ANON_DEV_MAP.load(Ordering::Acquire);
    if !p.is_null() {
        // SAFETY: snapshots are immutable once published; the pointer is
        // only ever replaced (never freed), so this reference stays valid.
        if let Some(&d) = unsafe { (*p).0.get(&fs_id) } {
            return d;
        }
    }
    let _guard = ANON_DEV_WRITE.lock();
    // Re-check under the write lock (another CPU may have just published).
    let p = ANON_DEV_MAP.load(Ordering::Acquire);
    if !p.is_null() {
        // SAFETY: see above.
        if let Some(&d) = unsafe { (*p).0.get(&fs_id) } {
            return d;
        }
    }
    let dev = super::types::DevNo::new(0, ANON_DEV_NEXT.fetch_add(1, Ordering::Relaxed));
    let mut next = alloc::collections::BTreeMap::new();
    if !p.is_null() {
        // SAFETY: see above; clone under the write lock.
        next.clone_from(unsafe { &(*p).0 });
    }
    next.insert(fs_id, dev);
    let fresh = alloc::boxed::Box::into_raw(alloc::boxed::Box::new(AnonDevMap(next)));
    ANON_DEV_MAP.store(fresh, Ordering::Release);
    dev
}

/// stat(2) st_dev of a filesystem instance: the USERSPACE dev_t encoding
/// (new_encode_dev layout — what struct stat carries and glibc
/// major()/minor() decode). Non-zero, distinct per instance, identical
/// for every inode of the instance (bind/move mounts included).
pub fn stat_dev_user(fs_id: u64) -> u64 {
    stat_dev_for_fs(fs_id).to_user_dev()
}

unsafe impl Send for Inode {}
unsafe impl Sync for Inode {}

impl Drop for Inode {
    fn drop(&mut self) {
        // R20-FS4: reclaim filesystem-private data when the last Arc<Inode>
        // goes away. Every filesystem stashed ownership in raw form
        // (ext4: Box<Ext4Inode> in `sb`; rootfs/devfs: Arc<Node> in
        // `private_data`) and provided a destroy_inode hook for exactly
        // this moment — but nothing ever called it, so every finally
        // dropped inode leaked its Box/Arc reference. The hooks use
        // Option::take(), so they are idempotent.
        if let Some(ops) = self.ops {
            if let Some(destroy_fn) = ops.destroy_inode {
                destroy_fn(self);
            }
        }
    }
}

impl Inode {
    /// (negative-lookup memo) Invalidate this directory's negative memos
    /// — call on every successful mutation dispatched through this
    /// inode as the parent. One fetch_add; the walk's memo-hit path
    /// compares generations lazily. Shared across bind-mount aliases
    /// (they are separate dentries over this one inode).
    #[inline]
    pub fn dir_mut_gen_bump(&self) {
        self.dir_mut_gen.fetch_add(1, core::sync::atomic::Ordering::AcqRel);
    }

    /// (negative-lookup memo) The directory's current content generation.
    #[inline]
    pub fn dir_mut_gen_load(&self) -> u64 {
        self.dir_mut_gen.load(core::sync::atomic::Ordering::Acquire)
    }

    /// Update the CACHED mode word after a successful setattr(ATTR_MODE).
    ///
    /// The icache shares Inode through Arc while the VFS reads `mode`
    /// lock-free (is_fifo/is_directory/bits). Filesystem setattr paths
    /// persist the new mode to their backing store but historically left
    /// this cached copy stale — stat (getattr) and open (cached field)
    /// then DISAGREED: an mknod-retyped FIFO stayed "regular" for every
    /// open while stat reported S_IFIFO, and chmod changes were invisible
    /// to DAC checks. A single aligned u32 volatile store cannot tear on
    /// this target; fences order it against the persisted store.
    pub fn update_cached_mode(&self, mode: InodeMode) {
        let ptr = &self.mode as *const InodeMode as *mut InodeMode;
        core::sync::atomic::fence(core::sync::atomic::Ordering::Release);
        // SAFETY: self is a live shared Inode; the store is aligned and
        // u32-sized (see comment) — concurrent readers observe either the
        // old or the new full word.
        unsafe { ptr.write_volatile(mode); }
        core::sync::atomic::fence(core::sync::atomic::Ordering::Release);
    }

    /// Create new inode
    pub fn new(ino: Ino, mode: InodeMode) -> Self {
        Self {
            fs_id: 0,
            ino,
            mode,
            size: AtomicU64::new(0),
            rdev: 0,
            rdev_atomic: AtomicU64::new(0),
            uid: AtomicU32::new(0),
            gid: AtomicU32::new(0),
            dir_mut_gen: AtomicU64::new(0),
            state: Spinlock::new(InodeState::INew),
            ops: None,
            sb: None,
            private_data: None,
            data: Spinlock::new(None),
            xattrs: Spinlock::new(None),
            ioc_flags: AtomicU32::new(0),
            open_total: AtomicU32::new(0),
            open_write: AtomicU32::new(0),
            open_breaking: AtomicU32::new(0),
            open_breaking_write: AtomicU32::new(0),
            ref_count: AtomicU64::new(1),
        }
    }

    /// Create new inode with superblock
    /// Create new inode with superblock
    pub fn with_superblock(ino: Ino, mode: InodeMode, sb: *mut u8) -> Self {
        Self {
            fs_id: 0,
            ino,
            mode,
            size: AtomicU64::new(0),
            rdev: 0,
            rdev_atomic: AtomicU64::new(0),
            uid: AtomicU32::new(0),
            gid: AtomicU32::new(0),
            dir_mut_gen: AtomicU64::new(0),
            state: Spinlock::new(InodeState::INew),
            ops: None,
            sb: Some(sb),
            private_data: None,
            data: Spinlock::new(None),
            xattrs: Spinlock::new(None),
            ioc_flags: AtomicU32::new(0),
            open_total: AtomicU32::new(0),
            open_write: AtomicU32::new(0),
            open_breaking: AtomicU32::new(0),
            open_breaking_write: AtomicU32::new(0),
            ref_count: AtomicU64::new(1),
        }
    }

    /// Read file data
    pub fn read_data(&self, offset: usize, buf: &mut [u8]) -> usize {
        if let Some(ref data) = *self.data.lock() {
            data.read(offset, buf)
        } else {
            0
        }
    }

    /// Append data at the current end of the file, atomically with
    /// respect to other appenders.
    ///
    /// Linux takes the O_APPEND position under the inode lock
    /// (generic_write_checks), so two writers on DIFFERENT open file
    /// descriptions cannot pick the same offset. The generic path read
    /// the size and then wrote without holding one lock across both, so
    /// two appenders could land on the same offset and the second write
    /// would overwrite the first.
    ///
    /// Returns the offset the data was written at and the byte count.
    pub fn append_data(&self, buf: &[u8]) -> (u64, usize) {
        let mut data_guard = self.data.lock();
        if data_guard.is_none() {
            *data_guard = Some(FileBuffer::new());
        }
        let Some(ref mut data) = *data_guard else {
            return (0, 0);
        };
        let end = data.len();
        let written = data.write(end, buf);
        // Update file size
        let new_size = data.len() as u64;
        self.size.store(new_size, Ordering::Release);
        (end as u64, written)
    }

    /// Write file data
    pub fn write_data(&self, offset: usize, buf: &[u8]) -> usize {
        let mut data_guard = self.data.lock();
        if data_guard.is_none() {
            *data_guard = Some(FileBuffer::new());
        }
        if let Some(ref mut data) = *data_guard {
            let written = data.write(offset, buf);
            // Update file size
            let new_size = data.len() as u64;
            self.size.store(new_size, Ordering::Release);
            written
        } else {
            0
        }
    }

    /// Load file content from bytes
    pub fn load_from_bytes(&self, bytes: &[u8]) {
        let mut data_guard = self.data.lock();
        *data_guard = Some(FileBuffer::from_bytes(bytes));
        self.size.store(bytes.len() as u64, Ordering::Release);
    }

    /// Set inode operations
    pub fn set_ops(&mut self, ops: &'static INodeOps) {
        self.ops = Some(ops);
    }

    /// Set private data
    pub fn set_private_data(&mut self, data: *mut u8) {
        self.private_data = Some(data);
    }

    /// Get file size
    pub fn get_size(&self) -> u64 {
        self.size.load(Ordering::Acquire)
    }

    /// Set file size
    pub fn set_size(&self, size: u64) {
        self.size.store(size, Ordering::Release);
    }

    /// Set the device number through a shared inode (mknod retype path).
    pub fn set_rdev(&self, rdev: u64) {
        self.rdev_atomic.store(rdev, Ordering::Release);
    }

    /// Current device number (atomic mirror wins once set).
    pub fn get_rdev(&self) -> u64 {
        let a = self.rdev_atomic.load(Ordering::Acquire);
        if a != 0 { a } else { self.rdev }
    }

    /// Increment reference count
    pub fn inc_ref(&self) {
        self.ref_count.fetch_add(1, Ordering::AcqRel);
    }

    /// Decrement reference count
    pub fn dec_ref(&self) -> u64 {
        self.ref_count.fetch_sub(1, Ordering::AcqRel) - 1
    }

    /// Get reference count
    pub fn get_ref(&self) -> u64 {
        self.ref_count.load(Ordering::Acquire)
    }

    // ==================== Inode Operations Helpers ====================

    /// Lookup entry in this directory
    ///
    /// # Arguments
    /// - `name`: Entry name to lookup
    ///
    /// # Returns
    /// - `Ok(ino)`: Inode number of found entry
    /// - `Err(errno)`: Error code
    #[inline]
    pub fn op_lookup(&self, name: &[u8]) -> Result<Ino, Errno> {
        if let Some(ops) = self.ops {
            if let Some(lookup_fn) = ops.lookup {
                return lookup_fn(self, name);
            }
        }
        Err(crate::errno::Errno::FunctionNotImplemented)
    }

    /// Create regular file in this directory
    #[inline]
    pub fn op_create(&self, name: &[u8], mode: InodeMode) -> Result<Arc<Inode>, Errno> {
        if let Some(ops) = self.ops {
            if let Some(create_fn) = ops.create {
                return create_fn(self, name, mode);
            }
        }
        Err(crate::errno::Errno::FunctionNotImplemented)
    }

    /// Create directory in this directory
    #[inline]
    pub fn op_mkdir(&self, name: &[u8], mode: InodeMode) -> Result<Arc<Inode>, Errno> {
        if let Some(ops) = self.ops {
            if let Some(mkdir_fn) = ops.mkdir {
                return mkdir_fn(self, name, mode);
            }
        }
        Err(crate::errno::Errno::FunctionNotImplemented)
    }

    /// Remove directory entry (unlink file)
    #[inline]
    pub fn op_unlink(&self, name: &[u8]) -> i32 {
        if let Some(ops) = self.ops {
            if let Some(unlink_fn) = ops.unlink {
                return unlink_fn(self, name);
            }
        }
        crate::errno::Errno::FunctionNotImplemented.as_neg_i32()
    }

    /// Remove empty directory
    #[inline]
    pub fn op_rmdir(&self, name: &[u8]) -> i32 {
        if let Some(ops) = self.ops {
            if let Some(rmdir_fn) = ops.rmdir {
                return rmdir_fn(self, name);
            }
        }
        crate::errno::Errno::FunctionNotImplemented.as_neg_i32()
    }

    /// Create hard link
    #[inline]
    pub fn op_link(&self, name: &[u8], target: &Inode) -> i32 {
        if let Some(ops) = self.ops {
            if let Some(link_fn) = ops.link {
                return link_fn(self, name, target);
            }
        }
        crate::errno::Errno::FunctionNotImplemented.as_neg_i32()
    }

    /// Create symbolic link
    #[inline]
    pub fn op_symlink(&self, name: &[u8], target: &[u8]) -> Result<Arc<Inode>, Errno> {
        if let Some(ops) = self.ops {
            if let Some(symlink_fn) = ops.symlink {
                return symlink_fn(self, name, target);
            }
        }
        Err(crate::errno::Errno::FunctionNotImplemented)
    }

    /// Rename file/directory
    #[inline]
    pub fn op_rename(&self, old_name: &[u8], new_dir: &Inode, new_name: &[u8]) -> i32 {
        if let Some(ops) = self.ops {
            if let Some(rename_fn) = ops.rename {
                return rename_fn(self, old_name, new_dir, new_name);
            }
        }
        crate::errno::Errno::FunctionNotImplemented.as_neg_i32()
    }

    /// Read symbolic link target
    #[inline]
    pub fn op_readlink(&self, buf: &mut [u8]) -> isize {
        if let Some(ops) = self.ops {
            if let Some(readlink_fn) = ops.readlink {
                return readlink_fn(self, buf);
            }
        }
        crate::errno::Errno::FunctionNotImplemented.as_neg_i32() as isize
    }

    /// Get attributes (stat)
    #[inline]
    pub fn op_getattr(&self, stat: &mut super::types::Stat) -> i32 {
        if let Some(ops) = self.ops {
            if let Some(getattr_fn) = ops.getattr {
                return getattr_fn(self, stat);
            }
        }
        // Default implementation
        stat.st_ino = self.ino;
        stat.st_mode = self.mode.bits();
        stat.st_size = self.size.load(Ordering::Acquire) as i64;
        0
    }

    /// Set attributes (chmod/chown/truncate)
    #[inline]
    pub fn op_setattr(&self, attr: u32, arg1: u64, arg2: u64) -> i32 {
        if let Some(ops) = self.ops {
            if let Some(setattr_fn) = ops.setattr {
                return setattr_fn(self, attr, arg1, arg2);
            }
        }
        crate::errno::Errno::ReadOnlyFileSystem.as_neg_i32()
    }

    /// Check permission
    #[inline]
    pub fn op_permission(&self, mask: u32) -> i32 {
        if let Some(ops) = self.ops {
            if let Some(perm_fn) = ops.permission {
                return perm_fn(self, mask);
            }
        }
        // Default: allow all
        0
    }
}

/// Create character device inode
pub fn make_char_inode(ino: Ino, rdev: u64) -> Inode {
    let mut inode = Inode::new(ino, InodeMode::new(InodeMode::S_IFCHR | 0o666));
    inode.rdev = rdev;
    inode
}

/// Create regular file inode
pub fn make_reg_inode(ino: Ino, size: u64) -> Inode {
    let inode = Inode::new(ino, InodeMode::new(InodeMode::S_IFREG | 0o666));
    inode.set_size(size);
    inode
}

/// Create regular file inode with data
pub fn make_reg_inode_with_data(ino: Ino, data: &[u8]) -> Inode {
    let inode = Inode::new(ino, InodeMode::new(InodeMode::S_IFREG | 0o666));
    inode.load_from_bytes(data);
    inode
}

/// Create directory inode
pub fn make_dir_inode(ino: Ino) -> Inode {
    Inode::new(ino, InodeMode::new(InodeMode::S_IFDIR | 0o755))
}

/// Create FIFO inode
pub fn make_fifo_inode(ino: Ino) -> Inode {
    Inode::new(ino, InodeMode::new(InodeMode::S_IFIFO | 0o666))
}

// ============================================================================
// Inode cache (icache)
// ============================================================================

/// Inode cache size - Was 256 (review 5.1: icache 冲突逐出后同文件双
/// Inode) — enlarged and paired with the eviction fix in
/// icache_evict_lru (never evict entries still referenced outside the
/// cache). Defined locally: config.rs is concurrently edited by other
/// repair agents.
const ICACHE_SIZE: usize = 1024;

impl InodeCacheStats {
    pub fn new() -> Self {
        Self {
            hits: AtomicU64::new(0),
            misses: AtomicU64::new(0),
            evictions: AtomicU64::new(0),
        }
    }

    pub fn record_hit(&self) {
        self.hits.fetch_add(1, Ordering::Relaxed);
    }

    pub fn record_miss(&self) {
        self.misses.fetch_add(1, Ordering::Relaxed);
    }

    pub fn record_eviction(&self) {
        self.evictions.fetch_add(1, Ordering::Relaxed);
    }

    pub fn get_hit_rate(&self) -> f64 {
        let hits = self.hits.load(Ordering::Relaxed);
        let misses = self.misses.load(Ordering::Relaxed);
        let total = hits + misses;
        if total == 0 {
            0.0
        } else {
            (hits as f64) / (total as f64)
        }
    }
}

impl Clone for InodeHashBucket {
    fn clone(&self) -> Self {
        Self {
            inode: self.inode.clone(),
            ino: self.ino,
            fs_id: self.fs_id,
            access_time: AtomicU64::new(self.access_time.load(Ordering::Relaxed)),
        }
    }
}

unsafe impl Send for InodeCache {}
unsafe impl Sync for InodeCache {}

/// Global Inode cache
static ICACHE: Spinlock<Option<InodeCache>> = Spinlock::new(None);

/// (perf-path lane) Inode-identity generation: bumped on every icache
/// membership change (insert / replace / evict / remove). Dentries stamp
/// the generation they last refreshed at, so a walk can decide with ONE
/// Relaxed load whether its cached inode Arc is still the icache's
/// current object for that (ino, fs_id) — replacing the per-component
/// global-lock icache_lookup on the dcache-hit fast path. The mapping
/// only ever changes when the bucket set changes, which is exactly what
/// bumps this counter.
static ICACHE_REGEN: core::sync::atomic::AtomicU64 =
    core::sync::atomic::AtomicU64::new(1);

/// (perf-path lane) Current inode-identity generation (see ICACHE_REGEN).
#[inline]
pub fn icache_regen() -> u64 {
    ICACHE_REGEN.load(Ordering::Relaxed)
}

/// Initialize Inode cache
///
/// (perf-syscall lane) The init check used to take the global ICACHE
/// spinlock on EVERY lookup — this runs once per boot, so a lock-free
/// done-flag fronts it. On the walk path icache_lookup is called per
/// component; the saved lock pair was pure overhead after boot.
static ICACHE_INIT_DONE: core::sync::atomic::AtomicBool =
    core::sync::atomic::AtomicBool::new(false);
fn icache_init() {
    if ICACHE_INIT_DONE.load(Ordering::Acquire) {
        return;
    }
    let mut cache = ICACHE.lock();
    if cache.is_some() {
        ICACHE_INIT_DONE.store(true, Ordering::Release);
        return;  // Already initialized
    }

    // Heap-allocate bucket array to avoid large stack allocation
    let buckets: alloc::vec::Vec<InodeHashBucket> = (0..ICACHE_SIZE)
        .map(|_| InodeHashBucket {
            inode: None,
            ino: 0,
            fs_id: 0,
            access_time: AtomicU64::new(0),
        })
        .collect();

    *cache = Some(InodeCache {
        buckets: buckets.into_boxed_slice(),
        count: 0,
        global_time: AtomicU64::new(1),
        stats: InodeCacheStats::new(),
    });
    ICACHE_INIT_DONE.store(true, Ordering::Release);
}

/// (perf-syscall lane) Hit/miss counters are diagnostics; the fetch_adds
/// ran on every lookup of every walk component. Armed on demand (the
/// LRU time updates stay unconditional — eviction order is functional).
static ICACHE_STATS_ARMED: core::sync::atomic::AtomicBool =
    core::sync::atomic::AtomicBool::new(false);
pub fn icache_stats_arm(on: bool) {
    ICACHE_STATS_ARMED.store(on, Ordering::Relaxed);
}

/// Calculate hash value
///
/// Uses FNV-1a hash algorithm with both fs_id and ino
fn inode_hash(ino: Ino, fs_id: u64) -> u64 {
    let mut hash = 0xcbf29ce484222325_u64;  // FNV offset basis

    // Mix filesystem identifier
    hash ^= fs_id;
    hash = hash.wrapping_mul(0x100000001b3);

    // Mix inode number
    hash ^= ino;
    hash = hash.wrapping_mul(0x100000001b3);

    hash
}

/// Lookup in Inode cache
///
pub fn icache_lookup(ino: Ino, fs_id: u64) -> Option<Arc<Inode>> {
    // Ensure cache is initialized
    icache_init();

    let mut cache = ICACHE.lock();
    let cache_inner = cache.as_mut()?;

    // Calculate hash value
    let hash = inode_hash(ino, fs_id);
    let index = (hash as usize) % ICACHE_SIZE;

    // Find matching entry
    let bucket = &cache_inner.buckets[index];

    if let Some(ref inode) = bucket.inode {
        // Compare inode number and filesystem id
        if bucket.ino == ino && bucket.fs_id == fs_id {
            // Update access time (for LRU)
            let current_time = cache_inner.global_time.fetch_add(1, Ordering::Relaxed);
            bucket.access_time.store(current_time, Ordering::Relaxed);

            // Record hit (diagnostics only — armed on demand)
            if ICACHE_STATS_ARMED.load(Ordering::Relaxed) {
                cache_inner.stats.record_hit();
            }

            return Some(inode.clone());
        }
    }

    // Record miss (diagnostics only — armed on demand)
    if ICACHE_STATS_ARMED.load(Ordering::Relaxed) {
        cache_inner.stats.record_miss();
    }

    None
}

/// Add Inode to cache
///
pub fn icache_add(inode: Arc<Inode>) {
    // Ensure cache is initialized
    icache_init();

    // Get inode number and fs_id (outside cache lock)
    let ino = inode.ino;
    let fs_id = inode.fs_id;

    // Calculate hash value
    let hash = inode_hash(ino, fs_id);

    let mut cache = ICACHE.lock();
    let inner = cache.as_mut().expect("icache not initialized");

    let index = (hash as usize) % ICACHE_SIZE;

    // Check if already exists
    if let Some(ref _existing) = inner.buckets[index].inode {
        if inner.buckets[index].ino == ino && inner.buckets[index].fs_id == fs_id {
            return;  // Already in cache
        }

        // Use LRU policy: find and evict least recently used entry
        icache_evict_lru(inner);
    }

    // Get current timestamp
    let current_time = inner.global_time.fetch_add(1, Ordering::Relaxed);

    // Add to cache (only increment count when the bucket was previously empty)
    let was_empty = inner.buckets[index].inode.is_none();
    inner.buckets[index] = InodeHashBucket {
        inode: Some(inode.clone()),
        ino,
        fs_id,
        access_time: AtomicU64::new(current_time),
    };
    if was_empty {
        inner.count += 1;
    }
    // (perf-path lane) membership changed — invalidate the walk-side
    // generation fast path (see ICACHE_REGEN).
    ICACHE_REGEN.fetch_add(1, Ordering::Relaxed);
}

/// LRU eviction policy: evict least recently used entry.
///
/// Review 5.1 (icache 冲突逐出后同文件双 Inode): entries still referenced
/// outside the cache (strong_count > 1 — dentries, open files) are NEVER
/// evicted. Dropping the cache's Arc while users still hold their own would
/// make the next lookup instantiate a SECOND VFS Inode for the same
/// on-disk inode, and the two copies' cached state (ext4 block map, size)
/// diverge with every write. Combined with the larger cache (ICACHE_SIZE
/// 1024) this closes the dual-instance window for working sets that fit.
fn icache_evict_lru(cache: &mut InodeCache) -> bool {
    // Find least recently used EVICTABLE entry (minimum access time).
    let mut lru_index = usize::MAX;
    let mut lru_time = u64::MAX;

    for (i, bucket) in cache.buckets.iter().enumerate() {
        if let Some(ref inode) = bucket.inode {
            // Skip actively-referenced entries: the cache holds only one of
            // possibly several Arc references; evicting a live one forks the
            // inode identity.
            if Arc::strong_count(inode) > 1 {
                continue;
            }
            let access_time = bucket.access_time.load(Ordering::Relaxed);
            if access_time < lru_time {
                lru_time = access_time;
                lru_index = i;
            }
        }
    }

    if lru_index == usize::MAX {
        return false; // nothing evictable
    }

    // Evict LRU entry
    cache.buckets[lru_index].inode = None;
    cache.buckets[lru_index].ino = 0;
    cache.buckets[lru_index].access_time.store(0, Ordering::Relaxed);
    cache.count -= 1;

    // Record eviction
    cache.stats.record_eviction();
    true
}

/// Remove from Inode cache
///
pub fn icache_remove(ino: Ino, fs_id: u64) {
    // Ensure cache is initialized
    icache_init();

    let mut cache = ICACHE.lock();
    let inner = cache.as_mut().expect("icache not initialized");

    // Calculate hash value
    let hash = inode_hash(ino, fs_id);
    let index = (hash as usize) % ICACHE_SIZE;

    // Remove entry
    if let Some(ref _inode) = inner.buckets[index].inode {
        if inner.buckets[index].ino == ino && inner.buckets[index].fs_id == fs_id {
            // Remove from cache
            inner.buckets[index].inode = None;
            inner.buckets[index].ino = 0;
            inner.buckets[index].fs_id = 0;
            inner.buckets[index].access_time.store(0, Ordering::Relaxed);
            inner.count -= 1;
            // (perf-path lane) membership changed — see ICACHE_REGEN.
            ICACHE_REGEN.fetch_add(1, Ordering::Relaxed);
        }
    }
}

/// Get cache statistics
pub fn icache_stats() -> (usize, usize) {
    // Ensure cache is initialized
    icache_init();

    let cache = ICACHE.lock();
    let cache_inner = cache.as_ref().expect("icache not initialized");

    (cache_inner.count, ICACHE_SIZE)
}

/// Get detailed cache statistics
pub fn icache_stats_detailed() -> (u64, u64, u64, f64) {
    // Ensure cache is initialized
    icache_init();

    let cache = ICACHE.lock();
    let cache_inner = cache.as_ref().expect("icache not initialized");

    (
        cache_inner.stats.hits.load(Ordering::Relaxed),
        cache_inner.stats.misses.load(Ordering::Relaxed),
        cache_inner.stats.evictions.load(Ordering::Relaxed),
        cache_inner.stats.get_hit_rate(),
    )
}

/// Clear Inode cache
///
pub fn icache_flush() {
    // Ensure cache is initialized
    icache_init();

    let mut cache = ICACHE.lock();
    let inner = cache.as_mut().expect("icache not initialized");

    // Clear all buckets
    for bucket in inner.buckets.iter_mut() {
        bucket.inode = None;
        bucket.ino = 0;
        bucket.access_time.store(0, Ordering::Relaxed);
    }

    inner.count = 0;
    // (perf-path lane) full flush — every identity mapping changed.
    ICACHE_REGEN.fetch_add(1, Ordering::Relaxed);
}


// ════════════════ dentry ══════════════════════════════
// (was dentry.rs)
// Directory Entry (Dentry) Management
//
//
// Core concepts:
// - `struct dentry`: Directory entry, representing an entry in a directory
// - `dcache`: Directory entry cache, speeds up path lookup
// - `LRU`: Least Recently Used eviction policy

impl DentryFlags {
    /// Directory entry not connected to dcache
    pub const DCACHE_UNHASHED: u32 = 0x00000001;
    /// Directory entry connected to dcache
    pub const DCACHE_HASHED: u32 = 0x00000002;
    /// Directory entry in use
    pub const DCACHE_REFERENCED: u32 = 0x00000010;
    /// Directory entry deleted
    pub const DCACHE_DENTRY_KILL: u32 = 0x00000040;

    pub fn new(flags: u32) -> Self {
        Self(flags)
    }

    pub fn is_hashed(&self) -> bool {
        (self.0 & Self::DCACHE_HASHED) != 0
    }

    pub fn is_unhashed(&self) -> bool {
        (self.0 & Self::DCACHE_UNHASHED) != 0
    }

    pub fn bits(&self) -> u32 {
        self.0
    }
}

/// sc181: mount attach-sequence allocator (see VfsMountInternal::seq).
static MOUNT_SEQ: core::sync::atomic::AtomicU64 = core::sync::atomic::AtomicU64::new(0);

impl VfsMountInternal {
    pub fn new(root: Arc<Dentry>, flags: MntFlags) -> Self {
        Self {
            root,
            flags: Spinlock::new(flags),
            seq: MOUNT_SEQ.fetch_add(1, core::sync::atomic::Ordering::Relaxed),
        }
    }
}

unsafe impl Send for VfsMountInternal {}
unsafe impl Sync for VfsMountInternal {}

// ============================================================================
// Reader banks + deferred retirement (gap-fs lane)
// ============================================================================
//
// The path walk's per-component costs were dominated by lock pairs:
// `children` (BTreeMap under a spinlock) and `inode` (Option<Arc> under a
// spinlock) — measured ~39 ns + ~20 ns per walked component under the fsw
// pathcost probe, with the line bouncing between the two vCPUs of the
// lmbench rig. The protocol below (the FdTable leg-52 lever-B pattern,
// generalized) lets the walk read both lock-free:
//
// READER: acquire a WalkClaim (a SeqCst increment of THIS CPU's reader
// bank — or, for a cpu id outside the bank range, the DENTRY_SLOW_READ
// irqsave lock), then load a memo slot's child pointer / the inode
// pointer mirror and, when an owned reference is needed, increment the
// target's strong count BEFORE releasing the claim.
//
// WRITER: every mutation of the child map or the inode slot bumps the
// dentry's `children_ver` (memo slots stamped with an older version are
// then ignored) and parks any Arc it removes in the RETIRED lists
// instead of dropping it in place.
//
// DRAIN: `dentry_drain_if_quiescent` reclaims the retired Arcs only
// after a SeqCst fence and a scan that observes EVERY bank at zero (plus
// DENTRY_SLOW_READ held across the take). A reader can therefore only
// load a pointer whose reference is provably alive: either the map /
// inode slot still publishes it, or the removing writer's drain is
// waiting for THIS reader's bank to return to zero before its drop. The
// reader's SeqCst claim-before-load and the drain's SeqCst-fence-then-
// scan close the store-load ordering hole (same argument as FdTable's
// get_file / drain_retired pair).
//
// Unlike FdTable (whose sections are irq-off and bounded), a WalkClaim
// is PREEMPTIBLE and held for the dcache-hot span of one path walk: a
// walk never holds it across an operation that can sleep (fs lookup on
// a dcache miss, symlink read/follow, mount descriptor cloning) — those
// arms materialize owned Arcs and drop the claim first. A task
// preempted mid-claim only delays reclamation: the drain has a spin
// budget and defers to the next mutation (DENTRY_DRAIN_DEFERS counts
// the gives-up; correctness is never affected).

/// Number of per-CPU reader banks. Kernel.toml's SMP ceiling is 4; 16
/// leaves generous headroom. A cpu id at or above this bound degrades to
/// the DENTRY_SLOW_READ lock (held for the claim's span — unreachable
/// with any current config, but kept correct rather than assumed away;
/// the FdTable r8final discipline).
const DENTRY_READER_BANKS: usize = 16;

static DENTRY_BANKS: [DentryReaderBank; DENTRY_READER_BANKS] = [const {
    DentryReaderBank(AtomicUsize::new(0))
}; DENTRY_READER_BANKS];

/// Slow-path exclusion for readers whose cpu id falls outside the bank
/// range; drains hold it across the drop of retired Arcs.
static DENTRY_SLOW_READ: Spinlock<()> = Spinlock::new(());

/// Dentries removed from a parent's child map (remove_child /
/// add_child displacement / clear / rehome) whose last strong reference
/// may still be racing a banked reader — parked until a drain observes
/// every reader bank at zero.
static DENTRY_RET_DENTRY: Spinlock<Vec<Arc<Dentry>>> = Spinlock::new(Vec::new());

/// Inodes swapped out of a dentry's inode slot (set_inode / clear_inode)
/// — same parking discipline.
static DENTRY_RET_INODE: Spinlock<Vec<Arc<Inode>>> = Spinlock::new(Vec::new());

/// Drain give-up counter (debug observability, FdTable discipline): a
/// drain that could not observe all banks at zero within its spin budget
/// defers the retired drop to the next writer.
pub static DENTRY_DRAIN_DEFERS: AtomicUsize = AtomicUsize::new(0);

impl WalkClaim {
    /// Claim this CPU's reader bank (or the slow-path lock for an
    /// out-of-range cpu id).
    pub fn acquire() -> Self {
        let cpu = crate::arch::cpu_id() as usize;
        if cpu < DENTRY_READER_BANKS {
            DENTRY_BANKS[cpu].0.fetch_add(1, Ordering::SeqCst);
            WalkClaim { cpu, slow: None }
        } else {
            // SAFETY of holding this lock for the claim's span: drains
            // take it across the retired drop, so a raw pointer loaded
            // under it cannot be freed mid-read. Unreachable with the
            // current SMP configs (banks sized above the ceiling).
            let g = DENTRY_SLOW_READ.lock_irqsave();
            WalkClaim { cpu: usize::MAX, slow: Some(g) }
        }
    }
}

impl Drop for WalkClaim {
    fn drop(&mut self) {
        if self.cpu != usize::MAX {
            DENTRY_BANKS[self.cpu].0.fetch_sub(1, Ordering::Release);
        } else {
            self.slow.take(); // releases the slow-path lock
        }
    }
}

/// Park a detached dentry until a reader-quiescent drain (see the
/// protocol comment above). Called by the child-map mutators with the
/// removed Arc in hand.
fn retire_dentry_arc(a: Arc<Dentry>) {
    DENTRY_RET_DENTRY.lock_irqsave().push(a);
}

/// Park a swapped-out inode (set_inode / clear_inode).
fn retire_inode_arc(a: Arc<Inode>) {
    DENTRY_RET_INODE.lock_irqsave().push(a);
}

/// (stat-2x lane) Park a replaced big-memo table (a banked walk reader
/// may still hold its base pointer mid-read); freed by the same
/// reader-quiescent drain as retired dentries/inodes.
static DENTRY_RET_MEMO: Spinlock<Vec<alloc::boxed::Box<BigMemoTable>>> =
    Spinlock::new(Vec::new());

/// Drop retired dentries/inodes once no reader can be mid-read.
///
/// Quiescence: every bank reads 0 (each scan load Acquire — reading 0
/// synchronizes with that reader's Release decrement, so its
/// strong-count increment has completed) AND the slow-path lock is held
/// across the take. Readers that START after a successful scan cannot
/// load these Arcs: the map/slot publications preceded the park, the
/// parks precede this drain's SeqCst fence, and a fresh reader's pointer
/// load follows its own SeqCst bank claim.
///
/// `parked`: the caller just pushed entries (skip the emptiness
/// pre-check). Called by the mutators after every retire and (cheaply)
/// when their retired lists have grown past the drain threshold.
pub fn dentry_drain_if_quiescent(parked: bool) {
    if !parked {
        // Cheap emptiness check first: most lookups/mutations park
        // nothing and most drains find a previous drain already took
        // the vecs.
        let d = DENTRY_RET_DENTRY.lock_irqsave();
        if d.is_empty() {
            let i = DENTRY_RET_INODE.lock_irqsave();
            if i.is_empty() {
                drop(i);
                drop(d);
                let m = DENTRY_RET_MEMO.lock_irqsave();
                if m.is_empty() {
                    return;
                }
            }
        }
    }
    let mut scans: usize = 0;
    loop {
        // The fence orders the earlier retire/park stores before the
        // bank reads below (the reader side of the handshake is its
        // SeqCst bank claim before its pointer load).
        core::sync::atomic::fence(Ordering::SeqCst);
        let mut all_zero = true;
        for b in DENTRY_BANKS.iter() {
            if b.0.load(Ordering::Acquire) != 0 {
                all_zero = false;
                break;
            }
        }
        if all_zero {
            break;
        }
        scans += 1;
        if scans >= 64 {
            // Defer, never fail: the next writer retries. Walk claims
            // are preemptible, so a deferral is expected whenever a
            // hot-walk CPU is mid-path — bounded by mutation bursts.
            DENTRY_DRAIN_DEFERS.fetch_add(1, Ordering::Relaxed);
            return;
        }
        core::hint::spin_loop();
    }
    {
        let _slow = DENTRY_SLOW_READ.lock_irqsave();
        let taken_d = core::mem::take(&mut *DENTRY_RET_DENTRY.lock_irqsave());
        let taken_i = core::mem::take(&mut *DENTRY_RET_INODE.lock_irqsave());
        let taken_m = core::mem::take(&mut *DENTRY_RET_MEMO.lock_irqsave());
        // Drops run inside the slow-lock scope: any cascade (a dentry's
        // child map / inode slot releasing further Arcs) cannot race a
        // banked reader, which by the scan above cannot exist now.
        drop(taken_d);
        drop(taken_i);
        drop(taken_m);
    }
}

/// Increment a dentry's strong count for a pointer loaded under a
/// reader claim (the claim blocks the drain that would otherwise free
/// it) and return an owned Arc.
///
/// # Safety
/// `p` must have been loaded from a dentry child memo slot / inode
/// pointer mirror while a WalkClaim is held by the caller, and `p` must
/// be non-null.
/// (INV-DENTRY-ADOPT-1: the claim-then-adopt protocol — the WalkClaim
/// blocks the deferred-retirement drain that would otherwise free the
/// target; increment_strong_count + from_raw under that claim is the
/// audited adopt edge. Both adopt fns and every call site ride it.)
pub unsafe fn dentry_arc_from_raw(p: *const Dentry) -> Arc<Dentry> {
    Arc::increment_strong_count(p);
    Arc::from_raw(p)
}

/// Same as [`dentry_arc_from_raw`] for inodes (the inode pointer mirror).
///
/// # Safety
/// See [`dentry_arc_from_raw`]; `p` non-null, loaded under a claim.
pub unsafe fn inode_arc_from_raw(p: *const Inode) -> Arc<Inode> {
    Arc::increment_strong_count(p);
    Arc::from_raw(p)
}

/// FNV-1a over the component bytes — the memo slot key.
#[inline]
fn child_name_hash(name: &[u8]) -> u64 {
    let mut hash = 0xcbf29ce484222325_u64;
    for &b in name {
        hash ^= b as u64;
        hash = hash.wrapping_mul(0x100000001b3);
    }
    hash
}

/// (stat-2x lane) Secondary lock-free memo for LARGE directories.
/// The inline 4-slot memo collapses to a ~1-in-N hit rate once a
/// directory holds more than a handful of children (a 1000-entry tree
/// cycling names: every final-component lookup missed and paid the
/// children spinlock + BTreeMap walk — the dominant stat/open cost on
/// the pbench tree shape; measured 0.491→0.291 µs med stat once the
/// final component rides a memo). The table is sized ADAPTIVELY
/// (next_pow2 of twice the live child count, clamped to
/// [CHILD_MEMO_BIG_MIN_SLOTS, CHILD_MEMO_BIG_MAX_SLOTS]) so a
/// direct-mapped slot count at or below the cycling name population
/// cannot thrash; it is reallocated under the children lock whenever
/// the directory outgrows it (a replaced table is parked in
/// DENTRY_RET_MEMO and freed by the same reader-quiescent drain that
/// frees retired dentries — a banked reader may still be mid-read of
/// the old base). Same seqlock-slot + children_ver discipline as the
/// inline memo — no new invalidation rules exist.
/// Entry threshold: below this the inline memo serves fine.
const CHILD_MEMO_BIG_MIN: usize = 12;
/// Size clamps: 128 slots (8 KB) minimum, 2048 slots (128 KB) maximum
/// per directory. Above the cap the hit rate degrades gracefully
/// (direct-mapped conflict misses fall to the locked map lookup).
const CHILD_MEMO_BIG_MIN_SLOTS: usize = 128;
const CHILD_MEMO_BIG_MAX_SLOTS: usize = 2048;

// SAFETY: the table's slots are shared-memory seqlock cells exactly like
// the inline `memo` array inside Sync Dentry; cross-thread access goes
// through the seqlock/children-lock protocol.
unsafe impl Send for BigMemoTable {}
unsafe impl Sync for BigMemoTable {}

impl ChildMemoSlot {
    const fn empty() -> Self {
        ChildMemoSlot {
            seq: AtomicU64::new(0),
            data: core::cell::UnsafeCell::new(ChildMemoData {
                ver: 0,
                hash: 0,
                name: [0; CHILD_MEMO_NAME_MAX],
                name_len: 0,
                child: core::ptr::null(),
            }),
        }
    }
}

/// Single-shot seqlock read of one memo slot against (ver, hash, name).
/// None on a writer race or a miss — the caller falls to the next tier
/// (inline → big → locked map), which is always authoritative.
#[inline]
fn memo_slot_read(
    slot: &ChildMemoSlot,
    ver: u64,
    h: u64,
    name: &[u8],
) -> Option<*const Dentry> {
    let s1 = slot.seq.load(Ordering::Acquire);
    if s1 & 1 != 0 {
        return None; // refill in flight
    }
    // SAFETY: seqlock-protected read (validated by the seq re-load
    // below; the sync::seqlock UnsafeCell discipline).
    // (INV-DENTRY-MEMO-1: the child-memo read family — seqlock odd/even
    // validation for the small slots, children-lock Release publication
    // + immutable nslots for the big table, walk-claim blocking the
    // drain; every memo/table row rides this.)
    let d = unsafe { &*slot.data.get() };
    let hit = d.ver == ver
        && d.hash == h
        && !d.child.is_null()
        && d.name_len as usize == name.len()
        && d.name[..name.len()] == *name;
    let p = d.child;
    if slot.seq.load(Ordering::Acquire) == s1 && hit {
        Some(p)
    } else {
        None
    }
}

// (INV-DENTRY-SEND-1: Dentry/VfsMountInternal/BigMemoTable Sync/Send
// are carried per-field — children/memo under their locks and seqlock,
// the retirement banks under the drain lock; no field races through
// a shared reference.)
unsafe impl Send for Dentry {}
unsafe impl Sync for Dentry {}

impl Dentry {
    /// Create new dentry
    pub fn new(name: String) -> Self {
        Self {
            name: Spinlock::new(name),
            parent: Spinlock::new(None),
            children: Spinlock::new(BTreeMap::new()),
            inode: Spinlock::new(None),
            vfsmount: Spinlock::new(None),
            mountpoint: Spinlock::new(None),
            state: Spinlock::new(DentryState::DUnhashed),
            flags: Spinlock::new(DentryFlags::new(DentryFlags::DCACHE_UNHASHED)),
            ref_count: AtomicU64::new(1),
            negative: AtomicBool::new(false),
            is_mountpoint: AtomicBool::new(false),
            inode_gen: AtomicU64::new(0),
            neg_gen: AtomicU64::new(0),
            neg_count: AtomicUsize::new(0),
            children_ver: AtomicU64::new(0),
            memo: [const { ChildMemoSlot::empty() }; CHILD_MEMO_SLOTS],
            big_memo: core::cell::UnsafeCell::new(None),
            big_memo_ptr: AtomicPtr::new(core::ptr::null_mut()),
            inode_ptr: AtomicPtr::new(core::ptr::null_mut()),
        }
    }

    /// (negative-lookup memo) The generation this negative child was
    /// stamped with at insert time.
    #[inline]
    pub fn neg_gen_load(&self) -> u64 {
        self.neg_gen.load(Ordering::Acquire)
    }

    /// Cap on negative memo children per parent. The OH boot's probe
    /// storm targets a small fixed name set per directory (dozens at
    /// most); 32 pins the working set while bounding the heap cost that
    /// made uncached negatives a leak (one Dentry + String per ENOENT,
    /// inode02's ALLOCTHROW family).
    pub const NEG_MEMO_CAP: usize = 32;

    /// (negative-lookup memo) Insert a NEGATIVE child for `name` — an
    /// ext4 ENOENT this walk just paid the full directory scan for.
    /// Bounded: at the cap, one existing negative child is evicted
    /// (FIFO-by-name is not needed; any eviction keeps the bound, and a
    /// later probe of the evicted name re-inserts it). A positive child
    /// (or a fresher racer's insert) is never replaced. Call only for
    /// filesystems whose content changes exclusively through VFS
    /// mutations (ext4) — dynamic filesystems (procfs/devfs/sysfs)
    /// change without them and must never memo.
    pub fn memo_negative(self: &Arc<Self>, name: &str, parent_gen: u64) {
        let mut guard = self.children.lock();
        if let Some(existing) = guard.get(name) {
            if existing.is_negative() {
                // Refresh the stamp so a mutation that happened between
                // our miss and this insert does not doom the memo.
                existing.neg_gen.store(parent_gen, Ordering::Release);
            }
            // Positive child: the file exists — nothing to memo.
            return;
        }
        if self.neg_count.load(Ordering::Acquire) >= Self::NEG_MEMO_CAP {
            // Evict one negative child (first found) to keep the bound.
            let victim = guard
                .iter()
                .find(|(_, v)| v.is_negative())
                .map(|(k, _)| k.clone());
            match victim {
                Some(v) => {
                    guard.remove(&v);
                    self.neg_count.fetch_sub(1, Ordering::AcqRel);
                    // (gap-fs lane) map mutation — retire memo slots
                    // stamped with the older version.
                    self.children_ver.fetch_add(1, Ordering::Release);
                }
                None => {
                    // Counter drift (evictions raced): cap refused this
                    // insert; the next probe re-runs the fs lookup.
                    self.neg_count
                        .store(0, Ordering::Release);
                    return;
                }
            }
        }
        let d = Arc::new(Dentry::new(alloc::string::String::from(name)));
        d.set_parent(self.clone());
        d.negative.store(true, Ordering::Release);
        d.neg_gen.store(parent_gen, Ordering::Release);
        guard.insert(alloc::string::String::from(name), d);
        // (stat-2x lane) negative children count toward the big-table
        // threshold — their lookups should ride the tier-2 memo too.
        self.big_memo_ensure_locked(&mut guard);
        self.neg_count.fetch_add(1, Ordering::AcqRel);
        // (gap-fs lane) map mutation — invalidate memo slots stamped
        // with the older version (a slot could otherwise keep serving a
        // hit for a name whose map entry changed under it).
        self.children_ver.fetch_add(1, Ordering::Release);
    }

    /// Set parent directory entry
    pub fn set_parent(&self, parent: Arc<Dentry>) {
        *self.parent.lock() = Some(parent);
    }

    /// Set inode
    pub fn set_inode(&self, inode: Arc<Inode>) {
        let old = {
            let mut slot = self.inode.lock();
            // Publish the mirror first: a concurrent banked reader sees
            // either the old pointer (kept alive by the slot until the
            // replace below, then by its retire until the drain) or the
            // new one (held by the slot) — both valid under the claim.
            self.inode_ptr
                .store(Arc::as_ptr(&inode) as *mut Inode, Ordering::Release);
            slot.replace(inode)
        };
        // (perf-path lane) stamp the icache generation this Arc was made
        // current at — see inode_gen.
        self.inode_gen
            .store(self::icache_regen(), Ordering::Relaxed);
        if let Some(old) = old {
            retire_inode_arc(old);
            dentry_drain_if_quiescent(true);
        }
    }

    /// (gap-fs lane) Drop the dentry's inode (unlink/rmdir/rename kill
    /// the cached entry). Publishes the null mirror and parks the old
    /// Arc for a reader-quiescent drain — replaces the direct
    /// `*inode.lock() = None` writes, which a banked reader of the old
    /// pointer could not be protected from.
    pub fn clear_inode(&self) {
        let old = {
            let mut slot = self.inode.lock();
            self.inode_ptr.store(core::ptr::null_mut(), Ordering::Release);
            slot.take()
        };
        if let Some(old) = old {
            retire_inode_arc(old);
            dentry_drain_if_quiescent(true);
        }
    }

    /// The current inode as a raw pointer, for callers holding a
    /// WalkClaim (see the reader-bank protocol comment): the object
    /// stays alive while the claim is held (the inode slot or a pending
    /// retire owns it). Null when the dentry has no inode.
    pub fn inode_ptr_walk(&self, _claim: &WalkClaim) -> *const Inode {
        self.inode_ptr.load(Ordering::Acquire)
    }

    /// Lock-free inode read for standalone callers: claim, load the
    /// mirror, take a strong reference, release.
    pub fn get_inode_fast(&self) -> Option<Arc<Inode>> {
        let claim = WalkClaim::acquire();
        let p = self.inode_ptr.load(Ordering::Acquire);
        let out = if p.is_null() {
            None
        } else {
            // SAFETY: p is non-null and kept alive by the inode slot or
            // its pending retire; our claim blocks the drain.
            Some(unsafe { inode_arc_from_raw(p) })
        };
        drop(claim);
        out
    }

    /// The icache generation `inode` was last refreshed at (see inode_gen).
    pub fn get_inode_gen(&self) -> u64 {
        self.inode_gen.load(Ordering::Relaxed)
    }

    /// (perf-path lane) Stamp the icache generation without touching the
    /// inode slot (the walk's refreshed-with-same-Arc case).
    pub fn set_inode_gen(&self, gen: u64) {
        self.inode_gen.store(gen, Ordering::Relaxed);
    }

    /// Get inode
    pub fn get_inode(&self) -> Option<Arc<Inode>> {
        self.inode.lock().clone()
    }

    /// Get name
    pub fn get_name(&self) -> String {
        self.name.lock().clone()
    }

    /// Build full path from root by walking parent chain
    pub fn build_path(&self) -> alloc::string::String {
        // The global climb can never fail (it terminates at the global
        // root); the Option only exists for the rooted variant below.
        self.build_path_rooted(None)
            .unwrap_or_else(|| alloc::string::String::from("/"))
    }

    /// Build the path of `self` the way Linux prepend_path() does: the
    /// climb stops at `stop` — the dentry treated as the process root —
    /// instead of the global root, so the result is ROOT-RELATIVE (after
    /// chroot("/usr") the "/usr/bin" dentry reports "/bin").
    ///
    /// Returns None when the climb reaches the global root without passing
    /// through `stop` — the path is not reachable under that root. getcwd
    /// translates this to ENOENT (Linux behavior for a cwd outside the
    /// process root); display-only callers may fall back to the global
    /// path.
    ///
    /// `stop = None` is the plain global path: same walk, same
    /// mount-boundary crossing as build_path() (a mount root climbs from
    /// its mountpoint so entries inside a mount carry the mountpoint
    /// prefix — chdir("/proc") must store cwd="/proc", not "/").
    pub fn build_path_rooted(
        &self,
        stop: Option<&Arc<Dentry>>,
    ) -> Option<alloc::string::String> {
        let mut components: alloc::vec::Vec<alloc::string::String> = alloc::vec::Vec::new();
        let name = self.get_name();
        // Limit depth to prevent infinite loops on corrupted dentry trees.
        // 256 (review 5.1: build_path>64 截断 — deep trees silently got
        // truncated paths, breaking /proc/self/fd links and getcwd).
        let max_depth = 256;
        // `self` IS the process root: the rooted path is "/".
        if let Some(s) = stop {
            if core::ptr::eq(self, s.as_ref()) {
                return Some(alloc::string::String::from("/"));
            }
        }
        // A mounted filesystem's root dentry has NO parent pointer; the
        // climb starts at (or continues into) the MOUNTPOINT dentry in the
        // parent filesystem instead, so paths of entries inside a mount
        // carry the mountpoint prefix. Without this hop, build_path() on
        // the procfs root returned "/" and chdir("/proc") silently stored
        // cwd="/" — cd appeared to have no effect (pwd and ls still saw /).
        let mut current: Option<Arc<Dentry>> = match self.parent.lock().clone() {
            Some(p) => Some(p),
            // `self` is a filesystem root; a mount root climbs from its
            // mountpoint, the global root contributes nothing.
            None => self.mountpoint_dentry(),
        };
        while let Some(d) = current {
            if components.len() >= max_depth {
                break;
            }
            // Arrived at the process root: stop here — everything collected
            // so far is the path BELOW the root.
            if let Some(s) = stop {
                if core::ptr::eq(d.as_ref(), s.as_ref()) {
                    break;
                }
            }
            let parent = d.parent.lock().clone();
            match parent {
                Some(p) => {
                    components.push(d.get_name());
                    current = Some(p);
                }
                None => {
                    // Reached a filesystem root. Its name is "/" — pushing
                    // it as a COMPONENT made the join below emit "//tmp/..."
                    // (a leading double slash) for every absolute path.
                    // Callers that string-compare results (LTP getcwd01,
                    // symlink01 chdir01 vs getcwd) need the canonical
                    // single-slash form, so the root contributes the leading
                    // '/', not a component. A MOUNT root instead crosses
                    // into the parent filesystem at its mountpoint (stacked
                    // mounts resolve one hop per loop iteration); the
                    // mountpoint's own name is pushed on the next iteration.
                    match d.mountpoint_dentry() {
                        Some(mp) => current = Some(mp),
                        // The global (or a detached) filesystem root: with a
                        // stop requested we never met the process root, so
                        // `self` is NOT under it (Linux: unreachable).
                        None => {
                            if stop.is_some() {
                                return None;
                            }
                            break;
                        }
                    }
                }
            }
        }
        components.reverse();
        // Build path — absolute: "/" + root-to-leaf components.
        let mut path = alloc::string::String::from("/");
        for comp in &components {
            if path != "/" {
                path.push('/');
            }
            path.push_str(comp);
        }
        if !name.is_empty() && name != "/" {
            if path != "/" {
                path.push('/');
            }
            path.push_str(&name);
        }
        Some(path)
    }

    /// Look up a child dentry by name. Returns None if not found.
    pub fn lookup_child(&self, name: &str) -> Option<Arc<Dentry>> {
        self.children.lock().get(name).cloned()
    }

    /// (gap-fs lane) Lock-free child lookup for the path walk. Returns
    /// the child as a RAW pointer valid only while `claim` is held (the
    /// child map — or the removed child's pending retire — owns it; the
    /// claim blocks the drain). Callers that need the reference beyond
    /// the claim must `dentry_arc_from_raw` it first.
    ///
    /// Memo hit path: version check + per-slot seqlock pair + one name
    /// compare — no lock, no refcount traffic. Miss path: the locked
    /// BTreeMap lookup, refilling the memo slot (serialized by the
    /// children lock) so the next walk of the same component rides the
    /// memo.
    ///
    /// (stat-2x lane) Two lock-free tiers before the lock: the inline
    /// 4-slot memo (small directories), then the lazily allocated big
    /// table (CHILD_MEMO_BIG_SLOTS seqlock slots for directories past
    /// CHILD_MEMO_BIG_MIN children — the inline memo thrashes there and
    /// every lookup used to pay the spinlock + BTreeMap walk).
    pub fn lookup_child_walk(
        &self,
        claim: &WalkClaim,
        name: &str,
    ) -> Option<*const Dentry> {
        if name.len() > CHILD_MEMO_NAME_MAX {
            // Long names can't ride the memo. Locked lookup (the
            // children lock serializes with every retire); the returned
            // Arc's map reference keeps the child alive under the claim
            // after our clone drops.
            let c = self.lookup_child(name)?;
            return Some(Arc::as_ptr(&c));
        }
        let bytes = name.as_bytes();
        let h = child_name_hash(bytes);
        let ver = self.children_ver.load(Ordering::Relaxed);
        // Tier 1: inline memo.
        {
            let slot = &self.memo[(h as usize) & CHILD_MEMO_MASK];
            if let Some(p) = memo_slot_read(slot, ver, h, bytes) {
                return Some(p);
            }
        }
        // Tier 2: big memo (large directories).
        let big = self.big_memo_ptr.load(Ordering::Acquire);
        if !big.is_null() {
            // SAFETY: published under the children lock with a Release
            // store; the table stays alive through the ownership slot or
            // the DENTRY_RET_MEMO park, and our walk claim blocks the
            // drain that would free it. `nslots` is immutable after
            // construction, so the base pointer alone yields a
            // consistent (slots, len) pair even across a concurrent grow.
            let table: &BigMemoTable = unsafe { &*big };
            let n = table.nslots;
            let slot = &table.slots[(h as usize) & (n - 1)];
            if let Some(p) = memo_slot_read(slot, ver, h, bytes) {
                return Some(p);
            }
        }
        // Tier 3: locked map lookup + refill both tiers.
        let child = {
            let mut guard = self.children.lock();
            let c = guard.get(name).cloned();
            if let Some(ref c) = c {
                self.big_memo_ensure_locked(&mut guard);
                self.refill_memo_locked(name, c);
            }
            c
        };
        child.map(|c| Arc::as_ptr(&c))
    }

    /// Lock-free child read for standalone callers: claim, memo/locked
    /// lookup, take a strong reference, release.
    pub fn lookup_child_fast(&self, name: &str) -> Option<Arc<Dentry>> {
        let claim = WalkClaim::acquire();
        let out = match self.lookup_child_walk(&claim, name) {
            Some(p) => {
                // SAFETY: loaded under the claim; see the protocol.
                Some(unsafe { dentry_arc_from_raw(p) })
            }
            None => None,
        };
        drop(claim);
        out
    }

    /// Refill a memo slot — called with the CHILDREN LOCK HELD (all
    /// refills and all `children_ver` bumps are serialized by it), so
    /// the plain-field writes race only readers, which the per-slot
    /// seqlock guards. (stat-2x lane) Refills BOTH tiers: the inline
    /// slot and, when the big table exists, its slot for this name.
    fn refill_memo_locked(&self, name: &str, child: &Arc<Dentry>) {
        if name.len() > CHILD_MEMO_NAME_MAX {
            return;
        }
        let ver = self.children_ver.load(Ordering::Relaxed);
        let h = child_name_hash(name.as_bytes());
        let slot = &self.memo[(h as usize) & CHILD_MEMO_MASK];
        // A fill that already matches the current version wins (another
        // CPU refilled between our miss and taking the lock).
        {
            // SAFETY: children lock held — all refills serialize here.
            let cur = unsafe { &*slot.data.get() };
            if cur.ver == ver && cur.hash == h && !cur.child.is_null() {
                return;
            }
        }
        let s = slot.seq.load(Ordering::Relaxed);
        slot.seq.store(s | 1, Ordering::Release); // odd — enter write
        // SAFETY: children lock held (serializes writers); racing
        // readers are guarded by the seqlock.
        {
            let d = unsafe { &mut *slot.data.get() };
            d.ver = ver;
            d.hash = h;
            d.name_len = name.len() as u8;
            d.name[..name.len()].copy_from_slice(name.as_bytes());
            d.child = Arc::as_ptr(child);
        }
        slot.seq.store((s | 1) + 1, Ordering::Release); // even — leave

        // Tier-2 refill (same discipline; only when the table exists).
        // The table base loaded here is the one the lock-free reader may
        // have raced onto — both are kept alive (ownership slot / park).
        let big = self.big_memo_ptr.load(Ordering::Relaxed);
        if !big.is_null() {
            // SAFETY: published table (children lock held here
            // serializes this writer against every other refill);
            // `nslots` immutable after construction.
            let table: &BigMemoTable = unsafe { &*big };
            let n = table.nslots;
            let bslot = &table.slots[(h as usize) & (n - 1)];
            // Same already-filled short-circuit as the inline slot.
            {
                // SAFETY: children lock held — all refills serialize.
                let cur = unsafe { &*bslot.data.get() };
                if cur.ver == ver && cur.hash == h && !cur.child.is_null() {
                    return;
                }
            }
            let s = bslot.seq.load(Ordering::Relaxed);
            bslot.seq.store(s | 1, Ordering::Release); // odd — enter write
            // SAFETY: children lock held; seqlock guards racing readers.
            {
                let d = unsafe { &mut *bslot.data.get() };
                d.ver = ver;
                d.hash = h;
                d.name_len = name.len() as u8;
                d.name[..name.len()].copy_from_slice(name.as_bytes());
                d.child = Arc::as_ptr(child);
            }
            bslot.seq.store((s | 1) + 1, Ordering::Release); // even — leave
        }
    }

    /// (stat-2x lane) Grow (or first-allocate) the secondary memo when
    /// the children map has outgrown the inline memo's range AND the
    /// current table. Called with the CHILDREN LOCK HELD (add_child,
    /// memo_negative, and the locked lookup fallback). Sizing:
    /// next_pow2(2 × live children), clamped — a direct-mapped table
    /// with fewer slots than the live name population thrashes to a
    /// ~0% hit rate (measured: 128 slots vs a cycling 1000-name tree).
    /// A replaced table is parked for the reader-quiescent drain (a
    /// banked reader may still hold the old base pointer mid-read).
    fn big_memo_ensure_locked(
        &self,
        guard: &mut crate::sync::spinlock::SpinlockGuard<'_, BTreeMap<String, Arc<Dentry>>>,
    ) {
        if guard.len() < CHILD_MEMO_BIG_MIN {
            return;
        }
        let want = (guard.len().saturating_mul(2))
            .next_power_of_two()
            .clamp(CHILD_MEMO_BIG_MIN_SLOTS, CHILD_MEMO_BIG_MAX_SLOTS);
        let cur = self
            .big_memo_ptr
            .load(Ordering::Relaxed);
        let cur_slots = if cur.is_null() {
            0
        } else {
            // SAFETY: published table pointer (children lock held here,
            // and the pointer only changes under this lock); nslots is
            // immutable after construction.
            unsafe { (*cur).nslots }
        };
        if want <= cur_slots {
            return;
        }
        let slots: alloc::vec::Vec<ChildMemoSlot> = (0..want)
            .map(|_| ChildMemoSlot::empty())
            .collect();
        let table = alloc::boxed::Box::new(BigMemoTable { nslots: want, slots });
        // Swap ownership, then publish the base with Release: a reader
        // that Acquire-loads this pointer sees the fully-initialized,
        // self-consistent table.
        // SAFETY: children lock held — this cell's only writers are
        // here and the final Dentry drop (post-quiescence); lock-free
        // readers never touch the ownership cell.
        let old = unsafe { (*self.big_memo.get()).replace(table) };
        let base = match unsafe { &*self.big_memo.get() } {
            Some(b) => &**b as *const BigMemoTable as *mut BigMemoTable,
            None => return,
        };
        self.big_memo_ptr.store(base, Ordering::Release);
        if let Some(old) = old {
            // The OLD base may still be loaded under banked walk claims:
            // park it like a retired dentry; the quiescent drain frees it.
            DENTRY_RET_MEMO.lock_irqsave().push(old);
            dentry_drain_if_quiescent(true);
        }
    }

    /// Add a child dentry. If a child with the same name exists, it is replaced.
    pub fn add_child(&self, name: String, child: Arc<Dentry>) {
        // lb-lane hunt (OH /storage invisibility): pid 1's early tmpfs
        // mounts (/mnt, /mnt/data, /storage — mounted rc=0 at ~1.2 s) are
        // invisible to pid 1 itself by 4.8 s (mkdir under /mnt -> EROFS,
        // mkdir /storage/media -> ENOENT, kernel-confirmed), while later
        // block mounts stay visible. add_child REPLACES a same-name child
        // — if anything re-creates a dentry whose predecessor carried a
        // mount, the replacement has none and every later walk loses the
        // mount. Ring exactly that case.
        {
            let guard = self.children.lock();
            if let Some(old) = guard.get(&name) {
                if old.vfsmount.lock().is_some() && child.vfsmount.lock().is_none() {
                    static DUPMNT_N: core::sync::atomic::AtomicUsize =
                        core::sync::atomic::AtomicUsize::new(0);
                    if DUPMNT_N.fetch_add(1, core::sync::atomic::Ordering::Relaxed) < 40 {
                        let pname = self.name.lock().clone();
                        crate::pr_warn!(
                            "DUPMNT-REPLACE parent='{}' name='{}' (pid {})",
                            pname,
                            name,
                            crate::process::current_pid()
                        );
                    }
                }
            }
        }
        let old = {
            let mut guard = self.children.lock();
            // (stat-2x lane) grow the secondary memo when the directory
            // crosses the big-table threshold (see big_memo_ensure_locked).
            self.big_memo_ensure_locked(&mut guard);
            guard.insert(name, child)
        };
        // (gap-fs lane) Invalidate memo slots stamped with the old
        // version, then park a displaced child for a reader-quiescent
        // drain (a banked reader may still hold its raw pointer).
        self.children_ver.fetch_add(1, Ordering::Release);
        if let Some(old) = old {
            retire_dentry_arc(old);
            dentry_drain_if_quiescent(true);
        }
    }

    /// Remove a child dentry by name.
    pub fn remove_child(&self, name: &str) {
        let old = {
            let mut guard = self.children.lock();
            let removed = guard.remove(name);
            if let Some(ref removed) = removed {
                // Keep the negative-memo bound honest: a detached
                // negative child (stale-memo discard, mutation
                // maintenance) frees its slot.
                if removed.is_negative() {
                    let was = self.neg_count.fetch_sub(1, Ordering::AcqRel);
                    if was == 0 {
                        // Counter underflow race — clamp.
                        self.neg_count.store(0, Ordering::Release);
                    }
                }
            }
            removed
        };
        // (gap-fs lane) Invalidate memo slots stamped with the old
        // version, then park the removed child for a reader-quiescent
        // drain (a banked reader may still hold its raw pointer).
        self.children_ver.fetch_add(1, Ordering::Release);
        if let Some(old) = old {
            retire_dentry_arc(old);
            dentry_drain_if_quiescent(true);
        }
    }

    /// Drop every cached child (mount(2) MS_MOVE onto "/": the old root's
    /// cached ramdisk names must not shadow the moved-in filesystem's
    /// root — lookups fall back to the new root inode's directory ops).
    pub fn clear_children(&self) {
        let old: Vec<Arc<Dentry>> = {
            let mut guard = self.children.lock();
            core::mem::take(&mut *guard).into_values().collect()
        };
        self.neg_count.store(0, Ordering::Release);
        self.children_ver.fetch_add(1, Ordering::Release);
        for c in old {
            retire_dentry_arc(c);
        }
        if !DENTRY_RET_DENTRY.lock_irqsave().is_empty() {
            dentry_drain_if_quiescent(true);
        }
    }

    /// Move every cached child of `self` into `into` (re-parenting them).
    /// mount(2) MS_MOVE onto "/": the mounts the userspace switcher
    /// attached UNDER the moved root (/proc, /dev, ... — children of the
    /// moved mount's root dentry) must survive the root dentry swap, or
    /// the new root loses its /proc and /dev entirely.
    pub fn rehome_children_into(&self, into: &Arc<Dentry>) {
        let moving: Vec<(String, Arc<Dentry>)> = self.children.lock().iter().map(|(k, v)| {
            (k.clone(), v.clone())
        }).collect();
        {
            let mut guard = self.children.lock();
            guard.clear();
        }
        self.children_ver.fetch_add(1, Ordering::Release);
        for (name, child) in moving {
            child.set_parent(into.clone());
            into.add_child(name, child.clone());
            // (gap-fs lane) Our clone drops here — if it was the last
            // live reference (no new-parent map entry, e.g. a racing
            // displacement), the free must wait out banked readers, so
            // park it like every other detached child.
            retire_dentry_arc(child);
        }
        if !DENTRY_RET_DENTRY.lock_irqsave().is_empty() {
            dentry_drain_if_quiescent(true);
        }
    }

    /// Detach the mount descriptor (mount(2) MS_MOVE source side and
    /// umount(2)). Also forgets the mounted root's mountpoint
    /// back-pointer so a detached mount's root stops claiming a
    /// mountpoint it no longer occupies.
    pub fn clear_mount(&self) {
        let mnt = self.vfsmount.lock().take();
        self.is_mountpoint.store(false, Ordering::Release);
        if let Some(mnt) = mnt {
            mnt.root.clear_mountpoint_back();
        }
    }

    /// (perf-path lane) Take the mount descriptor out and update the
    /// presence mirror — for teardown paths that handle the mountpoint
    /// back-reference themselves (identical to clear_mount otherwise).
    pub fn take_mount(&self) -> Option<Arc<VfsMountInternal>> {
        let mnt = self.vfsmount.lock().take();
        self.is_mountpoint.store(mnt.is_some(), Ordering::Release);
        mnt
    }

    /// Set the mount descriptor (marks this dentry as a mount point).
    pub fn set_mount(&self, mount: Arc<VfsMountInternal>) {
        *self.vfsmount.lock() = Some(mount);
        self.is_mountpoint.store(true, Ordering::Release);
    }

    /// Get the mount descriptor (if this is a mount point).
    pub fn get_mount(&self) -> Option<Arc<VfsMountInternal>> {
        self.vfsmount.lock().clone()
    }

    /// (perf-path lane) Lock-free mount-point presence test — the
    /// authoritative field stays `vfsmount` (set_mount/clear_mount keep
    /// this mirror in step; flag first, descriptor second on set;
    /// descriptor first, flag second on clear — a transient mismatch is
    /// impossible to observe worse than taking the slow lock path).
    pub fn has_mount(&self) -> bool {
        self.is_mountpoint.load(Ordering::Acquire)
    }

    /// (perf-path lane) Presence-mirror writer for teardown paths that
    /// mutate `vfsmount` under its own lock (see vfs_umount_object).
    pub fn set_mount_flag(&self, on: bool) {
        self.is_mountpoint.store(on, Ordering::Release);
    }

    /// Record the mountpoint dentry on a mounted filesystem's ROOT dentry
    /// (the reverse edge of `set_mount`'s mountpoint→root link, held Weak
    /// to avoid an Arc cycle). Set by vfs_mount()/vfs_move_mount().
    pub fn set_mountpoint_back(&self, mountpoint: Arc<Dentry>) {
        *self.mountpoint.lock() = Some(Arc::downgrade(&mountpoint));
    }

    /// The mountpoint this fs-root dentry is mounted on, if any (see
    /// set_mountpoint_back). Used by ancestry walks that must cross mount
    /// boundaries upward (MS_REC bind cloning).
    pub fn get_mountpoint_back(&self) -> Option<Arc<Dentry>> {
        self.mountpoint.lock().as_ref().and_then(|w| w.upgrade())
    }

    /// Forget the mountpoint back-pointer (mount detached/moved away).
    pub fn clear_mountpoint_back(&self) {
        *self.mountpoint.lock() = None;
    }

    /// The mountpoint dentry this filesystem root is mounted at, if this
    /// is a mounted root and the mountpoint dentry is still alive.
    pub fn mountpoint_dentry(&self) -> Option<Arc<Dentry>> {
        self.mountpoint.lock().as_ref().and_then(|w| w.upgrade())
    }

    /// Set to hashed state
    pub fn set_hashed(&self) {
        let mut flags = self.flags.lock();
        *flags = DentryFlags::new(flags.bits() | DentryFlags::DCACHE_HASHED);
        *self.state.lock() = DentryState::DHashed;
    }

    /// Set to unhashed state
    pub fn set_unhashed(&self) {
        let mut flags = self.flags.lock();
        *flags = DentryFlags::new(flags.bits() | DentryFlags::DCACHE_UNHASHED);
        *self.state.lock() = DentryState::DUnhashed;
    }

    /// Increment reference count
    pub fn inc_ref(&self) {
        self.ref_count.fetch_add(1, Ordering::AcqRel);
    }

    /// Decrement reference count
    pub fn dec_ref(&self) -> u64 {
        self.ref_count.fetch_sub(1, Ordering::AcqRel) - 1
    }

    /// Get reference count
    pub fn get_ref(&self) -> u64 {
        self.ref_count.load(Ordering::Acquire)
    }

    /// Mark as negative dentry (lookup found no file)
    pub fn set_negative(&self) {
        self.negative.store(true, Ordering::Release);
    }

    /// Check if this is a negative dentry
    pub fn is_negative(&self) -> bool {
        self.negative.load(Ordering::Acquire)
    }

    /// Clear negative flag (e.g. after file creation)
    pub fn clear_negative(&self) {
        self.negative.store(false, Ordering::Release);
    }
}

/// Create root directory entry
pub fn make_root_dentry() -> Option<Arc<Dentry>> {
    let dentry = Arc::new(Dentry::new("/".to_owned()));
    // Note: Arc returns &T when dereferenced
    // For now, we'll return the Arc directly - the caller can call set_hashed if needed
    Some(dentry)
}

// ============================================================================
// Dentry cache (dcache)
// ============================================================================

/// Dentry cache size - from config
const DCACHE_SIZE: usize = crate::config::DCACHE_SIZE;

impl DentryCacheStats {
    pub fn new() -> Self {
        Self {
            hits: AtomicU64::new(0),
            misses: AtomicU64::new(0),
            evictions: AtomicU64::new(0),
        }
    }

    pub fn record_hit(&self) {
        self.hits.fetch_add(1, Ordering::Relaxed);
    }

    pub fn record_miss(&self) {
        self.misses.fetch_add(1, Ordering::Relaxed);
    }

    pub fn record_eviction(&self) {
        self.evictions.fetch_add(1, Ordering::Relaxed);
    }

    pub fn get_hit_rate(&self) -> f64 {
        let hits = self.hits.load(Ordering::Relaxed);
        let misses = self.misses.load(Ordering::Relaxed);
        let total = hits + misses;
        if total == 0 {
            0.0
        } else {
            (hits as f64) / (total as f64)
        }
    }
}

impl Clone for DentryHashBucket {
    fn clone(&self) -> Self {
        Self {
            dentry: self.dentry.clone(),
            key: self.key,
            parent_ino: self.parent_ino,
            access_time: AtomicU64::new(self.access_time.load(Ordering::Relaxed)),
        }
    }
}

unsafe impl Send for DentryCache {}
unsafe impl Sync for DentryCache {}

/// Global Dentry cache
static DCACHE: Spinlock<Option<DentryCache>> = Spinlock::new(None);

/// Initialize Dentry cache
fn dcache_init() {
    let mut cache = DCACHE.lock();
    if cache.is_some() {
        return;  // Already initialized
    }

    // Heap-allocate bucket array to avoid large stack allocation
    let buckets: alloc::vec::Vec<DentryHashBucket> = (0..DCACHE_SIZE)
        .map(|_| DentryHashBucket {
            dentry: None,
            key: 0,
            parent_ino: 0,
            access_time: AtomicU64::new(0),
        })
        .collect();

    *cache = Some(DentryCache {
        buckets: buckets.into_boxed_slice(),
        count: 0,
        global_time: AtomicU64::new(1),
        stats: DentryCacheStats::new(),
    });
}

/// Calculate hash value
///
/// Uses simple FNV-1a hash algorithm
fn dentry_hash(name: &str, parent_ino: u64) -> u64 {
    let mut hash = 0xcbf29ce484222325_u64;  // FNV offset basis

    // Mix parent inode number
    hash ^= parent_ino;
    hash = hash.wrapping_mul(0x100000001b3);

    // Mix name
    for byte in name.bytes() {
        hash ^= byte as u64;
        hash = hash.wrapping_mul(0x100000001b3);
    }

    hash
}

/// Look up in Dentry cache
///
pub fn dcache_lookup(name: &str, parent_ino: u64) -> Option<Arc<Dentry>> {
    // Ensure cache is initialized
    dcache_init();

    let mut cache = DCACHE.lock();
    let cache_inner = cache.as_mut()?;

    // Calculate hash value
    let hash = dentry_hash(name, parent_ino);
    let index = (hash as usize) % DCACHE_SIZE;

    // Find matching entry
    let bucket = &cache_inner.buckets[index];

    if let Some(ref dentry) = bucket.dentry {
        // Compare hash key and parent_ino to avoid false cache hits on collision
        if bucket.key == hash && bucket.parent_ino == parent_ino {
            // Compare name
            if dentry.name.lock().as_str() == name {
                // Update access time (for LRU)
                let current_time = cache_inner.global_time.fetch_add(1, Ordering::Relaxed);
                bucket.access_time.store(current_time, Ordering::Relaxed);

                // Record hit
                cache_inner.stats.record_hit();

                return Some(dentry.clone());
            }
        }
    }

    // Record miss
    cache_inner.stats.record_miss();

    None
}

/// Add Dentry to cache
///
pub fn dcache_add(dentry: Arc<Dentry>, parent_ino: u64) {
    // Ensure cache is initialized
    dcache_init();

    // Calculate hash value (outside cache lock)
    let name = dentry.name.lock();
    let name_str = name.clone();
    drop(name);  // Release name lock
    let hash = dentry_hash(&name_str, parent_ino);

    let mut cache = DCACHE.lock();
    let inner = cache.as_mut().expect("dcache not initialized");

    let index = (hash as usize) % DCACHE_SIZE;

    // Check if already exists
    if let Some(ref _existing) = inner.buckets[index].dentry {
        if inner.buckets[index].key == hash {
            return;  // Already in cache
        }

        // Use LRU policy: find and evict least recently used entry
        dcache_evict_lru(inner);
    }

    // Get current timestamp
    let current_time = inner.global_time.fetch_add(1, Ordering::Relaxed);

    // Add to cache (only increment count when the bucket was previously empty)
    let was_empty = inner.buckets[index].dentry.is_none();
    inner.buckets[index] = DentryHashBucket {
        dentry: Some(dentry.clone()),
        key: hash,
        parent_ino,
        access_time: AtomicU64::new(current_time),
    };
    if was_empty {
        inner.count += 1;
    }

    // Mark as hashed (outside cache lock)
    drop(cache);  // Release cache lock
    dentry.set_hashed();
}

/// LRU eviction policy: evict least recently used entry
///
fn dcache_evict_lru(cache: &mut DentryCache) {
    // Find least recently used entry (minimum access time)
    let mut lru_index = 0;
    let mut lru_time = u64::MAX;
    let mut found = false;

    for (i, bucket) in cache.buckets.iter().enumerate() {
        if bucket.dentry.is_some() {
            let access_time = bucket.access_time.load(Ordering::Relaxed);
            if access_time < lru_time {
                lru_time = access_time;
                lru_index = i;
                found = true;
            }
        }
    }

    // Evict LRU entry
    if found {
        if let Some(ref dentry) = cache.buckets[lru_index].dentry {
            // Mark as unhashed
            dentry.set_unhashed();
        }

        cache.buckets[lru_index].dentry = None;
        cache.buckets[lru_index].key = 0;
        cache.buckets[lru_index].parent_ino = 0;
        cache.buckets[lru_index].access_time.store(0, Ordering::Relaxed);
        cache.count -= 1;

        // Record eviction
        cache.stats.record_eviction();
    }
}

/// Remove from Dentry cache
///
pub fn dcache_remove(name: &str, parent_ino: u64) {
    // Ensure cache is initialized
    dcache_init();

    let mut cache = DCACHE.lock();
    let inner = cache.as_mut().expect("dcache not initialized");

    // Calculate hash value
    let hash = dentry_hash(name, parent_ino);
    let index = (hash as usize) % DCACHE_SIZE;

    // Remove entry
    if let Some(ref dentry) = inner.buckets[index].dentry {
        if inner.buckets[index].key == hash {
            // Mark as unhashed
            dentry.set_unhashed();

            // Remove from cache
            inner.buckets[index].dentry = None;
            inner.buckets[index].key = 0;
            inner.buckets[index].access_time.store(0, Ordering::Relaxed);
            inner.count -= 1;
        }
    }
}

/// Get cache statistics
pub fn dcache_stats() -> (usize, usize) {
    // Ensure cache is initialized
    dcache_init();

    let cache = DCACHE.lock();
    let cache_inner = cache.as_ref().expect("dcache not initialized");

    (cache_inner.count, DCACHE_SIZE)
}

/// Get detailed cache statistics
pub fn dcache_stats_detailed() -> (u64, u64, u64, f64) {
    // Ensure cache is initialized
    dcache_init();

    let cache = DCACHE.lock();
    let cache_inner = cache.as_ref().expect("dcache not initialized");

    (
        cache_inner.stats.hits.load(Ordering::Relaxed),
        cache_inner.stats.misses.load(Ordering::Relaxed),
        cache_inner.stats.evictions.load(Ordering::Relaxed),
        cache_inner.stats.get_hit_rate(),
    )
}

/// Clear Dentry cache
///
pub fn dcache_flush() {
    // Ensure cache is initialized
    dcache_init();

    let mut cache = DCACHE.lock();
    let inner = cache.as_mut().expect("dcache not initialized");

    // Clear all buckets
    for bucket in inner.buckets.iter_mut() {
        if let Some(ref dentry) = bucket.dentry {
            // Mark as unhashed
            dentry.set_unhashed();
        }
        bucket.dentry = None;
        bucket.key = 0;
        bucket.access_time.store(0, Ordering::Relaxed);
    }

    inner.count = 0;
}


// ════════════════ elf ═════════════════════════════════
// (was elf.rs)
// ELF File Format Parsing and Loading
//
//
// Supported ELF formats:
// - 64-bit ELF (ELF64)
// - Little Endian
// - Executable files (ET_EXEC)
// - Dynamic linker support (future)

pub const ELF_MAGIC: [u8; 4] = [0x7f, b'E', b'L', b'F'];


pub const PF_X: u32 = 0x1;  // Executable
pub const PF_W: u32 = 0x2;  // Writable
pub const PF_R: u32 = 0x4;  // Readable

/// PT_GNU_STACK (UAPI): stack permission request. PF_X in p_flags asks
/// for an executable stack (EXSTACK_ENABLE_X); any other value keeps the
/// secure NX default. A MISSING header also means NX on this port —
/// neither arch maps onto the reference's READ_IMPLIES_EXEC fallback
/// (that path exists for 32-bit x86 binaries only).
pub const PT_GNU_STACK: u32 = 0x6474_e551;

impl Elf64Ehdr {
    /// Parse ELF header from byte buffer
    pub fn from_bytes(data: &[u8]) -> Option<Elf64Ehdr> {
        // Check minimum length
        if data.len() < size_of::<Elf64Ehdr>() {
            return None;
        }

        // Check magic number
        if &data[0..4] != ELF_MAGIC {
            return None;
        }

        // Check if 64-bit ELF
        if data[4] != 2 {
            return None;
        }

        // Check if little endian
        if data[5] != 1 {
            return None;
        }

        // Check if ELF64 version
        if data[6] != 1 {
            return None;
        }

        // Program header entry size must be exactly sizeof(Elf64Phdr).
        // Every phdr copy path multiplies e_phoff arithmetic by this value;
        // a forged larger value would read past the file end into kernel
        // memory (review 2R.12).
        if u16::from_le_bytes([data[54], data[55]]) != size_of::<Elf64Phdr>() as u16 {
            return None;
        }

        // Check ABI (accept System V and GNU ABI)
        // data[7] = EI_OSABI:
        //   0 = ELFOSABI_NONE/ELFOSABI_SYSV
        //   3 = ELFOSABI_GNU
        if data[7] != 0 && data[7] != 3 {
            return None;
        }

        // The unaligned header read rides CopyBytes (INV-CBYTES-2).
        crate::safety::bytes::from_bytes::<Elf64Ehdr>(data)
    }

    /// Check if ELF type is executable (ET_EXEC or ET_DYN for shared objects/PIE)
    pub fn is_executable(&self) -> bool {
        self.e_type == ElfType::ET_EXEC as u16
            || self.e_type == ElfType::ET_DYN as u16
    }

    /// Check if ELF type is dynamic (shared object)
    pub fn is_dynamic(&self) -> bool {
        self.e_type == ElfType::ET_DYN as u16
    }

    /// Check if machine type matches the running architecture
    pub fn check_machine(&self) -> bool {
        #[cfg(feature = "riscv64")]
        {
            self.e_machine == ElfMachine::EM_RISCV as u16
        }
        #[cfg(feature = "x86_64")]
        {
            self.e_machine == ElfMachine::EM_X86_64 as u16
        }
        #[cfg(feature = "aarch64")]
        {
            self.e_machine == ElfMachine::EM_AARCH64 as u16
        }
    }

    /// Get program headers
    pub fn get_program_headers(&self, data: &[u8]) -> Result<usize, ElfError> {
        // Only return program header count, avoid heap allocation
        let phdr_end = (self.e_phoff as usize)
            .checked_add((self.e_phnum as usize).wrapping_mul(size_of::<Elf64Phdr>()))
            .filter(|&end| end <= data.len())
            .ok_or(ElfError::InvalidFormat)?;
        let _ = phdr_end; // used only for bounds validation
        Ok(self.e_phnum as usize)
    }

    /// Get single program header
    pub fn get_program_header(&self, data: &[u8], index: usize) -> Option<Elf64Phdr> {
        if index >= self.e_phnum as usize {
            return None;
        }
        // Bounds-check the entry against the file image: e_phoff comes from
        // the (possibly attacker-controlled) ELF header, so it must never be
        // trusted as a raw pointer offset.
        let phdr_off = (self.e_phoff as usize)
            .checked_add(index.checked_mul(size_of::<Elf64Phdr>())?)?;
        let phdr_end = phdr_off.checked_add(size_of::<Elf64Phdr>())?;
        if phdr_end > data.len() {
            return None;
        }
        // The unaligned entry read rides CopyBytes (INV-CBYTES-2).
        crate::safety::bytes::read_at::<Elf64Phdr>(data, phdr_off)
    }
}

impl Elf64Phdr {
    /// Check if segment is loadable
    pub fn is_load(&self) -> bool {
        self.p_type == ElfPtType::PT_LOAD as u32
    }

    /// Check if segment is readable
    pub fn is_readable(&self) -> bool {
        (self.p_flags & PF_R) != 0
    }

    /// Check if segment is writable
    pub fn is_writable(&self) -> bool {
        (self.p_flags & PF_W) != 0
    }

    /// Check if segment is executable
    pub fn is_executable(&self) -> bool {
        (self.p_flags & PF_X) != 0
    }
}

impl ElfLoader {
    /// Check if ELF file is valid
    pub fn validate(data: &[u8]) -> Result<(), ElfError> {
        if data.len() < size_of::<Elf64Ehdr>() {
            return Err(ElfError::InvalidFormat);
        }

        let ehdr = Elf64Ehdr::from_bytes(data)
            .ok_or(ElfError::InvalidHeader)?;

        if !ehdr.is_executable() {
            return Err(ElfError::NotExecutable);
        }

        // Machine check on every platform: a foreign-arch image must
        // fail here with ENOEXEC, never load-and-jump into garbage.
        // This guard was once cfg-limited to aarch64/riscv64 (written
        // before the x86_64 port), which let an x86_64 kernel exec a
        // riscv64 ELF straight through (review CR-2).
        if !ehdr.check_machine() {
            return Err(ElfError::WrongMachine);
        }

        Ok(())
    }

    /// Get entry point address
    pub fn get_entry(data: &[u8]) -> Result<u64, ElfError> {
        let ehdr = Elf64Ehdr::from_bytes(data)
            .ok_or(ElfError::InvalidHeader)?;
        Ok(ehdr.e_entry)
    }

    /// Get program headers
    pub fn get_program_headers(data: &[u8]) -> Result<usize, ElfError> {
        let ehdr = Elf64Ehdr::from_bytes(data)
            .ok_or(ElfError::InvalidHeader)?;
        ehdr.get_program_headers(data)
    }

    /// Load ELF file into memory
    ///
    ///
    /// # Arguments
    /// - `data`: ELF file data
    /// - `base_addr`: Load base address (user virtual address)
    ///
    /// # Returns
    /// Load info on success, error on failure
    pub fn load(data: &[u8], base_addr: u64) -> Result<ElfLoadInfo<'_>, ElfError> {
        // Validate ELF file
        Self::validate(data)?;

        let ehdr = Elf64Ehdr::from_bytes(data)
            .ok_or(ElfError::InvalidHeader)?;

        // Get program header count
        let phdr_count = Self::get_program_headers(data)?;

        let mut load_count = 0;
        let mut min_vaddr = u64::MAX;
        let mut max_vaddr = 0u64;
        let mut interp_path: Option<&[u8]> = None;

        // First pass: calculate address range
        for i in 0..phdr_count {
            if let Some(phdr) = ehdr.get_program_header(data, i) {
                if phdr.p_type == ElfPtType::PT_LOAD as u32 {
                    let vaddr = phdr.p_vaddr;
                    let memsz = phdr.p_memsz;

                    if vaddr < min_vaddr {
                        min_vaddr = vaddr;
                    }

                    let end = vaddr + memsz;
                    if end > max_vaddr {
                        max_vaddr = end;
                    }

                    load_count += 1;
                } else if phdr.p_type == ElfPtType::PT_INTERP as u32 {
                    // Extract interpreter path
                    let offset = phdr.p_offset as usize;
                    let size = phdr.p_filesz as usize;

                    if offset + size <= data.len() {
                        // Find null terminator
                        let mut len = 0;
                        for i in 0..size {
                            if data[offset + i] == 0 {
                                len = i;
                                break;
                            }
                        }

                        if len > 0 {
                            interp_path = Some(&data[offset..offset + len]);
                        }
                    }
                }
            }
        }

        if load_count == 0 {
            return Err(ElfError::NoLoadSegments);
        }

        // Second pass: actually load segments
        for i in 0..phdr_count {
            if let Some(phdr) = ehdr.get_program_header(data, i) {
                if phdr.p_type == ElfPtType::PT_LOAD as u32 {
                    Self::load_segment(data, &phdr, base_addr)?;
                }
            }
        }

        Ok(ElfLoadInfo {
            entry: ehdr.e_entry,
            load_count,
            min_vaddr,
            max_vaddr,
            interp_path,
        })
    }

    /// Load single PT_LOAD segment
    ///
    /// ...
    ///
    /// # Arguments
    /// - `data`: ELF file data
    /// - `phdr`: Program header
    /// - `base_addr`: Load base address
    fn load_segment(data: &[u8], phdr: &Elf64Phdr, base_addr: u64) -> Result<(), ElfError> {
        let offset = phdr.p_offset as usize;
        let filesz = phdr.p_filesz as usize;
        let memsz = phdr.p_memsz as usize;
        let vaddr = base_addr.checked_add(phdr.p_vaddr).ok_or(ElfError::InvalidSegment)?;

        // Check boundaries
        offset.checked_add(filesz).filter(|&end| end <= data.len())
            .ok_or(ElfError::InvalidSegment)?;

        // SAFETY: INV-ELF-SEG — vaddr..vaddr+memsz is the destination span
        // the caller's address-space setup mapped for this PT_LOAD (the
        // exec path maps before loading); the file span was bounds-checked
        // above.
        unsafe {
            // Copy segment data to memory
            if filesz > 0 {
                let src = data.as_ptr().add(offset);
                let dst = vaddr as *mut u8;
                core::ptr::copy_nonoverlapping(src, dst, filesz);
            }

            // Zero BSS segment (p_memsz > p_filesz portion)
            if memsz > filesz {
                let bss_start = vaddr.checked_add(filesz as u64).ok_or(ElfError::InvalidSegment)?;
                let bss_size = memsz - filesz;
                core::ptr::write_bytes(bss_start as *mut u8, 0, bss_size);
            }
        }

        Ok(())
    }

    /// Get interpreter path (if exists)
    pub fn get_interpreter(data: &[u8]) -> Option<&[u8]> {
        let ehdr = Elf64Ehdr::from_bytes(data)?;
        let phdr_count = Self::get_program_headers(data).ok()?;

        for i in 0..phdr_count {
            let phdr = ehdr.get_program_header(data, i)?;
            if phdr.p_type == ElfPtType::PT_INTERP as u32 {
                let offset = phdr.p_offset as usize;
                let size = phdr.p_filesz as usize;

                if offset + size <= data.len() {
                    // Find null terminator
                    let mut len = 0;
                    for i in 0..size {
                        if data[offset + i] == 0 {
                            len = i;
                            break;
                        }
                    }

                    if len > 0 {
                        return Some(&data[offset..offset + len]);
                    }
                }
            }
        }

        None
    }
}


// ════════════════ buffer ══════════════════════════════
// (was buffer.rs)
// Page Cache and data block management
//
//
// Core concepts:
// - `struct page`: Page, representing a memory page (typically 4KB)
// - `struct address_space`: Address space, managing all pages of a file
// - `struct buffer_head`: Buffer head, used for block I/O
//
// Simplified implementation: Uses simple byte buffers instead of full page cache

// (INV-BUFCHUNK-1: the chunked-buffer family — the from_bytes/new/
// read/write/resize rows are the CopyBytes-shaped POD views plus the
// chunk-table stores under the buffer's own lock.)

pub const PAGE_SIZE: usize = 4096;


impl Page {
    /// Create new page
    pub fn new() -> Self {
        let mut data = Vec::with_capacity(PAGE_SIZE);
        unsafe {
            core::ptr::write_bytes(data.as_mut_ptr(), 0, PAGE_SIZE);
            data.set_len(PAGE_SIZE);
        }
        Self {
            data,
            flags: AtomicUsize::new(0),
            ref_count: AtomicUsize::new(1),
        }
    }

    /// Create page from data
    pub fn from_bytes(bytes: &[u8]) -> Self {
        let mut data = Vec::with_capacity(PAGE_SIZE);
        unsafe {
            data.set_len(PAGE_SIZE);
        }
        let copy_len = core::cmp::min(bytes.len(), PAGE_SIZE);
        data[..copy_len].copy_from_slice(&bytes[..copy_len]);

        Self {
            data,
            flags: AtomicUsize::new(0),
            ref_count: AtomicUsize::new(1),
        }
    }

    /// Read page data
    pub fn read(&self, offset: usize, buf: &mut [u8]) -> usize {
        if offset >= PAGE_SIZE {
            return 0;
        }
        let available = PAGE_SIZE - offset;
        let to_read = core::cmp::min(buf.len(), available);
        buf[..to_read].copy_from_slice(&self.data[offset..offset + to_read]);
        to_read
    }

    /// Write page data
    pub fn write(&mut self, offset: usize, buf: &[u8]) -> usize {
        if offset >= PAGE_SIZE {
            return 0;
        }
        let available = PAGE_SIZE - offset;
        let to_write = core::cmp::min(buf.len(), available);
        self.data[offset..offset + to_write].copy_from_slice(&buf[..to_write]);
        to_write
    }

    /// Increment reference count
    pub fn get(&self) {
        self.ref_count.fetch_add(1, Ordering::AcqRel);
    }

    /// Decrement reference count
    pub fn put(&self) -> usize {
        self.ref_count.fetch_sub(1, Ordering::AcqRel) - 1
    }
}

impl AddressSpace {
    /// Create new address space
    pub fn new() -> Self {
        Self {
            pages: Spinlock::new(Vec::new()),
            size: AtomicUsize::new(0),
        }
    }

    /// Get file size
    pub fn get_size(&self) -> usize {
        self.size.load(Ordering::Acquire)
    }

    /// Set file size
    pub fn set_size(&self, size: usize) {
        self.size.store(size, Ordering::Release);
    }

    /// Read file data
    ///
    /// Reads data from specified offset into buffer
    pub fn read(&self, offset: usize, buf: &mut [u8]) -> usize {
        let file_size = self.get_size();
        if offset >= file_size {
            return 0;
        }

        let available = file_size - offset;
        let to_read = core::cmp::min(buf.len(), available);

        let mut total_read = 0;
        let mut current_offset = offset;
        let mut buf_offset = 0;

        while total_read < to_read {
            let page_index = current_offset / PAGE_SIZE;
            let page_offset = current_offset % PAGE_SIZE;

            let pages = self.pages.lock();
            if page_index >= pages.len() {
                break;
            }

            let remaining = to_read - total_read;

            if let Some(ref page) = pages[page_index] {
                let read_in_page = page.read(page_offset, &mut buf[buf_offset..buf_offset + remaining]);
                total_read += read_in_page;
                buf_offset += read_in_page;
                current_offset += read_in_page;

                if read_in_page == 0 {
                    break;
                }
            } else {
                // Page does not exist, treat as zero-filled
                let page_end = ((page_index + 1) * PAGE_SIZE).min(file_size);
                let available_in_page = page_end - current_offset;
                let zero_len = core::cmp::min(available_in_page, remaining);
                buf[buf_offset..buf_offset + zero_len].fill(0);
                total_read += zero_len;
                buf_offset += zero_len;
                current_offset += zero_len;
            }
        }

        total_read
    }

    /// Write file data
    ///
    /// Writes data from buffer to specified offset
    pub fn write(&self, offset: usize, buf: &[u8]) -> usize {
        let mut total_written = 0;
        let mut current_offset = offset;
        let mut buf_offset = 0;

        while total_written < buf.len() {
            let page_index = current_offset / PAGE_SIZE;
            let page_offset = current_offset % PAGE_SIZE;

            let mut pages = self.pages.lock();

            // Ensure page exists
            while page_index >= pages.len() {
                pages.push(Some(Box::new(Page::new())));
            }

            if let Some(ref mut page) = pages[page_index] {
                let remaining = buf.len() - total_written;
                let written_in_page = page.write(page_offset, &buf[buf_offset..buf_offset + remaining]);
                total_written += written_in_page;
                buf_offset += written_in_page;
                current_offset += written_in_page;

                // Update file size
                let new_size = self.size.load(Ordering::Acquire).max(current_offset);
                self.size.store(new_size, Ordering::Release);

                if written_in_page == 0 {
                    break;
                }
            } else {
                // Create new page
                pages[page_index] = Some(Box::new(Page::new()));
                drop(pages);
                continue;
            }
        }

        total_written
    }

    /// Load file from byte data
    ///
    /// Used to initialize file from ELF or other static data
    pub fn load_from_bytes(&self, data: &[u8]) {
        let mut offset = 0;
        let chunk_size = PAGE_SIZE;

        while offset < data.len() {
            let remaining = data.len() - offset;
            let to_copy = core::cmp::min(remaining, chunk_size);

            let page_index = offset / PAGE_SIZE;
            let mut pages = self.pages.lock();

            while page_index >= pages.len() {
                pages.push(Some(Box::new(Page::new())));
            }

            if let Some(ref mut page) = pages[page_index] {
                let page_offset = offset % PAGE_SIZE;
                page.write(page_offset, &data[offset..offset + to_copy]);
            }

            offset += to_copy;
        }

        // Update file size
        self.size.store(data.len(), Ordering::Release);
    }

    /// Truncate file to specified size
    pub fn truncate(&self, new_size: usize) {
        let _old_size = self.size.swap(new_size, Ordering::AcqRel);

        // Release pages beyond new size
        let new_page_count = (new_size + PAGE_SIZE - 1) / PAGE_SIZE;
        let mut pages = self.pages.lock();
        if pages.len() > new_page_count {
            pages.truncate(new_page_count);
        }
    }
}

impl Default for AddressSpace {
    fn default() -> Self {
        Self::new()
    }
}

/// FileBuffer chunk granularity (R76). Chunks are order-4 (64 KiB) page
/// allocations from the zone allocator when available — Linux serves
/// memfd/shmem contents from tmpfs pages, never from a contiguous kmalloc.
/// The pre-R76 single `Vec::resize` made a 64 MiB ftruncate (observed from
/// gnome-shell init: ALLOCTHROW size=67108864, bigalloc3 run) one oversized
/// heap block that the 16 MiB buddy MAX_ORDER cannot serve; the interim
/// chunked-heap version then exhausted the 128 MB kernel heap outright
/// (bigalloc5: ALLOCTHROW size=65536 with the heap full). Page-backed
/// chunks draw from the 2 GiB zone allocator instead.
pub const FILE_BUFFER_CHUNK: usize = 64 * 1024;

/// log2(FILE_BUFFER_CHUNK / PAGE_SIZE) — order passed to alloc_pages.
const CHUNK_ORDER: usize = 4;

impl FileChunk {
    fn new() -> Option<Self> {
        let phys = crate::mm::page_alloc::alloc_pages(
            crate::mm::zone::GfpFlags::GFP_KERNEL,
            CHUNK_ORDER,
        );
        if phys != 0 {
            return Some(FileChunk::Page(phys));
        }
        // Fallback (early boot before zone init, or zone exhausted):
        // heap chunk. May itself fail on an exhausted heap — the caller
        // treats None as ENOMEM.
        let mut c = Vec::with_capacity(FILE_BUFFER_CHUNK);
        unsafe {
            core::ptr::write_bytes(c.as_mut_ptr(), 0, FILE_BUFFER_CHUNK);
            c.set_len(FILE_BUFFER_CHUNK);
        }
        Some(FileChunk::Heap(c))
    }

    /// Base pointer of the chunk storage.
    ///
    /// The chunk's base address (address computation only — inert until
    /// a deref; callers must not hold two live mutable slices into the
    /// same chunk, the FileBuffer lock serializes all access in
    /// practice).
    fn base_ptr(&mut self) -> *mut u8 {
        match self {
            FileChunk::Page(phys) => {
                crate::arch::mm::phys_to_virt(
                    crate::arch::mm::memory_layout::PhysAddr(*phys as u64),
                )
                .as_usize() as *mut u8
            }
            FileChunk::Heap(v) => v.as_mut_ptr(),
        }
    }
}

impl Drop for FileChunk {
    fn drop(&mut self) {
        if let FileChunk::Page(phys) = *self {
            crate::mm::page_alloc::free_pages(phys, CHUNK_ORDER);
        }
    }
}

impl FileBuffer {
    /// One zeroed chunk, allocated without transiting the (small) kernel
    /// stack: with_capacity mmaps from the heap directly.
    fn new_chunk() -> Vec<u8> {
        let mut c = Vec::with_capacity(FILE_BUFFER_CHUNK);
        unsafe {
            core::ptr::write_bytes(c.as_mut_ptr(), 0, FILE_BUFFER_CHUNK);
            c.set_len(FILE_BUFFER_CHUNK);
        }
        c
    }

    /// Create new file buffer
    pub fn new() -> Self {
        Self {
            len: 0,
            chunks: Vec::new(),
        }
    }

    /// Create from byte data
    pub fn from_bytes(bytes: &[u8]) -> Self {
        let mut fb = Self::new();
        fb.write(0, bytes);
        fb
    }

    /// Read data
    pub fn read(&self, offset: usize, buf: &mut [u8]) -> usize {
        if offset >= self.len {
            return 0;
        }
        let available = self.len - offset;
        let to_read = core::cmp::min(buf.len(), available);
        let mut done = 0;
        while done < to_read {
            let pos = offset + done;
            let ci = pos / FILE_BUFFER_CHUNK;
            let co = pos % FILE_BUFFER_CHUNK;
            let n = core::cmp::min(FILE_BUFFER_CHUNK - co, to_read - done);
            // SAFETY: const cast of the chunk reference — read-only use;
            // all FileBuffer access is serialized by the inode data lock.
            let src: &[u8] = unsafe {
                let fc = &self.chunks[ci] as *const FileChunk as *mut FileChunk;
                let base = (*fc).base_ptr();
                core::slice::from_raw_parts(base.add(co), n)
            };
            buf[done..done + n].copy_from_slice(src);
            done += n;
        }
        to_read
    }

    /// Write data (extends the buffer like Linux when offset+len exceeds
    /// the current size, zero-filling any gap).
    pub fn write(&mut self, offset: usize, buf: &[u8]) -> usize {
        if buf.is_empty() {
            return 0;
        }
        let end = offset + buf.len();
        if end > self.len {
            if self.resize(end).is_err() {
                // Could not grow (zone + heap both exhausted): write only
                // what the current extent holds, POSIX partial-write.
                if offset >= self.len {
                    return 0;
                }
            }
        }
        let limit = core::cmp::min(end, self.len);
        let writable = limit.saturating_sub(offset);
        let mut done = 0;
        while done < writable {
            let pos = offset + done;
            let ci = pos / FILE_BUFFER_CHUNK;
            let co = pos % FILE_BUFFER_CHUNK;
            let n = core::cmp::min(FILE_BUFFER_CHUNK - co, writable - done);
            // SAFETY: &mut access; serialized by the inode data lock.
            let dst: &mut [u8] = unsafe {
                let base = self.chunks[ci].base_ptr();
                core::slice::from_raw_parts_mut(base.add(co), n)
            };
            dst.copy_from_slice(&buf[done..done + n]);
            done += n;
        }
        done
    }

    /// Resize (ftruncate semantics: grow-with-zeros / shrink drops bytes).
    /// Growth allocates one chunk at a time; Err(ENOMEM) when the zone
    /// allocator and the heap both fail (R76).
    ///
    /// Shrink zeroes the tail of the kept last chunk: ftruncate(2) says the
    /// file "is extended, and the extended portion reads as null bytes" —
    /// a shrink-then-grow would otherwise serve the pre-shrink bytes back
    /// (the chunks are kept, only `len` bounds reads). Same discipline as
    /// TmpfsNode::truncate.
    pub fn resize(&mut self, new_len: usize) -> Result<(), ()> {
        let new_chunks = new_len.div_ceil(FILE_BUFFER_CHUNK);
        while self.chunks.len() < new_chunks {
            match FileChunk::new() {
                Some(c) => self.chunks.push(c),
                None => return Err(()),
            }
        }
        if new_len < self.len {
            // Shrink: drop whole trailing chunks, then zero the kept last
            // chunk's tail so a later re-extend exposes zeros, not stale
            // data.
            let keep = new_len.div_ceil(FILE_BUFFER_CHUNK);
            self.chunks.truncate(keep);
            let tail = new_len % FILE_BUFFER_CHUNK;
            if tail != 0 {
                if let Some(c) = self.chunks.last_mut() {
                    // &mut access to the chunk we own; the write stays
                    // inside the FILE_BUFFER_CHUNK-sized chunk.
                    // SAFETY: owned chunk, bounded tail zero.
                    unsafe {
                        core::ptr::write_bytes(
                            c.base_ptr().add(tail),
                            0,
                            FILE_BUFFER_CHUNK - tail,
                        );
                    }
                }
            }
        }
        self.len = new_len;
        Ok(())
    }

    /// Get size
    pub fn len(&self) -> usize {
        self.len
    }

    /// Check if empty
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }
}

impl Default for FileBuffer {
    fn default() -> Self {
        Self::new()
    }
}


// ════════════════ bio ═════════════════════════════════
// (was bio.rs)
// Buffer I/O Layer - Block Cache Management
//
// Core concepts:
// - `struct buffer_head`: Buffer head, represents a cached block
// - Block cache: Caches disk blocks to improve performance
// - Hash table with chaining: Fast lookup of cached blocks
// - LRU eviction: Reclaim least recently used buffers when cache is full

// ============================================================================
// Buffer State
// ============================================================================


impl BufferState {
    pub const BH_Uptodate: u8 = 0;  // Buffer contains valid data
    pub const BH_Dirty: u8 = 1;     // Buffer needs to be written to disk
    pub const BH_Lock: u8 = 2;      // Buffer is locked
    pub const BH_Req: u8 = 3;       // Buffer has been requested
    pub const BH_Mapped: u8 = 4;    // Buffer is mapped to a disk block

    pub fn new() -> Self {
        Self(0)
    }

    pub fn set(&mut self, bit: u8) {
        self.0 |= 1 << bit;
    }

    pub fn clear(&mut self, bit: u8) {
        self.0 &= !(1 << bit);
    }

    pub fn test(&self, bit: u8) -> bool {
        (self.0 & (1 << bit)) != 0
    }

    pub fn is_uptodate(&self) -> bool {
        self.test(Self::BH_Uptodate)
    }

    pub fn is_dirty(&self) -> bool {
        self.test(Self::BH_Dirty)
    }

    pub fn is_locked(&self) -> bool {
        self.test(Self::BH_Lock)
    }

    pub fn is_mapped(&self) -> bool {
        self.test(Self::BH_Mapped)
    }
}

// ============================================================================
// Buffer Head
// ============================================================================

// SAFETY: BufferHead's mutable state (b_data) is protected by BufferState spinlock;
// other fields are atomic or only accessed under lock.
unsafe impl Send for BufferHead {}
// SAFETY: all shared mutable state is protected by the BufferState spinlock;
// b_data is only mutated under lock or from a single thread.
unsafe impl Sync for BufferHead {}

impl BufferHead {
    /// Create new buffer head
    pub fn new(blocknr: u64, size: u32) -> Self {
        Self {
            b_device: None,
            b_blocknr: blocknr,
            b_size: size,
            b_state: Spinlock::new(BufferState::new()),
            b_data: vec![0u8; size as usize],
            b_count: AtomicU32::new(1),
        }
    }

    /// Create a buffer head with an UNINITIALIZED data buffer.
    ///
    /// Only for buffers whose every byte is about to be overwritten by the
    /// device (async read DMA target): skips the 4 KiB zero-fill of `new`,
    /// which was pure waste on the read-ahead path (one memset per block
    /// under TCG). Readers must observe BH_Uptodate (bread_wait status 0)
    /// before touching b_data — the same discipline the in-flight BH_Req
    /// state already requires.
    pub fn new_uninit(blocknr: u64, size: u32) -> Self {
        let mut b_data = Vec::with_capacity(size as usize);
        // SAFETY: the allocation holds `size` initialized bytes for the Vec's
        // purposes; no read of b_data happens before the DMA completes and
        // BH_Uptodate is set (documented contract above). The capacity is
        // exactly `size`, so set_len stays in bounds.
        unsafe { b_data.set_len(size as usize); }
        Self {
            b_device: None,
            b_blocknr: blocknr,
            b_size: size,
            b_state: Spinlock::new(BufferState::new()),
            b_data,
            b_count: AtomicU32::new(1),
        }
    }

    /// Set block device
    pub fn set_device(&mut self, device: &'static blkdev::GenDisk) {
        self.b_device = Some(device);
    }

    /// Get state
    pub fn get_state(&self) -> BufferState {
        let state = self.b_state.lock();
        *state
    }

    /// Set state bit
    pub fn set_state_bit(&self, bit: u8) {
        {
            let mut state = self.b_state.lock();
            state.set(bit);
        }
        // Deferred-publication capture (see PENDING_PUBLICATIONS): every
        // path that marks a buffer dirty passes through here, so this is
        // the single hook that lets an enclosing ext4 operation record
        // "these blocks were dirtied AFTER my entry-publication point"
        // (the delete-side frees) without knowing which subsystem wrote
        // them. Costs one task-local load when no capture is armed.
        if bit == BufferState::BH_Dirty {
            publication_capture_note_dirty(self.b_device, self.b_blocknr);
        }
    }

    /// Clear state bit
    pub fn clear_state_bit(&self, bit: u8) {
        let mut state = self.b_state.lock();
        state.clear(bit);
    }

    /// Check if dirty
    pub fn is_dirty(&self) -> bool {
        let state = self.b_state.lock();
        state.is_dirty()
    }

    /// Increment reference count
    pub fn get(&self) {
        self.b_count.fetch_add(1, Ordering::AcqRel);
    }

    /// Decrement reference count
    pub fn put(&self) -> u32 {
        self.b_count.fetch_sub(1, Ordering::AcqRel).wrapping_sub(1)
    }

    /// Get reference count
    pub fn count(&self) -> u32 {
        self.b_count.load(Ordering::Acquire)
    }

    /// Read data
    pub fn read(&self, offset: usize, buf: &mut [u8]) -> usize {
        if offset >= self.b_size as usize {
            return 0;
        }
        let available = self.b_size as usize - offset;
        let to_read = core::cmp::min(buf.len(), available);
        buf[..to_read].copy_from_slice(&self.b_data[offset..offset + to_read]);
        to_read
    }

    /// Write data
    pub fn write(&mut self, offset: usize, buf: &[u8]) -> usize {
        if offset >= self.b_data.len() {
            return 0;
        }
        let available = self.b_data.len() - offset;
        let to_write = core::cmp::min(buf.len(), available);
        self.b_data[offset..offset + to_write].copy_from_slice(&buf[..to_write]);
        self.set_state_bit(BufferState::BH_Dirty);
        to_write
    }

    /// Sync to disk
    pub fn sync(&self) -> Result<(), i32> {
        if !self.is_dirty() {
            return Ok(());
        }

        if let Some(device) = self.b_device {
            blkdev::blkdev_write(
                device,
                self.b_blocknr * (self.b_size as u64 / 512),
                &self.b_data,
            )?;
            self.clear_state_bit(BufferState::BH_Dirty);
            crate::debug::fsw::note_dev_write();
        }
        Ok(())
    }
}

// ============================================================================
// Cache Entry (for chaining and LRU)
// ============================================================================

impl CacheEntry {
    fn new(bh: Box<BufferHead>, device_major: u32, device_minor: u32, blocknr: u64) -> Self {
        Self {
            bh: Box::into_raw(bh),
            key: (device_major, device_minor, blocknr),
            hash_next: None,
            lru_prev: None,
            lru_next: None,
            evicting: false,
        }
    }
}

impl CacheEntry {
    /// Shared view of the entry's BufferHead; None for a dead entry.
    ///
    /// INV-BIO-BH: the caller holds the bucket lock (entry hash-linked)
    /// or a pin (refcount > 0) — under either, the Box backing `bh`
    /// cannot be freed for the borrow's duration.
    #[inline]
    fn bh(&self) -> Option<&BufferHead> {
        if self.bh.is_null() {
            None
        } else {
            // SAFETY: INV-BIO-BH; Box-owned, non-null (checked).
            Some(unsafe { &*self.bh })
        }
    }

    /// Exclusive view of the entry's BufferHead; None for a dead entry.
    ///
    /// Same contract as [`Self::bh`], plus: the caller must hold the
    /// bucket lock so no other holder observes the mutation window
    /// (exactly the discipline the raw `(*entry.bh).b_data` writes
    /// already carried).
    #[inline]
    fn bh_mut(&self) -> Option<&mut BufferHead> {
        if self.bh.is_null() {
            None
        } else {
            // SAFETY: INV-BIO-BH + bucket lock held; single live &mut
            // window under the same lock the pre-conversion writes had.
            Some(unsafe { &mut *self.bh })
        }
    }
}

/// Borrow a hash-linked (or LRU-linked) cache entry.
///
/// INV-BIO-ENTRY: `p` came from a bucket chain or the LRU list and the
/// corresponding lock (bucket / lru) is held — under that lock the entry
/// cannot be unlinked and freed, so the borrow is live for the walk.
/// The round-1 TaskRef shape applied to the buffer cache.
#[inline]
fn entry_ref(p: *mut CacheEntry) -> &'static CacheEntry {
    // SAFETY: INV-BIO-ENTRY; entries are Box::into_raw allocations that
    // live while linked under their locks.
    unsafe { &*p }
}

impl Drop for CacheEntry {
    fn drop(&mut self) {
        if !self.bh.is_null() {
            // SAFETY: self.bh was created by Box::into_raw in CacheEntry::new;
            // Drop is called once and bh is non-null (checked above), so this reclaims the Box.
            unsafe {
                let _ = Box::from_raw(self.bh);
            }
        }
    }
}

// ============================================================================
// Block Cache with Per-Bucket Locking and LRU
// ============================================================================

// SAFETY: BlockCache is only accessed via &self methods that use internal locking
// (per-bucket Spinlock and LRU Spinlock) and atomic count; raw pointers are
// confined to cache internals and never exposed without locks.
unsafe impl Send for BlockCache {}
// SAFETY: all shared mutable state (hash buckets, LRU list) is protected by
// Spinlocks; raw pointer access is always under the appropriate bucket lock.
unsafe impl Sync for BlockCache {}

/// Leg-52 debug counter: sync_all/sync_all_excluding walked a LINKED
/// cache entry whose bh was NULL (the R11-1 crash family's read side).
/// Non-zero names the residual producer for the fs lane; the walks skip
/// those entries instead of faulting.
static SYNC_WALK_NULL_BH: core::sync::atomic::AtomicUsize =
    core::sync::atomic::AtomicUsize::new(0);

impl BlockCache {
    /// The cache's fixed block size (4096 today). Multi-block request
    /// math (bread_async_multi's sector conversion) is expressed in these
    /// units; callers with a different fs block size must gate on this.
    pub fn cache_block_size(&self) -> u32 {
        self.block_size
    }

    fn new(hash_size: usize, max_entries: usize, block_size: u32) -> Self {
        let mut buckets = Vec::with_capacity(hash_size);
        for _ in 0..hash_size {
            buckets.push(Spinlock::new(HashBucket { head: None }));
        }

        Self {
            buckets,
            lru: Spinlock::new(LruState { head: None, tail: None }),
            count: AtomicU32::new(0),
            hash_size,
            max_entries,
            block_size,
        }
    }

    /// Acquire LRU lock while already holding a bucket lock.
    ///
    /// The bucket guard is passed as a TOKEN (unsafe-slim round 2): the
    /// compiler now proves the bucket→LRU lock ordering documented on
    /// BlockCache — this cannot be called without a live bucket guard.
    #[inline]
    fn lru_lock_under_bucket<'a, T>(
        &self,
        _bucket_held: &crate::sync::spinlock::SpinlockGuard<'a, T>,
    ) -> crate::sync::spinlock::SpinlockGuard<'_, LruState> {
        self.lru.lock()
    }

    /// Same guard-token contract, irqsave bucket flavor (bread_async's
    /// Phase 1/3 hold the bucket with IRQs off).
    #[inline]
    fn lru_lock_under_bucket_irqsave<'a, T>(
        &self,
        _bucket_held: &crate::sync::spinlock::SpinlockIrqGuard<'a, T>,
    ) -> crate::sync::spinlock::SpinlockGuard<'_, LruState> {
        self.lru.lock()
    }

    #[inline]
    fn hash_index(&self, device_major: u32, device_minor: u32, blocknr: u64) -> usize {
        let hash = (device_major as u64)
            .wrapping_mul(2654435761)
            .wrapping_add((device_minor as u64) << 32)
            .wrapping_add(blocknr);
        (hash as usize) & (self.hash_size - 1)
    }

    /// Move entry to LRU head. Caller must hold the lru lock
    /// (INV-BIO-ENTRY; the unsafe raw-deref window is confined to here).
    fn move_to_lru_head(lru: &mut LruState, entry_ptr: *mut CacheEntry) {
        // SAFETY: INV-BIO-ENTRY — lru lock held; entry and every neighbor
        // it names in prev/next are linked under the same lock, so the
        // whole relink is one raw-deref window.
        unsafe {
            let entry = &mut *entry_ptr;

            // R7-C1: an entry unlinked by evict_one Phase 1 (both links
            // None) but still visible in the hash chain can race here via
            // get(). Unlinking it again would drop lru.tail (lru_next None
            // -> tail = lru_prev = None) and leave the real tail orphaned
            // — instead treat it as a fresh insert (same as push_lru_head).
            if entry.lru_prev.is_none() && entry.lru_next.is_none() && lru.head != Some(entry_ptr) {
                Self::push_lru_head(lru, entry_ptr);
                return;
            }
            if lru.head == Some(entry_ptr) {
                return; // already at head
            }

            // Unlink from current position
            if let Some(prev) = entry.lru_prev {
                (*prev).lru_next = entry.lru_next;
            }
            if let Some(next) = entry.lru_next {
                (*next).lru_prev = entry.lru_prev;
            } else {
                lru.tail = entry.lru_prev;
            }

            // Insert at head
            entry.lru_prev = None;
            entry.lru_next = lru.head;
            if let Some(head) = lru.head {
                (*head).lru_prev = Some(entry_ptr);
            }
            lru.head = Some(entry_ptr);
            if lru.tail.is_none() {
                lru.tail = Some(entry_ptr);
            }
        }
    }

    /// Push an entry that is currently UNLINKED onto the LRU head.
    /// Caller must hold the lru lock (INV-BIO-ENTRY).
    fn push_lru_head(lru: &mut LruState, entry_ptr: *mut CacheEntry) {
        // R7-C1: idempotent — evict_one Phase 2 re-inserts after a pin
        // recheck; a concurrent get() may have re-linked the entry at head
        // already. Pushing again would self-loop (entry.lru_next = head =
        // entry itself).
        if lru.head == Some(entry_ptr) {
            return;
        }
        // SAFETY: INV-BIO-ENTRY — lru lock held; head is a linked entry.
        unsafe {
            let entry = &mut *entry_ptr;
            entry.lru_prev = None;
            entry.lru_next = lru.head;
            if let Some(head) = lru.head {
                (*head).lru_prev = Some(entry_ptr);
            }
            lru.head = Some(entry_ptr);
            if lru.tail.is_none() {
                lru.tail = Some(entry_ptr);
            }
        }
    }

    /// Unlink entry from LRU list. Caller must hold the lru lock
    /// (INV-BIO-ENTRY; the unsafe raw-deref window is confined to here).
    fn remove_from_lru(lru: &mut LruState, entry_ptr: *mut CacheEntry) {
        // SAFETY: INV-BIO-ENTRY — lru lock held; prev/next are linked
        // entries under the same lock.
        unsafe {
            let entry = &*entry_ptr;
            if let Some(prev) = entry.lru_prev {
                (*prev).lru_next = entry.lru_next;
            } else {
                lru.head = entry.lru_next;
            }
            if let Some(next) = entry.lru_next {
                (*next).lru_prev = entry.lru_prev;
            } else {
                lru.tail = entry.lru_prev;
            }
            (*entry_ptr).lru_prev = None;
            (*entry_ptr).lru_next = None;
        }
    }

    /// Evict one entry from the LRU tail.
    ///
    /// Scans LRU tail for an entry with refcount == 0, removes it from
    /// both the hash chain and LRU list, then syncs to disk **after**
    /// releasing all locks. Does not hold any bucket lock during I/O.
    fn evict_one(&self) -> bool {
        // R7-C1 restructuring (supersedes the VFS-H13 two-phase fix, which
        // still raced: a get() landing between the LRU unlink and the
        // bucket lock re-inserted/pinned the victim and Phase 2 then freed
        // a buffer the caller held — or, with the re-insert guard, freed an
        // entry still linked in the LRU). New order:
        //   Phase 1 (LRU lock): PICK a victim (count==0, not already
        //     evicting) but do not unlink anything.
        //   Phase 2 (bucket lock): re-verify count==0, set `evicting`,
        //     unlink from the hash chain. Once the flag is set under this
        //     lock, get() (which takes the same lock) can no longer pin
        //     the entry; with count==0 there are no existing holders.
        //   Phase 3 (LRU lock): unlink from the LRU.
        //   Phase 4 (no locks): sync if dirty, free.
        let victim = {
            let mut lru = self.lru.lock_irqsave();
            let mut current = lru.tail;
            let mut found = None;
            while let Some(entry_ptr) = current {
                // INV-BIO-ENTRY: lru lock held; walk mates are linked.
                let entry = entry_ref(entry_ptr);
                if !entry.evicting
                    && entry.bh().is_some_and(|bh| bh.count() == 0)
                {
                    found = Some(entry_ptr);
                    break;
                }
                current = entry.lru_prev;
            }
            match found {
                Some(entry_ptr) => entry_ptr,
                None => return false, // all buffers in use (or mid-eviction)
            }
        };
        // lru lock released; victim still fully linked — pinnable ONLY
        // until Phase 2 takes the bucket lock, and the count recheck there
        // aborts the eviction if a pin arrived in this window.

        let victim_key = entry_ref(victim).key;
        let bucket_idx = self.hash_index(victim_key.0, victim_key.1, victim_key.2);

        {
            let mut bucket = self.buckets[bucket_idx].lock();
            // R11-1 (S2 root cause): PRESENCE IS AUTHORITATIVE. Every free
            // path unlinks from the hash under this same bucket lock, so
            // "found in chain" is the proof the victim is still alive. The
            // previous order read count/evicting FIRST — a CPU delayed past
            // another CPU's full eviction (unhash + free + heap reuse)
            // then checked flags on freed memory, fell through the walk
            // that no longer found the victim (no abort!), wrote
            // remove_from_lru into the reused block, CAS'd b_state on
            // NULL+0x30 (the observed kernel panic) and double-freed.
            let mut prev: Option<*mut CacheEntry> = None;
            let mut current = bucket.head;
            let mut present = false;
            while let Some(cp) = current {
                if cp == victim {
                    // SAFETY: bucket lock held; cp/prev chain-linked
                    // (INV-BIO-ENTRY) — the unhash relink writes.
                    unsafe {
                        if let Some(pp) = prev {
                            (*pp).hash_next = (*cp).hash_next;
                        } else {
                            bucket.head = (*cp).hash_next;
                        }
                    }
                    present = true;
                    break;
                }
                prev = Some(cp);
                current = entry_ref(cp).hash_next;
            }
            if !present {
                // Another CPU already evicted (and possibly freed) this
                // victim — do not touch it again.
                return false;
            }
            // Alive (presence under the lock): now the pin/flag rechecks
            // are reads of valid memory.
            let ve = entry_ref(victim);
            if ve.bh().map_or(true, |bh| bh.count() != 0) {
                // Pinned between Phase 1 and Phase 2 — but we already
                // unlinked it! Re-link at the head and abort.
                // SAFETY: bucket lock held relink write (INV-BIO-ENTRY).
                unsafe {
                    (*victim).hash_next = bucket.head;
                }
                bucket.head = Some(victim);
                return false;
            }
            // SAFETY: bucket lock held; victim present in chain.
            unsafe { (*victim).evicting = true; }
        }
        // bucket lock released; entry is unpinnable and unhashed

        // rux:exthunt (retired debug=exthunt): the victim left the hash — from here until the
        // Phase-4 sync lands, every lookup of this key misses and may
        // fabricate a fresh entry over stale disk (the unhashed-victim
        // window; see the tracers in ext4/extent.rs).
        let ve = entry_ref(victim);
        let vkey = ve.key;
        let v_dirty = ve.bh().is_some_and(|bh| bh.is_dirty());
        drop(ve);
        if crate::trace::EVENT_EXTHUNT.armed()
            && crate::api::ext4::exthunt_phys_watched(vkey.2)
        {
            crate::api::ext4::exthunt_evict_unhash(vkey.2, v_dirty);
        }

        {
            let mut lru = self.lru.lock_irqsave();
            // INV-BIO-ENTRY: victim picked from the LRU list in Phase 1.
            Self::remove_from_lru(&mut lru, victim);
        }

        // Phase 4: Sync if dirty (NO locks held — I/O is safe)
        // victim is unhashed, unlinked and unpinnable; its bh field
        // points to a valid BufferHead owned by this entry.
        {
            let victim_bh = entry_ref(victim).bh();
            if v_dirty {
                // Ordered-publication guard: if this block is a pending
                // entry/post block, writing it here (before its prereqs)
                // would reopen the ghost-empty-file crash window. Satisfy
                // THIS block's ordering obligations first (per-block
                // constraint flush — the world-drain version made every
                // eviction pay the whole publication backlog); the flush
                // persists the constrained block's prerequisites, so the
                // sync below usually becomes a no-op.
                if publication_constrained(vkey.0, vkey.1, vkey.2) {
                    let _ = flush_publication_constraints(vkey.0, vkey.1, vkey.2);
                }
                let sync_rc = match victim_bh.map(|bh| bh.sync()) {
                    Some(Ok(())) => 0,
                    Some(Err(e)) => e,
                    None => -5,
                };
                if crate::trace::EVENT_EXTHUNT.armed()
                    && crate::api::ext4::exthunt_phys_watched(vkey.2)
                {
                    crate::api::ext4::exthunt_evict_done(vkey.2, sync_rc);
                }
                crate::debug::fsw::note_evict(true);
            } else {
                crate::debug::fsw::note_evict(false);
            }
            // SAFETY: victim is unhashed + unlinked + unpinnable; the
            // Box::into_raw from insertion is reclaimed exactly once.
            let _ = unsafe { Box::from_raw(victim) };
        }
        self.count.fetch_sub(1, Ordering::Release);
        true
    }

    /// Discard ONE dirty buffer without writing it (freed-block forget).
    ///
    /// Called by the block allocator when it frees a block: the freed
    /// block's cached content is DEAD — leaving the dirty buffer in the
    /// cache means the next publication drain / eviction / commit writes
    /// dead data to disk (the P6 mkdrmdir suite dirtied one fresh dir
    /// block per mkdir and freed it in the paired rmdir: every ordered
    /// drain then synchronously wrote ~64 already-freed blocks — the
    /// 3.1ms/pair amortized floor after the publication-batching fix).
    ///
    /// Drops the buffer ONLY when it is dirty and unreferenced; a clean
    /// or pinned buffer is left alone (clean costs nothing, pinned
    /// belongs to a live user — it will be written later, which is
    /// correct, just not optimal).
    ///
    /// Protocol: R7-C1-shaped like evict_one, minus the Phase-4 sync:
    ///   Phase 1 (bucket lock): find the entry, verify !evicting,
    ///     dirty, count==0; unhash and set evicting — one lock hold, no
    ///     pick/re-verify window (we address the block by key, and a
    ///     count!=0 entry simply aborts).
    ///   Phase 2 (LRU lock): unlink from the LRU.
    ///   Phase 3 (no locks): free.
    /// A pending publication record referencing the dropped blockno
    /// already no-ops: sync_block_ordered peeks by key, misses, returns
    /// Ok — the H1/H2 plans degrade exactly as they do for a block that
    /// was never cached. The bitmap free (which carries the semantics)
    /// rides its own deferred write with its own ordering record.
    fn drop_block(&self, mj: u32, mi: u32, blocknr: u64) {
        let index = self.hash_index(mj, mi, blocknr);
        let victim: *mut CacheEntry;
        {
            let mut bucket = self.buckets[index].lock();
            let mut found: Option<*mut CacheEntry> = None;
            let mut prev: Option<*mut CacheEntry> = None;
            let mut current = bucket.head;
            while let Some(cp) = current {
                // INV-BIO-ENTRY: bucket lock held; chain-linked entries.
                let ce = entry_ref(cp);
                if ce.key == (mj, mi, blocknr) {
                    found = Some(cp);
                    break;
                }
                prev = Some(cp);
                current = ce.hash_next;
            }
            let cp = match found {
                Some(cp) => cp,
                None => return, // nothing cached for this block
            };
            // cp was found in the chain under this lock.
            {
                let ce = entry_ref(cp);
                if ce.evicting {
                    return; // mid-eviction — nothing to drop
                }
                let Some(bh) = ce.bh() else {
                    return; // dead — nothing to drop
                };
                if bh.count() != 0 || !bh.is_dirty() {
                    return; // pinned or clean — leave it
                }
                // Unhash under the same lock that get() pins under:
                // after this, no new pins can arrive.
                // SAFETY: bucket lock held; unhash relink write
                // (INV-BIO-ENTRY).
                unsafe {
                    (*cp).evicting = true;
                    if let Some(pp) = prev {
                        (*pp).hash_next = (*cp).hash_next;
                    } else {
                        bucket.head = (*cp).hash_next;
                    }
                }
            }
            victim = cp;
        }
        // Bucket lock released; victim unhashed and unpinnable.
        {
            let mut lru = self.lru.lock_irqsave();
            Self::remove_from_lru(&mut lru, victim);
        }
        crate::debug::fsw::note_drop_block();
        // SAFETY: unhashed, LRU-unlinked, unpinnable; bh owned by it.
        unsafe { let _ = Box::from_raw(victim); }
        self.count.fetch_sub(1, Ordering::Release);
    }

    /// Get or create buffer (synchronous read on cache miss).
    fn get(&self, device: &'static blkdev::GenDisk, blocknr: u64) -> Option<*mut BufferHead> {
        // Chain walks go through entry_ref()/CacheEntry::bh() (INV-BIO-ENTRY
        // / INV-BIO-BH); the only raw windows left are the relink writes,
        // each marked inline.
        {
            let (device_major, device_minor) = (device.major, device.first_minor);
            let index = self.hash_index(device_major, device_minor, blocknr);

            // Phase 1: Lookup under bucket lock
            let mut skipped_evicting = false;
            {
                let mut bucket = self.buckets[index].lock();
                let mut prev: Option<*mut CacheEntry> = None;
                let mut current = bucket.head;

                while let Some(entry_ptr) = current {
                    let entry = entry_ref(entry_ptr);
                    if entry.evicting {
                        // Being evicted: treat as not found — pinning it
                        // would hand out a buffer that is about to be
                        // freed (R7-C1 resurrection race).
                        // rux:exthunt (retired debug=exthunt): same-key eviction = miss-causing
                        // event (see bread_async Phase 1).
                        if entry.key == (device_major, device_minor, blocknr) {
                            skipped_evicting = true;
                        }
                        prev = Some(entry_ptr);
                        current = entry.hash_next;
                        continue;
                    }
                    if entry.key == (device_major, device_minor, blocknr) {
                        // rux:exthunt (retired debug=exthunt): a SECOND live entry for the same
                        // block forks the buffer-cache view — writers and
                        // readers can land on different copies (the
                        // zzprobe4/ftest04 extent-revert family). Count
                        // same-key entries in the chain and report via
                        // the no-lock console (bucket spinlock held, same
                        // discipline as the dead-bh tripwire below).
                        if crate::trace::EVENT_EXTHUNT.armed() {
                            let mut dup = 0usize;
                            let mut c2 = bucket.head;
                            while let Some(cp2) = c2 {
                                let e2 = entry_ref(cp2);
                                if e2.bh().is_some()
                                    && e2.key == (device_major, device_minor, blocknr)
                                {
                                    dup += 1;
                                }
                                c2 = e2.hash_next;
                            }
                            if dup >= 2 {
                                use core::sync::atomic::{
                                    AtomicUsize, Ordering,
                                };
                                static DUPR: AtomicUsize = AtomicUsize::new(0);
                                if DUPR.fetch_add(1, Ordering::Relaxed) < 20 {
                                    let msg = b"EXT-HUNT-BHDUP blk=";
                                    {
                                        for &b in msg {
                                            crate::console::putchar_no_lock(b);
                                        }
                                        let mut v = blocknr;
                                        let mut digs = [0u8; 20];
                                        let mut n = 0;
                                        if v == 0 {
                                            digs[0] = b'0';
                                            n = 1;
                                        }
                                        while v > 0 {
                                            digs[n] = b'0' + (v % 10) as u8;
                                            n += 1;
                                            v /= 10;
                                        }
                                        while n > 0 {
                                            n -= 1;
                                            crate::console::putchar_no_lock(digs[n]);
                                        }
                                        crate::console::putchar_no_lock(b'\n');
                                    }
                                }
                            }
                        }
                        // R9 tripwire: hand out only intact buffers. A len-0
                        // b_data is freed-and-reused memory (BufferHead::new
                        // always allocates block_size bytes); serving it
                        // corrupted ext4 metadata handling (inode.rs:563
                        // slice panic). Report via SBI (safe under any lock)
                        // and treat as a miss so the caller re-reads.
                        if entry.bh().is_none_or(|bh| bh.b_data.len() != self.block_size as usize) {
                            let msg = b"bio: dead bh in chain blk=";
                            {
                                for &b in msg { crate::console::putchar_no_lock(b); }
                                let mut v = blocknr;
                                let mut digs = [0u8; 20];
                                let mut n = 0;
                                if v == 0 { digs[0] = b'0'; n = 1; }
                                while v > 0 { digs[n] = b'0' + (v % 10) as u8; n += 1; v /= 10; }
                                while n > 0 { n -= 1; crate::console::putchar_no_lock(digs[n]); }
                                crate::console::putchar_no_lock(b'\n');
                            }
                            prev = Some(entry_ptr);
                            current = entry.hash_next;
                            continue;
                        }
                        // Failed-async residue: a buffer whose async read
                        // FAILED stays cached !Uptodate (bread_wait only
                        // sets Uptodate on status 0) with new_uninit heap
                        // garbage in b_data. Serving it as a hit handed
                        // userspace uninitialized memory (r8 read02/
                        // readv02/mmapstress04 mismatches — the zero-fill
                        // of BufferHead::new used to mask this). Treat it
                        // as a miss: Phase 2 re-reads the block from disk.
                        if entry.bh().is_none_or(|bh| !bh.get_state().is_uptodate()) {
                            prev = Some(entry_ptr);
                            current = entry.hash_next;
                            continue;
                        }
                        // Found — move to hash chain head
                        if prev.is_some() {
                            // SAFETY: prev/entry are chain-linked under the
                            // bucket lock (INV-BIO-ENTRY); relinking writes.
                            unsafe {
                                let prev_entry = &mut *prev.unwrap();
                                prev_entry.hash_next = entry.hash_next;
                                (*entry_ptr).hash_next = bucket.head;
                            }
                            bucket.head = Some(entry_ptr);
                        }
                        // Move to LRU head (bucket lock held — enforces ordering)
                        let mut lru = self.lru_lock_under_bucket(&bucket);
                        Self::move_to_lru_head(&mut lru, entry_ptr);
                        let bh = entry.bh().unwrap();
                        bh.get();
                        return Some(entry.bh);
                    }
                    prev = Some(entry_ptr);
                    current = entry.hash_next;
                }
            }

            // Phase 1.5: Evict if cache is full (soft limit — wedge fix).
            // evict_one() SYNCS dirty victims: one synchronous block write
            // per eviction. Under a dirty-metadata storm (LTP inode02/
            // ftest* filling the disk) the old hard loop spent minutes
            // inside a single bread, all in kernel context — the test
            // runner's SIGKILL could never be delivered (the r2 WEDGE
            // family). Bound the reclaim work; a cache still full of
            // pinned/dirty entries admits the new buffer anyway (reads
            // must not fail on cache pressure — Linux grows its caches).
            let mut evict_tries = 0u32;
            while self.count.load(Ordering::Acquire) as usize >= self.max_entries {
                if !self.evict_one() || evict_tries >= 32 {
                    break;
                }
                evict_tries += 1;
            }

            // Phase 2: Read from disk (no locks held)
            // rux:exthunt (retired debug=exthunt): fresh-entry fabrication, sync path.
            if crate::trace::EVENT_EXTHUNT.armed() {
                crate::api::ext4::exthunt_fab(blocknr, skipped_evicting, true);
            }
            let mut bh = Box::new(BufferHead::new(blocknr, self.block_size));

            if let Err(_) = blkdev::blkdev_read(
                device,
                blocknr * (self.block_size as u64 / 512),
                &mut bh.b_data,
            ) {
                return None;
            }
            crate::debug::fsw::note_dev_read();

            bh.set_device(device);
            bh.set_state_bit(BufferState::BH_Uptodate);

            // Create cache entry
            let entry = Box::new(CacheEntry::new(bh, device_major, device_minor, blocknr));
            let entry_ptr = Box::into_raw(entry);

            // Phase 3: Insert into cache
            {
                let mut bucket = self.buckets[index].lock();

                // Double-check for duplicate inserted by another thread
                let mut current = bucket.head;
                while let Some(cp) = current {
                    let ce = entry_ref(cp);
                    if ce.key == (device_major, device_minor, blocknr) {
                        // R9-8: apply the same integrity guard as Phase 1 —
                        // a dead (freed/reused) duplicate entry must not be
                        // handed out here after the fresh read.
                        if ce.bh().is_none_or(|b| b.b_data.len() != self.block_size as usize) {
                            current = ce.hash_next;
                            continue;
                        }
                        // Same failed-async rule as Phase 1: a !Uptodate
                        // duplicate is residue, not data — skip it and
                        // insert the fresh buffer at the chain head (the
                        // stale entry is reclaimed by LRU eviction later).
                        if ce.bh().is_none_or(|b| !b.get_state().is_uptodate()) {
                            current = ce.hash_next;
                            continue;
                        }
                        ce.bh().unwrap().get();
                        let mut lru = self.lru_lock_under_bucket(&bucket);
                        Self::move_to_lru_head(&mut lru, cp);
                        // SAFETY: entry_ptr was created by Box::into_raw
                        // above; never published, dropped on the dup path.
                        let _ = unsafe { Box::from_raw(entry_ptr) };
                        return Some(ce.bh);
                    }
                    current = ce.hash_next;
                }

                // Insert at hash chain head
                // SAFETY: entry_ptr is the freshly Box::into_raw'd entry;
                // bucket lock held (INV-BIO-ENTRY relink write).
                unsafe {
                    (*entry_ptr).hash_next = bucket.head;
                }
                bucket.head = Some(entry_ptr);

                // Insert at LRU head (bucket lock held — enforces ordering)
                let mut lru = self.lru_lock_under_bucket(&bucket);
                Self::move_to_lru_head(&mut lru, entry_ptr);
            }

            self.count.fetch_add(1, Ordering::Release);
            // SAFETY: entry_ptr linked above under the bucket lock.
            Some(unsafe { (*entry_ptr).bh })
        }
    }

    /// getblk-style fetch for FULL-BLOCK overwrites: cache hit returns the
    /// buffer; a miss creates it ZEROED, marked Uptodate+Dirty, WITHOUT the
    /// disk read a bread() would do. Only for blocks whose existing disk
    /// contents are irrelevant (freshly allocated blocks being zeroed) —
    /// reading through this API would fabricate zeros for real data.
    fn get_zero(&self, device: &'static blkdev::GenDisk, blocknr: u64) -> Option<*mut BufferHead> {
        self.get_zero_impl(device, blocknr, true)
    }

    /// Full-block-overwrite fetch, no disk read on miss and NO zeroing on
    /// hit: the caller overwrites every byte before anyone can observe the
    /// buffer (same visibility class as any in-place metadata edit — this
    /// is exactly what the plain bread + copy path did, minus the read of
    /// data that is about to be discarded). Used by metadata writers that
    /// rewrite whole blocks (directory blocks, bitmaps, group descriptors):
    /// reading a just-allocated directory block from disk before rewriting
    /// it cost one synchronous round trip per create.
    fn get_overwrite(&self, device: &'static blkdev::GenDisk, blocknr: u64) -> Option<*mut BufferHead> {
        self.get_zero_impl(device, blocknr, false)
    }

    fn get_zero_impl(
        &self,
        device: &'static blkdev::GenDisk,
        blocknr: u64,
        zero_on_hit: bool,
    ) -> Option<*mut BufferHead> {
        // Chain walks go through entry_ref()/CacheEntry::bh() (INV-BIO-ENTRY
        // / INV-BIO-BH); the BufferHead is either found in the cache
        // (pinned via get()) or freshly created and inserted below, never
        // freed while the caller holds a reference.
        {
            let (device_major, device_minor) = (device.major, device.first_minor);
            let index = self.hash_index(device_major, device_minor, blocknr);

            // Phase 1: lookup under bucket lock (hit path identical to get)
            {
                let mut bucket = self.buckets[index].lock();
                let mut current = bucket.head;
                while let Some(entry_ptr) = current {
                    let entry = entry_ref(entry_ptr);
                    current = entry.hash_next;
                    if entry.evicting {
                        continue;
                    }
                    if entry.key == (device_major, device_minor, blocknr) {
                        if entry.bh().is_none_or(|b| b.b_data.len() != self.block_size as usize) {
                            continue; // dead entry — treat as miss
                        }
                        // Failed-async residue: never hand out a !Uptodate
                        // buffer (see get() Phase 1).
                        if entry.bh().is_none_or(|b| !b.get_state().is_uptodate()) {
                            continue;
                        }
                        // HIT: for get_zero callers, zero it. The caller just
                        // ALLOCATED this block for a partial-block first
                        // write and needs the unwritten span to read back
                        // as zeros — the cache may still hold the block's
                        // PREVIOUS life (freed by truncate, reallocated from
                        // the bitmap without an intervening eviction), and
                        // returning that stale content spliced old file
                        // data around the new write (LTP ftest05 "bad
                        // verify should be 0" read back a previous
                        // iteration's pattern). Dirty so the zeros also
                        // reach disk. get_overwrite callers skip this —
                        // they rewrite every byte themselves.
                        if zero_on_hit {
                            let bm = entry.bh_mut().unwrap();
                            bm.b_data.fill(0);
                            bm.set_state_bit(BufferState::BH_Dirty);
                        }
                        entry.bh().unwrap().get();
                        return Some(entry.bh);
                    }
                }
            }

            // Phase 1.5: evict if full (soft limit — see the read-path
            // Phase 1.5 comment; bounded reclaim, then admit).
            let mut evict_tries = 0u32;
            while self.count.load(Ordering::Acquire) as usize >= self.max_entries {
                if !self.evict_one() || evict_tries >= 32 {
                    break;
                }
                evict_tries += 1;
            }

            // Phase 2: create the buffer zeroed — NO disk read.
            let mut bh = Box::new(BufferHead::new(blocknr, self.block_size));
            bh.set_device(device);
            bh.set_state_bit(BufferState::BH_Uptodate);
            bh.set_state_bit(BufferState::BH_Dirty);

            let entry = Box::new(CacheEntry::new(bh, device_major, device_minor, blocknr));
            let entry_ptr = Box::into_raw(entry);

            // Phase 3: insert (same duplicate double-check as get)
            {
                let mut bucket = self.buckets[index].lock();
                let mut current = bucket.head;
                while let Some(cp) = current {
                    let ce = entry_ref(cp);
                    if ce.key == (device_major, device_minor, blocknr) {
                        if ce.bh().is_none_or(|b| b.b_data.len() != self.block_size as usize) {
                            current = ce.hash_next;
                            continue;
                        }
                        // Failed-async residue — skip, insert ours (get()
                        // Phase 3 discipline).
                        if ce.bh().is_none_or(|b| !b.get_state().is_uptodate()) {
                            current = ce.hash_next;
                            continue;
                        }
                        // Duplicate insert lost the race: same contract as
                        // Phase 1 (zero for get_zero callers; untouched for
                        // get_overwrite callers, who rewrite every byte).
                        if zero_on_hit {
                            let bm = ce.bh_mut().unwrap();
                            bm.b_data.fill(0);
                            bm.set_state_bit(BufferState::BH_Dirty);
                        }
                        ce.bh().unwrap().get();
                        // SAFETY: our never-published entry, dropped.
                        let _ = unsafe { Box::from_raw(entry_ptr) };
                        return Some(ce.bh);
                    }
                    current = ce.hash_next;
                }
                // SAFETY: fresh Box::into_raw entry; bucket lock held
                // (INV-BIO-ENTRY relink write).
                unsafe {
                    (*entry_ptr).hash_next = bucket.head;
                }
                bucket.head = Some(entry_ptr);
                let mut lru = self.lru_lock_under_bucket(&bucket);
                Self::move_to_lru_head(&mut lru, entry_ptr);
            }

            self.count.fetch_add(1, Ordering::Release);
            // SAFETY: entry_ptr linked above under the bucket lock.
            Some(unsafe { (*entry_ptr).bh })
        }
    }

    /// Release buffer (decrement refcount)
    pub fn put(&self, bh: *const BufferHead) {
        // SAFETY: bh is a raw pointer returned by get()/bread(); it points to a
        // valid BufferHead owned by a CacheEntry in the cache.
        unsafe {
            (*bh).put();
        }
    }

    /// Sync all dirty buffers.
    ///
    /// Phase 1: Collect dirty buffer pointers under per-bucket locks.
    /// Phase 2: Sync each buffer without holding any lock.
    fn sync_all(&self) -> Result<(), i32> {
        // Phase 1: Collect dirty buffers (increment refcount to prevent eviction)
        let mut dirty_list: Vec<*mut BufferHead> = Vec::new();

        // No need to disable interrupts globally: no interrupt handler (timer,
        // virtio, softirq) ever acquires a bucket spinlock.  Per-bucket
        // lock() (preempt_disable only) is sufficient and avoids the SMP
        // deadlock where another CPU holds a bucket lock while we spin with
        // IRQs disabled.
        for i in 0..self.hash_size {
            let bucket = self.buckets[i].lock();
            let mut current = bucket.head;
            while let Some(entry_ptr) = current {
                // INV-BIO-ENTRY: bucket lock held.
                let entry = entry_ref(entry_ptr);
                // Leg-52 (route-1 exposure): a linked entry with a null
                // bh has been observed (evict_one Phase 1 guards the
                // same shape; R11-1's family ends in exactly this
                // NULL+0x30 b_state panic). Skip and count — do not
                // dereference. The fs lane owns the producer hunt.
                if let Some(bh) = entry.bh() {
                    if bh.is_dirty() {
                        bh.get();
                        dirty_list.push(entry.bh);
                    }
                } else {
                    SYNC_WALK_NULL_BH.fetch_add(1, Ordering::Relaxed);
                }
                current = entry.hash_next;
            }
        }
        // Phase 2: Sync without holding any lock
        let mut first_error: i32 = 0;
        for bh in &dirty_list {
            // bh pointers were collected under bucket locks above and
            // had their refcount incremented (INV-BIO-PIN: valid, pinned).
            if let Err(e) = bh_pinned(&(*bh)).sync() {
                if first_error == 0 {
                    first_error = e;
                }
            }
            self.put(*bh);
        }

        if first_error != 0 {
            Err(first_error)
        } else {
            Ok(())
        }
    }

    /// Sync all dirty buffers of ONE device, optionally skipping a single
    /// block, in hash order.
    ///
    /// Used by the ext4 directory-entry publication barrier: the skipped
    /// block is the entry block being published, which must reach the disk
    /// strictly AFTER every block it names (new inode table block, bitmaps,
    /// data blocks) — the caller persists it itself, last. Order among the
    /// flushed blocks does not matter for that invariant; only their
    /// "all-before-the-entry" grouping does.
    ///
    /// Same locking discipline as sync_all (collect under per-bucket locks
    /// with a refcount bump, sync without any lock held).
    fn sync_all_excluding(
        &self,
        device: &'static blkdev::GenDisk,
        skip: Option<u64>,
    ) -> Result<(), i32> {
        let mut dirty_list: Vec<*mut BufferHead> = Vec::new();
        for i in 0..self.hash_size {
            let bucket = self.buckets[i].lock();
            let mut current = bucket.head;
            while let Some(entry_ptr) = current {
                // INV-BIO-ENTRY: bucket lock held.
                let entry = entry_ref(entry_ptr);
                // Leg-52: same null-bh guard as sync_all (the pa92nj
                // crash chain faulted HERE first).
                let Some(bh) = entry.bh() else {
                    SYNC_WALK_NULL_BH.fetch_add(1, Ordering::Relaxed);
                    current = entry.hash_next;
                    continue;
                };
                let same_dev = bh.b_device.is_some_and(|d| core::ptr::eq(d, device));
                if bh.is_dirty() && same_dev && Some(bh.b_blocknr) != skip {
                    bh.get();
                    dirty_list.push(entry.bh);
                }
                current = entry.hash_next;
            }
        }
        let mut first_error: i32 = 0;
        for bh in &dirty_list {
            // SAFETY: collected under bucket locks with a refcount pin;
            // valid BufferHeads.
            if let Err(e) = bh_pinned(&(*bh)).sync() {
                if first_error == 0 {
                    first_error = e;
                }
            }
            self.put(*bh);
        }
        if first_error != 0 {
            Err(first_error)
        } else {
            Ok(())
        }
    }

    /// Invalidate all buffers (for device removal, etc.)
    fn invalidate(&self) {
        for i in 0..self.hash_size {
            let mut bucket = self.buckets[i].lock();
            let mut current = bucket.head;
            while let Some(entry_ptr) = current {
                // SAFETY: bucket lock held and the chain is being drained;
                // Box::from_raw reclaims the CacheEntry and its BufferHead.
                let next = unsafe {
                    let next = (*entry_ptr).hash_next;
                    let _ = Box::from_raw(entry_ptr);
                    next
                };
                current = next;
            }
            bucket.head = None;
        }

        let mut lru = self.lru.lock();
        lru.head = None;
        lru.tail = None;
        self.count.store(0, Ordering::Release);
    }

    /// Invalidate every buffer of ONE device (loop-detach discipline,
    /// Linux's invalidate_bdev on LOOP_CLR_FD).
    ///
    /// A loop device whose backing-file write failed leaves a BH_Dirty
    /// buffer behind (sync failed, dirty bit stays). Once the loop is
    /// unbound, that buffer can never be written back — but it still sits
    /// in the shared cache, so the NEXT full-cache sync
    /// (ext4_mkdir's bio::sync_buffers, sync(2)) or an eviction would
    /// fail with the DEAD device's ENXIO and leak that errno into
    /// completely unrelated syscalls (the r8 mkdtemp(/tmp/LTP_*) ENXIO
    /// storm after every loop-format failure).
    ///
    /// Unpinned entries are freed WITHOUT syncing (their dirty data is
    /// failed-write data — detach discards it, same as Linux). Pinned
    /// entries (in-flight users) only get BH_Dirty cleared so their later
    /// natural eviction cannot try the dead device either.
    fn invalidate_device(&self, device_major: u32, device_minor: u32) {
        for i in 0..self.hash_size {
            let mut bucket = self.buckets[i].lock();
            let mut current = bucket.head;
            let mut prev: Option<*mut CacheEntry> = None;
            while let Some(entry_ptr) = current {
                // INV-BIO-ENTRY: bucket lock held.
                let entry = entry_ref(entry_ptr);
                let next = entry.hash_next;
                if entry.key.0 == device_major && entry.key.1 == device_minor {
                    // Behavior-preserving form: the original body
                    // dereferenced entry.bh unconditionally (a null bh
                    // faulted); keep the identical failure class.
                    let bh = entry.bh().expect("bio: dead bh in invalidate_device walk");
                    if bh.count() == 0 {
                        // Unlink from the chain; the LRU link is
                        // removed under the lru lock below.
                        // SAFETY: bucket lock held; the unhash relink
                        // write plus the guarded free (entry marked
                        // evicting first, so get() skips it).
                        unsafe {
                            (*entry_ptr).evicting = true;
                            match prev {
                                Some(pp) => (*pp).hash_next = next,
                                None => bucket.head = next,
                            }
                        }
                        let mut lru = self.lru.lock_irqsave();
                        Self::remove_from_lru(&mut lru, entry_ptr);
                        // No I/O, no sync: dirty data is discarded
                        // (detach semantics). Presence under the
                        // bucket lock makes the free safe (get()
                        // skips evicting entries).
                        // SAFETY: unhashed + evicting-marked + LRU-
                        // unlinked; the Box::into_raw reclaim.
                        let _ = unsafe { Box::from_raw(entry_ptr) };
                        self.count.fetch_sub(1, Ordering::Release);
                    } else {
                        // Pinned: keep the buffer for its holder, but
                        // make sure it never syncs against the dead
                        // device after release.
                        bh.clear_state_bit(BufferState::BH_Dirty);
                        prev = Some(entry_ptr);
                    }
                } else {
                    prev = Some(entry_ptr);
                }
                current = next;
            }
        }
    }
}

impl Drop for BlockCache {
    fn drop(&mut self) {
        self.invalidate();
    }
}

// ============================================================================
// Public API
// ============================================================================


static CACHE_INIT: AtomicBool = AtomicBool::new(false);
static BLOCK_CACHE: crate::safety::slot::OnceSlot<BlockCache> =
    crate::safety::slot::OnceSlot::new();
static CACHE_INIT_LOCK: Spinlock<()> = Spinlock::new(());

pub fn get_block_cache() -> &'static BlockCache {
    // Double-checked locking: fast path checks without lock,
    // slow path acquires lock then re-checks before initializing.
    if !CACHE_INIT.load(Ordering::Acquire) {
        let _guard = CACHE_INIT_LOCK.lock();
        if !CACHE_INIT.load(Ordering::Acquire) {
            // Capacity: 8192 entries (32 MiB at 4K blocks, allocated ON
            // DEMAND — an entry exists only once its block is first read).
            // The old 1024-entry/4 MiB cache evicted constantly under any
            // real metadata working set (pbench P6 tree ~1300 blocks:
            // ~2.5 evictions per mkdir+rmdir pair, ~46% of victims dirty —
            // each dirty eviction is a synchronous round trip INSIDE the
            // caller's bread, plus a publication-constraint guard pass).
            // The reference kernel caches all free memory; 8 MiB/2048 was
            // still churny, 32 MiB/8192 covers GNOME-class small loads.
            // Buckets 64 -> 2048 (power of two for the hash mask): at 8192
            // entries the old 64 buckets averaged 128-long chains, making
            // every bread/get/peek walk tens of pointers.
            let cache = BlockCache::new(2048, 8192, 4096);
            // INV-SLOT-1/2: the OnceSlot owns the publication protocol
            // the hand-rolled static-mut + flag pair carried.
            BLOCK_CACHE.publish(cache);
            // Release ordering ensures the publication is visible before
            // CACHE_INIT becomes true.
            CACHE_INIT.store(true, Ordering::Release);
        }
    }
    BLOCK_CACHE
        .get()
        .expect("block cache used before init_block_cache()")
}

/// Read a block from cache (or disk if not cached)
///
/// Read a block from cache (or disk if not cached)
// ============================================================================
// INV-BIO-BHREF (unsafe-slim r3): typed borrows of a PINED raw BufferHead
// handle. bread/bread_async hand out *mut BufferHead with the refcount pin
// (b_count >= 1); the pin holds until brelse. These accessors confine the
// raw deref to one marked span each; the returned borrow ties to the
// caller's handle borrow, so the pin window stays compiler-visible at the
// call site. (Local minimal primitive; consolidate with the KPtr/StaticRef
// family the sibling lane is landing.)
// ============================================================================

/// THE pinned-handle edge: adopt a bread-family buffer handle as a
/// shared view. INV-BIO-PIN: `bh` came from bread/bread_async/getblk
/// (non-null, the caller's refcount pin holds it until brelse) and the
/// borrow lives only as long as the caller's handle borrow.
#[inline]
fn bh_pinned<'a>(bh: &'a *mut BufferHead) -> &'a BufferHead {
    // SAFETY: INV-BIO-PIN — pinned by the caller's refcount; non-null
    // by the bread family's construction.
    unsafe { &**bh }
}

/// Shared view of a pinned buffer's data block.
pub fn bh_data<'a>(bh: &'a *mut BufferHead) -> &'a [u8] {
    &bh_pinned(bh).b_data
}

/// Exclusive view of a pinned buffer's data block (read-modify-write).
pub fn bh_data_mut<'a>(bh: &'a *mut BufferHead) -> &'a mut [u8] {
    // SAFETY: INV-BIO-PIN — the caller's pin holds the buffer; every
    // call site's `bh` local is a uniquely-held *mut (the metadata
    // read-modify-write discipline), so the &mut window aliases no live
    // shared borrow. (Kept as the one documented mut edge rather than
    // rippling &mut through dozens of ext4 call sites this round.)
    unsafe { &mut (**bh).b_data }
}

/// Block number of a pinned buffer (metadata loops).
pub fn bh_blocknr(bh: &*mut BufferHead) -> u64 {
    bh_pinned(bh).b_blocknr
}

/// State-bit set on a pinned buffer (dirty marking).
pub fn bh_set_state_bit(bh: &*mut BufferHead, bit: u8) {
    bh_pinned(bh).set_state_bit(bit)
}

/// State-bit clear on a pinned buffer.
pub fn bh_clear_state_bit(bh: &*mut BufferHead, bit: u8) {
    bh_pinned(bh).clear_state_bit(bit)
}

/// Dirty query on a pinned buffer.
pub fn bh_is_dirty(bh: &*mut BufferHead) -> bool {
    bh_pinned(bh).is_dirty()
}

pub fn bread(device: &'static blkdev::GenDisk, blocknr: u64) -> Option<*mut BufferHead> {
    crate::debug::fsw::note_bread();
    get_block_cache().get(device, blocknr)
}

/// Fetch a block for a full-block overwrite: no disk read on a miss — the
/// buffer is created zeroed and dirty (see BlockCache::get_zero). Callers
/// must overwrite the whole block (or rely on the zeros).
pub fn getblk_zero(device: &'static blkdev::GenDisk, blocknr: u64) -> Option<*mut BufferHead> {
    get_block_cache().get_zero(device, blocknr)
}

/// Fetch a block for a full-block overwrite: no disk read on a miss (the
/// buffer is created zeroed and dirty) and no zeroing on a hit. The caller
/// MUST overwrite the whole block before the buffer becomes observable.
/// See BlockCache::get_overwrite.
pub fn getblk_overwrite(device: &'static crate::drivers::blkdev::GenDisk, blocknr: u64) -> Option<*mut BufferHead> {
    get_block_cache().get_overwrite(device, blocknr)
}

/// Forget a FREED block's dirty buffer without writing it (see
/// BlockCache::drop_block). Best-effort: pinned or clean buffers are
/// left in place.
pub fn drop_freed_block(device: &'static crate::drivers::blkdev::GenDisk, blocknr: u64) {
    get_block_cache().drop_block(device.major, device.first_minor, blocknr);
}

/// Forget a FREED block's dirty buffer AND its jbd2 registration: same as
/// drop_freed_block, but first removes the buffer from the CURRENT task's
/// running transaction (jbd2_journal_forget) so a later commit does not
/// re-read the dead block from disk and write its stale content back (or
/// into the journal area on the revoke slow path). Called from the block
/// allocator's free path, which always runs inside the freeing op's
/// journal bracket.
pub fn drop_freed_block_forgotten(
    device: &'static crate::drivers::blkdev::GenDisk,
    blocknr: u64,
) {
    let (mj, mi) = (device.major, device.first_minor);
    // Forget under NO bio locks (peek pins, jbd2 locks only its own
    // transaction lists — no bucket->t_dirty nesting exists).
    if let Some(bh) = get_block_cache().peek_buffer((mj, mi), blocknr) {
        // The journal-forget seam row (rung-5): the crate resolves the
        // handle; the handle outlives this call (the freeing op's
        // bracket).
        let h = self::current_handle_raw();
        if !h.is_null() {
            crate::api::ext4::journal_forget(h, bh);
        }
        get_block_cache().put(bh);
    }
    get_block_cache().drop_block(mj, mi, blocknr);
}

/// Invalidate every cached buffer of `device` without writing anything
/// back (loop detach — see BlockCache::invalidate_device).
pub fn invalidate_device(device: &blkdev::GenDisk) {
    get_block_cache().invalidate_device(device.major, device.first_minor);
}

/// Async block read: submit I/O without blocking, return buffer head immediately.
///
/// On cache hit: returns buffer with `BH_Uptodate` set (no I/O needed).
/// On cache miss: creates a new BufferHead, submits async I/O via
/// `blkdev::blkdev_read_async`, inserts into cache, and returns the buffer.
/// The buffer data is **not** valid until `bread_wait()` completes.
/// Wait for a buffer whose I/O was submitted by ANOTHER caller to settle.
/// BH_Req is cleared by the owning bread_wait(), so poll it with short
/// sleeps (1 jiffy each). The buffer cache keeps the entry pinned by the
/// owner's reference, so `bh` stays valid. In IRQ/early context (no
/// current task) spin instead of sleeping. Returns 0 when the buffer is
/// uptodate, -EIO otherwise (review 2R.11).
///
/// WEDGE fix (LTP inode02/ftest02/04/06, sendmsg02): this wait had NO
/// timeout. When a buffer's completion was lost (or its owner errored out
/// before its bread_wait), the calling task looped here forever — always
/// in kernel context, so the test runner's SIGKILL could never be
/// delivered, and each iteration churned an add_timer/del_timer heap
/// allocation pair (the observed buddy-allocator livelock; the same
/// churn starved the timer softirq into ALLOCTHROW panics on other
/// CPUs). Bound the wait: after WAIT_DEADLINE_JIFFIES, give up and
/// report -EIO so the syscall unwinds and the task stays killable.
fn wait_buffer_io_done(bh: *mut BufferHead) -> i32 {
    const WAIT_DEADLINE_JIFFIES: u64 = crate::timer::msecs_to_jiffies(10_000);
    let mut slept = 0u32;
    let deadline = crate::timer::get_jiffies().saturating_add(WAIT_DEADLINE_JIFFIES);
    loop {
        // SAFETY: INV-BIO-PIN — the owner's reference pins the buffer
        // across this wait (the module doc above).
        let bh_ref: &BufferHead = unsafe { &*bh };
        let state = bh_ref.get_state();
        if !state.test(BufferState::BH_Req) {
            return if state.test(BufferState::BH_Uptodate) { 0 } else { -5 };
        }
        if crate::sched::current().is_some() {
            if crate::timer::get_jiffies() >= deadline {
                crate::pr_err!(
                    "bio: buffer io wait timeout block={} — reporting EIO (wedge fix)",
                    bh_ref.b_blocknr
                );
                return -5;
            }
            let pid = crate::sched::get_current_pid();
            let dl = crate::timer::get_jiffies().saturating_add(1);
            let id = crate::timer::add_timer_wakeup(dl, pid);
            // R54: schedule() now restores the caller's SIE state; wait-path callers re-arm explicitly (semaphore.rs discipline) so ticks/IPIs reach this CPU across the wait loop.
            crate::arch::cpu::restore_irq(true);
            crate::sched::schedule();
            if id != 0 {
                crate::timer::del_timer(id);
            }
            slept += 1;
        } else {
            // Early boot / IRQ context: no task to sleep, no timer budget —
            // spin as before (bounded by the caller's poll budget).
            core::hint::spin_loop();
        }
    }
}

pub fn bread_async(
    device: &'static blkdev::GenDisk,
    blocknr: u64,
    completion: &super::types::IoCompletion,
) -> Option<*mut BufferHead> {
    // Chain walks go through entry_ref()/CacheEntry::bh()
    // (INV-BIO-ENTRY / INV-BIO-BH); remaining raw windows are marked.
    {
        let (device_major, device_minor) = (device.major, device.first_minor);
        let cache = get_block_cache();
        let index = cache.hash_index(device_major, device_minor, blocknr);

        // Phase 1: Lookup under bucket lock
        let mut skipped_evicting = false;
        {
            let mut bucket = cache.buckets[index].lock_irqsave();
            let mut prev: Option<*mut CacheEntry> = None;
            let mut current = bucket.head;

            while let Some(entry_ptr) = current {
                let entry = entry_ref(entry_ptr);
                // R9-9: same guards as get() — skip entries being evicted
                // and dead (freed/reused) BufferHeads.
                if entry.evicting {
                    // rux:exthunt (retired debug=exthunt): an evicting entry with OUR key is the
                    // miss-causing event — its Phase-4 sync may not have
                    // landed, so a Phase-2 fabrication would read stale
                    // disk over a block whose only dirty copy is the
                    // victim. Recorded for the Phase-2 print.
                    if entry.key == (device_major, device_minor, blocknr) {
                        skipped_evicting = true;
                    }
                    prev = Some(entry_ptr);
                    current = entry.hash_next;
                    continue;
                }
                if entry.bh().is_none_or(|b| b.b_data.len() != cache.block_size as usize) {
                    prev = Some(entry_ptr);
                    current = entry.hash_next;
                    continue;
                }
                if entry.key == (device_major, device_minor, blocknr) {
                    // bh() is Some here: the length guard above continued
                    // on the dead-entry path.
                    let state = entry.bh().unwrap().get_state();
                    if !state.test(BufferState::BH_Uptodate)
                        && state.test(BufferState::BH_Req)
                    {
                        // In-flight entry owned by another caller: its I/O
                        // has not landed yet. Completing now would hand out
                        // stale buffer contents (review 2R.11) — take a
                        // reference, drop the lock, wait for the owner's
                        // I/O, then complete.
                        // SAFETY: entry.bh passed the len guard above
                        // (non-null, block-sized); pinned before unlock.
                        let (bh, status) = unsafe {
                            let bh = entry.bh;
                            (*bh).get();
                            (bh, wait_buffer_io_done(bh))
                        };
                        drop(bucket);
                        completion.complete(status);
                        return Some(bh);
                    }
                    if !state.test(BufferState::BH_Uptodate) {
                        // Failed-async residue (!Uptodate, !BH_Req): the
                        // previous read of this block FAILED and the buffer
                        // holds new_uninit heap garbage. Not a hit — fall
                        // through and submit a fresh read (Phase 3 skips
                        // this stale entry when inserting).
                        prev = Some(entry_ptr);
                        current = entry.hash_next;
                        continue;
                    }
                    // Cache hit (up to date)
                    if prev.is_some() {
                        // SAFETY: bucket lock held; chain relink write
                        // (INV-BIO-ENTRY).
                        unsafe {
                            let prev_entry = &mut *prev.unwrap();
                            prev_entry.hash_next = entry.hash_next;
                            (*entry_ptr).hash_next = bucket.head;
                        }
                        bucket.head = Some(entry_ptr);
                    }
                    let mut lru = cache.lru_lock_under_bucket_irqsave(&bucket);
                    BlockCache::move_to_lru_head(&mut lru, entry_ptr);
                    entry.bh().unwrap().get();
                    let hit_bh = entry.bh;
                    // Bucket/LRU locks drop HERE. The caller will bread_wait()
                    // on its completion; no I/O is in flight for a cache hit,
                    // so signal it right after releasing the locks — the
                    // in-flight branch above already drops the bucket lock
                    // before completing, and complete() takes the waiter's
                    // wait-queue lock (wake-under-bucket-lock was the last
                    // wake-nested-in-a-driver-lock site; INV-LOCK-6).
                    drop(lru);
                    drop(bucket);
                    // rux:exthunt (retired debug=exthunt): block-cache hit truth (buffer pointer +
                    // first bytes) — see exthunt_rxbit/exthunt_rxbhit.
                    // SAFETY: hit_bh passed the b_data length guard above.
                    unsafe {
                        let d = &(*hit_bh).b_data;
                        crate::api::ext4::exthunt_rxbhit(
                            blocknr,
                            d.as_ptr(),
                            d[0],
                            d[1],
                        );
                    }
                    completion.complete(0);
                    return Some(hit_bh);
                }
                prev = Some(entry_ptr);
                current = entry.hash_next;
            }
        }

        // Phase 1.5: Evict if cache is full (soft limit — see the
        // read-path Phase 1.5 comment; bounded reclaim, then admit).
        let mut evict_tries = 0u32;
        while cache.count.load(Ordering::Acquire) as usize >= cache.max_entries {
            if !cache.evict_one() || evict_tries >= 32 {
                break;
            }
            evict_tries += 1;
        }

        // Phase 2: Cache miss — submit async I/O (no lock held).
        // Uninit buffer: the device DMA fills every byte; zero-filling 4 KiB
        // per block was measurable waste on the batch read-ahead path.
        // rux:exthunt (retired debug=exthunt): fresh-entry fabrication (adjudicates the unhashed
        // evicting-victim race — see the tracers in ext4/extent.rs).
        if crate::trace::EVENT_EXTHUNT.armed() {
            crate::api::ext4::exthunt_fab(blocknr, skipped_evicting, false);
        }
        let block_size = cache.block_size;
        let mut bh = Box::new(BufferHead::new_uninit(blocknr, block_size));
        bh.set_device(device);
        bh.set_state_bit(BufferState::BH_Req);

        let sectors_per_block = block_size as u64 / 512;
        if let Err(_) = blkdev::blkdev_read_async(
            device,
            blocknr * sectors_per_block,
            &mut bh.b_data,
            completion,
        ) {
            return None;
        }

        // Phase 3: Insert into cache
        let entry = Box::new(CacheEntry::new(bh, device_major, device_minor, blocknr));
        let entry_ptr = Box::into_raw(entry);

        {
            let mut bucket = cache.buckets[index].lock_irqsave();

            // Double-check for duplicate
            let mut dup_bh: Option<*mut BufferHead> = None;
            let mut current = bucket.head;
            while let Some(cp) = current {
                let ce = entry_ref(cp);
                if ce.key == (device_major, device_minor, blocknr) {
                    // R13-2: same dead/evicting guards as get() Phase 3.
                    if ce.evicting
                        || ce.bh()
                            .is_none_or(|b| b.b_data.len() != cache.block_size as usize)
                    {
                        current = ce.hash_next;
                        continue;
                    }
                    // Failed-async residue: a !Uptodate, !BH_Req duplicate
                    // holds garbage from a FAILED read — do not return it;
                    // publish our fresh entry instead (the stale one is
                    // skipped by lookups and reclaimed by LRU eviction).
                    // bh() is Some here (length guard above).
                    let st = ce.bh().unwrap().get_state();
                    if !st.test(BufferState::BH_Uptodate) && !st.test(BufferState::BH_Req) {
                        current = ce.hash_next;
                        continue;
                    }
                    ce.bh().unwrap().get();
                    let mut lru = cache.lru_lock_under_bucket_irqsave(&bucket);
                    BlockCache::move_to_lru_head(&mut lru, cp);
                    dup_bh = Some(ce.bh);
                    break;
                }
                current = ce.hash_next;
            }
            drop(bucket);

            if let Some(existing_bh) = dup_bh {
                // A concurrent caller inserted the same block first. OUR
                // redundant I/O (Phase 2) is still going to DMA into the new
                // bh — free it only after that I/O lands (completion is the
                // one we passed to blkdev_read_async), then also wait for
                // the existing buffer to be up to date so the caller never
                // observes a half-filled cache hit (review 2R.11).
                let wait_status = completion.wait();
                if wait_status == self::WAIT_TIMED_OUT {
                    // Timed out: wait() already abandoned the pending (no
                    // late fire into this stack completion). Our chain may
                    // still DMA into the private bh — LEAK the entry, never
                    // free a buffer the device may still write.
                } else {
                    // SAFETY: entry_ptr was created by Box::into_raw above;
                    // our I/O has finished and the entry was never published.
                    let _ = unsafe { Box::from_raw(entry_ptr) };
                }
                // SAFETY: existing_bh was pinned in the dup walk above.
                let settle = wait_buffer_io_done(existing_bh);
                // Re-settle the completion as an INTERNAL signal carrying the
                // existing buffer's settled status: the token on it names OUR
                // redundant buffer, but the caller's bread_wait() will check
                // it against the EXISTING buffer we return — without this
                // re-settle the zero-serve guard would reject every dup-path
                // handback as misattributed. complete() stamps token 0
                // (always accepted); done is already set and no waiter can be
                // racing (wait() drained deliveries above).
                completion.complete(settle);
                // The caller's bread_wait() sees the completion our I/O
                // signaled; the winning buffer is settled either way.
                return Some(existing_bh);
            }

            {
                let mut bucket = cache.buckets[index].lock_irqsave();
                // SAFETY: fresh Box::into_raw entry; bucket lock held
                // (INV-BIO-ENTRY relink write).
                unsafe {
                    (*entry_ptr).hash_next = bucket.head;
                }
                bucket.head = Some(entry_ptr);

                let mut lru = cache.lru_lock_under_bucket_irqsave(&bucket);
                BlockCache::move_to_lru_head(&mut lru, entry_ptr);
            }

            cache.count.fetch_add(1, Ordering::Release);
            // SAFETY: entry_ptr linked above under the bucket lock.
            Some(unsafe { (*entry_ptr).bh })
        }
    }
}

/// Wait for an async buffer read to complete.
///
/// Blocks until the IoCompletion signals done, then marks the buffer
/// as up-to-date and clears the in-flight flag.
///
/// R20-FS8: returns the I/O status (0 = success, negative errno on failure)
/// so callers can refuse to consume/cache data from a failed read. The
/// buffer stays in the cache marked !Uptodate on error.
///
/// On [`crate::fs::hotpath::WAIT_TIMED_OUT`] the device may STILL be
/// writing the request's DMA target: wait() itself has already abandoned the
/// device-side pending entry (so its late completion can never fire into the
/// waiter's memory after this returns — the freed-kernel-stack completion
/// corruption family), and callers must NOT free the DMA target (multi-block
/// buffers are leaked by drain_batch; single-block buffers keep their pin).
pub fn bread_wait(bh: *mut BufferHead, completion: &super::types::IoCompletion) -> i32 {
    // SAFETY: bh is a raw pointer returned by bread_async(); it points to a
    // valid BufferHead owned by a CacheEntry in the cache.
    unsafe {
        let status = completion.wait();
        if status == 0 {
            // Zero-serve guard (the no-journal ext4 root-lookup family): a
            // device completion walker delivers with a token proving WHICH
            // buffer's chain completed. A token mismatch means the delivery
            // was misattributed — the waiter's own DMA may not have landed,
            // and b_data is still the new_uninit heap contents (all zeros on
            // a fresh page). Publishing that as BH_Uptodate caches silent
            // zeros for the block (every later lookup of the root directory
            // failed after "init: /test/pbench not found"). Refuse instead:
            // report EIO, leave the buffer !Uptodate (the failed-async
            // residue discipline re-reads it on the next miss) and make the
            // misattribution loud. Token 0 = internal signal (cache hit,
            // in-flight branch, dup-path re-settle) — always accept.
            let token = completion.delivered_token();
            if token != 0 && token != (*bh).b_data.as_ptr() as usize {
                crate::pr_err!(
                    "bio: misattributed completion for block {} (token {:x} != buffer {:x}) — refusing to publish, reporting EIO",
                    (*bh).b_blocknr,
                    token,
                    (*bh).b_data.as_ptr() as usize
                );
                (*bh).clear_state_bit(BufferState::BH_Req);
                return -5;
            }
            (*bh).set_state_bit(BufferState::BH_Uptodate);
        }
        (*bh).clear_state_bit(BufferState::BH_Req);
        status
    }
}

/// Release a buffer
pub fn brelse(bh: *const BufferHead) {
    get_block_cache().put(bh)
}

/// Non-blocking presence probe: does a live block-cache entry exist for
/// (device, blocknr)? No I/O, no pinning, no LRU touch.
///
/// Coherence guard for `bread_async_multi`: that path DMA-reads a whole
/// block run into a private buffer WITHOUT consulting the block cache.
/// If any member block has a live entry here — especially a DIRTY one
/// holding data the disk does not have yet (lazy write-back defers while
/// a journal handle is active) — the private read would fetch stale disk
/// bytes and poison the page cache with them. Callers must split such
/// runs and use per-block `bread_async`, which returns the cached
/// (uptodate, possibly dirty) contents instead.
pub fn block_cached(device: &'static blkdev::GenDisk, blocknr: u64) -> bool {
    // Entry traversal mirrors bread_async Phase 1 under the bucket lock
    // (INV-BIO-ENTRY / INV-BIO-BH).
    {
        let (device_major, device_minor) = (device.major, device.first_minor);
        let cache = get_block_cache();
        let index = cache.hash_index(device_major, device_minor, blocknr);
        let bucket = cache.buckets[index].lock_irqsave();
        // rux:exthunt (retired debug=exthunt): detect the guard's blind spot under the lock (an
        // evicting same-key entry makes this lookup return false while the
        // victim's dirty data may not be on disk yet); print after release.
        let mut evicting_match = false;
        let mut current = bucket.head;
        while let Some(entry_ptr) = current {
            let entry = entry_ref(entry_ptr);
            // Same validity guards as bread_async Phase 1: skip entries
            // being evicted and dead (freed/reused) BufferHeads.
            if entry.evicting {
                if entry.key == (device_major, device_minor, blocknr) {
                    evicting_match = true;
                }
                current = entry.hash_next;
                continue;
            }
            if entry.bh().is_none_or(|bh| bh.b_data.len() != cache.block_size as usize) {
                current = entry.hash_next;
                continue;
            }
            if entry.key == (device_major, device_minor, blocknr) {
                return true; // SpinlockGuard drops on early return
            }
            current = entry.hash_next;
        }
        drop(bucket);
        if evicting_match && crate::trace::EVENT_EXTHUNT.armed() {
            crate::api::ext4::exthunt_bc_blind(blocknr);
        }
        false
    }
}

/// Dirty-presence probe (paired-test item 3): TRUE only when the block
/// has a live cache entry that is BH_Dirty RIGHT NOW (bucket-lock walk,
/// no pin, no LRU touch). fsync's data walk uses it to skip absent and
/// already-clean blocks without the bread() pin round trip — the
/// per-fsync pin of every cached block of the file was 2048 hash+LRU
/// operations per fsync (the measured 3.9M breads/s burn on the
/// write+fsync row). A mid-eviction entry reports true (the caller's
/// bread slow path sees the settled state).
pub fn block_dirty_cached(device: &'static blkdev::GenDisk, blocknr: u64) -> bool {
    // Entry walk mirrors block_cached under the same bucket lock
    // (INV-BIO-ENTRY / INV-BIO-BH).
    {
        let (device_major, device_minor) = (device.major, device.first_minor);
        let cache = get_block_cache();
        let index = cache.hash_index(device_major, device_minor, blocknr);
        let bucket = cache.buckets[index].lock_irqsave();
        let mut current = bucket.head;
        while let Some(entry_ptr) = current {
            let entry = entry_ref(entry_ptr);
            if entry.evicting {
                if entry.key == (device_major, device_minor, blocknr) {
                    drop(bucket);
                    return true;
                }
                current = entry.hash_next;
                continue;
            }
            if entry.bh().is_none_or(|bh| bh.b_data.len() != cache.block_size as usize) {
                current = entry.hash_next;
                continue;
            }
            if entry.key == (device_major, device_minor, blocknr) {
                let dirty = entry.bh().unwrap().is_dirty();
                drop(bucket);
                return dirty;
            }
            current = entry.hash_next;
        }
        false
    }
}

/// Durability-by-absence probe: TRUE only when the block's buffer is
/// GONE from the cache AND no same-key eviction is still in flight.
///
/// Contract (evict_one Phase 4): a dirty victim is synchronously
/// written before its entry is freed, so a settled-absent block's
/// latest content is on disk. A mid-eviction entry does NOT count —
/// its sync write may not have landed yet — the caller must take the
/// slow path for it. This is what lets fsync's data loop skip the
/// synchronous re-read of every evicted block (the post-flush wall:
/// a 128 MB file turns over the 8192-entry cache ~4x, and the loop's
/// bread() of each absent block paid one 4 KiB device read apiece).
pub fn block_absent_durable(device: &'static blkdev::GenDisk, blocknr: u64) -> bool {
    // Bucket traversal mirrors block_cached under the same bucket lock
    // (INV-BIO-ENTRY / INV-BIO-BH).
    {
        let (device_major, device_minor) = (device.major, device.first_minor);
        let cache = get_block_cache();
        let index = cache.hash_index(device_major, device_minor, blocknr);
        let bucket = cache.buckets[index].lock_irqsave();
        let mut current = bucket.head;
        while let Some(entry_ptr) = current {
            let entry = entry_ref(entry_ptr);
            if entry.key == (device_major, device_minor, blocknr)
                && (entry.evicting
                    || entry
                        .bh()
                        .is_some_and(|bh| bh.b_data.len() == cache.block_size as usize))
            {
                // Present (or its eviction still in flight): not
                // provably durable by absence.
                return false;
            }
            current = entry.hash_next;
        }
        true
    }
}

/// Submit ONE async read covering `nblocks` consecutive disk blocks into a
/// single buffer — the coalesced-readahead fast path.
///
/// Every request costs a virtqueue chain (3 descriptors, a header/resp
/// allocation, and one device kick amortized over the batch); under TCG the
/// per-request fixed cost dwarfs the per-byte DMA cost, so a 32-block
/// (128 KiB) request is dramatically cheaper than 32 single-block ones.
///
/// The returned BufferHead is PRIVATE: it is never inserted into the block
/// cache (its odd size would be invisible to `block_size`-guarded lookups
/// anyway). Consume it with `bread_wait`, copy the data out (page-cache
/// inserts), then release it with `bfree_multi` — never `brelse`.
/// A return of None means submission failed (no async support / queue
/// full); the caller falls back to per-block reads.
pub fn bread_async_multi(
    device: &'static blkdev::GenDisk,
    start_blocknr: u64,
    nblocks: u32,
    completion: &super::types::IoCompletion,
) -> Option<*mut BufferHead> {
    if nblocks == 0 {
        return None;
    }
    if nblocks == 1 {
        return bread_async(device, start_blocknr, completion);
    }
    let cache = get_block_cache();
    let block_size = cache.block_size as usize;
    let total = nblocks as usize * block_size;
    let mut bh = Box::new(BufferHead::new_uninit(start_blocknr, total as u32));
    bh.set_device(device);
    bh.set_state_bit(BufferState::BH_Req);
    let sectors_per_block = cache.block_size as u64 / 512;
    // SAFETY-free: device/buffer validity mirrors bread_async Phase 2; the
    // caller keeps the BufferHead (and its Vec) alive until bread_wait.
    if blkdev::blkdev_read_async(
        device,
        start_blocknr * sectors_per_block,
        &mut bh.b_data,
        completion,
    )
    .is_err()
    {
        return None;
    }
    Some(Box::into_raw(bh))
}

/// Free a private multi-block BufferHead from `bread_async_multi`.
///
/// The caller must have waited for its I/O (bread_wait) first — the DMA
/// target must not be freed while the device still writes to it.
///
/// # Safety
/// `bh` must come from `bread_async_multi`, exactly once, and its I/O must
/// have completed.
pub fn bfree_multi(bh: *mut BufferHead) {
    if bh.is_null() {
        return;
    }
    // SAFETY: caller contract above; Box::into_raw in bread_async_multi.
    unsafe { drop(Box::from_raw(bh)) };
}

// ============================================================================
// Plugged writes (batch submit + single drain)
// ============================================================================
//
// The WRITE counterpart of the batch-async-read machinery above, in the
// shape Linux's blk-mq plugging gives ext4 writeback: submit N requests
// without waiting, then wait once for the whole batch. The synchronous
// alternative — one blkdev_write per span, each blocking for its own
// completion — serialized every 64 KiB span write behind a full device
// round trip (measured: the fsync flush wall, ~2048 serialized spans at
// 128 MB ≈ 6.2 s under KVM).
//
// DMA-source stability is the one discipline reads do not have: a write's
// data buffer is READ BY THE DEVICE, so it must stay valid AND UNMODIFIED
// until completion. The batch therefore copies every span into its own
// heap block at submit time (the same copy the synchronous Request path
// makes in blkdev_write), and nothing else references that copy — buffer
// heads can be re-dirtied, re-read, or evicted the moment their bytes are
// staged, and the pins/dirty-clear happen at drain, driven by per-span
// status. Callers that already own a stable, single-owner buffer may skip
// the copy by submitting that buffer's slice — the contract is on the
// BYTES, not on who allocated them.
//
// Ordering: nothing here reorders writes relative to any OTHER submission
// — every chain takes a submission ordinal under the device BLK lock and
// the device executes chains in submission order, so span i+1 leaves the
// device no earlier than span i. Relative to the caller's other I/O, the
// guarantees are exactly the synchronous path's: a write submitted before
// drain() returns is complete (device-acked) when drain() returns, and a
// failed/timed-out span reports its own status — the caller keeps that
// span's buffers dirty for the standing durability points.

impl WriteSlot {
    const EMPTY: WriteSlot = WriteSlot {
        data: WriteSource::Borrowed {
            ptr: core::ptr::null(),
            len: 0,
        },
        completion: super::types::IoCompletion::new(),
        sector: 0,
        dev: None,
    };
}

impl WriteSource {
    #[inline]
    fn as_ptr(&self) -> *const u8 {
        match self {
            WriteSource::Owned(b) => b.as_ptr(),
            WriteSource::Borrowed { ptr, .. } => *ptr,
        }
    }

    #[inline]
    fn as_slice(&self) -> &[u8] {
        match self {
            WriteSource::Owned(b) => b,
            WriteSource::Borrowed { ptr, len } => {
                // SAFETY: the Borrowed variant's contract — `ptr..ptr+len`
                // names the caller's live, unmodified DMA source for the
                // submission window (the write-batch discipline).
                unsafe {
                    if *len == 0 {
                        &[]
                    } else {
                        core::slice::from_raw_parts(*ptr, *len)
                    }
                }
            }
        }
    }

    #[inline]
    fn len(&self) -> usize {
        match self {
            WriteSource::Owned(b) => b.len(),
            WriteSource::Borrowed { len, .. } => *len,
        }
    }
}

impl WriteBatch {
    pub fn new() -> Self {
        Self {
            slots: [const { WriteSlot::EMPTY }; MAX_WRITE_BATCH],
            len: 0,
            results: [0; MAX_WRITE_BATCH],
            results_n: 0,
            deferred: false,
            mode_set: false,
        }
    }

    /// Number of spans currently in flight (not yet drained).
    pub fn in_flight(&self) -> usize {
        self.len
    }

    /// Outcome of entry `i` of the most recent flush (submission order).
    /// 0 = device-acked; negative errno otherwise (a timed-out span's
    /// bytes may not have reached the device — treat like EIO and keep
    /// the span's buffers dirty).
    pub fn status(&self, i: usize) -> i32 {
        if i < self.results_n {
            self.results[i]
        } else {
            -5
        }
    }

    /// Decide the submission mode from the device's capability (first
    /// submit). Returns false when the device has NEITHER SG NOR plain
    /// async write (the caller's synchronous fallback owns the span).
    fn mode_probe(&mut self, device: &'static blkdev::GenDisk) -> bool {
        if !self.mode_set {
            let (has_sg, has_plain) =
                (device.has_async_write_sg(), device.async_write_fn.is_some());
            if !has_sg && !has_plain {
                return false;
            }
            self.deferred = has_sg;
            self.mode_set = true;
        }
        true
    }

    /// Submit one span without waiting. Returns false when the batch
    /// window is full (flush, then retry) or the device has no async
    /// write at all (fall back to a synchronous write for this span —
    /// correctness is unchanged, only the batching is lost).
    ///
    /// In deferred (fusion) mode the span is only RECORDED; the device
    /// submission happens at flush() — see the struct's FUSION note.
    pub fn submit(
        &mut self,
        device: &'static blkdev::GenDisk,
        sector: u64,
        data: &[u8],
    ) -> bool {
        if data.is_empty() || self.len >= MAX_WRITE_BATCH {
            return false;
        }
        if !self.mode_probe(device) {
            return false;
        }
        // The private stable copy: the device DMAs FROM this block, so it
        // must not alias anything the kernel mutates before the drain.
        let owned: Box<[u8]> = alloc::vec::Vec::from(data).into_boxed_slice();
        if self.deferred {
            self.slots[self.len].data = WriteSource::Owned(owned);
            self.slots[self.len].sector = sector;
            self.slots[self.len].dev = Some(device);
            self.len += 1;
            return true;
        }
        // The write-batch contract lives on: `owned` and the slot's inline
        // completion stay valid (and unmodified) until the completion
        // fires — now enforced by the DMA-source discipline comments.
        let rc = blkdev::blkdev_write_async(
            device,
            sector,
            &owned,
            &self.slots[self.len].completion,
        );
        match rc {
            Ok(()) => {
                self.slots[self.len].data = WriteSource::Owned(owned);
                self.slots[self.len].sector = sector;
                self.slots[self.len].dev = Some(device);
                self.len += 1;
                true
            }
            Err(_) => {
                // Submission failed before any chain was built (the PCI
                // path deallocs its own io_buf on failure); the private
                // copy drops here — nothing references it.
                false
            }
        }
    }

    /// Submit one span WITHOUT the private copy: the device DMAs directly
    /// from `data` (the caller's buffer). The caller guarantees the bytes
    /// stay valid and unmodified until the NEXT flush() returns — the
    /// drain waits every entry before giving the buffer back (paired-test
    /// item 1: the DIO write fast path's staging slice). On a completion
    /// timeout the batch cannot leak a borrowed source; it spins on the
    /// completion (a virtio write that outlives a 10 s deadline means the
    /// machine is wedged far beyond this span).
    pub fn submit_ref(
        &mut self,
        device: &'static blkdev::GenDisk,
        sector: u64,
        data: &[u8],
    ) -> bool {
        if data.is_empty() || self.len >= MAX_WRITE_BATCH {
            return false;
        }
        if !self.mode_probe(device) {
            return false;
        }
        if self.deferred {
            self.slots[self.len].data = WriteSource::Borrowed {
                ptr: data.as_ptr(),
                len: data.len(),
            };
            self.slots[self.len].sector = sector;
            self.slots[self.len].dev = Some(device);
            self.len += 1;
            return true;
        }
        // submit_ref contract above: the caller's `data` and the slot's
        // inline completion stay valid (and the bytes unmodified) until
        // the drain.
        let rc = blkdev::blkdev_write_async(
            device,
            sector,
            data,
            &self.slots[self.len].completion,
        );
        match rc {
            Ok(()) => {
                self.slots[self.len].data = WriteSource::Borrowed {
                    ptr: data.as_ptr(),
                    len: data.len(),
                };
                self.slots[self.len].sector = sector;
                self.slots[self.len].dev = Some(device);
                self.len += 1;
                true
            }
            Err(_) => false,
        }
    }

    /// Kick the device once and wait for every in-flight span. Fills
    /// `status(i)` for i in 0..in_flight(), releases the completed
    /// entries, and leaves the batch empty. Returns the first nonzero
    /// status (0 when every span device-acked).
    pub fn flush(&mut self) -> i32 {
        if self.len == 0 {
            return 0;
        }
        if self.deferred {
            self.flush_deferred()
        } else {
            self.flush_immediate()
        }
    }

    /// Legacy flush: spans were already submitted (one chain each) at
    /// submit time; kick once, wait each in order.
    fn flush_immediate(&mut self) -> i32 {
        // One device kick for the whole quietly-submitted batch (the PCI
        // submit path publishes chains quietly; every notify is an MMIO
        // trap). The MMIO device notifies inline per chain — a no-op kick.
        crate::drivers::blkdev::kick_all_pending_disks();

        let n = self.len;
        self.results_n = n;
        let mut first_error = 0i32;
        // SUBMISSION order: slots waited in order; the device completes
        // them in submission order, so the first waiter sleeps while the
        // batch drains behind it.
        for i in 0..n {
            let status = self.slots[i].completion.wait();
            let status = self.wait_status_apply(i, status);
            self.results[i] = status;
            if status != 0 && first_error == 0 {
                first_error = status;
            }
        }
        self.retire_window(n);
        first_error
    }

    /// Post-wait status adjudication for one slot: the zero-serve token
    /// check on success, the leak/EIO split on timeout. Shared by both
    /// flush modes (the deferred mode's group heads use the same rules
    /// against the group's FIRST segment pointer).
    fn wait_status_apply(&mut self, i: usize, status: i32) -> i32 {
        if status == 0 {
            // Attribution guard (the read path's zero-serve analog):
            // the walker stamps the completion with the DMA data
            // pointer of the chain whose completion it delivered. A
            // token mismatch means some OTHER chain's completion fired
            // here — this span's write may not have landed, so its
            // buffers must stay dirty (report EIO, loudly).
            let token = self.slots[i].completion.delivered_token();
            let expected = self.slots[i].data.as_ptr() as usize;
            if token != 0 && token != expected {
                crate::pr_err!(
                    "bio: misattributed write completion (token {:x} != buffer {:x}) — refusing to ack",
                    token,
                    expected
                );
                -5
            } else {
                0
            }
        } else if status == self::WAIT_TIMED_OUT {
            match self.slots[i].data {
                WriteSource::Owned(_) => {
                    // The chain may STILL be in flight: wait() already
                    // tombstoned the device-side pending (abandon) and
                    // drained deliveries, so the walker will never fire
                    // this completion again. The DATA block is still
                    // the device's DMA source and must be LEAKED,
                    // never freed (the freed-kernel-DMA family).
                    core::mem::forget(core::mem::replace(
                        &mut self.slots[i].data,
                        WriteSource::Borrowed {
                            ptr: core::ptr::null(),
                            len: 0,
                        },
                    ));
                    status
                }
                WriteSource::Borrowed { ptr, len } => {
                    // A borrowed source cannot be leaked — the caller
                    // owns the buffer and reuses it after the drain,
                    // and wait() already tombstoned the software
                    // pending so no later delivery can be observed.
                    // A 10 s virtio deadline on this span means the
                    // machine is wedged far beyond it; report the
                    // error (the span's owner keeps the range
                    // unacknowledged) and hand the buffer back — the
                    // same post-timeout discipline the read side's
                    // bfree_multi already carries.
                    crate::pr_err!(
                        "bio: borrowed write span ({} bytes at {:p}) timed out — reporting EIO, buffer returned",
                        len, ptr
                    );
                    status
                }
            }
        } else {
            status
        }
    }

    /// Fused flush (deferred mode): build groups of device-adjacent
    /// spans, submit one SG chain per group (per-span fallback chains on
    /// SG failure), kick once, wait in order, propagate group status to
    /// member slots.
    fn flush_deferred(&mut self) -> i32 {
        const MAX_SEGS: usize = crate::drivers::virtio::MAX_SG_SEGS_PER_CHAIN;
        let n = self.len;
        self.results_n = n;

        // Per-slot submission state for this flush:
        //  - group_head[i] = Some(h): slot i is a MEMBER of the SG group
        //    headed at h (head included; h's completion carries the chain).
        //  - None: the slot got its OWN chain (per-span fallback) — its
        //    own completion is waited, or it never submitted (-5).
        let mut group_head: [Option<usize>; MAX_WRITE_BATCH] = [None; MAX_WRITE_BATCH];
        let mut span_armed: [bool; MAX_WRITE_BATCH] = [false; MAX_WRITE_BATCH];

        // ---- Phase 1: group + submit (quiet) ----
        let mut i = 0usize;
        while i < n {
            // Extend the group while the next span is device-adjacent
            // (same device, sector-contiguous, whole-sector lengths) and
            // the segment cap leaves room. Two integer compares per span
            // — the reference's back-merge test.
            let adj = |a: usize, b: usize| -> bool {
                let same_dev = match (self.slots[a].dev, self.slots[b].dev) {
                    (Some(x), Some(y)) => core::ptr::eq(x, y),
                    _ => false,
                };
                same_dev
                    && self.slots[a].sector + (self.slots[a].data.len() / 512) as u64
                        == self.slots[b].sector
                    && self.slots[a].data.len() % 512 == 0
            };
            let mut e = i + 1;
            while e < n && (e - i) < MAX_SEGS && adj(e - 1, e) {
                e += 1;
            }

            // Build the segment list from the group's slots.
            let mut segs: [blkdev::DmaSeg; MAX_SEGS] = [blkdev::DmaSeg {
                ptr: core::ptr::null_mut(),
                len: 0,
            }; MAX_SEGS];
            let k = e - i;
            for (j, s) in segs.iter_mut().take(k).enumerate() {
                s.ptr = self.slots[i + j].data.as_ptr() as *mut u8;
                s.len = self.slots[i + j].data.len();
            }
            let dev = self.slots[i].dev;
            let sector0 = self.slots[i].sector;
            // dev is a registered GenDisk (recorded at submit); every
            // segment's buffer stays a stable DMA source until this
            // flush's waits return — the write-batch contract.
            let submitted = match dev {
                Some(d) => blkdev::blkdev_write_async_sg(
                    d,
                    sector0,
                    &segs[..k],
                    &self.slots[i].completion,
                ),
                None => Err(-5),
            };
            match submitted {
                Ok(()) => {
                    for si in i..e {
                        group_head[si] = Some(i);
                    }
                }
                Err(_) => {
                    // SG submit refused (window lag, held budget, tiny
                    // queue): per-span fallback — each span takes its own
                    // 3-descriptor chain. A span that also fails to submit
                    // reports EIO unwaited (its buffers stay dirty; the
                    // standing durability points retry).
                    for si in i..e {
                        let d = self.slots[si].data.as_slice();
                        // Same dev/sector contract as the SG arm.
                        let rc = match dev {
                            Some(disk) => blkdev::blkdev_write_async(
                                disk,
                                self.slots[si].sector,
                                d,
                                &self.slots[si].completion,
                            ),
                            None => Err(-5),
                        };
                        if rc.is_ok() {
                            span_armed[si] = true;
                        } else {
                            self.results[si] = -5;
                        }
                    }
                }
            }
            i = e;
        }

        // ---- Phase 2: kick + wait ----
        // One kick for the whole window (chains were published quietly).
        crate::drivers::blkdev::kick_all_pending_disks();

        let mut first_error = 0i32;
        // Group heads and fallback spans, in slot order — the device
        // executes chains in submission order, so this wait order keeps
        // the first waiter sleeping while the window drains behind it.
        for si in 0..n {
            match group_head[si] {
                Some(h) if h == si => {
                    // SG group head: wait the group's chain once.
                    let status = self.slots[h].completion.wait();
                    let status = self.wait_status_apply(h, status);
                    // Propagate to every member slot. On timeout the
                    // head's data source was already leaked/returned by
                    // wait_status_apply; MEMBER sources are still the
                    // device's DMA targets and need the same discipline.
                    // Find the group's end (slots sharing this head).
                    let mut e = si + 1;
                    while e < n && group_head[e] == Some(h) {
                        e += 1;
                    }
                    for m in si..e {
                        let st = if status == 0 {
                            0
                        } else if status == self::WAIT_TIMED_OUT {
                            match self.slots[m].data {
                                WriteSource::Owned(_) => {
                                    // Same leak discipline as the head: the
                                    // fused chain (still possibly in flight)
                                    // DMAs from this block too.
                                    core::mem::forget(core::mem::replace(
                                        &mut self.slots[m].data,
                                        WriteSource::Borrowed {
                                            ptr: core::ptr::null(),
                                            len: 0,
                                        },
                                    ));
                                    status
                                }
                                WriteSource::Borrowed { ptr, len } => {
                                    crate::pr_err!(
                                        "bio: borrowed fused write span ({} bytes at {:p}) timed out — reporting EIO, buffer returned",
                                        len, ptr
                                    );
                                    status
                                }
                            }
                        } else {
                            // Real device error: the chain COMPLETED (EIO
                            // from the device) — DMA done, sources freed
                            // normally at retire.
                            status
                        };
                        self.results[m] = st;
                    }
                    if status != 0 && first_error == 0 {
                        first_error = status;
                    }
                }
                Some(_) => {
                    // Group member: status was set by its head above.
                    if self.results[si] != 0 && first_error == 0 {
                        first_error = self.results[si];
                    }
                }
                None => {
                    if span_armed[si] {
                        // Per-span fallback chain: the legacy wait.
                        let status = self.slots[si].completion.wait();
                        let status = self.wait_status_apply(si, status);
                        self.results[si] = status;
                    }
                    // else: unsubmitted (-5 already recorded).
                    if self.results[si] != 0 && first_error == 0 {
                        first_error = self.results[si];
                    }
                }
            }
        }

        self.retire_window(n);
        first_error
    }

    /// Retire the window: drop each live slot's data source (an Owned
    /// box's plain scope-end — safe on every completed path: the walker
    /// fired the completion, the delivery handshake drained inside
    /// wait(), and the chain's DMA is done, so the block is once again
    /// ordinary heap; timed-out Owned boxes were already leaked above)
    /// and re-arm the completion for the next window (the direct-read
    /// batch's stack-array discipline).
    fn retire_window(&mut self, n: usize) {
        for i in 0..n {
            self.slots[i].data = WriteSource::Borrowed {
                ptr: core::ptr::null(),
                len: 0,
            };
            self.slots[i].completion.reset();
            self.slots[i].sector = 0;
            self.slots[i].dev = None;
        }
        self.len = 0;
    }
}

impl Default for WriteBatch {
    fn default() -> Self {
        Self::new()
    }
}

impl Drop for WriteBatch {
    /// Safety net: an abandoned batch never leaves device-side pendings
    /// pointing at freed memory — drain it. Normally unreachable (the
    /// flush owner drains explicitly); a panic-unwind or an early return
    /// still lands here in task context, where sleeping is legal.
    fn drop(&mut self) {
        if self.len != 0 {
            let _ = self.flush();
        }
    }
}

/// Batched write-through push for a set of block-cache buffers
/// (paired-test item 3, 2026-11-17): pins each block, optionally marks
/// it dirty (the commit write-through belt), submits ONE device write
/// per dirty buffer through 32-span windows with a single drain per
/// window, clears BH_Dirty only for device-acked spans, and releases
/// every pin. Publication-constrained blocks and any span the device
/// refuses keep the ordered serial `sync_dirty_buffer` path — a
/// correctness fallback, only the batching is lost.
///
/// The caller must guarantee the buffers' bytes stay unmodified across
/// the call (the ext4 callers hold EXT4_BIG_LOCK, the same
/// serialization SpanFlusher::drain applies to its settle).
pub fn sync_dirty_blocks_batched(
    device: &'static blkdev::GenDisk,
    blocks: &[u64],
    force_dirty: bool,
) -> i32 {
    fn drain(
        batch: &mut WriteBatch,
        pinned: &mut alloc::vec::Vec<*mut BufferHead>,
        first_err: &mut i32,
    ) {
        if batch.in_flight() == 0 {
            return;
        }
        let rc = batch.flush();
        if rc != 0 && *first_err == 0 {
            *first_err = rc;
        }
        for (i, &bh) in pinned.iter().enumerate() {
            if batch.status(i) == 0 {
                // SAFETY: bh is pinned (bread below); device-acked write.
                bh_pinned(&bh).clear_state_bit(BufferState::BH_Dirty);
            }
            // SAFETY: pin balanced by bread below.
            get_block_cache().put(bh);
        }
        pinned.clear();
    }

    let spb = get_block_cache().block_size as u64 / 512;
    let (mj, mi) = (device.major, device.first_minor);
    let mut batch = WriteBatch::new();
    let mut pinned: alloc::vec::Vec<*mut BufferHead> = alloc::vec::Vec::new();
    let mut first_err = 0i32;

    for &blk in blocks {
        // SAFETY: bread returns a pinned BufferHead for the block or None.
        let bh = match bread(device, blk) {
            Some(b) => b,
            None => {
                if first_err == 0 {
                    first_err = 5; // EIO
                }
                break;
            }
        };
        // bh is valid and pinned for this iteration.
        {
            // SAFETY: pinned by bread above.
            if force_dirty {
                bh_pinned(&bh).set_state_bit(BufferState::BH_Dirty);
            }
            // SAFETY: same pin.
            if !unsafe { (*bh).is_dirty() } {
                get_block_cache().put(bh);
                continue;
            }
        }
        // Ordered-publication guard: constrained blocks take the serial
        // path that satisfies their pre/entry/post obligations first.
        if publication_constrained(mj, mi, blk) {
            {
                let _ = sync_dirty_buffer(bh);
                get_block_cache().put(bh);
            }
            continue;
        }
        // bh is pinned and its bytes are caller-stabilized; the span
        // drains before this function returns.
        // SAFETY: pinned; b_data read spans the drain window.
        let submitted = batch.submit_ref(device, blk * spb, &bh_pinned(&bh).b_data);
        if submitted {
            pinned.push(bh);
        } else {
            drain(&mut batch, &mut pinned, &mut first_err);
            // SAFETY: same pinned window.
            let retried = batch.submit_ref(device, blk * spb, &bh_pinned(&bh).b_data);
            if retried {
                pinned.push(bh);
            } else {
                {
                    let _ = sync_dirty_buffer(bh);
                    get_block_cache().put(bh);
                }
            }
        }
    }
    drain(&mut batch, &mut pinned, &mut first_err);
    first_err
}

/// Sync a dirty buffer to disk
///
/// Lazy write-back: while the current task holds an active ext4 journal
/// handle, the sync is deferred — the buffer simply stays BH_Dirty. This
/// covers ALL metadata writes inside a write(2)/create transaction (data
/// blocks, inode table, bitmaps, group descriptors, extent trees,
/// directory blocks): a synchronous virtio round trip per sync (~10-20ms
/// under TCG) made every small-write workload — each LTP test's setup
/// phase — blow the 30s wall-clock timeout (the r5 "post-exec hang"
/// family). Persistence is restored at the batch points: the journal
/// commit's write-through fast path (registered buffers), fsync/sync
/// (ext4_sync_file flushes the file's data blocks and forces the
/// transaction to commit; sync(2) writes the whole cache), and
/// buffer-cache eviction (dirty victims are synced before reuse).
pub fn sync_dirty_buffer(bh: *const BufferHead) -> Result<(), i32> {
    // The current task's journal-handle slot (type-erased, rung-5;
    // null-safe outside task ctx).
    let journal_active = !self::current_handle_raw().is_null();
    if journal_active {
        crate::debug::fsw::note_sync_dirty_skip();
        return Ok(());
    }
    crate::debug::fsw::note_sync_dirty();
    // Ordered-publication guard: this buffer may be a pending entry/post
    // block whose order constraints a plain sync would violate. Satisfy
    // THIS block's constraints first (per-block closure — the journal
    // commit's write-through path and every inline metadata sync come
    // through here, so the guard must not drain the world's backlog).
    // bh is a raw pointer returned by bread() (INV-BIO-PIN).
    {
        // SAFETY: pinned by the caller's refcount; read-only.
        let bh_ref: &BufferHead = unsafe { &*bh };
        if let Some(dev) = bh_ref.b_device {
            let (mj, mi) = dev_key(dev);
            if publication_constrained(mj, mi, bh_ref.b_blocknr) {
                let _ = flush_publication_constraints(mj, mi, bh_ref.b_blocknr);
            }
        }
    }
    // SAFETY: bh is a raw pointer returned by bread(); it points to a valid
    // BufferHead owned by a CacheEntry in the cache.
    unsafe {
        let bh_ref = &*bh;
        bh_ref.sync()
    }
}

/// Sync all dirty buffers
pub fn sync_buffers() -> Result<(), i32> {
    // Durability point: ordered publications must go out first (a plain
    // hash-order drain could persist an entry block before its metadata).
    let _ = flush_publications();
    crate::debug::fsw::note_sync_all();
    get_block_cache().sync_all()
}

/// Sync all dirty buffers of ONE device, optionally skipping one block.
///
/// Unlike sync_dirty_buffer this flushes regardless of any active ext4
/// journal handle.
pub fn sync_device_buffers_excluding(
    device: &'static crate::drivers::blkdev::GenDisk,
    skip: Option<u64>,
) -> Result<(), i32> {
    // Ordered-publication guard (same rationale as sync_buffers).
    let _ = flush_publications();
    get_block_cache().sync_all_excluding(device, skip)
}

/// Initialize block cache (lazy init on first use)
pub fn bio_init() {
    // Cache auto-initializes on first use
}

// ============================================================================
// Deferred entry-publication ordering (crash-safe batching)
// ============================================================================
//
// Replaces the per-operation synchronous entry barrier (ae288274) with a
// deferred, ordered drain. The barrier flushed the running transaction's
// buffers + every other dirty buffer of the device + the entry block
// itself on EVERY directory-entry publication (creat/mkdir/link/symlink/
// rename-add/unlink/rmdir/rename-replace) — 4-8 synchronous virtio round
// trips (~10-20ms each under TCG) per operation. Any workload that
// creates or removes a few hundred files (LTP creat05/fork09 open 1021
// files in their setup loops) blew the 30s per-test wall clock with the
// kernel merely crawling, not wedged.
//
// The crash-safety contract stays exactly the one the barrier bought
// (the "ghost empty file" fix): a directory entry block must never reach
// the disk before the metadata that initializes the inode it names
// (create side), and an inode/bitmap FREE must never reach the disk
// before the entry removal that makes the free safe (delete side — the
// cross-link twin). Deferring does not weaken this as long as the write
// ORDER at every durability point is: a publication's `pre` blocks,
// then its `entry` block, then its `post` blocks.
//
// Structure: each publishing operation appends one `Publication` record
// to PENDING_PUBLICATIONS:
//   - create side: the operation brackets itself with a PRE capture
//     window on its jbd2 handle (begin_pre_capture); every buffer it
//     marks dirty lands on the handle's list, and at the entry write
//     that list becomes the record's `pre` (an EXACT snapshot of this
//     operation's own metadata — bitmaps, inode table block, group
//     descriptors, superblock counters; the earlier device-wide dirty
//     snapshot was a correct superset but cost O(cache) per op and grew
//     the pre sets O(N) across un-drained create loops, which is what
//     kept LTP creat05/fork09 — 1021 files in setup — over the 30s cap
//     even after the synchronous barrier was removed), entry = the
//     directory block being published, post = []
//   - delete side: entry = the directory block the entry was removed
//     from, pre = [], and the frees that follow in the same operation are
//     captured into `post` by arming a POST capture window on the task's
//     journal handle (every dirty-marking funnels through
//     BufferHead::set_state_bit, which appends to the publication).
//
// Durability points call flush_publications(), which processes pending
// records IN APPEND ORDER (the causal order of the operations), each
// record pre -> entry -> post. Because the buffer cache is a single
// cumulative copy of every block, writing a block always persists its
// newest content; the per-record order is what keeps the crash windows
// closed. A `post` capture that arrives after its record was flushed
// (concurrent flush on another CPU) is appended as a fresh post-only
// record at the END of the queue — still after the entry it follows.
//
// Durability points satisfy the ordering contract for exactly the blocks
// they write (see the scoped-draining section below): fsync/fdatasync and
// the mkdir publication point flush the CALLING task's own records
// (flush_publications_scoped — per-record cookies); the forced jbd2 commit,
// inline single-buffer syncs, and buffer-cache eviction write order-
// constrained blocks only after flush_publication_constraints satisfied
// THAT block's obligations; sync(2)/syncfs/shutdown keep the whole-queue
// drain (flush_publications) because they write every dirty buffer anyway.
// A create-heavy workload bounds the queue via a high-water drain that the
// producer itself pays (see PUB_HIGH_WATER).
//
// Locking: PENDING_PUBLICATIONS is a Spinlock<Vec<_>> that is NEVER held
// across I/O (flush snapshots with mem::take and syncs lock-free). The
// capture hook may take it while the caller holds a bucket lock (the
// cache-internal dirty paths) — nesting is bucket -> PENDING only; the
// flush path takes PENDING without any bucket lock, so the order is
// acyclic.

static PENDING_PUBLICATIONS: Spinlock<PendingPublications> =
    Spinlock::new(PendingPublications::new());

impl PendingPublications {
    pub const fn new() -> Self {
        PendingPublications {
            list: Vec::new(),
            index: alloc::collections::BTreeMap::new(),
        }
    }
    fn index_record(index: &mut alloc::collections::BTreeMap<((u32, u32), u64), u32>, r: &Publication) {
        if let Some(e) = r.entry {
            *index.entry((r.device, e)).or_insert(0) += 1;
        }
        for &b in &r.post {
            *index.entry((r.device, b)).or_insert(0) += 1;
        }
    }
    pub fn push(&mut self, r: Publication) {
        Self::index_record(&mut self.index, &r);
        self.list.push(r);
    }
    /// Post-block capture on an existing record (the delete-side window).
    pub fn post_capture(&mut self, capture_id: u64, blocknr: u64) {
        for p in self.list.iter_mut().rev() {
            if p.id == capture_id {
                if !p.post.contains(&blocknr) {
                    p.post.push(blocknr);
                    *self.index.entry((p.device, blocknr)).or_insert(0) += 1;
                }
                return;
            }
        }
    }
    /// Wholesale take (the drain-snapshot pattern): empties both halves.
    pub fn take_list(&mut self) -> Vec<Publication> {
        self.index.clear();
        core::mem::take(&mut self.list)
    }
    /// Wholesale replace (the requeue pattern): rebuilds the index once.
    pub fn set_list(&mut self, v: Vec<Publication>) {
        self.index.clear();
        for r in &v {
            Self::index_record(&mut self.index, r);
        }
        self.list = v;
    }
    pub fn is_empty(&self) -> bool {
        self.list.is_empty()
    }
    pub fn len(&self) -> usize {
        self.list.len()
    }
    pub fn iter(&self) -> core::slice::Iter<'_, Publication> {
        self.list.iter()
    }
    /// H1/H2 membership: is this (device, block) any pending record's
    /// entry or post block?
    pub fn constrained(&self, mj: u32, mi: u32, blocknr: u64) -> bool {
        self.index.contains_key(&((mj, mi), blocknr))
    }
}
static NEXT_PUBLICATION_ID: AtomicU64 = AtomicU64::new(1);

/// Queue-length high-water mark: once crossed, the NEXT publication_defer
/// runs a bounded full drain (PUB_HIWAT_BATCHES batches) so a create-heavy
/// workload with no global sync(2) cannot grow the queue (and the O(queue)
/// scans of every scoped flush) without bound. The creator pays — it is
/// the task generating the backlog.
const PUB_HIGH_WATER: usize = 2048;

/// Op-boundary batch threshold (the fab0e029 prescription: records batch
/// per transaction window). With the per-mkdir scoped drain deleted, the
/// queue legitimately grows between durability points; this bounds it far
/// below PUB_HIGH_WATER so that (a) an out-of-band writer that hits a
/// constrained block (eviction victim, journal write-through) is
/// constrained by at most this many records' worth of dirty blocks, and
/// (b) the O(queue) snapshot scan of any scoped flush stays trivial.
/// The entry op whose record crosses the line pays ONE ordered whole-queue
/// drain (flush_publications) — amortized over PUB_BATCH operations, not
/// per operation. 64: small enough that a constraint flush's residual
/// I/O is a handful of unique blocks, large enough that the drain cost
/// amortizes below 1 block-write per op.
const PUB_BATCH: usize = 64;

/// Op-boundary publication batch drain: called at every ext4 journal-stop
/// bracket close (all entry mutations funnel through ext4_journal_stop).
/// O(1) queue-length check; drains only when the batch threshold is
/// crossed. See PUB_BATCH.
pub fn publication_batch_drain() {
    let over = {
        let pend = PENDING_PUBLICATIONS.lock();
        !pend.is_empty() && pend.len() >= PUB_BATCH
    };
    if over {
        crate::debug::fsw::note_pub_batch();
        // Whole queue, append order (pre -> entry -> post per record).
        // No ext4 locks are held by this path (PENDING is a leaf lock;
        // the I/O runs lock-free), so this cannot deadlock against the
        // caller's ENTRY_MUTEX/BIG_LOCK.
        let _ = flush_publications();
    }
}
/// Batches per high-water drain (each batch is one full ordered pass; see
/// flush_publications_bounded). Leftover records stay pending, ordered.
const PUB_HIWAT_BATCHES: u32 = 2;

/// Current task's publication cookie (0 when no task context exists).
fn publication_cookie() -> u64 {
    match crate::sched::current() {
        Some(t) => t as *mut _ as u64,
        None => 0,
    }
}

fn dev_key(device: &blkdev::GenDisk) -> (u32, u32) {
    (device.major, device.first_minor)
}

/// Public (major, minor) of a GenDisk — used by ext4 to address a
/// handle's post-capture window to the right device.
pub fn dev_key_of(device: &blkdev::GenDisk) -> (u32, u32) {
    dev_key(device)
}

/// Defer a create-side entry publication: `pre_blocks` must be persisted
/// before `entry_block`. Returns the record id (used by the delete-side
/// capture; create-side callers ignore it).
pub fn publication_defer(
    device: &blkdev::GenDisk,
    pre_blocks: &[u64],
    entry_block: u64,
) -> u64 {
    let id = NEXT_PUBLICATION_ID.fetch_add(1, Ordering::Relaxed);
    let mut pre = Vec::with_capacity(pre_blocks.len());
    for &b in pre_blocks {
        if b != entry_block && !pre.contains(&b) {
            pre.push(b);
        }
    }
    let mut over_hiwat = false;
    {
        let mut pend = PENDING_PUBLICATIONS.lock();
        pend.push(Publication {
            id,
            device: dev_key(device),
            pre,
            entry: Some(entry_block),
            post: Vec::new(),
            cookie: publication_cookie(),
        });
        over_hiwat = pend.len() > PUB_HIGH_WATER;
        crate::debug::fsw::note_pub_qmax(pend.len());
    }
    if over_hiwat {
        // Bounded ordered drain by the backlog's own producer (see
        // PUB_HIGH_WATER). No locks are held here and this runs in the
        // creator's syscall context, exactly where the old synchronous
        // barrier used to run.
        crate::debug::fsw::note_pub_hiwat();
        let _ = flush_publications_bounded(PUB_HIWAT_BATCHES);
    }
    id
}

/// Defer a delete-side entry publication: `entry_block` (the directory
/// block the entry was removed from) must persist BEFORE the frees the
/// caller performs next, which it captures via
/// jbd2::Handle::begin_post_capture. Returns the record id.
pub fn publication_defer_entry_only(
    device: &blkdev::GenDisk,
    entry_block: u64,
) -> u64 {
    let id = NEXT_PUBLICATION_ID.fetch_add(1, Ordering::Relaxed);
    let mut over_hiwat = false;
    {
        let mut pend = PENDING_PUBLICATIONS.lock();
        pend.push(Publication {
            id,
            device: dev_key(device),
            pre: Vec::new(),
            entry: Some(entry_block),
            post: Vec::new(),
            cookie: publication_cookie(),
        });
        over_hiwat = pend.len() > PUB_HIGH_WATER;
        crate::debug::fsw::note_pub_qmax(pend.len());
    }
    if over_hiwat {
        crate::debug::fsw::note_pub_hiwat();
        let _ = flush_publications_bounded(PUB_HIWAT_BATCHES);
    }
    id
}

/// Capture hook armed by jbd2::Handle's capture windows, driven from
/// BufferHead::set_state_bit(BH_Dirty):
/// - PRE mode (create side): the block is appended to the handle's
///   h_pre_list — the exact "this operation's own metadata" set that
///   becomes the publication's `pre` at the entry write. Replaces the
///   earlier device-wide dirty snapshot, which cost O(cache) per op and
///   grew the pre sets O(N) across un-drained create loops (LTP
///   creat05/fork09: 1021 files in setup).
/// - POST mode (delete side): the block is appended to the `post` set of
///   the addressed publication record.
/// Runs in the dirty-marking hot path; the unarmed fast path is two loads
/// (task, handle).
fn publication_capture_note_dirty(
    device: Option<&'static blkdev::GenDisk>,
    blocknr: u64,
) {
    use crate::fs::{hotpath::CAPTURE_POST, hotpath::CAPTURE_PRE, types::JournalCaptureState};
    let dev = match device {
        Some(d) => d,
        None => return,
    };
    let task = match crate::sched::current() {
        Some(t) => t,
        None => return,
    };
    // The task slot is type-erased (rung-5): the jbd2 Handle type is
    // crate-owned. The unarmed fast path stays TWO loads (task, slot).
    let hptr: *mut () = { (*task).journal_handle.get() };
    if hptr.is_null() {
        return;
    }
    // SAFETY: INV-JSEAM-1 (fs/journal_seam.rs) — the pointer is a
    // jbd2 Handle whose FIRST field (repr(C)) is the capture header;
    // the handle lives on the owner task's stack for the whole syscall
    // (see namei::set_current_handle).
    let hc: &JournalCaptureState = unsafe { &*(hptr as *const JournalCaptureState) };
    let (mode, capture_id, capture_dev) =
        (hc.mode.get(), hc.post_id.get(), hc.dev_key.get());
    if capture_dev != dev_key(dev) {
        return;
    }
    match mode {
        CAPTURE_PRE => {
            // Same-task access (the hook runs in the owner's syscall
            // context); the Spinlock also covers any stray cross-CPU
            // marker (harmless superset — see the design note).
            hc.pre_push(blocknr);
        }
        CAPTURE_POST => {
            let mut pend = PENDING_PUBLICATIONS.lock();
            pend.post_capture(capture_id, blocknr);
            // The record was flushed while our capture window was open
            // (another CPU hit a durability point). Append a post-only
            // record at the END of the queue — still after the entry
            // removal, which that flush persisted before returning.
            pend.push(Publication {
                id: capture_id,
                device: dev_key(dev),
                pre: Vec::new(),
                entry: None,
                post: vec![blocknr],
                cookie: publication_cookie(),
            });
        }
        _ => {}
    }
}

/// Is this block a pending `entry` or `post` block (order-constrained,
/// must not be persisted out of band)?
pub fn publication_constrained(mj: u32, mi: u32, blocknr: u64) -> bool {
    PENDING_PUBLICATIONS.lock().constrained(mj, mi, blocknr)
}

// ============================================================================
// Scoped publication draining (the leg-29A/30A O(pending) fix)
// ============================================================================
//
// The ordering contract every flush must preserve, stated over the
// cumulative buffer cache (writing any block persists its NEWEST content,
// so "record R's entry add reached disk" happens whenever anyone writes
// that dir block, not only when R itself is flushed):
//
//   H1 (no ghost file):  before ANY write of a block that is a pending
//                       record's `entry`, that record's `pre` blocks are
//                       on disk.
//   H2 (no cross-link):  before ANY write of a block in a pending record's
//                       `post`, that record's `entry` content is on disk
//                       (and by H1, that entry's own prerequisites too).
//
// The old implementation satisfied H1/H2 by draining the ENTIRE queue at
// every durability point. Under create churn (OH provisioning, thousands
// of publications) that made every fsync/fdatasync/mkdir pay the world's
// backlog — and the drain's racing-publisher loop could run unbounded
// (sc310's hiview fdatasync pinned for 43 min). The scoped forms below
// satisfy H1/H2 for exactly the blocks they (or their caller) are about
// to write:
//
//   - flush_publications_scoped(): the calling task's OWN records are
//     published in full (pre -> entry -> post), plus the minimal
//     cross-record obligations for every block in that write plan
//     (foreign records' pres/entries when blocks are shared). Foreign
//     records are never finished here; they stay pending and keep their
//     obligations for later writers.
//   - flush_publication_constraints(): H1/H2 for ONE block the caller is
//     about to write out-of-band (journal-commit registered buffers,
//     single-buffer sync, eviction victims).
//   - flush_publications(): whole queue, append order — unchanged, for
//     the true global points (sync(2)/syncfs/shutdown) that write every
//     dirty buffer anyway.
//
// Cross-record note (pre-existing, unchanged class): a shared metadata
// block (inode table/bitmap) dirtied by several pending records carries
// all their effects; the append-order drain writes it "at first mention",
// which can persist a later record's free before its own entry removal —
// the same mid-drain window the whole-queue drain has always had. The
// scoped flush keeps exactly that class: it orders pre -> entry -> post
// per record, and satisfies H1/H2 for every block IT writes.
//
// Locking: PENDING is a leaf lock (also taken under bucket locks by the
// capture hook). Every function here snapshots with mem::take, releases,
// does I/O lock-free, then re-merges under a fresh hold. Foreign records
// are re-merged BEFORE any records appended during the I/O (append order
// preserved).

impl WritePlan {
    fn new() -> Self {
        WritePlan { pre: Vec::new(), entry: Vec::new(), post: Vec::new(), entry_role: Vec::new() }
    }

    fn note_queue_entries(&mut self, pend: &[Publication], dev: (u32, u32)) {
        for p in pend {
            if p.device != dev {
                continue;
            }
            if let Some(e) = p.entry {
                if !self.entry_role.contains(&e) {
                    self.entry_role.push(e);
                }
            }
        }
    }

    fn push_pre(&mut self, b: u64) {
        // An entry-role block scheduled as someone's pre must NOT go out
        // in the pre phase (its own H1 pres are only guaranteed before
        // the entry phase). Push it to the entry phase instead — still
        // before all posts.
        if self.entry_role.contains(&b) {
            self.push_entry(b);
            return;
        }
        if !self.pre.contains(&b) {
            self.pre.push(b);
        }
    }

    fn push_entry(&mut self, b: u64) {
        if !self.entry.contains(&b) && !self.pre.contains(&b) {
            self.entry.push(b);
        }
    }

    fn push_post(&mut self, b: u64) {
        // Same exclusion as push_pre: a block that is a pending record's
        // entry anywhere in the plan must not go out before the entry
        // phase (its own H1 pres precede it there).
        if self.entry_role.contains(&b) {
            self.push_entry(b);
            return;
        }
        if !self.post.contains(&b) && !self.pre.contains(&b) && !self.entry.contains(&b) {
            self.post.push(b);
        }
    }
}

/// Grow `plan` until every H1/H2 obligation for every block it schedules
/// is itself scheduled earlier: a pending record whose `entry` is anywhere
/// in the plan contributes its pres (H1 — writing that entry-block
/// content, even as another record's pre or the caller's own out-of-band
/// write, publishes it); a pending record whose `post` intersects the plan
/// contributes its entry (H2) — and that entry then pulls its own H1 set.
/// Converges: every iteration either adds a block or stops.
///
/// Round-capped with a conservative fallback — ALLOCATION-FREE on purpose.
/// The closure is reachable from journal commits and buffer eviction under
/// spinlocks, so it must not enter the allocator (an earlier index+worklist
/// version allocated per mention and correlated with whole-boot allocator
/// class-lock wedges: samgr's workers frozen in RawVec finish_grow for
/// 293s, lb234/lb235). The unbounded round loop was the original crawl
/// engine instead: each round rescans every pending record against the
/// whole plan, and the plan grows a few blocks per round — thousands of
/// quadratic rounds burned 18+ MINUTES in one durability point (lb229:
/// distributeddata's OS_IPC_0_912 frozen at push_entry for the whole 1092s
/// store-load window). Now: at most MAX_ROUNDS cheap rounds, then one
/// linear conservative pass scheduling EVERY record's pres and entries of
/// the device (a strict superset of the true closure, same pre->entry
/// phase discipline) — deep dependency chains cost one linear pass, and
/// the pathological backlog actually drains. A cond_resched checkpoint
/// every other round bounds the latency added to the rest of the CPU (the
/// loop body is lock-free task context).
fn plan_add_constraints(plan: &mut WritePlan, pend: &[Publication], dev: (u32, u32)) {
    const MAX_ROUNDS: usize = 3;
    for round in 0..MAX_ROUNDS {
        let mut grew = false;
        for p in pend {
            if p.device != dev {
                continue;
            }
            // H2: some block we schedule carries this record's frees.
            let post_hit = p.post.iter().any(|b| plan.scheduled(*b));
            if post_hit {
                if let Some(e) = p.entry {
                    if !plan.scheduled(e) {
                        plan.push_entry(e);
                        grew = true;
                    }
                }
                // post-only stragglers (entry None) need nothing: the
                // flush that raced their capture persisted the entry
                // before the straggler was appended.
            }
            // H1: some block we schedule IS this record's entry.
            if let Some(e) = p.entry {
                if plan.scheduled(e) && !plan.scheduled_pre_of(p) {
                    for &b in &p.pre {
                        let before = plan.pre.len() + plan.entry.len();
                        plan.push_pre(b);
                        if plan.pre.len() + plan.entry.len() > before {
                            grew = true;
                        }
                    }
                }
            }
        }
        if !grew {
            return;
        }
        if round % 2 == 1 {
            crate::sched::cond_resched();
        }
    }
    // Closure not converged within the round cap: the dependency chain is
    // deep (heavy churn). Schedule EVERY record of the device — a strict
    // superset of the true closure with the same phase discipline (all
    // pres, then all entries; posts are only ever written by the owning
    // flush in the post phase, which now follows every entry). One linear
    // pass; obligations are force-satisfied early, never late.
    for p in pend {
        if p.device != dev {
            continue;
        }
        for &b in &p.pre {
            plan.push_pre(b);
        }
        if let Some(e) = p.entry {
            plan.push_entry(e);
        }
    }
}

impl WritePlan {
    fn scheduled(&self, b: u64) -> bool {
        self.pre.contains(&b) || self.entry.contains(&b) || self.post.contains(&b)
    }
    /// True when this record's pres are already all scheduled (H1 done).
    fn scheduled_pre_of(&self, p: &Publication) -> bool {
        p.pre.iter().all(|b| self.scheduled(*b))
    }
}

/// Flush the CALLING TASK's own publications (and nothing else of other
/// tasks'), in dependency-safe order. Called from per-task durability
/// points: ext4_sync_file (fsync/fdatasync) and the mkdir entry-publication
/// point. A task with no pending records does one O(queue) scan and zero
/// I/O — the hiview/accesstoken fdatasync case under foreign churn.
pub fn flush_publications_scoped() -> Result<(), i32> {
    let cookie = publication_cookie();
    loop {
        let mut snapshot = PENDING_PUBLICATIONS.lock().take_list();
        let mine: Vec<usize> = snapshot
            .iter()
            .enumerate()
            .filter(|(_, p)| p.cookie == cookie && p.cookie != 0)
            .map(|(i, _)| i)
            .collect();
        if mine.is_empty() {
            // Requeue the untouched snapshot (records may have been
            // appended during our scan; snapshot is older — prepend).
            if !snapshot.is_empty() {
                let mut pend = PENDING_PUBLICATIONS.lock();
                let rest = pend.take_list();
                snapshot.extend(rest);
                pend.set_list(snapshot);
            }
            return Ok(());
        }
        crate::debug::fsw::note_pub_scoped(mine.len());

        // One plan per device (a task may publish on several mounted
        // filesystems; blocks and obligations are device-keyed, so the
        // per-device closures are independent).
        let mut devs: Vec<(u32, u32)> = Vec::new();
        for &i in &mine {
            if !devs.contains(&snapshot[i].device) {
                devs.push(snapshot[i].device);
            }
        }
        let mut first_err: i32 = 0;
        for dev in &devs {
            let mut plan = WritePlan::new();
            plan.note_queue_entries(&snapshot, *dev);
            for &i in &mine {
                let p = &snapshot[i];
                if p.device != *dev {
                    continue;
                }
                for &b in &p.pre {
                    plan.push_pre(b);
                }
                if let Some(e) = p.entry {
                    plan.push_entry(e);
                }
                for &b in &p.post {
                    plan.push_post(b);
                }
            }
            plan_add_constraints(&mut plan, &snapshot, *dev);

            for phase in [&plan.pre, &plan.entry, &plan.post] {
                for &b in phase {
                    if let Err(e) = sync_block_ordered(*dev, b) {
                        if first_err == 0 {
                            first_err = e;
                        }
                        break;
                    }
                }
                if first_err != 0 {
                    break;
                }
            }
            if first_err != 0 {
                break;
            }
        }
        // Requeue: on success only the untouched foreign records remain;
        // on error everything goes back (idempotent — already-persisted
        // blocks sync as no-ops next time). Records appended during our
        // I/O land after the snapshot (they are newer).
        let mut foreign: Vec<Publication> = Vec::new();
        for (i, p) in snapshot.into_iter().enumerate() {
            if first_err != 0 || !mine.contains(&i) {
                foreign.push(p);
            }
        }
        {
            let mut pend = PENDING_PUBLICATIONS.lock();
            let rest = pend.take_list();
            foreign.extend(rest);
            pend.set_list(foreign);
        }
        if first_err != 0 {
            return Err(first_err);
        }
        // Loop: the same cookie may have appended during our I/O (other
        // threads of this task's process).
    }
}

/// Satisfy H1/H2 for ONE block the caller is about to write out of band
/// (journal-commit registered buffers, single dirty-buffer sync, eviction
/// victims): every pending record whose entry IS this block gets its pres
/// written first; every pending record whose post CONTAINS this block gets
/// its entry written first (with that entry's own H1 set). The block
/// itself is NOT written here. Foreign records stay pending.
pub fn flush_publication_constraints(mj: u32, mi: u32, blocknr: u64) -> Result<(), i32> {
    let mut snapshot = PENDING_PUBLICATIONS.lock().take_list();
    let dev = (mj, mi);
    // Fast path: nothing pending even references this block.
    let relevant = snapshot.iter().any(|p| {
        p.device == dev && (p.entry == Some(blocknr) || p.post.contains(&blocknr))
    });
    if !relevant {
        let mut pend = PENDING_PUBLICATIONS.lock();
        let rest = pend.take_list();
        snapshot.extend(rest);
        pend.set_list(snapshot);
        return Ok(());
    }
    crate::debug::fsw::note_pub_cstr();

    let mut plan = WritePlan::new();
    plan.note_queue_entries(&snapshot, dev);
    // The caller's imminent write of `blocknr` is the trigger: schedule it
    // (in whichever phase its role dictates) so the closure pulls in its
    // H1/H2 obligations. The write loops below skip it — the caller owns
    // that write.
    plan.push_pre(blocknr);
    plan_add_constraints(&mut plan, &snapshot, dev);

    let mut first_err: i32 = 0;
    for &b in &plan.pre {
        if b == blocknr {
            continue; // caller writes this one
        }
        if let Err(e) = sync_block_ordered(dev, b) {
            if first_err == 0 {
                first_err = e;
            }
            break;
        }
    }
    if first_err == 0 {
        for &b in &plan.entry {
            if b == blocknr {
                continue; // caller writes this one
            }
            if let Err(e) = sync_block_ordered(dev, b) {
                if first_err == 0 {
                    first_err = e;
                }
                break;
            }
        }
    }
    // Post phase is never written by a constraint flush (the caller's own
    // write is the constrained block, which is not a `post`-only role
    // write; H2 for posts is handled by pulling entries above).
    {
        let mut pend = PENDING_PUBLICATIONS.lock();
        let rest = pend.take_list();
        snapshot.extend(rest);
        pend.set_list(snapshot);
    }
    if first_err != 0 {
        Err(first_err)
    } else {
        Ok(())
    }
}

/// Flush all pending publications in append order (pre -> entry -> post
/// per record). Called from the GLOBAL durability points (sync(2)/syncfs/
/// shutdown paths, sync_buffers) and from the eviction/sync guards. Never
/// holds the pending lock across I/O; loops until a racing publisher
/// stops refilling the queue.
pub fn flush_publications() -> Result<(), i32> {
    flush_publications_bounded(u32::MAX)
}

/// flush_publications with a batch cap: each batch is one full ordered
/// pass over a mem::take snapshot; after `max_batches` batches (or an
/// empty take) whatever arrived meanwhile stays pending, ordered. Used by
/// the high-water creator-side drain so backlog reclamation is bounded
/// even under sustained churn.
pub fn flush_publications_bounded(max_batches: u32) -> Result<(), i32> {
    let mut batches = 0u32;
    loop {
        let mut batch = PENDING_PUBLICATIONS.lock().take_list();
        if batch.is_empty() {
            return Ok(());
        }
        crate::debug::fsw::note_pub_flush(batch.len());
        let mut first_err: i32 = 0;
        for p in &batch {
            for &b in &p.pre {
                if let Err(e) = sync_block_ordered(p.device, b) {
                    if first_err == 0 {
                        first_err = e;
                    }
                }
            }
            if let Some(e_blk) = p.entry {
                if let Err(e) = sync_block_ordered(p.device, e_blk) {
                    if first_err == 0 {
                        first_err = e;
                    }
                }
            }
            for &b in &p.post {
                if let Err(e) = sync_block_ordered(p.device, b) {
                    if first_err == 0 {
                        first_err = e;
                    }
                }
            }
        }
        if first_err != 0 {
            // Requeue what we did not get to; the error is reported.
            let mut pend = PENDING_PUBLICATIONS.lock();
            let drained = pend.take_list();
            batch.extend(drained);
            pend.set_list(batch);
            return Err(first_err);
        }
        batches += 1;
        if batches >= max_batches {
            return Ok(());
        }
        // Loop: a racing publisher may have appended during our I/O.
    }
}

/// Sync one block by (major, minor, blocknr) without reading it into the
/// cache on a miss (a miss means nothing cached is pending — the
/// publisher's own cached copy may have been evicted, and eviction of a
/// constrained block flushes first, so a miss here is benign).
fn sync_block_ordered(dev: (u32, u32), blocknr: u64) -> Result<(), i32> {
    match get_block_cache().peek_buffer(dev, blocknr) {
        Some(bh) => {
            // SAFETY: peek_buffer bumped the refcount; the bh stays valid
            // until the matching put below. sync() skips clean buffers,
            // so already-persisted blocks cost nothing.
            let r = unsafe { (*bh).sync() };
            get_block_cache().put(bh);
            r
        }
        None => Ok(()),
    }
}

impl BlockCache {
    /// Lookup a cached buffer WITHOUT any disk read (bread reads on a
    /// miss). Bumps the refcount on hit; caller must put(). Used by the
    /// publication flush.
    pub fn peek_buffer(&self, dev: (u32, u32), blocknr: u64) -> Option<*mut BufferHead> {
        let index = self.hash_index(dev.0, dev.1, blocknr);
        let bucket = self.buckets[index].lock();
        let mut current = bucket.head;
        while let Some(entry_ptr) = current {
            // INV-BIO-ENTRY: bucket lock held.
            let entry = entry_ref(entry_ptr);
            if entry.key == (dev.0, dev.1, blocknr)
                && !entry.evicting
                && entry
                    .bh()
                    .is_some_and(|bh| bh.b_data.len() == self.block_size as usize)
            {
                entry.bh().unwrap().get();
                return Some(entry.bh);
            }
            current = entry.hash_next;
        }
        None
    }
}

// ==================== Block-update protocol edge (round-5, L5) ====================

/// The ext4 metadata block-update protocol as ONE audited edge: bread →
/// typed &mut view → caller mutation → mark dirty → (journal tag if a
/// handle is active) → sync → brelse. INV-BIO-BLOCKUPD: `f` receives the
/// block's data (exactly b_size bytes) and the raw handle for the
/// journal tag; the protocol completes (sync+brelse) on every path.
pub fn with_block_mut<T>(
    device: &'static crate::drivers::blkdev::GenDisk,
    blocknr: u64,
    f: impl FnOnce(&mut [u8], *mut BufferHead) -> Result<T, i32>,
) -> Result<T, i32> {
    let bh = bread(device, blocknr).ok_or(crate::errno::Errno::IOError.as_neg_i32())?;
    // SAFETY: INV-BIO-PIN — bread pinned the buffer; the &mut window
    // rides this function's exclusive scope (no other holder).
    let data: &mut [u8] = unsafe { &mut (*bh).b_data };
    let out = f(data, bh);
    // SAFETY: as bh_set_state_bit (INV-BIO-PIN).
    unsafe { (*bh).set_state_bit(BufferState::BH_Dirty) };
    // The journal tag (rung-5 seam row): the crate resolves the handle
    // and tags the buffer; one indirect call per journaled metadata
    // write, replacing the two direct calls.
    let handle = self::current_handle_raw();
    if !handle.is_null() {
        crate::api::ext4::journal_dirty(handle, bh);
    }
    let sync_res = sync_dirty_buffer(bh);
    brelse(bh);
    sync_res?;
    out
}

/// The DEFERRED twin of [`with_block_mut`]: same protocol minus the
/// inline sync — the F4-R2 durability-deferred class (order-unconstrained
/// counters: group-desc and superblock free counts; the next barrier
/// flushes them). INV-BIO-BLOCKUPD as above.
pub fn with_block_deferred_mut<T>(
    device: &'static crate::drivers::blkdev::GenDisk,
    blocknr: u64,
    f: impl FnOnce(&mut [u8], *mut BufferHead) -> Result<T, i32>,
) -> Result<T, i32> {
    let bh = bread(device, blocknr).ok_or(crate::errno::Errno::IOError.as_neg_i32())?;
    // SAFETY: INV-BIO-PIN — the &mut window rides this exclusive scope.
    let data: &mut [u8] = unsafe { &mut (*bh).b_data };
    let out = f(data, bh);
    // SAFETY: as bh_set_state_bit (INV-BIO-PIN).
    unsafe { (*bh).set_state_bit(BufferState::BH_Dirty) };
    // The journal tag (rung-5 seam row; deferred-write twin).
    let handle = self::current_handle_raw();
    if !handle.is_null() {
        crate::api::ext4::journal_dirty(handle, bh);
    }
    brelse(bh);
    out
}

/// The SHARED twin of the block-update edges: bread -> typed &[u8] view
/// -> caller reads -> brelse. No mutation, no BH_Dirty, no journal —
/// INV-BIO-BLOCKUPD's read contract (the pin is this scope's refcount).
pub fn with_block<T>(
    device: &'static crate::drivers::blkdev::GenDisk,
    blocknr: u64,
    f: impl FnOnce(&[u8]) -> T,
) -> Option<T> {
    let bh = bread(device, blocknr)?;
    // SAFETY: INV-BIO-PIN — bread pinned the buffer; the &mut window
    // rides this function's exclusive scope.
    let data: &[u8] = unsafe { &(*bh).b_data };
    let out = f(data);
    brelse(bh);
    Some(out)
}

/// Read-only block window: bread + shared data view + brelse (the
/// read-side twin of [`with_block`]). No dirty, no journal, no sync —
/// a pure reader.
///
/// INV-BIO-BLOCKRO (read arm of the with_block family): `device` is a
/// live registered disk, `blocknr` any block on it; `bread` pins the
/// buffer for the closure's scope and `brelse` releases exactly that
/// pin on every path (the closure cannot early-return past the
/// release — the release runs after `f` returns).
pub fn with_block_ro<T>(
    device: &'static crate::drivers::blkdev::GenDisk,
    blocknr: u64,
    f: impl FnOnce(&[u8]) -> T,
) -> Option<T> {
    let bh = bread(device, blocknr)?;
    let data = bh_data(&bh);
    let out = f(data);
    brelse(bh);
    Some(out)
}


// ════════════════ vfs ═════════════════════════════════
// (was vfs.rs)
// Virtual File System (VFS) core functionality
//
// ## Architecture Overview
//
// The VFS layer provides a unified interface for all filesystems:
// - **RootFS**: Memory-backed filesystem for initial root
// - **ext4**: Block device backed filesystem
// - **procfs**: Process information filesystem
// - **devfs**: Device filesystem
//
// ## Key Concepts
//
// - **inode**: Represents a filesystem object (file, directory, etc.)
// - **dentry**: Directory entry, caches path lookups
// - **superblock**: Represents a mounted filesystem
// - **inode_operations**: Function pointers for filesystem operations
//
// ## Path Resolution
//
// All paths are resolved through `path_lookup()` which:
// 1. Normalizes the path (handles . and ..)
// 2. Resolves relative paths using current working directory
// 3. Handles mount points
// 4. Returns a `Path` structure with dentry and mount info

// ============================================================================
// VFS Core Structures
// ============================================================================

/// VFS lookup flags
pub mod lookup_flags {
    /// Follow symbolic links
    pub const LOOKUP_FOLLOW: u32 = 0x0001;
    /// Must be a directory
    pub const LOOKUP_DIRECTORY: u32 = 0x0002;
    /// Create if doesn't exist
    pub const LOOKUP_CREATE: u32 = 0x0004;
    /// Exclusive create
    pub const LOOKUP_EXCL: u32 = 0x0008;
    /// Don't follow symlinks at the end
    pub const LOOKUP_NO_SYMLINKS: u32 = 0x0010;
}


/// NAME_MAX (Linux): longest single path component we will ever look up.
pub const NAME_MAX: usize = 255;

/// Coarse-grained VFS namespace mutation lock (review 5.1: O_CREAT two-step
/// race — SMP double-create of the same name).
///
/// Design note (minimal correct scheme): a single global lock serializes the
/// lookup-then-mutate window of directory-modifying operations (create via
/// O_CREAT, mkdir, symlink, link, unlink, rmdir, rename). Per-parent hashing
/// would reduce contention but requires stable parent identity across the
/// dentry/mount walk; until dentries are fully refcount-pinned for the whole
/// operation, a single lock is the only scheme that cannot be defeated by a
/// rename of an ancestor between hash and use. ext4 additionally takes
/// EXT4_BIG_LOCK inside its ops, so mutual exclusion composes.
///
/// This MUST be a sleeping lock, not a Spinlock: the critical section
/// spans the ext4_*_wrapper callbacks, and those take EXT4_BIG_LOCK
/// whose slowpath parks in block I/O under contention. With a Spinlock
/// guard pinning preempt_count != 0 across that window, the sleeper's
/// schedule() is refused by __schedule's preempt discipline and the
/// acquire degenerates into a hot retry loop whose dequeue_if_enqueued
/// hammers the GRQ lock hard enough to starve the other CPU's timer
/// tick (which needs GRQ with IRQs disabled) — the sendmsg02 early-exec
/// machine-wide stall-quiet wedge (2/2 on main c517099, gdb frozen-state:
/// pid sendmsg02 preempt=0x2 inside the contended acquire, CPU1 spinning
/// on GRQ in scheduler_tick). All users are syscall-context directory
/// mutators, so sleeping is legal everywhere this lock is taken.
pub static VFS_MUTATION_LOCK: crate::sync::SleepMutex =
    crate::sync::SleepMutex::new_rt("VFS-MUTATION", false);


impl VfsPath {
    /// Create empty path
    pub fn new() -> Self {
        Self {
            dentry: None,
            mnt: None,
            inode: None,
        }
    }

    /// Create path with inode
    pub fn with_inode(inode: Arc<Inode>) -> Self {
        Self {
            dentry: None,
            mnt: None,
            inode: Some(inode),
        }
    }

    /// Check if path is valid
    pub fn is_valid(&self) -> bool {
        self.inode.is_some()
    }
}

impl Default for VfsPath {
    fn default() -> Self {
        Self::new()
    }
}

static VFS_STATE: Spinlock<VfsState> = Spinlock::new(VfsState {
    root_dentry: None,
    initialized: false,
    mounts: Vec::new(),
    mount_chain_index: BTreeMap::new(),
});

/// (review-s2b perf) Pinned mirror of `VFS_STATE.root_dentry` for lock-free
/// reads. The root dentry is WRITE-ONCE: only vfs::init() and vfs_mount's
/// ensure-root arm assign the slot (both before any thread can race), and
/// every later "/" overlay (vfs_mount("/"), vfs_move_mount to "/") replaces
/// the root's INODE in place — the dentry object, and therefore the Arc's
/// address, is stable for the kernel's lifetime. The publish installs a
/// deliberately-leaked extra reference, so the object can never be freed
/// while the pointer is readable; same mirror discipline as
/// Dentry::has_mount (the authoritative field stays VFS_STATE.root_dentry).
static VFS_ROOT_PINNED: core::sync::atomic::AtomicPtr<Dentry> =
    core::sync::atomic::AtomicPtr::new(core::ptr::null_mut());

/// (review-s2b perf) Publish the root pin. Callers hold VFS_STATE (the
/// serialized writer side of VfsState.root_dentry).
fn vfs_root_publish(root: &Arc<Dentry>) {
    if VFS_ROOT_PINNED
        .load(core::sync::atomic::Ordering::Acquire)
        .is_null()
    {
        // Keep a leaked strong reference: the slot in VFS_STATE also holds
        // one forever, but the pin's guarantee must not depend on it.
        let leaked = Arc::into_raw(Arc::clone(root));
        VFS_ROOT_PINNED.store(leaked as *mut Dentry, core::sync::atomic::Ordering::Release);
    }
}

/// Get the global VFS root dentry.
///
/// (review-s2b perf) Fast path: one Acquire load — the old
/// `VFS_STATE.lock().root_dentry.clone()` paid a global spinlock pair
/// (preempt bookkeeping + CAS) on the prologue of every path walk; the
/// reference kernel's walk-start root read is lock-free (current->fs->root
/// under RCU). Early boot (pin not yet installed) falls back to the
/// authoritative slot under the lock.
pub fn get_vfs_root() -> Option<Arc<Dentry>> {
    let p = VFS_ROOT_PINNED.load(core::sync::atomic::Ordering::Acquire);
    if !p.is_null() {
        // SAFETY: the pointer carries the deliberately-leaked reference
        // installed by vfs_root_publish (never dropped), so the Dentry is
        // alive for the whole read. Building a temporary Arc from it and
        // forgetting the temporary leaves the leaked count untouched; the
        // clone handed out owns its own balanced increment.
        unsafe {
            let tmp = Arc::from_raw(p as *const Dentry);
            let out = Arc::clone(&tmp);
            core::mem::forget(tmp);
            return Some(out);
        }
    }
    VFS_STATE.lock().root_dentry.clone()
}

/// If `dentry` is a mount point, return the mounted filesystem's root dentry.
/// Otherwise return `dentry` itself.
///
/// (stat-2x lane) Lock-free absence test FIRST: this runs at the START of
/// every path walk (and the ".." hop), and the common case — not a mount
/// point — paid the vfsmount spinlock pair + Option Arc clone on every
/// lookup. The is_mountpoint mirror's protocol (set_mount stores flag
/// first, descriptor second; clear_mount the reverse) makes a transient
/// mismatch no worse than this slow path: the lock decides, and a race
/// that still sees None simply stays on `dentry` exactly like a
/// non-mountpoint.
pub fn follow_mount(dentry: Arc<Dentry>) -> Arc<Dentry> {
    if !dentry.has_mount() {
        return dentry;
    }
    let mount = dentry.get_mount();
    match mount {
        Some(mnt) => mnt.root.clone(),
        None => dentry,
    }
}

/// Mount flags governing an ABSOLUTE dentry-tree path: walk the components
/// crossing mount points (exactly like lookups do) and remember the flags of
/// the LAST mount crossed. None = never left the root filesystem.
///
/// This is the EROFS enforcement hook: after `mount(2)` with
/// MS_REMOUNT|MS_RDONLY every modifying operation inside that subtree must
/// fail EROFS (LTP access04/creat06/unlink09/... needs_rofs family).
pub fn mount_flags_for_path(abs_path: &str) -> Option<super::types::MntFlags> {
    let vfs_root = VFS_STATE.lock().root_dentry.clone()?;
    let mut current = vfs_root;
    let mut flags: Option<super::types::MntFlags> = None;
    for component in abs_path.split('/').filter(|s| !s.is_empty()) {
        if let Some(mnt) = current.get_mount() {
            flags = Some(*mnt.flags.lock());
            current = mnt.root.clone();
        }
        // A component may not exist yet (creat/mkdir paths) or may not be in
        // the dentry cache — the governing mount is the last one crossed.
        match current.lookup_child(component) {
            Some(c) => current = c,
            None => return flags,
        }
    }
    // A trailing mountpoint (e.g. the mntpoint directory itself) also
    // crosses into the mounted fs.
    if let Some(mnt) = current.get_mount() {
        flags = Some(*mnt.flags.lock());
    }
    flags
}

/// True when the absolute path lives on a mount currently flagged read-only.
/// (perf-gap-hunt) Empty-registry fast gate: dentry vfsmount stamps and the
/// mount registry are updated in lockstep at every mount/umount site, so an
/// empty registry implies the component walk below could never cross a
/// mount — its verdict is `None` (not readonly) by construction.  On
/// mountless rigs (lmbench/pbench probes, single-rootfs boots) every write
/// open / creat / mkdir / rmdir / unlink previously paid a full component
/// dentry walk here just to learn there is no read-only mount; now they pay
/// one registry probe.  Rigs with mounts keep the exact walk semantics.
pub fn path_on_readonly_mount(abs_path: &str) -> bool {
    if VFS_STATE.lock().mounts.is_empty() {
        return false;
    }
    mount_flags_for_path(abs_path)
        .map(|f| f.is_readonly())
        .unwrap_or(false)
}

/// True when the FILE's filesystem is currently flagged read-only. Resolves
/// the mount by the fd's dentry (climb to the fs root, match against the
/// mount registry) — `build_path()` cannot be used: a mounted fs's root
/// dentry has no parent, so paths of files inside a mount come out as
/// "/file" (LTP fchmod06/fchown04 saw EPERM instead of EROFS).
pub fn file_on_readonly_mount(file: &super::types::File) -> bool {
    // SAFETY: dentry is written once at open time and never mutated.
    let dentry_opt = file.get_dentry().cloned();
    dentry_opt
        .map(|d| dentry_on_readonly_mount(&d))
        .unwrap_or(false)
}

/// Mount-readonly check for a dentry: climb to the top of its filesystem
/// (parent chain) and match that root dentry against the mount registry.
pub fn dentry_on_readonly_mount(dentry: &Arc<Dentry>) -> bool {
    let mut cur = dentry.clone();
    loop {
        let parent = cur.parent.lock().clone();
        match parent {
            Some(p) => cur = p,
            None => break,
        }
    }
    // cur is a filesystem root; is it the root of a registered mount?
    let state = VFS_STATE.lock();
    for mnt in state.mounts.iter() {
        if Arc::ptr_eq(&mnt.root, &cur) {
            return mnt.flags.lock().is_readonly();
        }
    }
    false
}

/// EROFS guard shared by the mutating vfs_* entry points (Linux mnt_want_write):
/// every create/delete/rename/attr-change inside a MS_RDONLY mount fails
/// before touching the filesystem (LTP needs_rofs family: unlink09, rmdir02,
/// mkdir03, link08, chmod06, chown04, utimes01, ...).
fn check_not_readonly(pathname: &str) -> Result<(), i32> {
    if path_on_readonly_mount(pathname) {
        return Err(errno::Errno::ReadOnlyFileSystem.as_neg_i32());
    }
    Ok(())
}

/// May the CURRENT task re-flag this mount? Linux unshare(CLONE_NEWNS)
/// clones the mount tree, so a namespace child's MS_REMOUNT re-flags ITS
/// copy only; Rux attaches one shared VfsMountInternal per dentry, so
/// without this gate the executor's ProtectSystem=strict pass
/// (bind_remount_recursive over every mount under / — /, /dev, /dev/pts,
/// ... — mount(NULL, "/proc/self/fd/N", MS_BIND|MS_REMOUNT|MS_RDONLY))
/// read-only-flagged the MAIN namespace's mounts: /dev and /run went
/// EROFS, journald died 209/STDOUT at open("/dev/null") (ub2404,
/// 2026-11-15). Rule: the init namespace re-flags anything (remount-fs,
/// LTP rofs); a private namespace only the mounts ATTACHED inside it
/// (ns_track_vfsmount) — a re-flag of an inherited mount reports success
/// without the global flag change (the sandbox is weaker, the system
/// stays writable — the contained trade for the un-cloned ns model).
fn ns_may_reflag(mnt: &Arc<VfsMountInternal>) -> bool {
    if crate::process::ns::in_init_mnt_ns() {
        return true;
    }
    let ns = crate::process::ns::current_mnt_ns();
    let tracked = ns.vfs_mounts.lock();
    tracked.iter().any(|m| Arc::ptr_eq(m, mnt))
}

/// Apply new mount flags to a VfsMountInternal, keeping the ext4 op-layer
/// ro latch in sync (shared by the path-walk and dentry-direct remount
/// entry points — see vfs_remount/vfs_remount_dentry for the callers).
fn apply_mnt_flags(
    mnt: &Arc<VfsMountInternal>,
    new_flags: super::types::MntFlags,
) {
    *mnt.flags.lock() = new_flags;
    // The ext4 op-layer ro latch is PER FILESYSTEM INSTANCE, and a bind
    // copy SHARES the instance with the original mount (mnt.root is the
    // same inode). Only the init mount namespace may close/open the
    // instance-wide latch: a private namespace re-flagging its own
    // ns-attached bind copy RO (gdm-hunt, 2026-11-16: the 24.04
    // executor's `mount-rootfs` bind re-flag, MS_BIND|MS_REMOUNT|
    // MS_RDONLY) must not read-only the real filesystem for everyone
    // else — logind's StateDirectory mkdir, gdm's `2>/var/gdm-err.txt`
    // and the PrivateTmp setup all died EROFS from exactly that leak.
    // The sandbox itself keeps its RO enforcement inside the namespace
    // through the per-mount mnt.flags guard (path_on_readonly_mount).
    if !crate::process::ns::in_init_mnt_ns() {
        return;
    }
    // Keep the underlying ext4's own ro latch in sync — its
    // op-layer EROFS guard reads fs.read_only (sc21), so a
    // remount,rw must reopen writes and remount,ro close them
    // at the fs layer too. A metadata_csum image stays
    // read-only regardless (mount-time downgrade policy: the
    // write path does not maintain checksums).
    if let Some(root_inode) = mnt.root.get_inode() {
        if let Some(ops) = root_inode.ops {
            if crate::api::ext4::is_ext4_inode_ops(ops) {
                // The leaf's ro latch sync (the fs instance and its
                // metadata_csum downgrade policy are crate-side).
                crate::api::ext4::remount_ro_latch(new_flags.is_readonly());
            }
        }
    }
}

/// Remount by RESOLVED DENTRY — the mount(2) MS_REMOUNT|MS_BIND shape
/// systemd v255 uses for every sandbox re-flag: the target arrives as a
/// /proc/self/fd/N magic link, which the syscall layer already resolved
/// to the referent dentry. Linux do_remount re-flags the mount that
/// COVERS the looked-up path in the CALLER's namespace — not "whatever
/// mount a global string walk happens to find under a dcache alias".
/// The string walk (vfs_remount) is wrong for this shape in two ways:
/// the fd's referent often lives under a bind mount whose canonical
/// dcache path is a DIFFERENT alias (the global walk then flags an
/// unrelated topmost mount — an ns child's RO re-flag could read-only a
/// mount in the MAIN namespace: the ub2404 journald 209/STDOUT
/// regression, /dev+/run EROFS, 2026-11-15), and the global root dentry
/// carries no mount descriptor at all (remount of "/" returned EINVAL
/// and killed every ProtectSystem=yes spawn).
///
/// Semantics here: re-flag the topmost mount AT the dentry; if the
/// dentry is not a mountpoint, climb to the nearest ancestor mountpoint
/// (the covering mount — same rule as vfs_remount's crossed-mount arm).
/// Reaching the global root without a mount: Ok(()) — Linux would
/// re-flag the root mount (which Rux models as root-inode replacement,
/// with no flag object); the spawn must proceed, the weaker sandbox is
/// the contained cost.
pub fn vfs_remount_dentry(
    dentry: &Arc<Dentry>,
    new_flags: super::types::MntFlags,
) -> Result<(), i32> {
    let mut cur = dentry.clone();
    let root = VFS_STATE.lock().root_dentry.clone();
    loop {
        if let Some(mnt) = cur.get_mount() {
            if ns_may_reflag(&mnt) {
                apply_mnt_flags(&mnt, new_flags);
            }
            return Ok(());
        }
        if let Some(r) = root.as_ref() {
            if Arc::ptr_eq(&cur, r) {
                // The global root: no mount descriptor exists (root
                // mounts are inode-replacement). Linux re-flags the
                // root mount here; accept without a global flag change
                // so namespace-using spawns do not die EINVAL.
                return Ok(());
            }
        }
        let parent = cur.parent.lock().clone();
        match parent {
            Some(p) => cur = p,
            None => {
                // A mounted filesystem's root without a mountpoint
                // back-hop (unreachable via normal path walks — set at
                // attach time); treat as the root case above.
                match cur.mountpoint_dentry() {
                    Some(p) => cur = p,
                    None => return Ok(()),
                }
            }
        }
    }
}

/// Update the flags of the mount attached at `mountpoint` (mount(2) with
/// MS_REMOUNT). Returns Ok(()) when a mount was found and updated,
/// Err(EINVAL) when the path is not a mount point.
pub fn vfs_remount(mountpoint: &str, new_flags: super::types::MntFlags) -> Result<(), i32> {
    // Caller-relative discipline (same as vfs_attach_mount_at / vfs_mount):
    // a task virtually switch-rooted into its namespace's crafted root
    // (vfs_virtual_switch_root) or chrooted remounts paths AS IT SEES
    // THEM — "/dev" is the crafted clone's /dev, not the global mount.
    // Without this, a namespace child's ProtectSystem/ProtectKernel*
    // read-only flips landed on the GLOBAL mounts (serial-155614:
    // generators' namespace left the global /dev read-only and every
    // later mknod/mkdir under it EROFS'd).
    let owned_mp;
    let mountpoint = {
        let root = get_process_root();
        if root != "/" && mountpoint.starts_with('/') {
            let joined = format!("{}{}", root.trim_end_matches('/'), mountpoint);
            owned_mp = path_normalize(&joined);
            owned_mp.as_str()
        } else {
            mountpoint
        }
    };
    let vfs_root = VFS_STATE.lock().root_dentry.clone()
        .ok_or(errno::Errno::NoSuchFileOrDirectory.as_neg_i32())?;
    let mut current = vfs_root;
    let mut crossed: Option<alloc::sync::Arc<VfsMountInternal>> = None;
    for component in mountpoint.split('/').filter(|s| !s.is_empty()) {
        if let Some(mnt) = current.get_mount() {
            crossed = Some(mnt.clone());
            current = mnt.root.clone();
        }
        current = match current.lookup_child(component) {
            Some(c) => c,
            None => return Err(errno::Errno::NoSuchFileOrDirectory.as_neg_i32()),
        };
    }
    // The TOPMOST mount covering the path wins: a mount attached AT the
    // terminal dentry (a bind of a FILE, e.g. systemd's ProtectHostname
    // step mount(NULL, /proc/sys/kernel/domainname, MS_BIND|MS_REMOUNT|
    // MS_RDONLY)) shadows whatever mount was crossed on the way down.
    // The old walk only consulted the terminal dentry when NO mount had
    // been crossed, so the remount flags landed on the ENCLOSING mount
    // (the whole procfs) instead of the bind. Linux __do_loopback/
    // do_remount semantics: flags apply to the last-mounted covering
    // mount of the path.
    let found = current.get_mount().or(crossed);
    match found {
        Some(mnt) => {
            if ns_may_reflag(&mnt) {
                apply_mnt_flags(&mnt, new_flags);
            }
            Ok(())
        }
        None => Err(errno::Errno::InvalidArgument.as_neg_i32()),
    }
}

/// Shallow dentry-tree walk (root → components) crossing mount points.
///
/// Unlike `path_lookup()` this does no path normalization, DAC checks,
/// negative-dentry handling, or icache refreshes — it only follows cached
/// child dentries. Intended for kernel-internal cache maintenance (e.g.
/// evicting a stale /dev/pts/N dentry after a dynamic node is created or
/// removed) that runs NESTED INSIDE a deep syscall path: a nested full
/// `path_lookup()` there multiplies the debug-build frame depth, and the
/// scheduler's TICK-CANARY (sched.rs, r18-3) already diagnosed such nested
/// chains as spilling past the bottom of the 64KB kernel stack into the
/// adjacent heap page — zeroing whatever object lives there.
pub fn shallow_dentry_walk(components: &[&str]) -> Option<Arc<Dentry>> {
    let mut current = follow_mount(get_vfs_root()?);
    for component in components {
        if *component == "/" || component.is_empty() {
            continue;
        }
        current = follow_mount(current.lookup_child(component)?);
    }
    Some(current)
}

/// Mount a filesystem at the given path, building the dentry tree.
///
/// This replaces the old `mount_at()` string-based routing with dentry tree
/// construction. The dentry tree allows `path_lookup()` to walk the tree
/// and cross mount points via `follow_mount()`.
///
/// Returns the mounted filesystem's fresh root dentry (so recursive bind
/// clones can attach INSIDE it), or None for the "/" overlay special case.
pub fn vfs_mount(
    mountpoint: &str,
    root_inode: Arc<Inode>,
    mnt_flags: MntFlags,
) -> Option<Arc<Dentry>> {
    // Namespace discipline (sc36): attach at the mountpoint AS THE
    // CALLER SEES IT. path_lookup prefixes absolute paths with the
    // task root, but this walk started at the GLOBAL root — a
    // prefixed process (appspawn child inside the system sandbox)
    // binding /mnt/sandbox/0/<pkg>/dev attached the mount on the
    // direct-global dentry side, while every later lookup walked the
    // through-sandbox-prefix side: two dentry trees over the same
    // tmpfs nodes, mounts visible from one side only. Post-pivot
    // /dev/null resolved to the bare tmpfs dir and the spawn child
    // died at appspawn_common.c:350 (sc33-sc36). Prepend the task root
    // exactly like make_absolute_rooted; kernel threads and early boot
    // (root "/") are unchanged.
    let owned_mountpoint;
    let mountpoint = {
        let root = get_process_root();
        if root != "/" && mountpoint.starts_with('/') {
            owned_mountpoint = format!("{}{}", root.trim_end_matches('/'), mountpoint);
            owned_mountpoint.as_str()
        } else {
            mountpoint
        }
    };
    let mut state = VFS_STATE.lock();

    // Ensure VFS root dentry exists
    let vfs_root = match state.root_dentry.clone() {
        Some(d) => d,
        None => {
            let d = Arc::new(Dentry::new(String::from("/")));
            d.set_hashed();
            state.root_dentry = Some(d.clone());
            vfs_root_publish(&d);
            d
        }
    };

    // Create the mounted filesystem's root dentry
    let mounted_root = Arc::new(Dentry::new(String::from("/")));
    mounted_root.set_inode(root_inode);
    mounted_root.set_hashed();

    // Walk from VFS root to the mount point, creating intermediate dentries
    // Special case: mounting at "/" means we overlay the VFS root's inode.
    // We do NOT set a VfsMountInternal here because that would cause follow_mount
    // to jump to a new dentry without children. Instead, we directly replace the
    // root dentry's inode, so children (proc, dev, etc.) remain accessible.
    if mountpoint == "/" {
        vfs_root.set_inode(mounted_root.get_inode().unwrap());
        return None;
    }

    // For non-root mountpoints (e.g., "/dev", "/proc"), walk from VFS root
    let components: Vec<&str> = mountpoint
        .split('/')
        .filter(|s| !s.is_empty())
        .collect();

    let mut current = vfs_root.clone();
    current = follow_mount(current);

    for (i, component) in components.iter().enumerate() {
        let is_last = i == components.len() - 1;
        let name = String::from(*component);

        if is_last {
            // This is the mount point — create/replace the dentry and attach mount
            let child = match current.lookup_child(&name) {
                Some(existing) => existing,
                None => {
                    let d = Arc::new(Dentry::new(name.clone()));
                    d.set_parent(current.clone());
                    current.add_child(name.clone(), d.clone());
                    d
                }
            };

            // Create mount descriptor
            let mnt_desc = Arc::new(VfsMountInternal::new(mounted_root.clone(), mnt_flags));
            child.set_mount(mnt_desc.clone());
            state.mounts.push(mnt_desc.clone());
            // sc181: index the mount under its mountpoint's parent chain
            // (MS_REC clone scan — see collect_subtree_mounts).
            mount_index_insert(&mut state, &mnt_desc, &child);
            // Mountpoint back-reference: dentries inside the mount climb
            // parent==None at the mount root and must hop to THIS
            // mountpoint dentry to carry the prefix (build_path_rooted).
            // The hop existed but was never wired here — every path
            // built from a dentry inside a mount was mount-relative
            // (/dev/dri reported "/dri"), so dirfd-relative openat
            // resolved "/dri" → ENOENT: OH's composer VDI
            // (FindAndOpenKmsCard) readdir'd /dev/dri fine but its
            // openat(dirfd, "card0") failed silently, the DRM chain saw
            // "can't open drm card device", zero displays, and the whole
            // graphics stack ran screen-less (rs-egl r3-r8).
            mounted_root.set_mountpoint_back(child.clone());
            // sc98: remember the mount in the CALLER's namespace so a dying
            // private namespace (killed appspawn children) unmounts it
            // instead of leaking it into the shared tree forever — see
            // MountNamespace::vfs_mounts. MUST run AFTER dropping VFS_STATE:
            // the lazy init_mnt_ns() inside current_mnt_ns() reaches
            // get_vfs_root() → VFS_STATE.lock() — self-deadlock under the
            // guard held here (sc98 first-boot DEADLOCK).
            drop(state);
            crate::process::ns::ns_track_vfsmount(mnt_desc);
            return Some(mounted_root);
        } else {
            // Intermediate component — create if not exists
            let child = match current.lookup_child(&name) {
                Some(existing) => follow_mount(existing),
                None => {
                    let d = Arc::new(Dentry::new(name.clone()));
                    d.set_parent(current.clone());
                    current.add_child(name.clone(), d.clone());
                    d
                }
            };
            current = child;
        }
    }
    // Unreachable for non-empty component lists; an empty mountpoint
    // string ("", "//") attaches nothing.
    None
}

// ============================================================================
// Filesystem Type Enumeration
// ============================================================================

/// Is `d` inside the filesystem tree mounted at `mnt_root`? Identity climb
/// through parent links; at a filesystem root the covered mountpoint
/// dentry (mountpoint back-ref) is entered so files in SUBMOUNTS of the
/// tested mount also report busy. The iteration cap bounds malformed
/// back-ref cycles.
fn dentry_in_mount_subtree(d: &Arc<Dentry>, mnt_root: &Arc<Dentry>) -> bool {
    let mut cur = d.clone();
    for _ in 0..128 {
        if Arc::ptr_eq(&cur, mnt_root) {
            return true;
        }
        // Bind the climb hop to a local so the parent-spinlock guard (a
        // temporary borrowed from `cur`) is released before the
        // reassignment.
        let next = { cur.parent.lock().clone() };
        match next {
            Some(p) => cur = p,
            None => {
                let hop = cur.mountpoint_dentry();
                match hop {
                    Some(mp) if !Arc::ptr_eq(&mp, &cur) => cur = mp,
                    _ => return false,
                }
            }
        }
    }
    false
}

/// Would detaching the mount at `mnt_root` strand live users? Linux's
/// propagate_mount_busy() refuses a plain umount while references beyond
/// the walk's own exist; the reference sources modeled here are the ones
/// userspace actually trips over: open file descriptions on any task whose
/// dentry lies inside the mount (umount02 holds an fd on `mntpoint/file`),
/// and any task whose cwd or chroot lies inside it. MNT_DETACH skips this
/// check entirely (lazy unmount — the references keep working until they
/// close).
fn mount_is_busy(mnt_root: &Arc<Dentry>) -> bool {
    use core::sync::atomic::{AtomicBool, Ordering};

    let busy = AtomicBool::new(false);
    // SAFETY: the pid-hash walk holds the bucket lock for each task (it
    // cannot be freed mid-callback); we only take non-sleeping locks
    // (fdtable entry lock, dentry parent spinlocks, FsStruct rwlocks).
    crate::sched::for_each_task(|t| {
        if busy.load(Ordering::Relaxed) {
            return;
        }
        let task = unsafe { &*t };
        // Open descriptors: any file whose dentry sits in the subtree.
        if let Some(fdtable) = task.try_fdtable() {
            fdtable.for_each_file(|_fd, file| {
                // dentry is write-once at open time (get_dentry doc).
                if let Some(d) = file.get_dentry() {
                    if dentry_in_mount_subtree(d, mnt_root) {
                        busy.store(true, Ordering::Relaxed);
                    }
                }
            });
        }
        if busy.load(Ordering::Relaxed) {
            return;
        }
        // cwd / chroot dentries pin the mount the same way.
        if let Some(fs) = task.fs_arc() {
            if let Some(pwd) = fs.cwd_dentry() {
                if dentry_in_mount_subtree(&pwd, mnt_root) {
                    busy.store(true, Ordering::Relaxed);
                    return;
                }
            }
            if let Some(root) = fs.root_dentry() {
                if dentry_in_mount_subtree(&root, mnt_root) {
                    busy.store(true, Ordering::Relaxed);
                }
            }
        }
    });
    busy.load(Ordering::Relaxed)
}

/// The durability sequence shared by sync(2) and umount(2) (data-integrity
/// lane, 2026-11-11 for sync; umount hookup 2026-11-16): drain dirty
/// page-cache frames into the ext4 write path, write the flushed files'
/// DATA blocks first and their inode-table blocks last (ordered data —
/// the metadata must never claim data the device has not received), then
/// drain the buffer cache and persist the device's volatile cache.
///
/// umount(2) needs this for the same reason sync(2) does: the reference
/// umount writes the filesystem out before dropping the mount, and a
/// dirty page left behind at detach was only reachable through the DEAD
/// mount's fs instance afterwards — LTP umount2_01's MNT_DETACH case
/// wrote 26 bytes through an fd on the mounted fs, lazy-unmounted,
/// remounted the same device, and read EOF: the bytes lived in the old
/// instance's dirty page-cache frames and never reached the device.
///
/// Returns Err(EIO) only when the final device-cache persist fails (the
/// sync(2) contract); umount callers treat that as best-effort.
pub fn sync_dirty_filesystems() -> Result<(), i32> {
    // Delayed allocation (2026-11): buffered write(2) leaves data ONLY in
    // dirty page-cache frames — drain them into the ext4 write path (and
    // thus the buffer cache) BEFORE syncing the buffer cache, or the sync
    // would persist nothing of every un-fsynced write.
    //
    // The drain returns the (fs, inode) targets it flushed: their DATA
    // blocks must reach the device BEFORE the inode-table blocks that
    // describe them (ordered data), or a crash in between leaves a file
    // that claims 8 MB of data the device never received.
    let flushed_targets = self::get_page_cache().flush_all_dirty();
    // ORDERED DATA: the flushed files' DATA blocks first. The plain
    // buffer-cache drain below writes every dirty buffer in HASH ORDER —
    // the inode-table block (the file's new size) could reach the device
    // BEFORE the data blocks it describes, and a crash in between leaves
    // a file that claims 8 MB of data the device never received
    // (measured: the fiE3 crash-window boot — full size, full extent
    // map, ~35 % of the data). The data goes first; the metadata last.
    let _ = crate::api::ext4::sync_flushed_data(&flushed_targets);
    // Flush all buffer cache
    let _ = self::sync_buffers();
    // INODE-TABLE BLOCKS (data-integrity lane, 2026-11-11): the size the
    // flushed files just learned lives in their inode-table blocks.
    // fsync has always synced that block explicitly (ext4_sync_file_inner
    // bakes the inode-table block + sync_dirty_buffer); sync(2) had NO
    // equivalent, so the block stayed dirty in the buffer cache and a
    // crash right after sync() returned left every synced file at its
    // creation size (0 bytes, md5-of-empty) with its data blocks already
    // on the device. Synced AFTER the buffer-cache drain above, so the
    // metadata lands after the data it describes (ordered data).
    let _ = crate::api::ext4::sync_inode_tables(&flushed_targets);
    // And persist the disk's volatile cache (see sys_fsync).
    crate::drivers::virtio::flush_pci_blk().map(|_| ()).map_err(|_| -(errno::constants::EIO))
}

/// Unmount a filesystem from the dentry tree.
///
/// Removes the mount point dentry (and its `VfsMountInternal`) from the parent.
/// The root "/" cannot be unmounted.
///
/// `lazy` is MNT_DETACH: skip the busy check (the reference's do_umount
/// detaches unconditionally under MNT_DETACH) and keep going.
/// `nofollow` is UMOUNT_NOFOLLOW: resolve the target WITHOUT following a
/// final symlink (Linux umount walks with LOOKUP_MOUNTPOINT — the
/// umount2("symlink", UMOUNT_NOFOLLOW) of LTP umount2_02 must see the
/// link itself and answer EINVAL, not unmount through it).
pub fn vfs_umount(mountpoint: &str, lazy: bool, nofollow: bool) -> Result<(), i32> {
    if mountpoint == "/" || mountpoint.is_empty() {
        return Err(errno::Errno::DeviceOrResourceBusy.as_neg_i32());
    }

    // Linux path_umount(): user_path_at resolves the target FIRST —
    // resolution failures (ENOENT / ENOTDIR / ENAMETOOLONG / EACCES)
    // propagate directly, and EINVAL ("not a mountpoint") is only for a
    // path that RESOLVES but is not a mount root (LTP umount02 "Directory
    // not found" expects ENOENT; the old parent-split arm answered EINVAL
    // for the missing child).
    let lookup_flags = if nofollow { LOOKUP_NOFOLLOW } else { 0 };
    let target_vpath = path_lookup(mountpoint, lookup_flags)?;
    let mnt_root = target_vpath.dentry
        .ok_or(errno::Errno::NoSuchFileOrDirectory.as_neg_i32())?;

    // path_lookup crossed INTO the mount: a mount root dentry carries the
    // mountpoint back-reference to the covered dentry. A plain directory
    // (or file) has none → EINVAL, exactly the reference's
    // `path.dentry != path.mnt->mnt_root` arm.
    let child = mnt_root
        .mountpoint_dentry()
        .ok_or(errno::Errno::InvalidArgument.as_neg_i32())?;
    let mnt = child
        .get_mount()
        .ok_or(errno::Errno::InvalidArgument.as_neg_i32())?;

    // EBUSY: without MNT_DETACH, live users pin the mount (see
    // mount_is_busy). Linux checks this in do_umount AFTER the
    // mountpoint checks — EINVAL still wins for a non-mountpoint.
    if !lazy && mount_is_busy(&mnt_root) {
        return Err(errno::Errno::DeviceOrResourceBusy.as_neg_i32());
    }

    // Detach the mount but KEEP the mountpoint dentry: Linux umount leaves
    // the covered directory in place (the underlying dir "re-appears").
    // Removing the dentry made the mountpoint itself vanish — a later mount
    // at the same target failed ENOENT (LTP chdir01's per-filesystem
    // iteration 2: "Cannot resolve the absolute path of mntpoint").
    let name = child.get_name();
    let parent_dentry = { child.parent.lock().clone() }
        .ok_or(errno::Errno::InvalidArgument.as_neg_i32())?;
    {
        let mut state = VFS_STATE.lock();
        state.mounts.retain(|m| !Arc::ptr_eq(m, &mnt));
        // sc181: drop from the chain index BEFORE the mountpoint back-ref
        // is cleared below (the chain is recomputed from the mountpoint).
        mount_index_remove(&mut state, &mnt, &child);
    }
    // Drop the mountpoint back-reference with the mount (see vfs_mount).
    // take_mount also clears the lock-free presence mirror (perf-path).
    mnt.root.clear_mountpoint_back();
    child.take_mount();
    // A mount whose mountpoint DENTRY it created itself (vfs_mount's
    // bare-dentry arm — boot-time /proc, /sys, ... never went through a
    // path_lookup first) leaves an INODE-LESS dentry behind after the
    // unmount: the walk's dcache hit then reads it as a NEGATIVE entry
    // and every lookup of the mountpoint fails ENOENT. systemd's
    // mount_private_apivfs (ProtectProc=/PrivateMounts services,
    // systemd-udevd on noble) umounts /proc and MS_MOVEs a fresh
    // instance onto it — the failed target lookup aborted the whole
    // namespace setup (status 226/NAMESPACE, udevd restart loop).
    // Drop such dentries from the parent: the next walk re-resolves the
    // name against the underlying filesystem and the covered directory
    // "re-appears" like Linux's umount. Dentries that DO carry an inode
    // are kept as-is — removing those broke LTP chdir01's
    // remount-at-same-target.
    if child.get_inode().is_none() {
        parent_dentry.remove_child(&name);
    }
    // Write the filesystem out before reporting success — the reference's
    // umount syncs the superblock (see sync_dirty_filesystems for the
    // data-loss case). MNT_DETACH included: the detached instance keeps
    // serving its open fds, but nothing else will ever flush its dirty
    // pages, and a remount of the same device reads the DEVICE, not the
    // dead mount's page cache. Best-effort: an EIO from the final device
    // cache persist does not fail an otherwise-complete unmount.
    let _ = sync_dirty_filesystems();
    Ok(())
}

/// sc98: detach one known mount OBJECT (namespace-teardown path —
/// MountNamespace::Drop). Unlike vfs_umount this takes no path: the
/// mountpoint dentry is recovered from the mount's own back-reference.
/// The mount is only detached when it is STILL the live mount at its
/// mountpoint — a newer mount stacked on the same dentry replaced it and
/// owns the slot (the shadowed mount just leaves the registry).
pub fn vfs_umount_object(mnt: &Arc<VfsMountInternal>) {
    let Some(mp) = mnt.root.get_mountpoint_back() else {
        // Never attached via vfs_mount (mount-at-"/" overlays the root
        // inode instead) or already torn down: just drop the registry row.
        let mut state = VFS_STATE.lock();
        state.mounts.retain(|m| !Arc::ptr_eq(m, mnt));
        return;
    };
    {
        let mut cur = mp.vfsmount.lock();
        if let Some(top) = cur.as_ref() {
            if !Arc::ptr_eq(top, mnt) {
                // Shadowed by a newer mount at the same mountpoint: detach
                // from the registry AND the chain index. The old code kept
                // the index row on purpose (the DFS still reached this
                // mount's subtree), but that left STALE rows behind after
                // the mount left the registry: every MS_REC clone walk
                // (collect_subtree_mounts iterates the INDEX, not the
                // registry) then cloned these dead mounts into each new
                // namespace — a compounding multiplier (ub2404: registry
                // grew to 4258 mounts in minutes; each polluted clone
                // attached stale subtrees over live paths, and later
                // executors found /var/lib gone — the accounts-daemon
                // STATE_DIRECTORY ENOENT that blocks the gdm greeter).
                // A dying mount's subtree is unmounted by its own
                // namespace Drop iterations (iter().rev() ordering).
                drop(cur);
                let mut state = VFS_STATE.lock();
                state.mounts.retain(|m| !Arc::ptr_eq(m, mnt));
                mount_index_remove(&mut state, mnt, &mp);
                return;
            }
            *cur = None;
        }
        // (perf-path lane) keep the lock-free presence mirror in step.
        mp.set_mount_flag(cur.is_some());
    }
    let mut state = VFS_STATE.lock();
    state.mounts.retain(|m| !Arc::ptr_eq(m, mnt));
    // sc181: live unmount — drop the index entry before the back-ref
    // clear below (the chain is recomputed from `mp`).
    mount_index_remove(&mut state, mnt, &mp);
    // Expose the mount this one was STACKED ON (Linux umount semantics):
    // when a short-lived namespace mounted over an existing mountpoint
    // (systemd 255's credentials child overmounts /dev/shm as its
    // private workspace), the attach replaced the dentry slot; tearing
    // the namespace down must restore the UNDERLYING mount, not strand
    // the mountpoint slot empty — ub2404: every later credentials child
    // found no mount, mounted its own tmpfs, and when IT died the
    // slot stayed None with a bare mountpoint dentry left behind.
    let restore = state.mounts.iter().rev().find(|m| {
        m.root
            .get_mountpoint_back()
            .map(|under| Arc::ptr_eq(&under, &mp))
            .unwrap_or(false)
    });
    if let Some(under) = restore {
        let under = under.clone();
        drop(state);
        *mp.vfsmount.lock() = Some(under);
        mp.set_mount_flag(true);
    } else {
        drop(state);
        // No underlying mount. A mountpoint dentry the mount itself
        // created (inode-less — the walk's bare-dentry arm) would read
        // as a NEGATIVE dcache entry after this unmount and every
        // lookup of the name would fail ENOENT (same discipline as
        // vfs_umount's cleanup; drop it so the next walk re-resolves
        // the name against the underlying filesystem).
        if mp.get_inode().is_none() {
            let name = mp.get_name();
            let parent = mp.parent.lock().clone();
            if let Some(p) = parent {
                p.remove_child(&name);
            }
        }
    }
    mnt.root.clear_mountpoint_back();
}

/// Relative component names from `anc` down to `d` (exclusive of `anc`),
/// walking the dentry tree upward and hopping mount boundaries via the
/// fs-root mountpoint back-references. None when `d` is not a strict
/// descendant of `anc` (or is `anc` itself).
fn dentry_relpath_below(anc: &Arc<Dentry>, d: &Arc<Dentry>) -> Option<Vec<String>> {
    let mut cur = d.clone();
    let mut comps: Vec<String> = Vec::new();
    loop {
        if Arc::ptr_eq(&cur, anc) {
            // comps were collected child-first on the way up; the caller
            // wants them ancestor-first (a path relative to `anc`).
            comps.reverse();
            return Some(comps);
        }
        let next = {
            let parent = cur.parent.lock().clone();
            match parent {
                Some(p) => {
                    comps.push(cur.get_name());
                    p
                }
                None => {
                    // Top of a mounted filesystem: hop to its mountpoint in
                    // the covering tree so mounts under nested mounts are
                    // still recognized as descendants.
                    match cur.get_mountpoint_back() {
                        Some(m) => m,
                        None => return None,
                    }
                }
            }
        };
        cur = next;
    }
}

// ============================================================================
// sc181: mount-registry chain index (MS_REC bind clone scan)
// ============================================================================

/// sc181: pure-parent chain of a mountpoint dentry: [mp itself, each
/// parent, ..., the first parentless (fs-root) dentry]. Never crosses
/// mount hops — a chain lives inside ONE filesystem; cross-mount nesting
/// is resolved at query time by the DFS in `collect_subtree_mounts`
/// (mounts inside another mount's tree key their chains under that
/// mount's ROOT dentry, and the DFS descends into every found mount's
/// root). Dentry parents are immutable after creation, so the chain is
/// stable — the one exception (MS_MOVE-onto-"/" rehoming) rebuilds the
/// whole index.
fn mountpoint_chain(mp: &Arc<Dentry>) -> Vec<Arc<Dentry>> {
    let mut chain = Vec::new();
    let mut cur = mp.clone();
    loop {
        chain.push(cur.clone());
        let parent = cur.parent.lock().clone();
        match parent {
            Some(p) => cur = p,
            None => return chain,
        }
    }
}

/// Index one freshly attached mount under every dentry of its
/// mountpoint's parent chain. Callers hold VFS_STATE.
fn mount_index_insert(state: &mut VfsState, mnt: &Arc<VfsMountInternal>, mp: &Arc<Dentry>) {
    for d in mountpoint_chain(mp) {
        state
            .mount_chain_index
            .entry(Arc::as_ptr(&d) as usize)
            .or_insert_with(|| MountBucket {
                anchor: d.clone(),
                mounts: Vec::new(),
            })
            .mounts
            .push(mnt.clone());
    }
}

/// Drop one mount from the index. Callers hold VFS_STATE; `mp` must still
/// be the mount's live mountpoint (call before clear_mountpoint_back —
/// the chain is recomputed from it, and parents are immutable so it
/// matches the insertion-time chain).
fn mount_index_remove(state: &mut VfsState, mnt: &Arc<VfsMountInternal>, mp: &Arc<Dentry>) {
    for d in mountpoint_chain(mp) {
        let key = Arc::as_ptr(&d) as usize;
        let mut drop_key = false;
        if let Some(bucket) = state.mount_chain_index.get_mut(&key) {
            bucket.mounts.retain(|m| !Arc::ptr_eq(m, mnt));
            drop_key = bucket.mounts.is_empty();
        }
        if drop_key {
            state.mount_chain_index.remove(&key);
        }
    }
}

/// Rebuild the chain index from the registry (MS_MOVE-onto-"/" rehomed
/// mountpoint dentries to new parents; every cached chain changed).
fn mount_index_rebuild(state: &mut VfsState) {
    state.mount_chain_index.clear();
    let mounts = state.mounts.clone();
    for mnt in mounts.iter() {
        if let Some(mp) = mnt.root.get_mountpoint_back() {
            mount_index_insert(state, mnt, &mp);
        }
    }
}

/// sc181: the MS_REC clone set — mounts nested under `anc` — via the
/// chain index, replacing the old whole-registry scan
/// (`state.mounts.iter()` + `dentry_relpath_below` per mount, i.e.
/// O(registry x depth) parent climbs per bind; sc180 measured sandbox
/// mount phases at 1.7-1.9 s because of it).
///
/// Equivalence with the old scan, where the old predicate was
/// "dentry_relpath_below(anc, m.mp) is Some(non-empty)" (a parent climb
/// WITH mount hops from each registry mount's mountpoint):
/// - a mount whose PURE chain contains `anc` is in bucket[anc] — its
///   climb passes `anc`, relpath non-empty: cloned;
/// - a mount with mountpoint == `anc` (the governing mount itself, or a
///   stack) is in bucket[anc] too but has an EMPTY relpath: not cloned —
///   exactly the old `rel.is_empty()` filter — while its subtree still
///   is, so the DFS descends into its root dentry;
/// - a mount inside ANOTHER mount's filesystem tree never reaches `anc`
///   by pure parents (its chain tops at that mount's root); the DFS
///   finds it by descending into each found mount's root, whose bucket
///   contains every mount attached directly in its tree.
/// Results are sorted by attach sequence — byte-identical order to the
/// old registry scan — so stacked clones attach parents before children
/// (bind_clone_attach crosses earlier clones while walking).
fn collect_subtree_mounts(
    anc: &Arc<Dentry>,
    fresh_root: &Arc<Dentry>,
) -> Vec<(Vec<String>, Arc<Dentry>, MntFlags)> {
    let state = VFS_STATE.lock();
    let mut found: Vec<(u64, Vec<String>, Arc<Dentry>, MntFlags)> = Vec::new();
    // Visited-mount dedup as a SET, not a Vec scan: the ub2404 boot
    // wedged with one CPU monopolizing collect_subtree_mounts while
    // every other task piled up on VFS_STATE — the Vec::contains linear
    // probe made the DFS O(mounts^2) and a service-restart-polluted
    // registry (thousands of namespace rows) turned that into a
    // minutes-long critical section (MONOPOLIST-TICK pid=603 at
    // collect_subtree_mounts+0x239, the cmp/lea/jn scan loop; soft
    // lockups on CPUs 2/4/6/7; serial silent from there).
    let mut visited: BTreeSet<*const VfsMountInternal> = BTreeSet::new();
    let mut stack: Vec<Arc<Dentry>> = Vec::new();
    stack.push(anc.clone());
    while let Some(node) = stack.pop() {
        let Some(bucket) = state.mount_chain_index.get(&(Arc::as_ptr(&node) as usize)) else {
            continue;
        };
        for mnt in bucket.mounts.iter() {
            let mptr = Arc::as_ptr(mnt) as *const VfsMountInternal;
            if !visited.insert(mptr) {
                continue;
            }
            // Never clone the just-attached bind onto itself.
            if Arc::ptr_eq(&mnt.root, fresh_root) {
                continue;
            }
            let Some(mp) = mnt.root.get_mountpoint_back() else {
                continue;
            };
            // Mounts deeper inside this mount's tree key their chains
            // under its root dentry — descend regardless of whether this
            // mount itself gets cloned.
            stack.push(mnt.root.clone());
            if Arc::ptr_eq(&mp, anc) {
                // Mounted AT anc: empty relpath — the old rel.is_empty()
                // filter; not cloned itself.
                continue;
            }
            if let Some(rel) = dentry_relpath_below(anc, &mp) {
                if !rel.is_empty() {
                    found.push((mnt.seq, rel, mnt.root.clone(), *mnt.flags.lock()));
                }
            }
        }
        // Anomaly report (one line per call that crosses the threshold):
        // a subtree clone that visits thousands of mounts means the
        // registry is polluted (dying-namespace rows surviving) or the
        // walk escaped the source subtree — either way the MS_REC bind
        // cost is about to be visible in every VFS_STATE waiter.
        if visited.len() == 4096 {
            crate::pr_warn!(
                "vfs: MS_REC clone walk crossed {} mounts (registry pollution or subtree escape); registry mounts={} chain_index={}",
                visited.len(),
                state.mounts.len(),
                state.mount_chain_index.len()
            );
            // Identity sample: the 8 most-recently-attached registry rows'
            // mountpoint paths — who is filling the registry.
            let n = state.mounts.len();
            for m in state.mounts.iter().skip(n.saturating_sub(8)) {
                let mp = m
                    .root
                    .get_mountpoint_back()
                    .and_then(|d| d.build_path_rooted(None))
                    .unwrap_or_else(|| alloc::string::String::from("(no-mp)"));
                crate::pr_warn!("vfs: registry row mp={} seq={}", mp, m.seq);
            }
        }
    }
    drop(state);
    found.sort_by_key(|(seq, _, _, _)| *seq);
    found
        .into_iter()
        .map(|(_, rel, root, flags)| (rel, root, flags))
        .collect()
}

/// Bind mount: attach the subtree rooted at `source` over `target`
/// (Linux mount(2) with MS_BIND — do_loopback). OH's appspawn sandbox
/// construction binds /proc, /dev, /sys, /system/... into
/// /mnt/sandbox/<user>/<pkg>/, and init's system sandbox binds chipsets
/// the same way. The mount created at `target` SHARES the source
/// directory's inode: the target exposes the same tree through the same
/// inode ops (no copy, writes are visible on both sides, like Linux).
/// Target existence is the caller's (sys_mount's) path_lookup check;
/// source resolution follows symlinks and mounts on the way (/system is
/// a symlink into the /usr ext4 mount — the bind must capture the
/// resolved inode, exactly what path_lookup yields).
///
/// `recursive` (MS_BIND|MS_REC — every OH sandbox bind carries it):
/// clone the mounts nested under the source subtree at the
/// corresponding target paths (Linux clone_mnt of the whole subtree).
/// Without this the bind exposed only the source's own inode tree:
/// the /sys bind hid selinuxfs at /sys/fs/selinux, samgr's selinux
/// check failed closed, and every AddSystemAbility was denied —
/// hdf_devmgr (critical) crash-looped into a panic reboot (sc22).
pub fn vfs_bind_mount(
    source: &str,
    target: &str,
    mnt_flags: MntFlags,
    recursive: bool,
) -> Result<(), i32> {
    // sc98 mount-latency probe: phase breakdown of every bind (rate
    // limited). TSC cycles — relative attribution only; the appspawn
    // slog already showed per-mount wall time at 5-25 ms and growing
    // over the boot, and the growth curve tracks the registry size
    // printed here.
    #[cfg(feature = "x86_64")]
    let t0 = crate::arch::x86_64::cpu::read_counter();
    let src = match path_lookup(source, 0) {
        Ok(p) => p,
        Err(e) => {
            // b20: sources that demonstrably exist at runtime (SetBundleQuota
            // opened /data/app/el2/0/base/com.ohos.systemui one minute before
            // the child's bind of the same path failed ENOENT) — name the
            // deepest prefix that DOES resolve so the break is one glance.
            // b22: also print the prefix's INODE — baked-image inodes are
            // known (debugfs), so a mismatch proves the runtime shadowed or
            // recreated the dir rather than the lookup being broken.
            if e == -2 {
                // sc160: the launcher crash-retry loop re-runs the whole
                // sandbox bind set on every respawn — 4153 of these in
                // sc159, each a printk under the UART irqsave lock and
                // part of the IRQ-OFF storm that trips foundation's
                // XCollie. First 300 carry the diagnosis; the rest are
                // repeats of the same paths.
                // 110th: the walk + print now ride the ohhunt gate
                // (~229 lines on every perf boot, each costing UART
                // emit + hilogd drain; the prefix probe walk itself
                // allocates and re-lookups paths).
                if !crate::debug::switches::oh_hunt_prints_on() {
                    return Err(e);
                }
                static BINDWALK_N: core::sync::atomic::AtomicUsize =
                    core::sync::atomic::AtomicUsize::new(0);
                if BINDWALK_N.fetch_add(1, core::sync::atomic::Ordering::Relaxed) >= 300 {
                    return Err(e);
                }
                let mut ok_until = String::from("/");
                let mut ok_ino: u64 = 0;
                let mut comps: Vec<&str> =
                    source.split('/').filter(|s| !s.is_empty()).collect();
                while !comps.is_empty() {
                    let probe = format!("/{}", comps.join("/"));
                    if let Ok(p) = path_lookup(&probe, 0) {
                        if let Some(i) = p.inode.as_ref() {
                            ok_ino = i.ino;
                        }
                        ok_until = probe;
                        break;
                    }
                    comps.pop();
                }
                crate::pr_debug!(
                "bindwalk: '{}' ENOENT, resolves until '{}' ino={}",
                    source,
                    ok_until,
                    ok_ino
                );
                // datatap (el2/100 hunt): dump the kernel's cached children
                // of the deepest resolved dir — with the baked-image inos
                // known from debugfs, a divergence here separates "guest
                // mutated the tree" (runtime inodes) from "dcache went
                // stale/wrong" (baked inos but lookup still misses).
                if crate::trace::EVENT_DATATAP.armed()
                    && source.starts_with("/data/")
                {
                    if let Ok(p) = path_lookup(&ok_until, 0) {
                        if let Some(ref d) = p.dentry {
                            let kids: Vec<String> = d
                                .children
                                .lock()
                                .iter()
                                .map(|(n, c)| {
                                    if c.is_negative() {
                                        format!("{n}=NEG")
                                    } else {
                                        let ino = c.get_inode().map(|i| i.ino).unwrap_or(0);
                                        format!("{n}={ino}")
                                    }
                                })
                                .collect();
                            crate::pr_warn!(
                                "apptap dcache '{}': [{}]",
                                ok_until,
                                kids.join(" ")
                            );
                        }
                    }
                }
            }
            return Err(e);
        }
    };
    let inode = match src.inode.clone() {
        Some(i) => i,
        None => match src.dentry.as_ref().and_then(|d| d.get_inode()) {
            Some(i) => i,
            None => return Err(errno::Errno::NoSuchFileOrDirectory.as_neg_i32()),
        },
    };
    // A bind clone inherits the source mount's read-only flag (Linux
    // clone_mnt copies mnt_flags minus propagation bits — a bind of a ro
    // mount IS ro; sc21). Without this, a mkdir/create under a bind of the
    // ro /usr or /vendor ext4 slipped past check_not_readonly (the new
    // mount carried only the syscall's flags), dove into the ext4 write
    // machinery, and surfaced as EIO — sc20's sandbox prep saw
    // mkdir '/mnt/sandbox/system/vendor/firmware' fail -5 where Linux
    // answers EROFS and init merely warns and moves on.
    let mnt_flags = if path_on_readonly_mount(source) {
        MntFlags::new(mnt_flags.bits() | MntFlags::MNT_READONLY)
    } else {
        mnt_flags
    };
    // sc31 hunt: what did the sandbox's own mounts actually capture? The
    // '/'-bind at the sandbox's /mnt decides what /mnt/sandbox means for
    // every pivoted process — print the resolved source dentry's GLOBAL
    // path so the captured tree is unambiguous. Rate-limited alongside
    // bindrec (sc37: per-spawn prints x retry storms flooded the UART).
    // 110th: rides the ohhunt gate with the rest of the mount hunt
    // family (build_path walks the dentry chain per line).
    if sbx_want(target) && crate::debug::switches::oh_hunt_prints_on() {
        if let Some(ref sd) = src.dentry {
            static SBXBIND_N: core::sync::atomic::AtomicUsize =
                core::sync::atomic::AtomicUsize::new(0);
            if SBXBIND_N.fetch_add(1, core::sync::atomic::Ordering::Relaxed) < 200 {
                crate::pr_info!(
                    "sbxbind '{}' -> '{}': src dentry global='{}' ino={:#x}",
                    source,
                    target,
                    sd.build_path(),
                    inode.ino
                );
            }
        }
    }
    let fresh_root = vfs_mount(target, inode.clone(), mnt_flags);
    #[cfg(feature = "x86_64")]
    let t2 = crate::arch::x86_64::cpu::read_counter();

    // MS_REC: clone the mounts nested under the source subtree to the
    // same relative paths under the target (see the doc comment). The
    // enumeration hops ONE mount boundary outward from the resolved
    // source dentry: for a plain bind (/dev) that is equivalent, but for
    // OH's SELF-bind (/mnt/sandbox/<user>/<pkg> onto itself, re-flagging
    // propagation for pivot_root) the resolved dentry is the freshly
    // attached bind root whose subtree is still EMPTY — the appspawn
    // child mounts live under the ORIGINAL mountpoint dentry. Without
    // the hop (and without cloning at all for self-binds) the fresh
    // root shadowed the child binds: post-pivot /dev/null resolved to
    // the bare tmpfs dir and the child died at appspawn_common.c:350
    // "open dev_null error: 2" (sc27).
    //
    // sc31 LESSON — clones attach by fs-walking INSIDE the fresh bind
    // root, never by global-path vfs_mount() walks: the old global walk
    // fabricated INODE-LESS placeholder dentries for missing
    // intermediates (and stacked a clone of the just-made bind onto
    // itself). The placeholders then answered real lookups: every
    // '/mnt/...' resolution from inside the pivoted system sandbox hit
    // the stub 'sandbox' inside the /-bind copy and failed ENOENT —
    // appspawn's mkdir('/mnt/sandbox/100') returned -2 200k times and
    // no app binary ever exec'd (sc28). Linux clone_mnt builds the new
    // subtree by cloning dentries, so no placeholder can leak; here the
    // equivalent discipline is: walk the fresh root with plain fs
    // lookups (the bind root SHARES the source inode, so every mounted
    // subpath resolves), cross into earlier clones for stacking, and
    // DROP any clone whose path does not resolve — no fabrication.
    if recursive {
        let fresh_root = match fresh_root {
            Some(r) => r,
            None => return Ok(()),
        };
        // SELF-BINDS (source == target, OH's sandbox re-flag idiom):
        // skip the clone phase. Since vfs_mount attaches at the
        // CALLER-visible mountpoint (a9595213), every LATER bind's
        // target walk crosses this self-bind and lands INSIDE the copy
        // naturally — cloning the subtree again only stacks duplicate
        // mounts, ~50 per appspawn spawn, each registered forever (the
        // registry is never pruned), which made every later clone
        // enumeration slower until spawns blew appspawn's 3s watchdog
        // (sc37/sc38: 'wait child timeout', no app exec). The sc27
        // reason for cloning self-binds (post-pivot /dev/null shadowed
        // by a bare copy) is superseded by that attach-side fix.
        {
            let src_norm = source.trim_end_matches('/');
            let tgt_norm = target.trim_end_matches('/');
            if src_norm == tgt_norm {
                return Ok(());
            }
        }
        let anc = match src.dentry.clone() {
            Some(d) => d.get_mountpoint_back().unwrap_or(d),
            None => return Ok(()),
        };
        // sc181: indexed DFS over the mounts nested under the source
        // subtree (was: the whole-registry scan with a parent climb per
        // mount — O(registry x depth) per bind, the 1.7-1.9 s sandbox
        // mount phases in sc180's telemetry).
        let clones = collect_subtree_mounts(&anc, &fresh_root);
        #[cfg(feature = "x86_64")]
        let (t3, n_mounts) = {
            (
                crate::arch::x86_64::cpu::read_counter(),
                VFS_STATE.lock().mounts.len(),
            )
        };
        let nclones = clones.len();
        for (rel, root, flags) in clones {
            // Rate-limited (sc37 lesson): one boot printed 1,012,926 of
            // these — ~50 clones per spawn x the appspawn retry storm —
            // and the synchronous UART writes alone pushed every spawn
            // past appspawn's 3s child watchdog (exit -9 mid-prep,
            // forever). The clone list is visible in the first 200.
            static BINDREC_N: core::sync::atomic::AtomicUsize =
                core::sync::atomic::AtomicUsize::new(0);
            if BINDREC_N.fetch_add(1, core::sync::atomic::Ordering::Relaxed) < 200 {
                // 97th (hp97): pr_warn, not pr_info — the hunt rigs run
                // LOGLEVEL=4 and these sandbox-clone records (the face-C
                // spawn-path evidence: which child cloned which mounts)
                // were dropped before the ring. Rate-capped at 200/boot;
                // sprobe=0 silences the sibling mtprobe but not this —
                // bindrec rides every boot by design (appclone forensics).
                // 110th: "by design" reversed — ~90 lines on every perf
                // boot, each costing UART emit + hilogd drain; rides the
                // ohhunt gate with the rest of the mount hunt family.
                if crate::debug::switches::oh_hunt_prints_on() {
                    crate::pr_warn!(
                        "bindrec: cloned '/{}' under '{}' (flags {:#x})",
                        rel.join("/"),
                        target,
                        flags.bits()
                    );
                }
            }
            bind_clone_attach(&fresh_root, &anc, &rel, &root, flags);
        }
        #[cfg(feature = "x86_64")]
        {
            let t4 = crate::arch::x86_64::cpu::read_counter();
            static MTPROBE_N: core::sync::atomic::AtomicUsize =
                core::sync::atomic::AtomicUsize::new(0);
            // sc108: the print itself was the launcher killer — UART TX
            // is a busy THRE poll (115200 baud ≈ 87us/byte), so each
            // ~150-byte line burns ~13ms of stime in the MOUNTING task's
            // context; the post-exec launcher child mounts its sandbox
            // and paid its whole 3s appspawn watchdog to this probe (the
            // sc37 bindrec lesson, replayed). 110th: default flipped —
            // arms only via rux:ohhunt (retired debug=ohhunt) (or legacy sprobe=1).
            if crate::debug::switches::oh_hunt_prints_on()
                && MTPROBE_N.fetch_add(1, core::sync::atomic::Ordering::Relaxed) < 400
            {
                crate::pr_debug!(
                "mtprobe: bind '{}' -> '{}': lookup+attach={}cyc clone-scan={}cyc clone-attach={}cyc nmounts={} nclones={}",
                    source,
                    target,
                    t2 - t0,
                    t3 - t2,
                    t4 - t3,
                    n_mounts,
                    nclones
                );
            }
        }
    }
    Ok(())
}

/// Attach one MS_REC clone `src_root` at `rel` INSIDE the fresh bind root.
///
/// Walks the fresh root's dentry tree with dcache hits and fs lookups
/// only — crossing mounts already cloned there so stacked submounts land
/// where lookups traverse them — and silently drops the clone when a
/// component does not resolve: the bind root SHARES the source inode, so
/// every genuinely mounted subpath resolves; a miss means we would be
/// fabricating a placeholder dentry, which is exactly the sc31 bug (stubs
/// answered real lookups with ENOENT forever).
fn bind_clone_attach(
    fresh_root: &Arc<Dentry>,
    src_base: &Arc<Dentry>,
    rel: &[String],
    src_root: &Arc<Dentry>,
    flags: MntFlags,
) {
    let mut cur = fresh_root.clone();
    // Parallel SOURCE-side cursor (mount-crossing, like the target walk):
    // the fallback inode source for kernel-created mountpoints — see the
    // miss arm below (ub2404-login flip6).
    let mut src_cur = src_base.clone();
    let Some(last) = rel.last() else { return };
    for comp in rel.iter() {
        // Cross an earlier clone attached at this level: later siblings
        // must land inside the stacked copy, matching lookup traversal.
        cur = follow_mount(cur);
        let is_last = core::ptr::eq(comp, last);
        if is_last {
            let child = match cur.lookup_child(comp) {
                Some(c) => c,
                None => {
                    let dir_inode = match cur.get_inode() {
                        Some(i) => i,
                        None => return, // placeholder territory — drop the clone
                    };
                    let ops = match dir_inode.ops.as_ref() {
                        Some(o) => o,
                        None => return,
                    };
                    let child_inode = match {
                        // INV-VFSOPS-1 dispatchers (best-effort clone
                        // attach: every miss maps to None — try source side).
                        let ino = match ops.call_lookup(
                            &*dir_inode,
                            comp.as_bytes(),
                            Err(errno::Errno::NoSuchFileOrDirectory),
                        ) {
                            // absent on disk — try source side
                            Err(_) => None,
                            Ok(ino) => Some(ino),
                        };
                        match ino {
                            Some(ino) => match ops.call_iget(
                                &*dir_inode,
                                comp.as_bytes(),
                                ino,
                                Err(errno::Errno::NoSuchFileOrDirectory),
                            ) {
                                Ok(i) => Some(i),
                                Err(_) => None,
                            },
                            None => None,
                        }
                    } {
                        Some(i) => i,
                        // SOURCE-SIDE FALLBACK (ub2404-login flip6, 2026-11-15):
                        // the mountpoint has no on-disk entry — /proc, /dev,
                        // /sys on a rootfs image without baked placeholder
                        // dirs. The ORIGINAL tree still has the dentry (the
                        // mount created it in the dcache), so the clone's
                        // target child can carry THAT dentry's inode. This
                        // is not fabrication: the source-side dentry exists
                        // and is the very thing being bound. Without this,
                        // the recursive bind of "/" dropped the /proc,
                        // /dev, /sys clones — walks through the bind copy
                        // (and, combined with the root flip, the whole
                        // post-flip view) lost every kernel-created
                        // mountpoint and namespace-sandboxed execs died
                        // 203/EXEC (flip6 [thru]/[post] matrices).
                        //
                        // The mountpoint dentry itself carries NO inode
                        // (vfs_mount's creation arm only attaches the mount
                        // — the inode lives on the mount's root dentry), so
                        // take the inode the WALK would reach: cross the
                        // mount and read its root's inode (flip6 round 2:
                        // every clone was dropped here because /proc, /sys,
                        // /dev, /run mountpoints are all inode-less
                        // kernel-created dentries — FLIP6-ATTACH kids 0->0
                        // x9, [thru] matrix all ERR).
                        None => match src_cur.lookup_child(comp) {
                            Some(sd) => match sd
                                .get_inode()
                                .or_else(|| follow_mount(sd.clone()).get_inode())
                            {
                                Some(i) => i,
                                None => return,
                            },
                            None => return, // genuinely absent — drop the clone
                        },
                    };
                    let d = Arc::new(Dentry::new(comp.clone()));
                    d.set_inode(child_inode);
                    d.set_parent(cur.clone());
                    cur.add_child(comp.clone(), d.clone());
                    d
                }
            };
            let Some(root_inode) = src_root.get_inode() else { return };
            let mounted_root = Arc::new(Dentry::new(String::from("/")));
            mounted_root.set_inode(root_inode);
            mounted_root.set_hashed();
            let mnt_desc = Arc::new(VfsMountInternal::new(mounted_root.clone(), flags));
            child.set_mount(mnt_desc.clone());
            mounted_root.set_mountpoint_back(child.clone());
            let mut state = VFS_STATE.lock();
            state.mounts.push(mnt_desc.clone());
            // sc181: index the clone under its mountpoint chain too.
            mount_index_insert(&mut state, &mnt_desc, &child);
            drop(state);
            // sc98: MS_REC clones belong to the caller's namespace too —
            // a dying private ns must unmount them with the rest.
            crate::process::ns::ns_track_vfsmount(mnt_desc);
            return;
        }
        // Intermediate component — dcache hit or fs lookup; never fabricate
        // (the source-side fallback below only carries inodes of dentries
        // that exist in the ORIGINAL tree).
        cur = match cur.lookup_child(comp) {
            Some(c) => c,
            None => {
                let dir_inode = match cur.get_inode() {
                    Some(i) => i,
                    None => return,
                };
                let ops = match dir_inode.ops.as_ref() {
                    Some(o) => o,
                    None => return,
                };
                let child_inode = match {
                    // INV-VFSOPS-1 dispatchers (best-effort clone
                    // attach: every miss maps to None — try source side).
                    let ino = match ops.call_lookup(
                        &*dir_inode,
                        comp.as_bytes(),
                        Err(errno::Errno::NoSuchFileOrDirectory),
                    ) {
                        // absent on disk — try source side
                        Err(_) => None,
                        Ok(ino) => Some(ino),
                    };
                    match ino {
                        Some(ino) => match ops.call_iget(
                            &*dir_inode,
                            comp.as_bytes(),
                            ino,
                            Err(errno::Errno::NoSuchFileOrDirectory),
                        ) {
                            Ok(i) => Some(i),
                            Err(_) => None,
                        },
                        None => None,
                    }
                } {
                    Some(i) => i,
                    // SOURCE-SIDE FALLBACK — see the final arm's comment
                    // (including the inode-less mountpoint crossing).
                    None => match src_cur.lookup_child(comp) {
                        Some(sd) => match sd
                            .get_inode()
                            .or_else(|| follow_mount(sd.clone()).get_inode())
                        {
                            Some(i) => i,
                            None => return,
                        },
                        None => return,
                    },
                };
                let d = Arc::new(Dentry::new(comp.clone()));
                d.set_inode(child_inode);
                d.set_parent(cur.clone());
                cur.add_child(comp.clone(), d.clone());
                d
            }
        };
        // Advance the parallel source cursor (mount-crossing, like the
        // target walk): deeper kernel-created mountpoints (/proc/sys/...)
        // resolve through it when the disk has no placeholder entries.
        src_cur = match src_cur.lookup_child(comp) {
            Some(c) => follow_mount(c),
            None => src_cur,
        };
    }
}

/// Move a mount: mount(2) with MS_MOVE re-attaches the filesystem
/// mounted at `from` over `to` (Linux move_mount/MS_MOVE — OH's
/// switch_root moves /dev,/proc,/sys,/run into the new root's tree and
/// finally moves /usr onto /, replacing the initramfs root).
///
/// `to == "/"` overlays the VFS root the same way `vfs_mount("/")`
/// does (root inode replacement), and additionally drops the old
/// root's cached children so ramdisk names cannot shadow the moved-in
/// filesystem's root (lookups resolve through the new root inode).
/// Virtual switch_root for a PRIVATE mount namespace — the shadowing-
/// correct answer for `MS_MOVE <crafted-root> /` from a namespace child.
///
/// systemd 255's mount_namespace() builds a recursive clone of / under
/// /run/systemd/mount-rootfs, applies the service's mount entries onto
/// the CLONE, then does `mount(root, "/", MS_MOVE)` + chroot inside the
/// service's own CLONE_NEWNS (namespace.c: root = "/run/systemd/
/// mount-rootfs"; the temporary dir "prevents any mounts from being
/// potentially obscured by other mounts we already applied"). In the
/// reference the MS_MOVE re-roots ONLY that namespace.
///
/// Rux has one dentry tree: the old code swapped the GLOBAL root (root
/// inode swap + child rehome) and every OTHER task — PID 1 included —
/// inherited the service's crafted root; when the namespace then died,
/// its Drop unmounted the tracked mounts, tearing pieces off the LIVE
/// root (serial-155614: journald's teardown left /dev/shm ENOENT,
/// /proc/<pid>/mountinfo ENOENT, udevd 226/NAMESPACE, random-seed and
/// sysusers failing downstream). The reference behavior — caller gets
/// the new root, everyone else keeps theirs — is produced WITHOUT a
/// namespace-private mount tree by re-rooting only the CALLER:
///
///  - the crafted tree stays attached at its global path (its mounts
///    keep their registry rows and the namespace keeps its teardown
///    list — Drop still detaches exactly what this ns attached);
///  - the task's fs root becomes (root-path = the crafted mountpoint's
///    global path, root-dentry = the crafted mount's root), so every
///    absolute lookup starts INSIDE the crafted tree (path_lookup's
///    fast-base) and every mount/remount from this task resolves
///    through the root-path prefix INTO the crafted tree (the same
///    discipline vfs_attach_mount_at / vfs_mount already apply for
///    chrooted tasks — flag flips stay private to the clone);
///  - getcwd answers root-relative paths (build_path_rooted), so the
///    service sees "/" like after a real pivot.
///
/// Consumed by sys_mount's MS_MOVE and sys_move_mount when the target is
/// "/" and the caller's mount namespace is not the init namespace.
pub fn vfs_virtual_switch_root(from: &str) -> Result<(), i32> {
    if from == "/" {
        return Err(errno::Errno::InvalidArgument.as_neg_i32());
    }
    // Source: the MOUNTPOINT dentry (final component not followed) —
    // the same walk discipline as vfs_move_mount's from-side.
    let src_child = {
        let vfs_root = VFS_STATE.lock().root_dentry.clone()
            .ok_or(errno::Errno::NoSuchFileOrDirectory.as_neg_i32())?;
        let comps: Vec<&str> = from.split('/').filter(|s| !s.is_empty()).collect();
        let mut current = vfs_root;
        for (i, component) in comps.iter().enumerate() {
            let child = match current.lookup_child(component) {
                Some(c) => c,
                None => {
                    crate::pr_warn!(
                        "vswitch-root: walk miss at '{}' of '{}' (pid {})",
                        component,
                        from,
                        crate::process::current_pid()
                    );
                    return Err(errno::Errno::NoSuchFileOrDirectory.as_neg_i32());
                }
            };
            current = if i + 1 == comps.len() {
                child
            } else {
                follow_mount(child)
            };
        }
        current
    };
    let mnt = match src_child.get_mount() {
        Some(m) => m.clone(),
        None => {
            crate::pr_warn!(
                "vswitch-root: no mount object at '{}' (pid {})",
                from,
                crate::process::current_pid()
            );
            return Err(errno::Errno::InvalidArgument.as_neg_i32());
        }
    };
    // The crafted root must be ATTACHED (a mountpoint back-ref exists);
    // a detached mount fd or a plain directory is EINVAL, like Linux
    // refusing to MS_MOVE a non-mount.
    if mnt.root.get_mountpoint_back().is_none() {
        crate::pr_warn!(
            "vswitch-root: no attached mount at '{}' (pid {})",
            from,
            crate::process::current_pid()
        );
        return Err(errno::Errno::InvalidArgument.as_neg_i32());
    }

    // Re-root the CALLER (path + dentry, chroot discipline).
    if let Some(task) = crate::sched::current() {
        if let Some(fs) = task.fs_arc() {
            fs.set_root_with_dentry(from.as_bytes(), Some(mnt.root.clone()));
        }
    }

    // Namespace anchor: setns(CLONE_NEWNS) re-anchoring and Drop
    // bookkeeping read ns.root; record the crafted root like a pivot.
    let ns = crate::process::ns::current_mnt_ns();
    *ns.root.lock() = Some(mnt.root.clone());
    // Teardown tracking (mntput-on-nsput): the attach path usually
    // tracked this mount already — dedupe by identity so Drop unmounts
    // it exactly once.
    {
        let mut list = ns.vfs_mounts.lock();
        if !list.iter().any(|m| alloc::sync::Arc::ptr_eq(m, &mnt)) {
            list.push(mnt.clone());
        }
    }
    crate::pr_info!(
        "vswitch-root: task re-rooted at '{}' (pid {})",
        from,
        crate::process::current_pid()
    );
    Ok(())
}

pub fn vfs_move_mount(from: &str, to: &str) -> Result<(), i32> {
    if from == "/" {
        return Err(errno::Errno::DeviceOrResourceBusy.as_neg_i32());
    }

    // Source: the MOUNTPOINT dentry (not the mounted root) — the walk
    // follows mounts on the way but takes the final component without
    // following, so `from` names the covered dentry that carries the
    // VfsMountInternal. Intermediate results must cross their mounts
    // (path_lookup discipline): resolving /mnt/data descends into the
    // tmpfs mounted on /mnt BEFORE looking up "data" — the old walk
    // looked "data" up in the ramdisk's /mnt placeholder and OH's
    // switch_root MS_MOVE /mnt/data → /usr/mnt/data failed ENOENT
    // (lb9: switch_root.c:121), stranding that tmpfs.
    let src_child = {
        let vfs_root = VFS_STATE.lock().root_dentry.clone()
            .ok_or(errno::Errno::NoSuchFileOrDirectory.as_neg_i32())?;
        let comps: Vec<&str> = from.split('/').filter(|s| !s.is_empty()).collect();
        let mut current = vfs_root;
        for (i, component) in comps.iter().enumerate() {
            let child = current
                .lookup_child(component)
                .ok_or(errno::Errno::NoSuchFileOrDirectory.as_neg_i32())?;
            current = if i + 1 < comps.len() {
                follow_mount(child)
            } else {
                child
            };
        }
        current
    };
    let mnt = src_child
        .get_mount()
        .ok_or(errno::Errno::InvalidArgument.as_neg_i32())?
        .clone();

    // Detach from the source mountpoint.
    // sc181: drop the chain-index entry first (the chain is recomputed
    // from the still-live mountpoint back-ref).
    {
        let mut state = VFS_STATE.lock();
        mount_index_remove(&mut state, &mnt, &src_child);
    }
    src_child.clear_mount();
    mnt.root.clear_mountpoint_back();

    if to == "/" {
        // Root overlay: root inode := moved mount's root inode; the moved
        // mount's cached children (the /proc, /dev, ... mounts the
        // switcher attached under it) are rehomed onto the VFS root so
        // they stay reachable; then the OLD root's stale ramdisk children
        // are gone with the swap (fresh names resolve through the new
        // root inode's directory ops). Mirrors vfs_mount("/")'s inode
        // overlay plus the MS_MOVE child carry-over.
        let mut state = VFS_STATE.lock();
        state.mounts.retain(|m| !Arc::ptr_eq(m, &mnt));
        if let Some(root) = state.root_dentry.clone() {
            // SELF-BIND FLIP (ub2404-login, 2026-11-15): when the moved
            // mount's root carries the SAME inode as the VFS root, the
            // mount is a recursive bind OF "/" itself (systemd v255's
            // executor idiom: mount("/", "/run/systemd/mount-rootfs",
            // MS_BIND|MS_REC) ... mount(".", "/", MS_MOVE)). The
            // wipe-and-rehome below annihilates in that shape —
            // clear_children() empties the root's map and
            // rehome_children_into moves the (same, now-empty) alias
            // children — orphaning every top-level dentry INCLUDING the
            // kernel-created mountpoints (/proc, /dev, /sys: dcache-only,
            // no on-disk entry to re-resolve). Post-flip lookups then hit
            // the bare ext4 placeholders and every namespace-sandboxed
            // service died 203/EXEC on execve("/proc/self/fd/N") while
            // open() still worked through the procfs string shortcut
            // (flip6 probe, ser-154804). Linux's view after this move is
            // IDENTICAL to before (the moved tree IS the root tree): drop
            // the mount and keep the tree untouched.
            let self_bind = match (mnt.root.get_inode(), root.get_inode()) {
                (Some(a), Some(b)) => Arc::ptr_eq(&a, &b),
                _ => false,
            };
            if self_bind {
                crate::pr_info!(
                    "move_mount: self-bind flip onto / — identity, tree kept"
                );
                return Ok(());
            }
            if let Some(inode) = mnt.root.get_inode() {
                root.set_inode(inode);
            }
            root.clear_children();
            mnt.root.rehome_children_into(&root);
            // lb-lane hunt (switch_root): the moved-in mounts must stay
            // reachable — post-switch mkdir /storage/media and /mnt/* on
            // lb3-lb6 say they are NOT (ENOENT/EROFS). Dump the new root's
            // children with mount bits right after the rehome.
            {
                let kids: Vec<(String, bool, bool)> = root
                    .children
                    .lock()
                    .iter()
                    .map(|(n, d)| {
                        (
                            n.clone(),
                            d.vfsmount.lock().is_some(),
                            d.get_inode().is_some(),
                        )
                    })
                    .collect();
                let shown: alloc::string::String = kids
                    .iter()
                    .map(|(n, m, i)| {
                        alloc::format!("{}{}{}", n, if *m { "(M)" } else { "" }, if *i { "" } else { "(noino)" })
                    })
                    .collect::<Vec<_>>()
                    .join(" ");
                crate::pr_warn!(
                    "SWROOT-CHILDREN ({}): {} | src-root-children-now: {}",
                    kids.len(),
                    shown,
                    mnt.root.children.lock().len()
                );
            }
            // sc181: rehoming reparented every mountpoint dentry under
            // the moved root — all cached chains changed wholesale.
            mount_index_rebuild(&mut state);
        }
        return Ok(());
    }

    // Regular target: find-or-create the mountpoint dentry (same walk
    // discipline as vfs_mount — follow mounts on intermediate nodes).
    let comps: Vec<&str> = to.split('/').filter(|s| !s.is_empty()).collect();
    let vfs_root = VFS_STATE.lock().root_dentry.clone()
        .ok_or(errno::Errno::NoSuchFileOrDirectory.as_neg_i32())?;
    let mut current = vfs_root;
    current = follow_mount(current);
    for (i, component) in comps.iter().enumerate() {
        let is_last = i + 1 == comps.len();
        let name = String::from(*component);
        let child = match current.lookup_child(&name) {
            Some(existing) => existing,
            None => {
                let d = Arc::new(Dentry::new(name.clone()));
                d.set_parent(current.clone());
                current.add_child(name.clone(), d.clone());
                d
            }
        };
        if is_last {
            child.set_mount(mnt.clone());
            // Re-point the moved mount's root at the new mountpoint (the
            // back-reference drives the mountpoint prefix in dentry paths;
            // see vfs_mount).
            mnt.root.set_mountpoint_back(child.clone());
            // sc181: index at the NEW mountpoint's chain.
            let mut state = VFS_STATE.lock();
            mount_index_insert(&mut state, &mnt, &child);
        } else {
            current = follow_mount(child);
        }
    }
    Ok(())
}

/// Attach a DETACHED mount object (fsmount/open_tree-CLONE product, or a
/// mount just detached by move_mount) at `target` — the move_mount(2)
/// attach step. Shares the mountpoint-walk discipline of vfs_mount:
/// intermediate components cross their mounts, the final dentry is
/// found-or-created and receives the mount.
///
/// Returns the mountpoint dentry the mount landed on (for registry
/// bookkeeping by the caller).
pub fn vfs_attach_mount_at(
    mnt: &Arc<VfsMountInternal>,
    target: &str,
) -> Result<Arc<Dentry>, i32> {
    // Namespace discipline (same as vfs_mount): attach at the mountpoint
    // AS THE CALLER SEES IT.
    let owned_target;
    let target = {
        let root = get_process_root();
        if root != "/" && target.starts_with('/') {
            owned_target = format!("{}{}", root.trim_end_matches('/'), target);
            owned_target.as_str()
        } else {
            target
        }
    };

    let mut state = VFS_STATE.lock();
    let vfs_root = state
        .root_dentry
        .clone()
        .ok_or(errno::Errno::NoSuchFileOrDirectory.as_neg_i32())?;

    if target == "/" {
        // Root attach: overlay the VFS root's inode with the mount's root
        // inode and carry the mount's cached children over (same policy
        // as vfs_move_mount's to == "/" arm).
        state.mounts.retain(|m| !Arc::ptr_eq(m, mnt));
        if let Some(inode) = mnt.root.get_inode() {
            vfs_root.set_inode(inode);
        }
        vfs_root.clear_children();
        mnt.root.rehome_children_into(&vfs_root);
        mount_index_rebuild(&mut state);
        return Ok(vfs_root);
    }

    let comps: Vec<&str> = target.split('/').filter(|s| !s.is_empty()).collect();
    let mut current = vfs_root;
    current = follow_mount(current);
    let mut mountpoint: Option<Arc<Dentry>> = None;
    for (i, component) in comps.iter().enumerate() {
        let is_last = i + 1 == comps.len();
        let name = String::from(*component);
        let child = match current.lookup_child(&name) {
            Some(existing) => existing,
            None => {
                let d = Arc::new(Dentry::new(name.clone()));
                d.set_parent(current.clone());
                current.add_child(name.clone(), d.clone());
                d
            }
        };
        if is_last {
            child.set_mount(mnt.clone());
            mnt.root.set_mountpoint_back(child.clone());
            state.mounts.push(mnt.clone());
            mount_index_insert(&mut state, mnt, &child);
            mountpoint = Some(child);
        } else {
            current = follow_mount(child);
        }
    }
    let mountpoint = mountpoint
        .ok_or(errno::Errno::InvalidArgument.as_neg_i32())?;
    // ns_track_vfsmount must run AFTER dropping VFS_STATE (lazy
    // ns init reaches get_vfs_root() — see the sc98 note in vfs_mount).
    drop(state);
    crate::process::ns::ns_track_vfsmount(mnt.clone());
    Ok(mountpoint)
}

/// The TOPMOST mount covering `path` — the mount whose flags
/// mount_setattr/reconfigure apply (Linux path mounting semantics: the
/// last-mounted mount at the terminal dentry, or the mount crossed on
/// the way down when none sits on the terminal dentry).
pub fn vfs_covering_mount(path: &str) -> Option<Arc<VfsMountInternal>> {
    let owned;
    let path = {
        let root = get_process_root();
        if root != "/" && path.starts_with('/') {
            owned = format!("{}{}", root.trim_end_matches('/'), path);
            owned.as_str()
        } else {
            path
        }
    };
    let vfs_root = VFS_STATE.lock().root_dentry.clone()?;
    // vfs_remount's walk discipline: check for a mount on the current
    // dentry BEFORE each component (the topmost mount covering the path
    // wins; a mount stacked AT the terminal dentry shadows everything
    // crossed on the way down).
    let mut current = vfs_root;
    let mut crossed: Option<Arc<VfsMountInternal>> = None;
    for component in path.split('/').filter(|s| !s.is_empty()) {
        if let Some(mnt) = current.get_mount() {
            crossed = Some(mnt.clone());
            current = mnt.root.clone();
        }
        current = current.lookup_child(component)?;
    }
    current.get_mount().or(crossed)
}

/// Detach a mount from its current mountpoint (move_mount's from-side
/// for an attached mount): drops the registry row and index entry and
/// clears the dentry/back-reference links. The mount object itself
/// (Arc) stays alive for re-attachment.
pub fn vfs_detach_mount(mnt: &Arc<VfsMountInternal>) -> Result<(), i32> {
    let mp = mnt
        .root
        .get_mountpoint_back()
        .ok_or(errno::Errno::InvalidArgument.as_neg_i32())?;
    {
        let mut state = VFS_STATE.lock();
        // sc181: drop the chain-index entry BEFORE the back-ref clear
        // (the chain is recomputed from the still-live mountpoint).
        mount_index_remove(&mut state, mnt, &mp);
        state.mounts.retain(|m| !Arc::ptr_eq(m, mnt));
    }
    // Only clear the slot when this mount is still the live one there (a
    // newer stacked mount owns the slot — same guard as vfs_umount_object).
    {
        let mut cur = mp.vfsmount.lock();
        if let Some(top) = cur.as_ref() {
            if Arc::ptr_eq(top, mnt) {
                *cur = None;
            }
        }
        mp.set_mount_flag(cur.is_some());
    }
    mnt.root.clear_mountpoint_back();
    Ok(())
}

/// The mount GOVERNING `d`: the topmost mount stacked ON the dentry, or
/// — when none sits on it — the mount whose filesystem tree contains it
/// (the climb walks parent links up to a mounted root, then outward
/// through its mountpoint). None means the dentry lives in the root
/// filesystem proper (no VfsMountInternal covers it — the global root
/// overlay). open_tree(CLONE) clones this object; "/" answers None and
/// callers fall back to cloning the root inode.
pub fn vfs_governing_mount_of(d: &Arc<Dentry>) -> Option<Arc<VfsMountInternal>> {
    if let Some(m) = d.get_mount() {
        return Some(m);
    }
    let mut cur = d.clone();
    loop {
        // SAFETY: plain parent-pointer read under its spinlock.
        let parent = cur.parent.lock().clone();
        match parent {
            Some(p) => cur = p,
            None => {
                // A filesystem root. Mounted? (mountpoint back-ref set.)
                if let Some(_mp) = cur.mountpoint_dentry() {
                    // Find the registry mount whose root IS this dentry —
                    // a newer stack on the same mountpoint may own the
                    // dentry's vfsmount slot, so the registry is the
                    // authority (rare path; a short scan).
                    let state = VFS_STATE.lock();
                    let found = state
                        .mounts
                        .iter()
                        .rev()
                        .find(|m| Arc::ptr_eq(&m.root, &cur))
                        .cloned();
                    if let Some(m) = found {
                        return Some(m);
                    }
                    // Mountpoint back-ref without a registry row (torn
                    // detach): treat as unmounted, climb outward.
                    cur = _mp;
                } else {
                    // The global root — the root filesystem, no mount.
                    return None;
                }
            }
        }
    }
}

/// fsctx (open_tree AT_RECURSIVE): materialize recorded submount clones
/// at their relative paths INSIDE a freshly attached mount root — the
/// same never-fabricate walk the MS_REC bind clone uses
/// (bind_clone_attach; see the sc31 lesson there). `src_base` is the
/// ORIGINAL subtree root the rel-paths are relative to (open_tree's
/// resolved source `anc`): the source-side fallback cursor's start, so
/// kernel-created mountpoints (/proc, /dev, /sys: dcache-only, no
/// on-disk entries) resolve through it. None falls back to the clone
/// root itself — only fsmount passes None, and it never carries
/// submounts.
pub fn vfs_clone_submounts(
    root: &Arc<Dentry>,
    src_base: Option<&Arc<Dentry>>,
    clones: &[(Vec<String>, Arc<Dentry>, MntFlags)],
) {
    let base = src_base.unwrap_or(root);
    for (rel, src_root, flags) in clones {
        bind_clone_attach(root, base, rel, src_root, *flags);
    }
}

/// fsctx (open_tree CLONE|AT_RECURSIVE): the mounts nested under `anc`,
/// as relative-path clone descriptors (see collect_subtree_mounts).
/// `fresh_root` is the clone's own root — used to skip self-cloning.
pub fn vfs_collect_submounts(
    anc: &Arc<Dentry>,
    fresh_root: &Arc<Dentry>,
) -> Vec<(Vec<String>, Arc<Dentry>, MntFlags)> {
    collect_subtree_mounts(anc, fresh_root)
}

/// The registry's (/proc/mounts) row for the mountpoint path `mp`, if
/// one exists — move_mount's row relocation needs the old device/type.
pub fn vfs_mount_registry_row(
    mp: &str,
) -> Option<(String, String)> {
    self::get_mounts()
        .into_iter()
        .find(|(_, m, _, _)| m == mp)
        .map(|(dev, _, ty, _)| (dev, ty))
}

impl FsType {
    /// Parse filesystem type from a string (e.g., "ext4", "proc", "devfs").
    pub fn from_str(s: &str) -> Result<Self, i32> {
        match s {
            "ext4" => Ok(FsType::Ext4),
            "proc" | "procfs" => Ok(FsType::ProcFS),
            "devfs" | "devtmpfs" => Ok(FsType::DevFS),
            "rootfs" | "ramfs" => Ok(FsType::RootFS),
            _ => Err(errno::Errno::InvalidArgument.as_neg_i32()),
        }
    }
}

// ============================================================================
// VFS Initialization
// ============================================================================

/// Initialize VFS
pub fn vfs_init() {
    crate::pr_info!("vfs: Initializing Virtual File System...");

    {
        let mut state = VFS_STATE.lock();
        // Create VFS root dentry (inode will be set by first vfs_mount("/"))
        let root = Arc::new(Dentry::new(String::from("/")));
        root.set_hashed();
        state.root_dentry = Some(root.clone());
        vfs_root_publish(&root);
        state.initialized = true;
    }

    crate::pr_info!("vfs: VFS layer initialized [OK]");
}

// ============================================================================
// Path Lookup (Unified Path Resolution)
// ============================================================================

/// Resolve path to determine which filesystem it belongs to
///
/// Returns (filesystem_type, relative_path_within_filesystem)
///
/// The relative path preserves the leading "/" separator after the mount point.
/// For example:
/// Get current working directory
fn get_cwd() -> String {
    if let Some(current) = crate::sched::current() {
        // Verify alignment of the underlying pointer (fixes H62).
        let ptr = current as *const crate::process::task::Task;
        if (ptr as usize) % core::mem::align_of::<crate::process::task::Task>() != 0 {
            return String::from("/");
        }
        let cwd_bytes = current.get_cwd();
        match core::str::from_utf8(&cwd_bytes) {
            Ok(s) => String::from(s),
            Err(_) => String::from("/"),
        }
    } else {
        String::from("/")
    }
}

/// Convert relative path to absolute path
fn make_absolute(path: &str) -> String {
    if path.starts_with('/') {
        String::from(path)
    } else {
        let cwd = get_cwd();
        if cwd.ends_with('/') {
            format!("{}{}", cwd, path)
        } else {
            format!("{}/{}", cwd, path)
        }
    }
}

// ============================================================================
// chroot (P1): per-task root prefix in path resolution
// ============================================================================

/// The current task's root path ("/" when not chrooted). The root is stored
/// as a REAL (global-namespace) path in fs_struct; a chrooted task resolves
/// absolute paths by prefixing it. Kernel threads / early boot see "/".
pub fn get_process_root() -> String {
    if let Some(current) = crate::sched::current() {
        let root = current.get_root();
        match core::str::from_utf8(&root) {
            Ok(s) if !s.is_empty() => {
                // Normalize (the stored root was normalized at chroot time,
                // but be defensive against a stale FDT-shared value).
                let n = path_normalize(s);
                String::from(n)
            }
            _ => String::from("/"),
        }
    } else {
        String::from("/")
    }
}

/// Whether the current task runs under a chroot (root != "/").
pub fn chrooted() -> bool {
    get_process_root() != "/"
}

/// (perf-syscall lane) The allocation-free chroot probe for
/// path_lookup's fast path: reads the fs_struct slots directly instead
/// of materializing the root String (get_root() allocates a Vec and,
/// with a recorded root dentry, walks the whole parent chain — ~5 heap
/// objects per call, paid 3x per lookup before this).
pub fn process_rooted() -> bool {
    match crate::sched::current() {
        Some(t) => t.process_rooted_cheap(),
        None => false,
    }
}

/// (perf-syscall lane) Fast normality probe: true when `abs` (an
/// absolute path) is already in path_normalize's normal form — no
/// empty components, no "."/".." components, no trailing slash. One
/// byte scan, no allocations; lets the common clean-absolute-path
/// lookup skip path_normalize entirely.
fn path_is_normalized_fast(abs: &str) -> bool {
    if abs.is_empty() || !abs.starts_with('/') {
        return false;
    }
    if abs == "/" {
        return true;
    }
    if abs.ends_with('/') {
        return false;
    }
    // No empty component (== "//"), no "." or ".." component. Walk
    // slash-separated segments.
    let bytes = abs.as_bytes();
    let mut i = 0usize;
    while i < bytes.len() {
        // skip the separator
        i += 1;
        let start = i;
        while i < bytes.len() && bytes[i] != b'/' {
            i += 1;
        }
        let seg = &abs[start..i];
        if seg.is_empty() {
            return false; // "//"
        }
        if seg == "." || seg == ".." {
            return false;
        }
    }
    true
}

/// The current task's cwd AS THE USER SEES IT: relative to the task root
/// (the getcwd(3) string, e.g. "/bin" under chroot("/usr")). Callers that
/// feed the result into path_lookup-style resolution — which PREFIXES the
/// task root onto absolute paths — must join relative user paths against
/// THIS string, not the global cwd: joining the global cwd produced
/// absolute paths that the prefixer then double-prefixed (every relative
/// chdir()/openat(AT_FDCWD) under chroot() failed with ENOENT).
///
/// Falls back to the global cwd when the cwd is not representable under
/// the root (cwd outside the jail — string roots cannot express that; the
/// lookup then clamps at the jail root, which is the same place ".."
/// stops).
pub fn get_cwd_user() -> String {
    if let Some(current) = crate::sched::current() {
        // SAFETY: current is the running task's Task pointer from
        // sched::current(); fs_arc() only clones the Arc out of it.
        if let Some(fs) = current.fs_arc() {
            let root = get_process_root();
            if root == "/" {
                return get_cwd();
            }
            if let Some(cwd_d) = fs.cwd_dentry() {
                if let Some(root_d) = fs.root_dentry() {
                    if let Some(p) = cwd_d.build_path_rooted(Some(&root_d)) {
                        return p;
                    }
                }
                // cwd outside the jail: use the global cwd; the ".."
                // clamp keeps the lookup inside the jail.
                return cwd_d.build_path();
            }
            // Legacy string-only state: strip the root prefix.
            let cwd = get_cwd();
            let trimmed = root.trim_end_matches('/');
            if cwd == trimmed {
                return String::from("/");
            }
            if let Some(rel) = cwd.strip_prefix(&format!("{}/", trimmed)) {
                return format!("/{}", rel);
            }
            return cwd;
        }
    }
    get_cwd()
}

/// User-visible path of a dentry — Linux d_path() semantics: the string is
/// computed relative to the ROOT OF THE READING TASK, not the global root.
/// This is what /proc/<pid>/fd/N readlink and /proc/<pid>/maps show: a
/// chrooted reader sees jail-relative names ("/bin/init"), an unchrooted
/// reader sees the global path (same string, since the jail prefix is
/// absent). Falls back to the global path when the dentry is not under the
/// reader's root (display-only; Linux prints "(unreachable)" there).
pub fn dentry_user_path(dentry: &alloc::sync::Arc<super::types::Dentry>) -> String {
    if let Some(current) = crate::sched::current() {
        // SAFETY: current is the running task's Task pointer from
        // sched::current(); fs_arc() only clones the Arc out of it.
        if let Some(fs) = current.fs_arc() {
            if let Some(root_d) = fs.root_dentry() {
                return dentry
                    .build_path_rooted(Some(&root_d))
                    .unwrap_or_else(|| dentry.build_path());
            }
        }
    }
    dentry.build_path()
}

/// Interpret `path` in the current task's namespace: absolute paths get the
/// chroot prefix prepended; relative paths stay cwd-joined (cwd is stored
/// as a real path, so the result is always a real-namespace path).
fn make_absolute_rooted(path: &str) -> String {
    if !path.starts_with('/') {
        return make_absolute(path);
    }
    let root = get_process_root();
    if root == "/" {
        return String::from(path);
    }
    let trimmed = root.trim_end_matches('/');
    debug_assert!(!trimmed.is_empty());
    format!("{}{}", trimmed, path)
}

/// Is `abs` (an unnormalized real-namespace path) at or under `root`?
fn is_under_root(abs: &str, root: &str) -> bool {
    if root == "/" {
        return true;
    }
    let trimmed = root.trim_end_matches('/');
    abs == trimmed || abs.starts_with(&format!("{}/", trimmed))
}

/// Lexical normalization with a chroot floor: ".." never pops above
/// `root`'s component depth (Linux follow_dotdot stops at nd->root). When
/// the path is not under the root (cwd outside the jail — allowed after
/// chroot in Linux too, the classic fchdir escape) the floor is the real
/// root, i.e. plain path_normalize semantics.
fn normalize_with_root(abs: &str, root: &str) -> String {
    if root == "/" || !abs.starts_with('/') {
        return path_normalize(abs);
    }

    let floor_len = if is_under_root(abs, root) {
        root.split('/').filter(|s| !s.is_empty()).count()
    } else {
        0
    };

    let mut stack: Vec<&str> = Vec::new();
    for comp in abs.split('/').filter(|s| !s.is_empty() && *s != ".") {
        if comp == ".." {
            if stack.len() > floor_len {
                stack.pop();
            }
            // else: at the chroot floor — ".." stays put (the clamp that
            // makes `chroot("/jail"); open("/..") == "/jail"` hold).
        } else {
            stack.push(comp);
        }
    }

    let mut out = String::from("/");
    for (i, c) in stack.iter().enumerate() {
        if i > 0 {
            out.push('/');
        }
        out.push_str(c);
    }
    out
}

/// Walk the dentry tree from the VFS root to `path` (a REAL-namespace,
/// already-normalized path), no symlink following, ".." clamped at the
/// process root. Used to find the task's root dentry for absolute-symlink
/// resolution under chroot.
fn dentry_walk_no_symlink(path: &str) -> Option<Arc<Dentry>> {
    let mut current = follow_mount(get_vfs_root()?);
    for comp in path.split('/').filter(|s| !s.is_empty() && *s != ".") {
        if comp == ".." {
            let parent = current.parent.lock().clone()?;
            current = follow_mount(parent);
            continue;
        }
        let child = current.lookup_child(comp)?;
        if child.is_negative() {
            return None;
        }
        current = follow_mount(child);
    }
    Some(current)
}

/// Unified path lookup — dentry tree traversal with mount point crossing.
///
/// This function resolves a pathname by walking the dentry tree.
/// At each level, it checks for mount points via `follow_mount()`.
///
/// # Arguments
/// - `pathname`: Path to resolve (absolute or relative)
/// - `flags`: Lookup flags (LOOKUP_FOLLOW, LOOKUP_DIRECTORY, etc.)
///
/// # Returns
/// - `Ok(VfsPath)`: Resolved path with dentry and inode
/// - `Err(errno)`: Error code
/// Lookup flags
pub const LOOKUP_FOLLOW: u32 = 0x01;    // Follow symlinks (default)
pub const LOOKUP_NOFOLLOW: u32 = 0x02;  // Don't follow final symlink

// ---------------------------------------------------------------------------
// sc29/sc30 hunt: trace failing lookups/creates under /mnt/sandbox with a
// PER-PATH budget so the init sandbox-setup noise cannot starve the
// interesting failures (appspawn child mkdir('/mnt/sandbox/100') -> ENOENT
// forever while mkdir('/mnt/sandbox') -> EEXIST one syscall earlier).
// sc29: stage=parentdir — the PARENT lookup fails; and resolution of
// 'sandbox' flips fail->ok between consecutive lookups during setup.
// ---------------------------------------------------------------------------
fn sbx_want(path: &str) -> bool {
    // App-sandbox paths only ('/mnt/sandbox/<uid>/<pkg>/...'): the
    // system-sandbox hunt is closed (sc31), and the usage_report /
    // hiview churn under /mnt/sandbox/system/... burned the trace
    // tables (600 distinct paths -> silent dropouts, sc35).
    let rest = match path.find("/mnt/sandbox/") {
        Some(i) => &path[i + "/mnt/sandbox/".len()..],
        None => return false,
    };
    let mut it = rest.split('/');
    match it.next() {
        Some(uid) => !uid.is_empty() && uid.bytes().all(|b| b.is_ascii_digit()),
        None => false,
    }
}

/// Budget-burn filter (sc30 lesson: the dynamic linker's library scan
/// ("/mnt/sandbox/system/usr/.../*.so", hundreds of distinct paths)
/// exhausted a 4000-line global cap in the first minutes of boot, before
/// the appspawn stage ever ran).
fn sbx_noise(path: &str) -> bool {
    path.ends_with(".so") || path.contains("/lib")
}

fn sbx_trace(kind: &str, key: &str, detail: &str) {
    static SBX_BUDGETS: Spinlock<Vec<(String, usize)>> = Spinlock::new(Vec::new());
    static SBX_TOTAL: core::sync::atomic::AtomicUsize =
        core::sync::atomic::AtomicUsize::new(0);
    // sc33 lesson: counting ATTEMPTS against the global cap let the
    // usage_report/hiview retry churn (five failed lookups per cycle,
    // thousands of cycles) exhaust 30000 before the appspawn stage —
    // while printing only ~1000 lines. Count PRINTS instead; the
    // per-path cap (4) already bounds any single path.
    let mut budgets = SBX_BUDGETS.lock();
    let mut slot: Option<&mut usize> = None;
    for (p, n) in budgets.iter_mut() {
        if p.as_str() == key {
            slot = Some(n);
            break;
        }
    }
    let n = match slot {
        Some(n) => n,
        None => {
            if budgets.len() >= 600 {
                return;
            }
            budgets.push((String::from(key), 0));
            match budgets.last_mut() {
                Some((_, n)) => n,
                None => return,
            }
        }
    };
    if *n >= 4 {
        return;
    }
    *n += 1;
    let total = SBX_TOTAL.fetch_add(1, core::sync::atomic::Ordering::Relaxed);
    if total > 30000 {
        return;
    }
    crate::pr_info!(
        "sbx{}[{},p{}] {} (pid {})",
        kind,
        total,
        *n,
        detail,
        crate::process::current_pid()
    );
}

/// Parent-state summary for walk traces: name, inode presence+type, mount.
fn sbx_dentry_state(d: &Dentry) -> String {
    let mnt = if d.get_mount().is_some() { "+mnt" } else { "-mnt" };
    match d.get_inode() {
        Some(i) => format!("'{}' ino={:#x} mode={:#o} {}", d.get_name(), i.ino, i.mode.bits(), mnt),
        None => format!("'{}' NO-INODE {}", d.get_name(), mnt),
    }
}

pub fn path_lookup(pathname: &str, flags: u32) -> Result<VfsPath, i32> {
    // Empty path is invalid
    if pathname.is_empty() {
        return Err(errno::Errno::NoSuchFileOrDirectory.as_neg_i32());
    }
    crate::debug::fsw::note_walk();
    // pathcost: walk prologue bracket (normalize + root fetch + split).
    let pc_pre = crate::debug::fsw::pc_now();

    // Convert to absolute path and normalize. P1 chroot: absolute paths are
    // interpreted in the CURRENT TASK'S namespace (root prefix), and the
    // normalization floor clamps ".." at that root — a chrooted process
    // cannot lexically climb out of the jail.
    // (perf-syscall lane) Root + normalize with ZERO heap objects on
    // the common shape (not chrooted, absolute already-clean path):
    // the old sequence paid ~15 allocations per lookup — make_absolute_
    // rooted's String, THREE get_process_root() Strings (each itself a
    // Vec clone + path_normalize's two Vec<&str> collects + output
    // String), and path_normalize's output for the abs path — before
    // the walk even started. Only chrooted tasks and non-normal paths
    // take the allocating arms now.
    let rooted = process_rooted();
    // (21st successor) CHROOT FAST BASE: when the jail root is recorded
    // as a dentry (set_root_with_dentry at chroot time) and the caller's
    // path is absolute, start the walk AT the jail root and feed the raw
    // components straight into the loop — its "."/".."/trailing-slash
    // arms already carry the semantics, and the ".." clamp anchors at
    // this same dentry. Replaces the per-lookup make_absolute_rooted +
    // get_process_root + normalize_with_root allocation train AND the
    // dentry_walk_no_symlink RE-WALK of the jail prefix (lb346: walk
    // prologue averaged 66.6us over 781k walks = 52s wall, comparable to
    // the whole walk loop; every OH service is chrooted).
    let mut fast_base: Option<Arc<Dentry>> = None;
    let rooted = if rooted && pathname.starts_with('/') {
        match crate::sched::current()
            .and_then(|t| t.fs_arc())
            .and_then(|fs| fs.root_dentry())
        {
            Some(rd) => {
                fast_base = Some(rd);
                // Components come raw from pathname; the walk below starts
                // at fast_base instead of the global root.
                false
            }
            None => true,
        }
    } else {
        rooted
    };
    let abs_owned: Option<String>;
    let abs_path: &str = if pathname.starts_with('/') {
        if rooted {
            abs_owned = Some(make_absolute_rooted(pathname));
            abs_owned.as_deref().unwrap()
        } else {
            pathname
        }
    } else {
        abs_owned = Some(make_absolute(pathname));
        abs_owned.as_deref().unwrap()
    };
    let root_owned: Option<String>;
    let root_str: &str = if rooted {
        root_owned = Some(get_process_root());
        root_owned.as_deref().unwrap()
    } else {
        "/"
    };
    let norm_owned: Option<String>;
    let normalized: alloc::borrow::Cow<'_, str> = if rooted || !path_is_normalized_fast(abs_path) {
        alloc::borrow::Cow::Owned(if rooted {
            normalize_with_root(abs_path, root_str)
        } else {
            path_normalize(abs_path)
        })
    } else {
        alloc::borrow::Cow::Borrowed(abs_path)
    };

    // sc30/sc31 hunt: collect a component-by-component trail for sandbox
    // walks (the topology question — which mount each step lands in — is
    // exactly what the serial needs to answer). (perf-syscall lane)
    // Hunt instrumentation — the two sbx_want/sbx_noise byte scans ran
    // on EVERY lookup in every boot; now only on sysforensic boots.
    let sbx_tracing = crate::trace::EVENT_SYSFORENSIC.armed()
        && (sbx_want(normalized.as_ref()) || sbx_want(pathname))
        && !sbx_noise(normalized.as_ref())
        && !sbx_noise(pathname);
    let mut trail = String::new();

    // lb-lane hunt (switch_root /storage invisibility): pid 1's
    // mkdir('/storage/media') gets ENOENT although the moved tmpfs is
    // confirmed attached at the VFS root's "storage" child
    // (SWROOT-CHILDREN). The failure exits before the final-dentry
    // probe, so record the walk's starting identity instead: VFS-root
    // vs task-root (chroot) dentry pointers and the root's view of
    // "storage"/"mnt" — the divergence the errnos point at.
    if normalized.as_ref() == "/storage/media" || normalized.as_ref() == "/mnt/sandbox" {
        static WALKPRB_N: core::sync::atomic::AtomicUsize =
            core::sync::atomic::AtomicUsize::new(0);
        // 110th: rides the ohhunt gate (the probe takes VFS_STATE +
        // walks root children per hit).
        if WALKPRB_N.fetch_add(1, core::sync::atomic::Ordering::Relaxed) < 6
            && crate::debug::switches::oh_hunt_prints_on()
        {
            let (vfs_root_ptr, vfs_root_has_storage, vfs_root_has_mnt) = {
                let st = VFS_STATE.lock();
                let r = st.root_dentry.clone();
                match r {
                    Some(r) => (
                        Arc::as_ptr(&r) as usize,
                        r.lookup_child("storage")
                            .map(|c| c.vfsmount.lock().is_some())
                            .unwrap_or(false),
                        r.lookup_child("mnt")
                            .map(|c| c.vfsmount.lock().is_some())
                            .unwrap_or(false),
                    ),
                    None => (0, false, false),
                }
            };
            let task_root_ptr = crate::sched::current()
                .and_then(|t| t.fs_arc())
                .and_then(|fs| fs.root_dentry())
                .map(|d| Arc::as_ptr(&d) as usize)
                .unwrap_or(0);
            crate::pr_warn!(
                "WALKPROBE '{}' vfsroot={:#x} taskroot={:#x} procroot='{}' vfsroot-storage-mount={} vfsroot-mnt-mount={}",
                normalized,
                vfs_root_ptr,
                task_root_ptr,
                get_process_root(),
                vfs_root_has_storage,
                vfs_root_has_mnt
            );
        }
    }

    // Get VFS root dentry
    // (review-s2b perf) lock-free pinned read — was the walk's only
    // remaining global-lock pair in the prologue.
    let vfs_root = get_vfs_root()
        .ok_or(errno::Errno::NoSuchFileOrDirectory.as_neg_i32())?;

    // Start from root, follow mount. P1 chroot: also resolve the task's
    // root dentry (when chrooted) for the ".." clamp below and for absolute
    // symlink bases in follow_symlink.
    // (21st successor) CHROOT FAST BASE: with a recorded jail-root dentry
    // the walk starts THERE (no jail-prefix re-walk, no root string);
    // the same dentry anchors the ".." clamp.
    //
    // (gap-fs lane) Walk position under a reader-bank claim: `current`
    // OWNS the position dentry whenever an arm produced an Arc (miss /
    // symlink / mount / ".." hops); after a lock-free memo advance the
    // position is `current_raw` alone — kept alive by the child map (or
    // a pending retire that our claim's bank blocks from draining; see
    // the dentry reader-bank protocol). Every dentry the walk can land
    // on is reachable that way (root: mount-held/pinned; children:
    // parent map; follow_mount: mount descriptor; symlink landings:
    // tree dentries from the recursive lookup). The claim is dropped
    // before any operation that can sleep (fs lookup, symlink follow);
    // those arms materialize owned Arcs first.
    let mut current: Option<alloc::sync::Arc<Dentry>> = match fast_base {
        Some(ref rd) => Some(follow_mount(rd.clone())),
        None => Some(follow_mount(vfs_root.clone())),
    };
    let mut current_raw: *const Dentry = core::ptr::null();
    let mut claim: Option<super::types::WalkClaim> = None;
    let mut symlink_depth: usize = 0;
    let task_root_dentry: Option<Arc<Dentry>> = if let Some(ref rd) = fast_base {
        Some(rd.clone())
    } else if rooted {
        dentry_walk_no_symlink(root_str)
    } else {
        None
    };

    // Split into path components, skip empty ones.
    // (perf-path lane) STACK array for the common shape: the old
    // Vec<&str> collect paid a heap allocation + free on every lookup
    // (measured ~40-60 ns of the walk prologue). Paths deeper than 16
    // components spill to the allocating form.
    let mut comp_buf: [&str; 16] = ["";
        16];
    let mut comp_n: usize = 0;
    let mut spill: alloc::vec::Vec<&str> = alloc::vec::Vec::new();
    for seg in normalized.split('/').filter(|s| !s.is_empty()) {
        if spill.is_empty() && comp_n < comp_buf.len() {
            comp_buf[comp_n] = seg;
            comp_n += 1;
        } else {
            if spill.is_empty() {
                spill.extend_from_slice(&comp_buf[..comp_n]);
            }
            spill.push(seg);
        }
    }
    let components: &[&str] = if spill.is_empty() {
        &comp_buf[..comp_n]
    } else {
        &spill[..]
    };

    // sc30 hunt: count mount boundaries the walk actually crosses — the
    // sandbox paths cross at least one bind; a divergence here vs the
    // expected topology names the wrong-tree walk immediately.
    // (perf-path lane) has_mount(): lock-free presence test.
    let mut crossed: usize = if vfs_root.has_mount() { 1 } else { 0 };

    // (perf-path lane) The CURRENT dentry's inode, carried across loop
    // iterations: every hop into a child already fetched that child's
    // inode (dcache-hit refresh / iget), so the next iteration's parent
    // dir+search checks reuse it instead of re-taking the dentry inode
    // lock + Arc clone. (gap-fs lane) now a RAW pointer — valid only
    // while the walk claim is held; arms that drop the claim null it
    // and the next iteration re-fetches through the mirror.
    let mut cur_inode_raw: *const super::types::Inode = core::ptr::null();

    crate::debug::fsw::pc_add(&crate::debug::fsw::WALK_PRE_NS, pc_pre);
    let pc_loop = crate::debug::fsw::pc_now();

    for (ci, component) in components.iter().enumerate() {
        // pathcost: one count per walked component (divisor for A-D).
        if pc_loop != 0 {
            crate::debug::fsw::WALK_COMP_N.fetch_add(1, core::sync::atomic::Ordering::Relaxed);
        }
        // NAME_MAX check (review 5.5): components longer than 255 bytes can
        // never exist on any of our filesystems — fail with ENAMETOOLONG
        // instead of truncating into u8 name_len fields downstream.
        if component.len() > NAME_MAX {
            return Err(-(errno::constants::ENAMETOOLONG));
        }

        // (gap-fs lane) (Re)acquire the reader claim for this iteration
        // (an arm that could sleep dropped it) and refresh the raw
        // position from the owned Arc.
        if claim.is_none() {
            claim = Some(super::types::WalkClaim::acquire());
            current_raw = Arc::as_ptr(
                current.as_ref().expect("walk position dentry"),
            );
        }
        let cl = claim.as_ref().unwrap();
        // SAFETY: current_raw is protected by the claim (see the dentry
        // reader-bank protocol); it is non-null (set from a live Arc or
        // a memo-slot hit the same protocol validates).
        // (INV-VFS-WALK-1: the path-walk's raw-position family — every
        // &Dentry/&Inode deref in this walk (current_raw, child_raw,
        // ino_ptr, the memo-slot hits) holds a WalkClaim that blocks
        // the retirement drain, or is refreshed from a live owned Arc;
        // the *_arc_from_raw adopts ride INV-DENTRY-ADOPT-1. All walk
        // rows in this file ride this contract.)
        let cur_d: &Dentry = unsafe { &*current_raw };

        // ENOTDIR (Linux link_path_walk): `current` must be a directory to
        // walk INTO the next component — a regular file / FIFO / device in
        // the middle of a path fails with ENOTDIR, not ENOENT (LTP
        // chmod06 "t_file/tfile_3" expects ENOTDIR).
        // DAC: search (x) permission is required on every directory we
        // traverse through (Linux checks MAY_EXEC per component).
        // (perf-path lane) the carried inode from the previous iteration
        // removes the per-component get_inode lock pair; (gap-fs lane)
        // the first fetch of a position goes through the lock-free inode
        // pointer mirror instead.
        let pc_a = crate::debug::fsw::pc_now();
        if cur_inode_raw.is_null() {
            cur_inode_raw = cur_d.inode_ptr_walk(cl);
        }
        if !cur_inode_raw.is_null() {
            // SAFETY: carried under the claim (see above).
            let cur_inode = unsafe { &*cur_inode_raw };
            if !cur_inode.mode.is_directory() {
                return Err(errno::Errno::NotADirectory.as_neg_i32());
            }
            if !self::inode_permission(cur_inode, self::MAY_EXEC) {
                return Err(errno::Errno::PermissionDenied.as_neg_i32());
            }
        }
        crate::debug::fsw::pc_add(&crate::debug::fsw::WALK_A_NS, pc_a);

        // Skip "." — current directory
        if *component == "." {
            continue;
        }

        // Handle ".." — parent directory. The floor normalization above
        // already removed ".." components, so this arm is defense-in-depth;
        // it additionally clamps at the PROCESS root dentry (chroot) so a
        // stray ".." can never walk out of the jail via the dentry tree.
        if *component == ".." {
            if let Some(ref root_d) = task_root_dentry {
                if core::ptr::eq(current_raw, Arc::as_ptr(root_d)) {
                    continue; // at (task) root, stay
                }
            }
            let at_root = {
                let name = cur_d.name.lock();
                name.as_str() == "/"
            };
            if at_root {
                // Already at root, stay
                continue;
            }
            let parent_opt = cur_d.parent.lock().clone();
            match parent_opt {
                Some(p) => {
                    // Go to parent, then follow mount (for mount point traversal)
                    let landed = follow_mount(p);
                    current_raw = Arc::as_ptr(&landed);
                    current = Some(landed);
                    // (gap-fs lane) landed dentry's inode not carried.
                    cur_inode_raw = core::ptr::null();
                }
                None => {
                    // No parent (shouldn't happen), stay
                    continue;
                }
            }
            continue;
        }

        // Look up child in dentry tree
        // (gap-fs lane) lock-free under the reader claim: memo hit path
        // = version check + per-slot seqlock pair + one name compare —
        // no lock pair, no Arc traffic; miss falls to the locked map
        // lookup and refills the memo for the next walk.
        let pc_b = crate::debug::fsw::pc_now();
        let mut found: Option<*const Dentry> = cur_d.lookup_child_walk(cl, component);
        // (21st successor) STALE negative memo normalization: the parent
        // mutated since the memo was inserted (its mut_gen moved past the
        // child's stamp). Detach and re-resolve from the filesystem — the
        // reference kernel drops negative dentries on every parent
        // mutation; ours refreshes lazily on the next walk.
        // (25th successor) the stale case must reach the MISS arm below,
        // exactly like the pre-3f377d13 `None` it replaced: returning a
        // null pointer from this match fell straight into the dcache-hit
        // deref (`&*child_raw` + is_negative()) and panicked at NULL+0x98
        // (lb357, first negstale of the boot). Rewriting `found` to None
        // keeps the routing the old Option-based code had.
        // (stress-port r6 validation: the same fix landed independently
        // as 87c51458; negstorm 8w+16w rc=0, 568,699 stale hits clean.)
        if let Some(p) = found {
            // SAFETY: p is protected by the claim (memo/map-held).
            if (unsafe { &*p }).is_negative() && crate::debug::fsw::negmemo_on() {
                // The stamp lives on the parent's INODE (shared across
                // bind-mount aliases) — carried here in cur_inode_raw.
                let parent_gen = if !cur_inode_raw.is_null() {
                    // SAFETY: carried under the claim (see above).
                    unsafe { &*cur_inode_raw }.dir_mut_gen_load()
                } else {
                    match cur_d.get_inode_fast() {
                        Some(i) => i.dir_mut_gen_load(),
                        None => 0,
                    }
                };
                if (unsafe { &*p }).neg_gen_load() != parent_gen {
                    // STALE memo: the parent mutated since the memo was
                    // inserted (through this dentry OR any bind alias).
                    // Detach and re-resolve from the filesystem — the
                    // reference kernel drops negative dentries on every
                    // parent mutation; ours refreshes lazily here.
                    crate::debug::fsw::note_negstale();
                    cur_d.remove_child(component);
                    found = None;
                }
            }
        }
        // (scan3) procfs pid-dir revalidation (Linux proc_flush_task /
        // d_revalidate shape): a cached POSITIVE dentry for /proc/<pid>
        // or /proc/<tgid>/task/<tid> outlives its task — nothing dropped
        // it at free_pid time, and the walk answered from the dentry tree
        // without re-asking procfs. Observable contract break: access(2)
        // kept reporting success for a dead pid forever while stat(2)
        // (whose procfs getattr consults the pid table) answered ENOENT
        // on the very same path. LTP tgkill03 polls access() after
        // pthread_join; one lookup landing inside the exit window
        // (join wake → free_pid, measured 12µs..12ms) poisoned the
        // dentry for the whole test budget. Fix: on a procfs pid-shape
        // cache hit, verify the pid is still alive; a stale child is
        // detached and re-resolved through the filesystem, which answers
        // ENOENT via is_valid_pid. Scope: pid-shape inodes only
        // (private_data None, ino < 10000 — pid dirs and task-dir tid
        // aliases both use ino == pid; synthetic pid*10000+off dirs are
        // unreachable once their pid dir dies, and pid values ≥ 10000
        // are skipped to avoid ino aliasing with the offset ranges).
        // Non-procfs walks pay exactly one fs_id compare here.
        if let Some(p) = found {
            // SAFETY: p is protected by the claim (memo/map-held).
            let child = unsafe { &*p };
            if !child.is_negative() {
                // SAFETY: raw mirror read under the walk claim (same
                // contract as inode_ptr_walk's callers below); the claim
                // blocks the drain, no Arc traffic on the hot path.
                let ino_ptr = child.inode_ptr_walk(cl);
                if !ino_ptr.is_null() {
                    // SAFETY: non-null and claim-protected (see above).
                    let inode = unsafe { &*ino_ptr };
                    if inode.fs_id == self::FS_ID_PROCFS
                        && inode.private_data.is_none()
                        && inode.ino < 10000
                        && inode.ino != 1 // procfs sb root (ino 1) is not a pid dir
                        && !self::procfs::is_valid_pid(inode.ino)
                    {
                        cur_d.remove_child(component);
                        found = None;
                    }
                }
            }
        }
        let child_raw: *const Dentry = match found {
            Some(p) => p,
            None => {
                // Not in dentry cache — ask the filesystem to look it up.
                // (gap-fs lane) this arm can sleep (fs lookup / iget):
                // materialize the owned position Arc, drop the claim.
                crate::debug::fsw::pc_add(&crate::debug::fsw::WALK_B_NS, pc_b);
                cur_inode_raw = core::ptr::null();
                current = Some(match current.take() {
                    Some(a) => a,
                    // SAFETY: current_raw is protected by the claim held
                    // by `claim` (still alive — dropped below, AFTER this
                    // strong-count increment).
                    None => unsafe { self::dentry_arc_from_raw(current_raw) },
                });
                drop(claim.take());
                let pc_m = crate::debug::fsw::pc_now();
                crate::debug::fsw::note_walk_miss();
                let cur_now = current.as_ref().unwrap();
                let dir_inode = match cur_now.get_inode() {
                    Some(i) => i,
                    None => {
                        if sbx_tracing {
                            sbx_trace(
                                "walk",
                                &format!("NOINODE {}", normalized),
                                &format!(
                                    "'{}' parent dentry NO INODE at '{}' | state {} | crossed={} | trail={}",
                                    normalized,
                                    component,
                                    sbx_dentry_state(&**cur_now),
                                    crossed,
                                    trail
                                ),
                            );
                        }
                        return Err(errno::Errno::NoSuchFileOrDirectory.as_neg_i32());
                    }
                };
                let ops = dir_inode.ops.as_ref()
                    .ok_or(errno::Errno::NotADirectory.as_neg_i32())?;

                // INV-VFSOPS-1 dispatchers below carry the fs callbacks;
                // unsupported errno is ENOTDIR for both (the original
                // fn-None branches).
                {
                    // Call lookup to get inode number
                    let ino = match ops.call_lookup(
                        &*dir_inode,
                        component.as_bytes(),
                        Err(errno::Errno::NotADirectory),
                    ) {
                        Ok(ino) => ino,
                        Err(e) => {
                                    // (21st successor) Bounded negative-lookup
                                    // memo, reference-dcache parity: existence
                                    // probes re-scanned the WHOLE directory on
                                    // every miss (the OH boot's ENOENT storm
                                    // paid the full ext4 dir walk per probe).
                                    // Cache the ENOENT as a negative child,
                                    // stamped with the parent's content
                                    // generation: any later mutation through
                                    // the parent (create/unlink/rename/...)
                                    // invalidates it, the per-parent cap bounds
                                    // the heap (the old uncached-negative
                                    // objection), and only mutation-only
                                    // filesystems (ext4) participate — dynamic
                                    // filesystems' content changes without VFS
                                    // mutations (pid reuse in procfs!). With
                                    // negmemo off this stays the pure re-scan
                                    // it always was.
                                    if e == errno::Errno::NoSuchFileOrDirectory {
                                        crate::debug::fsw::note_walk_miss_enoent();
                                        // ext4-only gate: ops.lookup IS
                                        // ext4_lookup's fn pointer for ext4
                                        // directories (dynamic filesystems
                                        // never memo).
                                        if crate::debug::fsw::negmemo_on()
                                            && crate::api::ext4::is_ext4_lookup(ops)
                                        {
                                            let pgen = dir_inode.dir_mut_gen_load();
                                            cur_now.memo_negative(component, pgen);
                                        }
                                    }
                                    if sbx_tracing {
                                        sbx_trace(
                                            "walk",
                                            &format!("FS {}", normalized),
                                            &format!(
                                                "'{}' fs lookup '{}' -> {} | parent {} | crossed={} | trail={}",
                                                normalized,
                                                component,
                                                e.as_neg_i32(),
                                                sbx_dentry_state(&**cur_now),
                                                crossed,
                                                trail
                                            ),
                                        );
                                    }
                                    return Err(e.as_neg_i32());
                                }
                    };

                    // Call iget to instantiate the VFS Inode
                    let child_inode = ops
                        .call_iget(
                            &*dir_inode,
                            component.as_bytes(),
                            ino,
                            Err(errno::Errno::NotADirectory),
                        )
                        .map_err(|e| e.as_neg_i32())?;

                    // Create new dentry and cache it
                    let name = String::from(*component);
                    let d = Arc::new(Dentry::new(name.clone()));
                    d.set_inode(child_inode.clone());
                    d.set_parent(cur_now.clone());
                    cur_now.add_child(name.clone(), d.clone());

                    // Add to icache (clone: the symlink-check hint below
                    // still needs the Arc)
                    self::icache_add(child_inode.clone());

                    // Move to child, follow mount, follow symlink
                    let hopped = d.has_mount();
                    if hopped {
                        crossed += 1;
                    }
                    current = Some(follow_mount(d));
                    // (perf-path lane) carry the iget'd inode across the
                    // iteration boundary (no mount hop = current IS d).
                    // (gap-fs lane) claim is dropped here; the next
                    // iteration refetches through the mirror.
                    if sbx_tracing {
                        trail.push_str(&format!(
                            "{}{}={} ",
                            component,
                            if hopped { "*" } else { "" },
                            current.as_ref().unwrap().get_name()
                        ));
                    }
                    // Respect LOOKUP_NOFOLLOW on the final component here as
                    // well — lstat must not depend on dentry cache state.
                    // (perf-syscall lane) the fresh inode is in hand — no
                    // mount hop means current IS the child we iget'd.
                    let is_last = ci == components.len() - 1;
                    if is_last && (flags & LOOKUP_NOFOLLOW) != 0 {
                        // Don't follow symlink on the final component
                    } else {
                        let pre_ptr = Arc::as_ptr(current.as_ref().unwrap()) as usize;
                        let hint = if hopped { None } else { Some(&child_inode) };
                        let landed =
                            follow_symlink_hinted(current.clone().unwrap(), hint, components, &mut symlink_depth)?;
                        // A symlink follow landed elsewhere: its inode was
                        // not fetched (perf-path carried-inode discipline).
                        if Arc::as_ptr(&landed) as usize != pre_ptr {
                            // landed elsewhere — carried inode invalid
                        }
                        current = Some(landed);
                    }
                    crate::debug::fsw::pc_add(&crate::debug::fsw::WALK_MISSCOST_NS, pc_m);
                    continue;
                }
            }
        };

        // ---- dcache hit ----
        crate::debug::fsw::pc_add(&crate::debug::fsw::WALK_B_NS, pc_b);
        // SAFETY: child_raw came from lookup_child_walk under the claim
        // (memo slot or the child map — the claim pins its lifetime).
        let c: &Dentry = unsafe { &*child_raw };
        // Negative dentry — file known not to exist
        if c.is_negative() {
            crate::debug::fsw::note_neghit();
            if sbx_tracing {
                sbx_trace(
                    "walk",
                    &format!("NEG {}", normalized),
                    &format!(
                        "'{}' NEG-dentry at '{}' | parent {} | crossed={} | trail={}",
                        normalized,
                        component,
                        sbx_dentry_state(cur_d),
                        crossed,
                        trail
                    ),
                );
            }
            // datatap (el2/100 hunt): the negative cache has NO
            // invalidation on parent mutation, so a stale NEG entry
            // permanently hides freshly created files. Name hits
            // under /data so the dt boot can attribute each
            // "invisible" dir to either this cache or a real
            // on-disk absence.
            if crate::trace::EVENT_DATATAP.armed() {
                let mut prefix = String::new();
                for c2 in components.iter().take(ci + 1) {
                    prefix.push('/');
                    prefix.push_str(c2);
                }
                if prefix.starts_with("/data/") {
                    crate::pr_warn!(
                        "apptap negdentry hit '{}' (cached ENOENT, pid {})",
                        prefix,
                        crate::process::current_pid()
                    );
                }
            }
            return Err(errno::Errno::NoSuchFileOrDirectory.as_neg_i32());
        }
        // Check icache for fresh inode data
        // (perf-syscall lane) skip the set_inode lock+Arc swap
        // when the icache hands back the SAME inode the dentry
        // already holds — a no-op replace that still took the
        // inode spinlock and churned the Arc refcount on every
        // walk of every cached component.
        // (perf-path lane) generation guard: the identity mapping
        // (ino, fs_id) -> Arc only changes when icache membership
        // changes, and every membership change bumps icache's
        // generation. While the dentry's stamp matches the current
        // generation, the cached Arc IS the icache's object — the
        // global-lock icache_lookup is skipped entirely (it cost a
        // lock pair + Arc churn on EVERY hit of EVERY walk).
        // (gap-fs lane) the cached inode is a raw pointer through
        // the mirror; only an identity change pays the Arc swap.
        let pc_c = crate::debug::fsw::pc_now();
        let mut inode_raw: *const super::types::Inode = c.inode_ptr_walk(cl);
        let gen_now = self::icache_regen();
        if c.get_inode_gen() != gen_now {
            if !inode_raw.is_null() {
                // SAFETY: read under the claim.
                let cached = unsafe { &*inode_raw };
                if let Some(fresh) = self::icache_lookup(cached.ino, cached.fs_id) {
                    if Arc::as_ptr(&fresh) as *const super::types::Inode != inode_raw {
                        c.set_inode(alloc::sync::Arc::clone(&fresh));
                        inode_raw = Arc::as_ptr(&fresh);
                    }
                }
            }
            // Stamp whatever verdict this slow path reached; a
            // later change bumps the generation again.
            c.set_inode_gen(self::icache_regen());
        }
        crate::debug::fsw::pc_add(&crate::debug::fsw::WALK_C_NS, pc_c);
        crate::debug::fsw::note_walk_hit();

        // Follow mount point at child, then follow symlink
        // (perf-path lane) has_mount() keeps the common no-mountpoint
        // case at one Relaxed load; follow_mount (lock + Arc clone) only
        // runs when there is actually a mount to follow.
        // (gap-fs lane) the no-hop advance is a RAW pointer move — no
        // Arc clone, no refcount traffic; the mount-hop arm materializes
        // (rare).
        let pc_d = crate::debug::fsw::pc_now();
        let hopped = c.has_mount();
        if hopped {
            crossed += 1;
        }
        if hopped {
            // SAFETY: child_raw protected by the claim (see above).
            let child_arc = unsafe { self::dentry_arc_from_raw(child_raw) };
            let landed = follow_mount(child_arc);
            current_raw = Arc::as_ptr(&landed);
            current = Some(landed);
            cur_inode_raw = core::ptr::null();
        } else {
            current_raw = child_raw;
            // Position is map-held; drop any arm-materialized pin.
            current = None;
            // (perf-path lane) hit arm already fetched the child's inode.
            cur_inode_raw = inode_raw;
        }
        if sbx_tracing {
            trail.push_str(&format!(
                "{}{}={} ",
                component,
                if hopped { "*" } else { "" },
                unsafe { &*current_raw }.get_name()
            ));
        }
        // If LOOKUP_NOFOLLOW and this is the last component, skip symlink resolution
        // (gap-fs lane) the is-symlink test runs through the raw inode
        // under the claim; only a real follow pays the materialize +
        // claim drop (the follow can read the target, i.e. sleep).
        let is_last = ci == components.len() - 1;
        let is_symlink = !hopped
            && !inode_raw.is_null()
            && (unsafe { &*inode_raw }).mode.is_symlink();
        if is_last && (flags & LOOKUP_NOFOLLOW) != 0 {
            // Don't follow symlink on the final component
        } else if is_symlink {
            // SAFETY: inode_raw protected by the claim.
            let inode_arc =
                unsafe { self::inode_arc_from_raw(inode_raw) };
            let d_arc = match current.take() {
                Some(a) if Arc::as_ptr(&a) == current_raw => a,
                // SAFETY: current_raw protected by the claim (still held —
                // dropped below, after this increment).
                _ => unsafe { self::dentry_arc_from_raw(current_raw) },
            };
            cur_inode_raw = core::ptr::null();
            drop(claim.take());
            let pre_ptr = Arc::as_ptr(&d_arc) as usize;
            let landed =
                follow_symlink_hinted(d_arc, Some(&inode_arc), components, &mut symlink_depth)?;
            // Symlink follow landed elsewhere: drop the carried inode
            // (perf-path discipline — its inode was not fetched).
            current = Some(landed);
            // (claim is None: the next iteration / the tail re-claims and
            // refreshes current_raw from the owned Arc.)
            let _ = pre_ptr;
        }
        crate::debug::fsw::pc_add(&crate::debug::fsw::WALK_D_NS, pc_d);
    }
    crate::debug::fsw::pc_add(&crate::debug::fsw::WALK_LOOP_NS, pc_loop);
    let pc_tail = crate::debug::fsw::pc_now();

    // (gap-fs lane) An arm may have dropped the claim on the final
    // component (symlink follow); re-acquire for the tail reads.
    if claim.is_none() {
        claim = Some(super::types::WalkClaim::acquire());
        current_raw = Arc::as_ptr(
            current.as_ref().expect("walk position dentry"),
        );
    }
    let cl = claim.as_ref().unwrap();
    // SAFETY: protected by the claim (see the protocol).
    let dentry_d: &Dentry = unsafe { &*current_raw };

    // Build VfsPath from final dentry — materialize BOTH owned Arcs
    // while the claim is held (the strong-count increments must not
    // race a drain), then release.
    let inode = {
        let p = dentry_d.inode_ptr_walk(cl);
        if p.is_null() {
            if sbx_tracing {
                sbx_trace(
                    "walk",
                    &format!("FINAL {}", normalized),
                    &format!(
                        "'{}' FINAL dentry no inode | state {} | crossed={} | trail={}",
                        normalized,
                        sbx_dentry_state(dentry_d),
                        crossed,
                        trail
                    ),
                );
            }
            return Err(errno::Errno::NoSuchFileOrDirectory.as_neg_i32());
        }
        // SAFETY: protected by the claim.
        unsafe { self::inode_arc_from_raw(p) }
    };
    let dentry: Arc<Dentry> = match current.take() {
        Some(a) if Arc::as_ptr(&a) == current_raw => a,
        // SAFETY: protected by the claim.
        _ => unsafe { self::dentry_arc_from_raw(current_raw) },
    };
    drop(claim.take());

    // POSIX/Linux path resolution: a TRAILING SLASH demands a directory —
    // "file/" on a regular file is ENOTDIR, never a silent success (Linux
    // link_path_walk; LTP acct01 "./tmpfile/" case).
    if pathname.ends_with('/')
        && pathname.len() > 1
        && !inode.mode.is_directory()
    {
        return Err(errno::Errno::NotADirectory.as_neg_i32());
    }
    crate::debug::fsw::pc_add(&crate::debug::fsw::WALK_TAIL_NS, pc_tail);

    Ok(VfsPath {
        dentry: Some(dentry),
        mnt: None,
        inode: Some(inode),
    })
}

/// Follow symbolic link: if dentry's inode is a symlink, resolve its target.
/// `remaining` is the remaining path components (not yet processed).
/// `depth` tracks nesting to prevent loops (max 8).
fn follow_symlink(
    dentry: alloc::sync::Arc<Dentry>,
    remaining: &[&str],
    depth: &mut usize,
) -> Result<alloc::sync::Arc<Dentry>, i32> {
    follow_symlink_hinted(dentry, None, remaining, depth)
}

/// (perf-syscall lane) Same walk with the caller's pre-fetched inode:
/// both walk loops already hold the child's Arc (the dcache-hit arm's
/// icache refresh / the iget arm's fresh inode), and re-reading it here
/// cost one dentry-inode spinlock + Arc clone per component on the
/// no-symlink fast path (the overwhelmingly common case).
/// (perf-path lane) BORROW the hint for the is_symlink test — the old
/// inode_hint.cloned() churned one Arc refcount pair per component even
/// though 99.9% of components are not symlinks; only the rare symlink
/// arm materializes an owned reference.
fn follow_symlink_hinted(
    dentry: alloc::sync::Arc<Dentry>,
    inode_hint: Option<&alloc::sync::Arc<super::types::Inode>>,
    remaining: &[&str],
    depth: &mut usize,
) -> Result<alloc::sync::Arc<Dentry>, i32> {
    // Fast path: mode check through a reference, no Arc clone.
    let is_symlink = match inode_hint {
        Some(i) => i.mode.is_symlink(),
        None => match dentry.get_inode() {
            Some(i) => i.mode.is_symlink(),
            None => return Ok(dentry),
        },
    };
    if !is_symlink {
        return Ok(dentry);
    }

    // Slow path (symlink): materialize the owned Arc.
    let inode_owned: alloc::sync::Arc<super::types::Inode> = match inode_hint {
        Some(i) => alloc::sync::Arc::clone(i),
        None => match dentry.get_inode() {
            Some(i) => i,
            None => return Ok(dentry),
        },
    };
    let inode = &inode_owned;

    // /proc/[pid]/ns/<kind> magic link: TERMINAL for path resolution —
    // the readlink target "<kind>:[<inum>]" is an nsfs identifier, not a
    // walkable path (Linux nd_jump_link: opening the link yields an nsfd;
    // walking the string is always wrong). Return the link dentry itself;
    // file_open recognizes the (pid, kind) inode and builds the ns fd.
    // Without this, open("/proc/self/ns/mnt") ENOENTs — OH's beget then
    // loses InitDefaultNamespace/EnterDefaultNamespace and init stays
    // stuck inside the sandbox after its pivot_root (the lb-lane
    // /storage-invisibility root cause).
    if inode.fs_id == self::FS_ID_PROCFS && inode.private_data.is_none() {
        let pid_val = inode.ino / 10000;
        let rem = inode.ino % 10000;
        if self::procfs::is_valid_pid(pid_val)
            && rem >= self::procfs::PROCFS_NS_LINK_INO_OFF
            && rem < self::procfs::PROCFS_NS_LINK_INO_OFF + 6
        {
            return Ok(dentry);
        }
    }

    // /proc/[pid]/fd/N magic link: resolution goes straight to the target
    // descriptor's dentry, never through the target path STRING — the
    // printed path is stale for unlinked files (O_TMPFILE linkat, LTP
    // open14/openat03) and unwalkable for pipes/sockets. This mirrors
    // Linux proc magic-link semantics (nd_jump_link).
    if inode.fs_id == self::FS_ID_PROCFS && inode.private_data.is_none() {
        let pid_val = inode.ino / 10000;
        let rem = inode.ino % 10000;
        if self::procfs::is_valid_pid(pid_val)
            && rem >= self::procfs::PROCFS_FD_LINK_INO_OFF
            && rem < self::procfs::PROCFS_FD_LINK_INO_OFF + 1024
        {
            if let Some(file) = self::procfs::get_fd_file(
                pid_val,
                (rem - self::procfs::PROCFS_FD_LINK_INO_OFF) as u32,
            ) {
                // dentry written once at open; accessor handles it.
                let target = file.get_dentry().cloned();
                if let Some(d) = target {
                    // Unlinked-while-open (O_TMPFILE, or any fd surviving
                    // an unlink): vfs_unlink strips the dentry's inode to
                    // keep readdir honest, but the DESCRIPTOR still pins
                    // the inode — exactly like Linux's unhashed-but-live
                    // dentry. A magic-link walk referencing this fd
                    // re-attaches the live inode so linkat/chmod/stat
                    // through /proc/[pid]/fd/N work on the real file.
                    if d.get_inode().is_none() {
                        // inode written once at open; accessor handles it.
                        let live = file.get_inode().cloned();
                        if let Some(inode_arc) = live {
                            d.set_inode(inode_arc);
                            d.clear_negative();
                        }
                    }
                    *depth += 1;
                    if *depth > crate::config::MAX_SYMLINKS {
                        return Err(errno::Errno::TooManySymbolicLinks.as_neg_i32());
                    }
                    return Ok(follow_mount(d));
                }
            }
            // No dentry (pipe/socket/anon inode) or task gone: fall
            // through to the string-based walk below, which reports
            // ENOENT for the unwalkable target — same observable errno
            // as Linux for these.
        }
    }

    *depth += 1;
    // Linux MAXSYMLINKS = 40 (review 5.1: was 8, rejecting deep-but-legal
    // symlink chains that glibc/coreutils happily create).
    if *depth > crate::config::MAX_SYMLINKS {
        return Err(errno::Errno::TooManySymbolicLinks.as_neg_i32());
    }

    // Read symlink target. Heap-allocate the buffer: follow_symlink is
    // recursive (one frame per nested symlink hop, up to MAX_SYMLINKS=40),
    // and the old [0u8; 4096] stack array burned ~4KB of the 128KB kernel
    // stack per level — a symlink loop like LTP's test_eloop overflowed it
    // before the depth counter could return ELOOP (chmod06 STACK-OVERFLOW
    // → KERNPANIC).
    let mut target_buf = alloc::vec![0u8; 4096];
    let target_len = inode.op_readlink(&mut target_buf);
    if target_len <= 0 {
        return Err(errno::Errno::NoSuchFileOrDirectory.as_neg_i32());
    }

    let target = core::str::from_utf8(&target_buf[..target_len as usize])
        .map_err(|_| errno::Errno::InvalidArgument.as_neg_i32())?;

    // Resolve target path relative to the symlink's parent directory.
    let vfs_root = VFS_STATE.lock().root_dentry.clone()
        .ok_or(errno::Errno::NoSuchFileOrDirectory.as_neg_i32())?;

    // P1 chroot: an ABSOLUTE symlink target is interpreted in the CURRENT
    // TASK'S namespace (Linux: absolute symlinks resolve from nd->root, not
    // the global root). Walk the (normalized) root prefix to its dentry;
    // ".." inside the target is clamped at that dentry below.
    let task_root_dentry: Arc<Dentry> = {
        let root = get_process_root();
        if root == "/" {
            vfs_root.clone()
        } else {
            let rooted = normalize_with_root(&root, &root);
            dentry_walk_no_symlink(&rooted).unwrap_or_else(|| vfs_root.clone())
        }
    };

    let base = if target.starts_with('/') {
        // Absolute symlink — start from the task's root
        follow_mount(task_root_dentry.clone())
    } else {
        // Relative symlink — start from symlink's parent
        let parent_opt = dentry.parent.lock().clone();
        match parent_opt {
            Some(p) => follow_mount(p),
            None => follow_mount(task_root_dentry.clone()),
        }
    };

    // Parse target path components
    let target_components: Vec<&str> = target
        .split('/')
        .filter(|s| !s.is_empty() && *s != ".")
        .collect();

    let mut current = base;
    for component in target_components.iter() {
        // ENOTDIR: same rule as the path_lookup main loop — every
        // component source during symlink-body resolution must be a
        // directory.
        if let Some(ref cur_inode) = current.get_inode() {
            if !cur_inode.mode.is_directory() {
                return Err(errno::Errno::NotADirectory.as_neg_i32());
            }
        }

        // DAC (B4): resolving a symlink body walks directories the caller
        // never named.  Linux checks search (MAY_EXEC) permission on every
        // directory traversed during symlink expansion, exactly like the
        // path_lookup main loop above; without this, a world-readable
        // symlink pointing into a 0700 directory bypassed the traversal
        // check entirely (open /link succeeded where open /dir/file got
        // EACCES).  Nested symlinks re-enter follow_symlink and hit the
        // same check on their own walks.
        if let Some(ref dir_inode) = current.get_inode() {
            if !self::inode_permission(dir_inode, self::MAY_EXEC) {
                return Err(errno::Errno::PermissionDenied.as_neg_i32());
            }
        }

        if *component == ".." {
            // Clamp at the task root (chroot) — an absolute symlink like
            // "/../../etc" must not climb out of the jail.
            if Arc::ptr_eq(&current, &task_root_dentry) {
                continue;
            }
            let parent_opt = current.parent.lock().clone();
            match parent_opt {
                Some(p) => current = follow_mount(p),
                None => {}
            }
            continue;
        }

        // Look up in dentry cache or ask filesystem
        let child = match current.lookup_child(component) {
            Some(c) => {
                // Negative dentry — file known not to exist
                if c.is_negative() {
                    return Err(errno::Errno::NoSuchFileOrDirectory.as_neg_i32());
                }
                // Check icache for fresh inode data
                // (perf-syscall lane) skip the set_inode lock+Arc swap
                // when the icache hands back the SAME inode the dentry
                // already holds — a no-op replace that still took the
                // inode spinlock and churned the Arc refcount on every
                // walk of every cached component.
                if let Some(ref cached_inode) = c.get_inode() {
                    if let Some(fresh) = self::icache_lookup(cached_inode.ino, cached_inode.fs_id) {
                        if !alloc::sync::Arc::ptr_eq(&fresh, cached_inode) {
                            c.set_inode(fresh);
                        }
                    }
                }
                c
            }
            None => {
                let dir_inode = current.get_inode()
                    .ok_or(errno::Errno::NoSuchFileOrDirectory.as_neg_i32())?;
                let ops = dir_inode.ops.as_ref()
                    .ok_or(errno::Errno::NotADirectory.as_neg_i32())?;

                // INV-VFSOPS-1 dispatchers; unsupported errno is ENOTDIR
                // for both (the original fn-None branches).
                {
                    let ino = match ops.call_lookup(
                        &*dir_inode,
                        component.as_bytes(),
                        Err(errno::Errno::NotADirectory),
                    ) {
                        Ok(ino) => ino,
                        Err(e) => {
                            // No negative-dentry caching on ENOENT
                            // (same unbounded-leak reasoning as the
                            // other path-walk variant).
                            return Err(e.as_neg_i32());
                        }
                    };
                    let child_inode = ops
                        .call_iget(
                            &*dir_inode,
                            component.as_bytes(),
                            ino,
                            Err(errno::Errno::NotADirectory),
                        )
                        .map_err(|e| e.as_neg_i32())?;
                    let name = String::from(*component);
                    let d = alloc::sync::Arc::new(Dentry::new(name.clone()));
                    d.set_inode(child_inode.clone());
                    d.set_parent(current.clone());
                    current.add_child(name.clone(), d.clone());
                    self::icache_add(child_inode.clone());
                    let hopped = d.get_mount().is_some();
                    current = follow_mount(d);
                    let hint = if hopped { None } else { Some(&child_inode) };
                    current = follow_symlink_hinted(current, hint, remaining, depth)?;
                    continue;
                }
            }
        };
        current = follow_mount(child);
        current = follow_symlink(current, remaining, depth)?;
    }

    Ok(current)
}

/// Lookup parent directory and extract final component
///
/// Splits a path into (parent_dir, filename)
/// For example: "/usr/bin/ls" -> ("/usr/bin", "ls")
pub fn path_parent_and_name(path: &str) -> Result<(String, String), i32> {
    let normalized = path_normalize(path);

    if normalized == "/" || normalized.is_empty() {
        return Err(errno::Errno::NoSuchFileOrDirectory.as_neg_i32());
    }

    // Find last '/'
    if let Some(idx) = normalized.rfind('/') {
        let (parent, name): (&str, &str) = if idx == 0 {
            ("/", &normalized[1..])
        } else {
            (&normalized[..idx], &normalized[idx + 1..])
        };

        if name.is_empty() {
            return Err(errno::Errno::NoSuchFileOrDirectory.as_neg_i32());
        }

        return Ok((String::from(parent), String::from(name)));
    }

    // No '/' found, relative path with single component
    Ok((get_cwd(), normalized))
}

// ============================================================================
// Unified Directory Operations (using inode_operations)
// ============================================================================

/// Lookup parent directory path and return its VfsPath with inode
///
/// Check MAY_WRITE permission on a parent inode for directory modification operations.
fn check_parent_write_permission(parent_inode: &Inode) -> Result<(), i32> {
    let inode_mode = parent_inode.mode.bits() as u16;
    let inode_uid = parent_inode.uid.load(core::sync::atomic::Ordering::Relaxed);
    let inode_gid = parent_inode.gid.load(core::sync::atomic::Ordering::Relaxed);
    let cred = if let Some(task) = crate::sched::current() {
        task.cred().clone()
    } else {
        crate::process::task::Cred::new_init()
    };
    if !self::generic_permission(
        inode_mode, inode_uid, inode_gid,
        self::MAY_WRITE, &cred,
    ) {
        return Err(errno::Errno::PermissionDenied.as_neg_i32());
    }
    Ok(())
}

/// Check MAY_EXEC on a parent inode: directory modification ops on Linux
/// require search permission on the parent in addition to write permission
/// (may_create/may_delete check MAY_WRITE|MAY_EXEC). Review 5.1 (low):
/// check_parent only checked MAY_WRITE.
fn check_parent_exec_permission(parent_inode: &Inode) -> Result<(), i32> {
    let inode_mode = parent_inode.mode.bits() as u16;
    let inode_uid = parent_inode.uid.load(core::sync::atomic::Ordering::Relaxed);
    let inode_gid = parent_inode.gid.load(core::sync::atomic::Ordering::Relaxed);
    let cred = if let Some(task) = crate::sched::current() {
        task.cred().clone()
    } else {
        crate::process::task::Cred::new_init()
    };
    if !self::generic_permission(
        inode_mode, inode_uid, inode_gid,
        self::MAY_EXEC, &cred,
    ) {
        return Err(errno::Errno::PermissionDenied.as_neg_i32());
    }
    Ok(())
}

/// Sticky bit (S_ISVTX) check for deleting/renaming an entry in a sticky
/// directory (review 5.1 high: without this any user with write permission
/// can unlink other users' files in /tmp).
///
/// Mirrors Linux may_delete() → check_sticky(): when the parent directory
/// has the sticky bit, the caller may only remove/rename an entry it owns
/// (entry uid == euid), or the entry's owner is the caller, or the caller
/// holds CAP_FOWNER.
fn check_sticky(parent_inode: &Inode, target_inode: Option<&Inode>) -> Result<(), i32> {
    const S_ISVTX: u32 = 0o1000;
    if parent_inode.mode.bits() & S_ISVTX == 0 {
        return Ok(());
    }

    let cred = if let Some(task) = crate::sched::current() {
        task.cred().clone()
    } else {
        crate::process::task::Cred::new_init()
    };

    if crate::security::has_capability(&cred, crate::security::CAP_FOWNER) {
        return Ok(());
    }

    // Owner of the parent directory may delete anything in it.
    let parent_uid = parent_inode.uid.load(core::sync::atomic::Ordering::Relaxed);
    if cred.euid == parent_uid {
        return Ok(());
    }

    // Otherwise the caller must own the entry itself.
    if let Some(target) = target_inode {
        let target_uid = target.uid.load(core::sync::atomic::Ordering::Relaxed);
        if cred.euid == target_uid {
            return Ok(());
        }
    }

    Err(errno::Errno::PermissionDenied.as_neg_i32())
}

// ============================================================================
// inotify notification helpers (P0-4)
//
// Every VFS change point below calls inotify::notify at its tail so
// registered watches see {IN_CREATE, IN_DELETE, IN_MOVED_FROM/TO,
// IN_MODIFY, IN_ATTRIB, IN_DELETE_SELF, IN_MOVE_SELF} events. Directory
// watches receive the events tagged with the entry name; direct inode
// watches receive them name-less. IN_OPEN/IN_ACCESS/IN_CLOSE_* come from
// the open/read/write/close paths (file.rs / file_open / file_opendir).
// ============================================================================


/// Parent inode of a dentry (for directory-watch name events).
fn dentry_parent_inode(d: &Dentry) -> Option<Arc<Inode>> {
    d.parent.lock().clone().and_then(|p| p.get_inode())
}

/// Notify a change on `inode`, also reaching watches on the parent
/// directory of `dentry` with the entry `name`.
fn notify_about(
    dentry: Option<&Arc<Dentry>>,
    inode: Option<&Inode>,
    mask: u32,
    name: Option<&[u8]>,
    cookie: u32,
) {
    let parent = dentry.and_then(|d| dentry_parent_inode(d));
    self::notify(parent.as_deref(), inode, mask, name, cookie);
}

/// Link count of an inode (for IN_DELETE_SELF suppression on hard-linked
/// files: deleting one link does not delete the inode).
fn inode_nlink(inode: &Inode) -> u32 {
    let mut st = super::types::Stat::default();
    if inode.op_getattr(&mut st) == 0 {
        st.st_nlink
    } else {
        1
    }
}

/// This helper function is used by operations that need to modify a directory
/// (mkdir, rmdir, unlink, etc.)
fn lookup_parent_dir(pathname: &str) -> Result<(VfsPath, String), i32> {
    let (parent_path, name) = path_parent_and_name(pathname)?;
    // The PARENT's final component is an intermediate component of the
    // operand path — Linux link_path_walk resolves it WITH symlink
    // following (mkdir "symdir/x" creates inside symdir's target). The
    // old lookup_flags::LOOKUP_DIRECTORY argument (0x2) numerically
    // aliased the top-level LOOKUP_NOFOLLOW bit and silently suppressed
    // that follow: creating/renaming through a symlinked directory
    // failed ENOTDIR, and the 42-43-hop ../-chains of LTP rename11 /
    // renameat01 returned ENOTDIR where the reference answers ELOOP
    // (the ELOOP fires one hop later for deeper chains, which is why
    // only that window was wrong).
    let parent_vpath = path_lookup(&parent_path, 0)?;

    // Verify it's a directory
    if let Some(ref inode) = parent_vpath.inode {
        if !inode.mode.is_directory() {
            return Err(errno::Errno::NotADirectory.as_neg_i32());
        }
    }

    Ok((parent_vpath, name))
}

/// F4 route-4 (getdents64 cache): global directory-content epoch.
/// Every SUCCESSFUL directory mutation dispatch below (mkdir, mknod,
/// symlink, rmdir, unlink, link, create via open(O_CREAT), rename,
/// rename_exchange) bumps this counter; a cached getdents64 listing
/// (File::dirent_cache) records the epoch observed when it was
/// materialized and is dropped the moment the epoch moves. One global
/// counter rather than a per-inode epoch: the invalidation story stays
/// airtight (no mutation path can forget to bump a per-inode field it
/// does not know about) at the cost of over-invalidation — a mkdir in
/// one directory also drops unrelated cached listings, which is just a
/// re-scan on a box whose getdents bursts run between mutations.
/// Dynamic filesystems (procfs/devfs/...) never populate the cache, so
/// their un-bumped content changes cannot be served stale.
static VFS_DIR_EPOCH: core::sync::atomic::AtomicU64 = core::sync::atomic::AtomicU64::new(0);

/// Read the directory-content epoch (getdents64 cache key part).
pub fn vfs_dir_epoch() -> u64 {
    VFS_DIR_EPOCH.load(core::sync::atomic::Ordering::Acquire)
}

/// Bump the directory-content epoch — call on EVERY successful
/// directory mutation dispatch (see VFS_DIR_EPOCH above).
fn vfs_dir_epoch_bump() {
    VFS_DIR_EPOCH.fetch_add(1, core::sync::atomic::Ordering::Release);
}


/// Create directory - unified implementation using inode_operations
///
/// This function works across all filesystem types by:
/// 1. Resolving the parent directory path
/// 2. Calling the parent's inode_operations->mkdir
pub fn vfs_mkdir(pathname: &str, mode: u32) -> Result<(), i32> {
    // Serialize the lookup+mutate window (see VFS_MUTATION_LOCK note).
    let _mutation_guard = VFS_MUTATION_LOCK.guard();

    // sc29/sc30 hunt: name the failing stage of a sandbox mkdir. parentdir
    // failures also print the PREFIXED parent path the walk actually used.
    let sbx_mkdir_stage = |st: &str, e: i32| {
        if sbx_want(pathname) && !sbx_noise(pathname) {
            let extra = if st == "parentdir" {
                let (pp, _) = path_parent_and_name(pathname)
                    .unwrap_or((String::from("?"), String::new()));
                format!(" parent='{}'", make_absolute_rooted(&pp))
            } else {
                String::new()
            };
            sbx_trace(
                "mkdir",
                &format!("{} {}", pathname, st),
                &format!("'{}' stage {} -> {}{}", pathname, st, e, extra),
            );
        }
    };

    // EEXIST before any mutation (Linux do_mkdirat; LTP mkdir03) — the
    // old path left the "already exists" decision to the filesystem's
    // mkdir callback, which succeeded.
    //
    // EROFS comes AFTER the existence decision (Linux order:
    // filename_create reports -EEXIST before mnt_want_write can fail
    // -EROFS): mkdir of an EXISTING name inside a read-only bind returns
    // EEXIST, not EROFS — OH's sandbox MakeDirRecursive over the ro
    // /vendor bind treats EEXIST as success (old order aborted the whole
    // bind chain with EROFS).
    match path_lookup(pathname, LOOKUP_NOFOLLOW) {
        Ok(_) => {
            sbx_mkdir_stage("precheck", -17);
            return Err(errno::Errno::FileExists.as_neg_i32());
        }
        // Only a genuinely ABSENT name may be created. Other lookup
        // failures — ELOOP on a symlink ring (LTP mkdir03/rmdir02/
        // mkdirat02 43-hop rings), ENOTDIR, EACCES — propagate to the
        // caller; recomputing the parent below replaced ELOOP with the
        // parent walk's ENOTDIR (observed: 43 hops → ENOTDIR, 44+ →
        // ELOOP). Same rule sys_open already follows.
        Err(e) if e == -(errno::constants::ENOENT) => {}
        Err(e) => {
            sbx_mkdir_stage("precheck", e);
            return Err(e);
        }
    }

    // Write-intent guard (mnt_want_write): new names on a MS_RDONLY mount
    // fail EROFS (LTP needs_rofs family: mkdir03, unlink09, ...).
    check_not_readonly(pathname)?;

    let (parent_vpath, name) = match lookup_parent_dir(pathname) {
        Ok(v) => v,
        Err(e) => {
            sbx_mkdir_stage("parentdir", e);
            return Err(e);
        }
    };

    // Get parent inode
    let parent_inode = parent_vpath.inode.as_ref()
        .ok_or(errno::Errno::NotADirectory.as_neg_i32())?;

    check_parent_write_permission(parent_inode)?;
    check_parent_exec_permission(parent_inode)?;

    // Get inode operations
    let ops = parent_inode.ops.as_ref()
        .ok_or(errno::Errno::ReadOnlyFileSystem.as_neg_i32())?;

    // Call mkdir through inode_operations (INV-VFSOPS-1 dispatcher; the
    // unsupported errno below is the original fn-None branch — EROFS).
    let inode_mode = InodeMode::new(InodeMode::S_IFDIR | (mode & 0o7777));
    let new_inode = match ops.call_mkdir(
        parent_inode.as_ref(),
        name.as_bytes(),
        inode_mode,
        Err(errno::Errno::ReadOnlyFileSystem),
    ) {
        Ok(i) => i,
        Err(e) => {
            let e = e.as_neg_i32();
            sbx_mkdir_stage("fs-mkdir", e);
            return Err(e);
        }
    };
    vfs_dir_epoch_bump();
    parent_inode.dir_mut_gen_bump();

    // inode_init_owner (Linux): a new entry gets the caller's fsuid,
    // and when the PARENT directory has S_ISGID set the child
    // inherits the parent's GID — plus the S_ISGID bit itself for
    // directories. LTP mkdir02 depends on both. Mode AND gid come
    // from the filesystem's getattr: a prior chown of the parent
    // updates the on-disk/fs-private inode while the cached VFS
    // inode keeps its instantiation-time gid, so
    // parent_inode.gid.load() returned a STALE gid and the child
    // inherited the wrong group.
    let (parent_mode_bits, parent_gid) = {
        let mut st = super::types::Stat::default();
        if parent_inode.op_getattr(&mut st) == 0 {
            (st.st_mode, st.st_gid as u32)
        } else {
            (
                parent_inode.mode.bits(),
                parent_inode.gid.load(Ordering::Relaxed),
            )
        }
    };
    if parent_mode_bits & 0o2000 != 0 {
        let mut st = super::types::Stat::default();
        if new_inode.op_getattr(&mut st) == 0 {
            let keep_uid = st.st_uid as u64;
            let _ = new_inode.op_setattr(
                self::setattr_attr::ATTR_UID_GID,
                keep_uid,
                parent_gid as u64,
            );
            // Re-read the (possibly updated) mode and set S_ISGID on
            // the new directory, preserving its type bits.
            let mut st2 = super::types::Stat::default();
            if new_inode.op_getattr(&mut st2) == 0 {
                let _ = new_inode.op_setattr(
                    self::setattr_attr::ATTR_MODE,
                    (st2.st_mode | 0o2000) as u64,
                    0,
                );
            }
        }
    }

    // Invalidate negative dentry and cache the new one
    if let Some(ref parent_dentry) = parent_vpath.dentry {
        parent_dentry.remove_child(&name);
        let d = Arc::new(Dentry::new(name.clone()));
        d.set_inode(new_inode.clone());
        d.set_parent(parent_dentry.clone());
        parent_dentry.add_child(name.clone(), d);
    }

    // inotify: IN_CREATE|IN_ISDIR on the parent (named).
    self::notify(
        Some(parent_inode),
        Some(&new_inode),
        self::ino_events::IN_CREATE | self::ino_events::IN_ISDIR,
        Some(name.as_bytes()),
        0,
    );

    Ok(())
}

/// Create a special node (device / FIFO / socket) on the filesystem that
/// OWNS the parent directory — Linux do_mknodat + vfs_mknod parity (OH
/// Phase 1b: OH's init mounts its own tmpfs over /dev and mknods
/// /dev/{null,random,urandom,kmsg}; the node must land on that tmpfs, not
/// in the devfs tree the string prefix alone would suggest).
///
/// `mode` carries the S_IFMT type bits plus permissions; `dev` is the
/// USERSPACE dev_t exactly as the syscall received it (new_encode_dev
/// layout — the filesystem stores it verbatim so stat() reports what
/// userspace makedev(3) built).
///
/// Filesystems without an mknod inode op report EOPNOTSUPP so the caller
/// can fall back to legacy paths (devfs's registry-internal mknod).
/// umask is applied by the caller (sys_mknodat), matching
/// do_mknodat's `mode &= ~current_umask()`.
pub fn vfs_mknod(pathname: &str, mode: u32, dev: u64) -> Result<(), i32> {
    // Serialize the lookup+mutate window (see VFS_MUTATION_LOCK note).
    let _mutation_guard = VFS_MUTATION_LOCK.guard();

    // EEXIST before any mutation (do_mknodat resolves through
    // user_path_create, which fails on an existing name). EROFS after
    // the existence decision — same order as vfs_mkdir.
    match path_lookup(pathname, LOOKUP_NOFOLLOW) {
        Ok(_) => return Err(errno::Errno::FileExists.as_neg_i32()),
        Err(e) if e == -(errno::constants::ENOENT) => {}
        Err(e) => return Err(e),
    }

    // Write-intent guard after the existence decision (see vfs_mkdir).
    check_not_readonly(pathname)?;

    let (parent_vpath, name) = lookup_parent_dir(pathname)?;
    let parent_inode = parent_vpath.inode.as_ref()
        .ok_or(errno::Errno::NotADirectory.as_neg_i32())?;

    check_parent_write_permission(parent_inode)?;
    check_parent_exec_permission(parent_inode)?;

    let ops = parent_inode.ops.as_ref()
        .ok_or(-(errno::constants::EOPNOTSUPP))?;

    // INV-VFSOPS-1 dispatcher; unsupported errno is EOPNOTSUPP (the
    // original fn-None branch — callers fall back to legacy paths).
    {
        let inode_mode = super::types::InodeMode::new(mode & 0o170000 | (mode & 0o7777));
        ops.call_mknod(
            parent_inode.as_ref(),
            name.as_bytes(),
            inode_mode,
            dev,
            Err(errno::Errno::OperationNotSupported),
        )
        .map_err(|e| e.as_neg_i32())?;
    }
    vfs_dir_epoch_bump();
    parent_inode.dir_mut_gen_bump();

    // Invalidate any stale (negative) dentry, the same
    // discipline as vfs_mkdir. The mknod callback returns no
    // inode here, so the next lookup repopulates it lazily.
    if let Some(ref parent_dentry) = parent_vpath.dentry {
        parent_dentry.remove_child(&name);
    }

    // inotify: IN_CREATE (named) on the parent.
    self::notify(
        Some(parent_inode),
        None,
        self::ino_events::IN_CREATE,
        Some(name.as_bytes()),
        0,
    );

    Ok(())
}

/// Create symbolic link - unified implementation using inode_operations
pub fn vfs_symlink(pathname: &str, target: &str) -> Result<(), i32> {
    // Serialize the lookup+mutate window (see VFS_MUTATION_LOCK note).
    let _mutation_guard = VFS_MUTATION_LOCK.guard();

    // EEXIST before any mutation (Linux sys_symlinkat; LTP symlink01
    // derivatives expect failure when the link name is taken). EROFS
    // after the existence decision — same order as vfs_mkdir.
    if path_lookup(pathname, LOOKUP_NOFOLLOW).is_ok() {
        return Err(errno::Errno::FileExists.as_neg_i32());
    }

    check_not_readonly(pathname)?;

    let (parent_vpath, name) = lookup_parent_dir(pathname)?;

    let parent_inode = parent_vpath.inode.as_ref()
        .ok_or(errno::Errno::NotADirectory.as_neg_i32())?;

    check_parent_write_permission(parent_inode)?;
    check_parent_exec_permission(parent_inode)?;

    let ops = parent_inode.ops.as_ref()
        .ok_or(errno::Errno::ReadOnlyFileSystem.as_neg_i32())?;

    // INV-VFSOPS-1 dispatcher; unsupported errno is EROFS (the original
    // fn-None branch).
    {
        let new_inode = ops
            .call_symlink(
                parent_inode.as_ref(),
                name.as_bytes(),
                target.as_bytes(),
                Err(errno::Errno::ReadOnlyFileSystem),
            )
            .map_err(|e| e.as_neg_i32())?;
        vfs_dir_epoch_bump();
        parent_inode.dir_mut_gen_bump();

        // Invalidate negative dentry and cache the new one
        if let Some(ref parent_dentry) = parent_vpath.dentry {
            parent_dentry.remove_child(&name);
            let d = Arc::new(Dentry::new(name.clone()));
            d.set_inode(new_inode);
            d.set_parent(parent_dentry.clone());
            parent_dentry.add_child(name.clone(), d);
        }

        // inotify: IN_CREATE on the parent (named).
        self::notify(
            Some(parent_inode),
            None,
            self::ino_events::IN_CREATE,
            Some(name.as_bytes()),
            0,
        );

        Ok(())
    }
}

/// Remove directory - unified implementation using inode_operations
pub fn vfs_rmdir(pathname: &str) -> Result<(), i32> {
    // Linux do_rmdir: "." (or "..") as the final component is EINVAL,
    // not an attempt to remove the parent directory itself (LTP
    // rmdir02's EINVAL case used to surface as ENOTEMPTY from the
    // resolved cwd). The test runs on the RAW path — normalization
    // strips "." components, so it is checked before normalizing. It
    // also precedes every filesystem-touching check (do_rmdir rejects
    // LAST_DOT before any lookup: rmdir(".") on a read-only filesystem
    // is EINVAL, not EROFS).
    {
        let last = pathname.trim_end_matches('/').rsplit('/').next().unwrap_or("");
        if last == "." || last == ".." {
            return Err(errno::Errno::InvalidArgument.as_neg_i32());
        }
    }

    // Linux may_delete(): a dentry that is a mountpoint answers EBUSY —
    // and this BEATS the read-only check of the mounted filesystem (the
    // victim's mount is what is busy; the parent decides writability).
    // LTP rmdir02's EBUSY case runs on the framework's READ-ONLY tmpfs
    // mntpoint: the entry check_not_readonly below saw the RO mount
    // first and answered EROFS. Gated on the target being on a
    // read-only mount — the only case where the RO check would preempt
    // EBUSY — so read-write workloads (pbench mkdir/rmdir churn) pay no
    // extra parent walk. Probe-only-if-positive: every other resolution
    // outcome (missing parent, non-directory mid-path, ...) falls
    // through to the regular path below, whose error precedence (ENOENT
    // / ENOTDIR / ELOOP) is unchanged.
    if path_on_readonly_mount(pathname) {
        if let Ok((parent_vpath, name)) = lookup_parent_dir(pathname) {
            if let Some(ref parent_dentry) = parent_vpath.dentry {
                if let Some(child) = parent_dentry.lookup_child(&name) {
                    if child.get_mount().is_some() {
                        return Err(errno::Errno::DeviceOrResourceBusy.as_neg_i32());
                    }
                }
            }
        }
    }

    check_not_readonly(pathname)?;

    // Serialize the lookup+mutate window (see VFS_MUTATION_LOCK note).
    let _mutation_guard = VFS_MUTATION_LOCK.guard();

    // Look up the target inode to get its ino for cache invalidation
    // (and its owner for the sticky-bit check). Walk errors other than
    // the final component's ENOENT propagate (Linux
    // filename_parent_directory): ENOTDIR for a non-directory mid-path
    // (rmdir "file/x") and ELOOP on symlink rings — the old `.ok()`
    // swallow let both fall through to the parent resolution and
    // resurface as ENOENT.
    let target_vpath = match path_lookup(pathname, 0) {
        Ok(vp) => Some(vp),
        Err(e) if e == -(errno::constants::ENOENT) => None,
        Err(e) => return Err(e),
    };
    let target_ino_and_fs_id = target_vpath.as_ref().and_then(|vp| {
        vp.inode.as_ref().map(|i| (i.ino, i.fs_id))
    });

    // chattr gate (Linux may_delete): IMMUTABLE and APPEND-only entries
    // cannot be removed — EPERM, regardless of ownership. The flags come
    // from FS_IOC_SETFLAGS (ext4 persists them in the on-disk i_flags).
    if let Some(flags) = target_vpath.as_ref().and_then(|vp| {
        vp.inode.as_ref().map(|i| {
            i.ioc_flags.load(core::sync::atomic::Ordering::Acquire)
        })
    }) {
        if flags
            & (self::FS_IMMUTABLE_FL | self::FS_APPEND_FL)
            != 0
        {
            return Err(errno::Errno::OperationNotPermitted.as_neg_i32());
        }
    }

    let (parent_vpath, name) = lookup_parent_dir(pathname)?;

    // Get parent inode
    let parent_inode = parent_vpath.inode.as_ref()
        .ok_or(errno::Errno::NotADirectory.as_neg_i32())?;

    check_parent_write_permission(parent_inode)?;
    check_parent_exec_permission(parent_inode)?;

    // Sticky bit: rmdir of another user's entry in a +t directory.
    check_sticky(
        parent_inode,
        target_vpath.as_ref().and_then(|vp| vp.inode.as_ref().map(|a| a.as_ref())),
    )?;

    // A mount point cannot be rmdir'd — EBUSY (Linux may_delete sees the
    // dentry's live mount; LTP rmdir02's MNT_POINT case). Removing the
    // covered dentry under a live mount would strand it.
    if let Some(ref parent_dentry) = parent_vpath.dentry {
        if let Some(child) = parent_dentry.lookup_child(&name) {
            if child.get_mount().is_some() {
                return Err(errno::Errno::DeviceOrResourceBusy.as_neg_i32());
            }
        }
    }

    // Get inode operations
    let ops = parent_inode.ops.as_ref()
        .ok_or(errno::Errno::ReadOnlyFileSystem.as_neg_i32())?;

    // Call rmdir through inode_operations (INV-VFSOPS-1 dispatcher;
    // unsupported errno is EROFS, the original fn-None branch).
    let result = ops.call_rmdir(
        parent_inode.as_ref(),
        name.as_bytes(),
        errno::Errno::ReadOnlyFileSystem.as_neg_i32(),
    );
    if result == 0 {
        vfs_dir_epoch_bump();
        parent_inode.dir_mut_gen_bump();
        // Invalidate icache entry for the removed directory
        if let Some((ino, fs_id)) = target_ino_and_fs_id {
            self::icache_remove(ino, fs_id);
        }
        // Kill the cached dentry the same way unlink does: negative
        // flag for fds still holding an Arc (getdents02), inode
        // dropped, entry detached from the parent's child map —
        // cached-forever negative dentries are an unbounded heap
        // leak under mkdir/rmdir churn.
        if let Some(ref parent_dentry) = parent_vpath.dentry {
            if let Some(child) = parent_dentry.lookup_child(&name) {
                child.set_negative();
                child.clear_inode();
                parent_dentry.remove_child(&name);
            }
        }
        // inotify: IN_DELETE|IN_ISDIR on the parent (named) and
        // IN_DELETE_SELF on the directory itself (auto-removes its
        // watches, delivering IN_IGNORED).
        let target_inode = target_vpath.as_ref().and_then(|vp| vp.inode.clone());
        self::notify(
            Some(parent_inode),
            None,
            self::ino_events::IN_DELETE | self::ino_events::IN_ISDIR,
            Some(name.as_bytes()),
            0,
        );
        if let Some(ref ti) = target_inode {
            // IN_ISDIR is NOT set on IN_DELETE_SELF (Linux
            // fsnotify_nameremove / inotify(7): the flag belongs
            // to the parent's named IN_DELETE above).
            self::notify(
                None,
                Some(ti),
                self::ino_events::IN_DELETE_SELF,
                None,
                0,
            );
        }
        Ok(())
    } else {
        Err(result)
    }
}

/// Unlink file - unified implementation using inode_operations
pub fn vfs_unlink(pathname: &str) -> Result<(), i32> {
    check_not_readonly(pathname)?;

    // POSIX/Linux: an empty pathname is ENOENT (name resolution fails
    // before anything else; resolving "" must never fall back to the
    // current/root directory) — LTP unlink07.
    if pathname.is_empty() {
        return Err(errno::Errno::NoSuchFileOrDirectory.as_neg_i32());
    }

    // Serialize the lookup+mutate window (see VFS_MUTATION_LOCK note).
    let _mutation_guard = VFS_MUTATION_LOCK.guard();

    // Look up the target inode to get its ino for cache invalidation
    // (and its owner for the sticky-bit check).
    let target_vpath = path_lookup(pathname, 0).ok();
    let target_ino_and_fs_id = target_vpath.as_ref().and_then(|vp| {
        vp.inode.as_ref().map(|i| (i.ino, i.fs_id))
    });

    // chattr gate (Linux may_delete): IMMUTABLE and APPEND-only entries
    // cannot be removed — EPERM, regardless of ownership. The flags come
    // from FS_IOC_SETFLAGS (ext4 persists them in the on-disk i_flags).
    if let Some(flags) = target_vpath.as_ref().and_then(|vp| {
        vp.inode.as_ref().map(|i| {
            i.ioc_flags.load(core::sync::atomic::Ordering::Acquire)
        })
    }) {
        if flags
            & (self::FS_IMMUTABLE_FL | self::FS_APPEND_FL)
            != 0
        {
            return Err(errno::Errno::OperationNotPermitted.as_neg_i32());
        }
    }

    let (parent_vpath, name) = lookup_parent_dir(pathname)?;

    // Get parent inode
    let parent_inode = parent_vpath.inode.as_ref()
        .ok_or(errno::Errno::NotADirectory.as_neg_i32())?;

    check_parent_write_permission(parent_inode)?;
    check_parent_exec_permission(parent_inode)?;

    // Sticky bit: unlink of another user's entry in a +t directory
    // (e.g. /tmp) must fail with EACCES (review 5.1 high).
    check_sticky(
        parent_inode,
        target_vpath.as_ref().and_then(|vp| vp.inode.as_ref().map(|a| a.as_ref())),
    )?;

    // Get inode operations
    let ops = parent_inode.ops.as_ref()
        .ok_or(errno::Errno::ReadOnlyFileSystem.as_neg_i32())?;

    // Call unlink through inode_operations (INV-VFSOPS-1 dispatcher;
    // unsupported errno is EROFS, the original fn-None branch).
    let result = ops.call_unlink(
        parent_inode.as_ref(),
        name.as_bytes(),
        errno::Errno::ReadOnlyFileSystem.as_neg_i32(),
    );
    if result == 0 {
        vfs_dir_epoch_bump();
        parent_inode.dir_mut_gen_bump();
        // inotify: capture the target inode before the caches drop
        // it — IN_DELETE on the parent (named); IN_DELETE_SELF on
        // the inode itself only when the last link went away.
        let target_inode = target_vpath.as_ref().and_then(|vp| vp.inode.clone());
        let last_link = target_inode
            .as_ref()
            .map(|i| inode_nlink(i) <= 1)
            .unwrap_or(true);

        // Invalidate icache entry for the removed inode
        if let Some((ino, fs_id)) = target_ino_and_fs_id {
            self::icache_remove(ino, fs_id);
        }
        // P1 FIFO: drop the named-pipe peer registered for this
        // inode — the path is going away, and a future mknod of
        // the same name allocates a NEW inode (fresh pipe). Fds
        // that still hold the old pipe keep it alive via their
        // private_data Arc (POSIX unlinked-FIFO semantics).
        if let Some(ref vp) = target_vpath {
            if let Some(ref i) = vp.inode {
                if i.mode.is_fifo() {
                    self::fifo_forget(i.fs_id, i.ino);
                }
            }
        }
        // Kill the cached dentry: mark it negative first (fds that
        // still hold their own Arc must observe the deletion —
        // getdents02's unlinked-directory readdir), clear its inode,
        // then DETACH it from the parent's child map. Keeping the
        // negative entry cached forever leaked one Dentry + name
        // String per deleted file (no dcache reclaim exists), which
        // exhausted the 128MB kernel heap under creat/unlink churn
        // (LTP inode02: ALLOCTHROW storm ~40s into the run).
        if let Some(ref parent_dentry) = parent_vpath.dentry {
            if let Some(child) = parent_dentry.lookup_child(&name) {
                child.set_negative();
                child.clear_inode();
                parent_dentry.remove_child(&name);
            }
        }

        // IN_DELETE goes to the parent watch (named); the inode
        // itself first gets IN_ATTRIB — unlink(2) drops its link
        // count, and that metadata change is reported to the
        // file's own watch (LTP inotify04: an unlinked watched
        // file must see IN_ATTRIB before IN_DELETE_SELF) — then
        // IN_DELETE_SELF when the last link went away.
        self::notify(
            Some(parent_inode),
            None,
            self::ino_events::IN_DELETE,
            Some(name.as_bytes()),
            0,
        );
        if let Some(ref ti) = target_inode {
            self::notify(None, Some(ti), self::ino_events::IN_ATTRIB, None, 0);
        }
        if last_link {
            if let Some(ref ti) = target_inode {
                self::notify(
                    None,
                    Some(ti),
                    self::ino_events::IN_DELETE_SELF,
                    None,
                    0,
                );
            }
        }
        Ok(())
    } else {
        Err(result)
    }
}

/// Create hard link - unified implementation using inode_operations
pub fn vfs_link(oldpath: &str, newpath: &str) -> Result<(), i32> {
    // Serialize the lookup+mutate window (see VFS_MUTATION_LOCK note).
    let _mutation_guard = VFS_MUTATION_LOCK.guard();

    // EROFS when the DESTINATION would be created on a read-only mount.
    check_not_readonly(newpath)?;

    // Lookup the source file
    let src_vpath = path_lookup(oldpath, 0)?;
    let src_inode = src_vpath.inode.as_ref()
        .ok_or(errno::Errno::NoSuchFileOrDirectory.as_neg_i32())?;

    // Linux may_linkat: hard-linking a DIRECTORY is EPERM (directory link
    // counts are maintained by mkdir/rmdir only). LTP link08/linkat01
    // expect EPERM, previously the filesystem callback surfaced EISDIR.
    if src_inode.mode.is_directory() {
        return Err(errno::Errno::OperationNotPermitted.as_neg_i32());
    }

    // Lookup parent directory of new path
    let (parent_vpath, name) = lookup_parent_dir(newpath)?;
    let parent_inode = parent_vpath.inode.as_ref()
        .ok_or(errno::Errno::NotADirectory.as_neg_i32())?;

    // Cross-device link is not allowed: source and destination must live on
    // the same filesystem (compare inode ops tables). Without this, the
    // parent's link callback would type-confuse a foreign inode.
    if !core::ptr::eq(
        src_inode.ops.as_ref().map(|o| *o as *const _).unwrap_or(core::ptr::null()),
        parent_inode.ops.as_ref().map(|o| *o as *const _).unwrap_or(core::ptr::null()),
    ) {
        return Err(errno::Errno::CrossDeviceLink.as_neg_i32());
    }

    check_parent_write_permission(parent_inode)?;
    check_parent_exec_permission(parent_inode)?;

    // Get inode operations
    let ops = parent_inode.ops.as_ref()
        .ok_or(errno::Errno::ReadOnlyFileSystem.as_neg_i32())?;

    // Call link through inode_operations (INV-VFSOPS-1 dispatcher;
    // unsupported errno is EROFS, the original fn-None branch).
    let result = ops.call_link(
        parent_inode.as_ref(),
        name.as_bytes(),
        src_inode.as_ref(),
        errno::Errno::ReadOnlyFileSystem.as_neg_i32(),
    );
    if result == 0 {
        vfs_dir_epoch_bump();
        parent_inode.dir_mut_gen_bump();
        // Invalidate stale/negative dentry at new path
        if let Some(ref parent_dentry) = parent_vpath.dentry {
            parent_dentry.remove_child(&name);
        }
        // inotify: a hard link appearing is IN_CREATE in the
        // destination directory (named); the linked inode itself
        // sees IN_ATTRIB (its link count changed).
        self::notify(
            Some(parent_inode),
            None,
            self::ino_events::IN_CREATE,
            Some(name.as_bytes()),
            0,
        );
        self::notify(None, Some(src_inode), self::ino_events::IN_ATTRIB, None, 0);
        Ok(())
    } else {
        Err(result)
    }
}

/// Rename file/directory
pub fn vfs_rename(oldpath: &str, newpath: &str) -> Result<(), i32> {
    // Serialize the lookup+mutate window (see VFS_MUTATION_LOCK note):
    // both the source and destination sequences must be atomic against a
    // concurrent creator/unlinker.
    let _mutation_guard = VFS_MUTATION_LOCK.guard();
    // EROFS when either end lives on a read-only mount (Linux mnt_want_write
    // on both the source and destination parents).
    check_not_readonly(oldpath)?;
    check_not_readonly(newpath)?;
    vfs_rename_locked(oldpath, newpath)
}

/// Lock-free rename core — caller must hold VFS_MUTATION_LOCK (either
/// directly via vfs_rename, or across a multi-step sequence such as
/// vfs_rename_exchange that must not interleave with other mutations).
fn vfs_rename_locked(oldpath: &str, newpath: &str) -> Result<(), i32> {
    // Lookup parent directories of both paths
    let (old_parent_vpath, old_name) = lookup_parent_dir(oldpath)?;
    let (new_parent_vpath, new_name) = lookup_parent_dir(newpath)?;

    let old_parent = old_parent_vpath.inode.as_ref()
        .ok_or(errno::Errno::NoSuchFileOrDirectory.as_neg_i32())?;
    let new_parent = new_parent_vpath.inode.as_ref()
        .ok_or(errno::Errno::NoSuchFileOrDirectory.as_neg_i32())?;

    // Rename across filesystems is not allowed: both parents must share the
    // same inode ops table, otherwise the rename callback would type-confuse
    // a foreign parent inode (e.g. rootfs_rename on a procfs inode).
    if !core::ptr::eq(
        old_parent.ops.as_ref().map(|o| *o as *const _).unwrap_or(core::ptr::null()),
        new_parent.ops.as_ref().map(|o| *o as *const _).unwrap_or(core::ptr::null()),
    ) {
        return Err(errno::Errno::CrossDeviceLink.as_neg_i32());
    }

    check_parent_write_permission(old_parent)?;
    check_parent_exec_permission(old_parent)?;
    check_parent_write_permission(new_parent)?;
    check_parent_exec_permission(new_parent)?;

    // Sticky-bit checks on BOTH parents: renaming out of a sticky dir
    // requires owning the source entry; renaming into a sticky dir
    // requires owning the replaced entry (if any) — mirrors Linux
    // may_delete() on both ends (review 5.1 high).
    let source_vpath = path_lookup(oldpath, 0).ok();
    // The source must exist (ENOENT) — checked before any no-op logic so
    // rename(missing, x) reports ENOENT (rename13's control case).
    let src_inode = source_vpath
        .as_ref()
        .and_then(|vp| vp.inode.as_ref())
        .ok_or(errno::Errno::NoSuchFileOrDirectory.as_neg_i32())?
        .clone();
    check_sticky(old_parent, Some(src_inode.as_ref()))?;
    let replaced_vpath = path_lookup(newpath, 0).ok();
    let replaced_inode = replaced_vpath
        .as_ref()
        .and_then(|vp| vp.inode.as_ref())
        .map(|a| a.clone());
    if replaced_vpath.is_some() {
        check_sticky(
            new_parent,
            replaced_vpath.as_ref().and_then(|vp| vp.inode.as_ref()).map(|a| a.as_ref()),
        )?;
    }

    // Final-component length: a destination name over NAME_MAX would be
    // uncreatable (rename10: a 256-char single component must fail
    // ENAMETOOLONG even when the total path is short).
    const NAME_MAX: usize = 255;
    if new_name.len() > NAME_MAX || old_name.len() > NAME_MAX {
        return Err(-(errno::constants::ENAMETOOLONG));
    }

    // Renaming onto the same entry (identical path or hard link) is a
    // successful no-op (rename(2): "If oldpath and newpath are ... hard
    // links referring to the same file, rename() does nothing and returns
    // success" — rename13).
    if let Some(ref ri) = replaced_inode {
        if Arc::ptr_eq(&ri, &src_inode) {
            return Ok(());
        }
    }

    // Type clash (may_delete/may_create parity): a non-directory cannot
    // replace an existing directory (EISDIR — rename05), and a directory
    // cannot replace an existing non-directory (ENOTDIR — rename07).
    if let Some(ref ri) = replaced_inode {
        let src_is_dir = src_inode.mode.is_directory();
        let dst_is_dir = ri.mode.is_directory();
        if !src_is_dir && dst_is_dir {
            return Err(errno::Errno::IsADirectory.as_neg_i32());
        }
        if src_is_dir && !dst_is_dir {
            return Err(errno::Errno::NotADirectory.as_neg_i32());
        }
    }


    // Rename a directory into itself or its own subdirectory would create a
    // ".." cycle — check the ancestor chain of the new parent (review 5.5:
    // rename 环检查错). Only directories can form cycles.
    if let Some(ref src_inode) = source_vpath.as_ref().and_then(|vp| vp.inode.as_ref()) {
        if src_inode.mode.is_directory() {
            // Renaming a dir to the same place is a no-op.
            if let (Some(ref old_d), Some(ref new_d)) = (&old_parent_vpath.dentry, &new_parent_vpath.dentry) {
                if Arc::ptr_eq(old_d, new_d) && old_name == new_name {
                    return Ok(());
                }
            }
            let new_parent_ino = new_parent.ino;
            if new_parent_ino == src_inode.ino
                || is_ancestor_of(Arc::clone(new_parent), src_inode.ino)
            {
                return Err(errno::Errno::InvalidArgument.as_neg_i32());
            }
        }
    }

    // Use old_parent's inode ops for rename
    let result = old_parent.op_rename(old_name.as_bytes(), new_parent, new_name.as_bytes());
    if result == 0 {
        vfs_dir_epoch_bump();
        // Negative-memo invalidation: the name left old_parent (its
        // still-missing verdict stays TRUE but is re-proven by the gen
        // bump) and arrived in new_parent (any memo there was wrong the
        // moment the name appeared).
        old_parent.dir_mut_gen_bump();
        new_parent.dir_mut_gen_bump();
        // Keep the dentry cache in step with the on-disk rename by MOVING
        // the renamed entry's cached dentry (reference d_move): the dentry
        // — with its whole cached subtree — is re-attached under the new
        // parent/name. The old invalidate-both code dropped it, which left
        // detached-but-still-linked chains behind: any task holding a
        // dentry reference INTO the renamed subtree (cwd/root recorded as
        // a dentry) kept building the OLD path from the stale chain, so
        // every relative lookup under that prefix failed with ENOENT (LTP
        // inotify02 renames its own working directory; the following
        // relative unlink() broke).
        if let Some(ref new_pd) = new_parent_vpath.dentry {
            // The replaced entry (if any) was deleted by the rename:
            // invalidate its cached dentry so the moved one can take the
            // name slot.
            if let Some(replaced) = new_pd.lookup_child(&new_name) {
                replaced.set_negative();
                replaced.clear_inode();
                new_pd.remove_child(&new_name);
            }
        }
        if let Some(ref old_pd) = old_parent_vpath.dentry {
            if let Some(child) = old_pd.lookup_child(&old_name) {
                old_pd.remove_child(&old_name);
                *child.name.lock() = new_name.clone();
                if let Some(ref new_pd) = new_parent_vpath.dentry {
                    child.set_parent(new_pd.clone());
                    new_pd.add_child(new_name.clone(), child);
                } else {
                    // New parent has no cached dentry to hang the moved
                    // subtree from — fall back to plain invalidation (the
                    // entry is reachable again through a fresh lookup).
                    child.set_negative();
                    child.clear_inode();
                }
            }
        }

        // inotify: IN_MOVED_FROM on the old parent and IN_MOVED_TO on the
        // new parent share a nonzero cookie so watchers can correlate the
        // halves; the inode itself gets IN_MOVE_SELF.
        let src_inode = source_vpath.as_ref().and_then(|vp| vp.inode.clone());
        let isdir = src_inode
            .as_ref()
            .map(|i| i.mode.is_directory())
            .unwrap_or(false);
        let dir_bit = if isdir { self::ino_events::IN_ISDIR } else { 0 };
        let cookie = self::alloc_cookie();
        // MOVED_FROM/MOVED_TO go to parent-directory watches (named); a
        // direct watch on the file sees only IN_MOVE_SELF below.
        self::notify(
            Some(old_parent),
            None,
            self::ino_events::IN_MOVED_FROM | dir_bit,
            Some(old_name.as_bytes()),
            cookie,
        );
        self::notify(
            Some(new_parent),
            None,
            self::ino_events::IN_MOVED_TO | dir_bit,
            Some(new_name.as_bytes()),
            cookie,
        );
        if let Some(ref si) = src_inode {
            // IN_ISDIR is NOT set on IN_MOVE_SELF (Linux fsnotify_move
            // tags only the parent's named MOVED_FROM/MOVED_TO records).
            self::notify(
                None,
                Some(si),
                self::ino_events::IN_MOVE_SELF,
                None,
                0,
            );
        }
        Ok(())
    } else {
        Err(result)
    }
}

/// Walk the ".." chain of `dir` and report whether `candidate_ino` is an
/// ancestor of `dir` (bounded to 64 hops to survive corrupt trees).
fn is_ancestor_of(start: Arc<Inode>, candidate_ino: u64) -> bool {
    let mut current = start;
    let mut guard_count = 0;
    while guard_count < 64 {
        guard_count += 1;
        // Read ".." through the filesystem's lookup op.
        match current.op_lookup(b"..") {
            Ok(parent_ino) => {
                if parent_ino == candidate_ino {
                    return true;
                }
                if parent_ino == current.ino {
                    return false; // reached filesystem root
                }
                // Materialize the parent inode through iget
                // (INV-VFSOPS-1 dispatcher; unsupported → give up).
                let ops = match current.ops {
                    Some(o) => o,
                    None => return false,
                };
                let parent_inode = match ops.call_iget(
                    &current,
                    b"..",
                    parent_ino,
                    Err(errno::Errno::NoSuchFileOrDirectory),
                ) {
                    Ok(i) => i,
                    Err(_) => return false,
                };
                current = parent_inode;
            }
            Err(_) => return false,
        }
    }
    false
}

/// renameat2(RENAME_EXCHANGE): atomically swap the two paths.
///
/// Both paths must exist (ENOENT otherwise). The swap runs under one
/// VFS_MUTATION_LOCK hold as a three-rename ballet through a unique
/// hidden temp name in the NEW path's parent directory:
///   A → tmp, B → A, tmp → B
/// The whole sequence is serialized against every other VFS mutation
/// (create/unlink/rename take the same lock), so no concurrent mutation
/// can interleave. Concurrent READS can observe the intermediate
/// A-missing window — a full directory-entry-level swap would need
/// per-filesystem support; documented approximation, final state and
/// crash-window-mates are correct.
pub fn vfs_rename_exchange(oldpath: &str, newpath: &str) -> Result<(), i32> {
    use alloc::format;
    use alloc::string::ToString;

    if oldpath == newpath {
        // Exchanging a path with itself is a no-op (Linux returns 0).
        // But it must still exist.
        let mut st = super::types::Stat::new();
        return stat_file_by_path(oldpath, &mut st);
    }

    let _mutation_guard = VFS_MUTATION_LOCK.guard();

    // Both endpoints must exist.
    let old_vpath = path_lookup(oldpath, 0)
        .map_err(|_| errno::Errno::NoSuchFileOrDirectory.as_neg_i32())?;
    let new_vpath = path_lookup(newpath, 0)
        .map_err(|_| errno::Errno::NoSuchFileOrDirectory.as_neg_i32())?;

    // A directory swap across an ancestor relationship would create a
    // ".." cycle — reject like plain rename does.
    if let (Some(ref oi), Some(ref ni)) = (&old_vpath.inode, &new_vpath.inode) {
        if oi.mode.is_directory() || ni.mode.is_directory() {
            if is_ancestor_of(Arc::clone(oi), ni.ino) || is_ancestor_of(Arc::clone(ni), oi.ino) {
                return Err(errno::Errno::InvalidArgument.as_neg_i32());
            }
        }
    }

    // Unique hidden temp name in the new path's parent directory (same
    // filesystem as B by construction, so the renames cannot hit EXDEV).
    static EXCHANGE_COUNTER: core::sync::atomic::AtomicU64 =
        core::sync::atomic::AtomicU64::new(0);
    let n = EXCHANGE_COUNTER.fetch_add(1, core::sync::atomic::Ordering::Relaxed);
    let tmp_name = format!(
        ".rux-rex-{:x}-{:x}",
        crate::timer::get_jiffies(),
        n
    );
    let new_parent_str = match newpath.rfind('/') {
        Some(0) => "/".to_string(),
        Some(idx) => newpath[..idx].to_string(),
        None => ".".to_string(),
    };
    let tmp_path = format!("{}/{}", new_parent_str.trim_end_matches('/'), tmp_name);

    // A → tmp (B's directory), B → A, tmp → B.
    vfs_rename_locked(oldpath, &tmp_path)?;
    if let Err(e) = vfs_rename_locked(newpath, oldpath) {
        // Roll back: tmp → A restores the original state.
        let _ = vfs_rename_locked(&tmp_path, oldpath);
        return Err(e);
    }
    if let Err(e) = vfs_rename_locked(&tmp_path, newpath) {
        // B already sits at A's name; restore by moving it back and
        // unwinding the first rename.
        let _ = vfs_rename_locked(oldpath, newpath);
        let _ = vfs_rename_locked(&tmp_path, oldpath);
        return Err(e);
    }
    Ok(())
}
///
/// # Arguments
/// - `pathname`: file path
/// - `mode`: new permission bits (e.g., 0o644)
pub fn vfs_chmod(pathname: &str, mode: u32) -> Result<(), i32> {
    check_not_readonly(pathname)?;

    let vpath = path_lookup(pathname, 0)?;
    let inode = vpath.inode.as_ref()
        .ok_or(errno::Errno::NoSuchFileOrDirectory.as_neg_i32())?;

    // Permission check: root or owner
    let cred = if let Some(task) = crate::sched::current() {
        task.cred().clone()
    } else {
        crate::process::task::Cred::new_init()
    };
    let inode_uid = inode.uid.load(Ordering::Relaxed);
    if cred.euid != 0 && cred.euid != inode_uid {
        return Err(errno::Errno::OperationNotPermitted.as_neg_i32());
    }

    // Linux chmod_common/notify_change: only the permission + special bits
    // (S_IALLUGO = 0o7777) are honored — type bits in the request are
    // ignored, not rejected (LTP chmod05 passes S_IFDIR|mode).
    let mode = mode & 0o7777;
    // notify_change: an unprivileged caller that is not in the file's group
    // loses S_ISGID on chmod (setgid dirs/ executables must not survive a
    // downgrade by a non-owner). Root (CAP_FSETID) keeps it.
    let inode_gid = inode.gid.load(Ordering::Relaxed);
    let mode = if mode & 0o2000 != 0
        && cred.euid != 0
        && cred.egid != inode_gid
        && !cred.groups.contains(&inode_gid)
    {
        mode & !0o2000
    } else {
        mode
    };

    let result = inode.op_setattr(self::setattr_attr::ATTR_MODE, mode as u64, 0);
    if result == 0 {
        // inotify: mode change → IN_ATTRIB. The subject's ISDIR modifier
        // rides on BOTH the parent's named record and the inode's own
        // record (reference fsnotify_change) — LTP inotify10 expects
        // IN_ATTRIB|IN_ISDIR from a chmod on a watched directory.
        let mut ev_mask = self::ino_events::IN_ATTRIB;
        if inode.mode.is_directory() {
            ev_mask |= self::ino_events::IN_ISDIR;
        }
        let name = vpath.dentry.as_ref().map(|d| d.get_name().into_bytes());
        notify_about(vpath.dentry.as_ref(), Some(inode), ev_mask, name.as_deref(), 0);
        Ok(())
    } else {
        Err(result)
    }
}

/// Change file ownership (chown)
///
/// # Arguments
/// - `pathname`: file path
/// - `uid`: new owner uid (u32::MAX = no change)
/// - `gid`: new owner gid (u32::MAX = no change)
/// - `follow`: follow a final symlink (chown) or act on the link itself
///   (lchown / fchownat AT_SYMLINK_NOFOLLOW)
pub fn vfs_chown(pathname: &str, uid: u32, gid: u32, follow: bool) -> Result<(), i32> {
    check_not_readonly(pathname)?;

    let lookup_flags = if follow { 0 } else { LOOKUP_NOFOLLOW };
    let vpath = path_lookup(pathname, lookup_flags)?;
    let inode = vpath.inode.as_ref()
        .ok_or(errno::Errno::NoSuchFileOrDirectory.as_neg_i32())?;

    let cred = if let Some(task) = crate::sched::current() {
        task.cred().clone()
    } else {
        crate::process::task::Cred::new_init()
    };
    let inode_uid = inode.uid.load(Ordering::Relaxed);
    let inode_gid = inode.gid.load(Ordering::Relaxed);

    // Linux chown_ok/chgrp_ok (fs/attr.c): CAP_CHOWN holders may set
    // anything; an unprivileged OWNER may re-set its own uid and any gid it
    // belongs to (LTP chown03: nobody chgrps its own file to its own
    // group); everything else is EPERM. The old blanket euid!=0 → EPERM
    // rejected the legal owner case.
    let is_priv = crate::security::has_capability(&cred, crate::security::CAP_CHOWN);
    let owner = cred.euid == inode_uid;
    if !is_priv {
        if uid != u32::MAX && !(owner && uid == inode_uid) {
            return Err(errno::Errno::OperationNotPermitted.as_neg_i32());
        }
        if gid != u32::MAX && !(owner && cred.in_group(gid)) {
            return Err(errno::Errno::OperationNotPermitted.as_neg_i32());
        }
    }

    // Resolve actual uid/gid (u32::MAX means no change)
    let actual_uid = if uid == u32::MAX {
        inode_uid
    } else {
        uid
    };
    let actual_gid = if gid == u32::MAX {
        inode.gid.load(Ordering::Relaxed)
    } else {
        gid
    };

    // POSIX: clear setuid/setgid bits on owner change (per Linux notify_change).
    // Read the CURRENT mode through the filesystem's getattr, not the cached
    // inode mode word: filesystems whose authoritative attributes live in
    // fs-private nodes (devfs entry, tmpfs node) update those in setattr
    // while the cached inode keeps its instantiation-time word — chmod 600
    // followed by chown rewrote the stale 0666 back over the entry.
    let mode = {
        let mut st = super::types::Stat::default();
        if inode.op_getattr(&mut st) == 0 {
            st.st_mode
        } else {
            inode.mode.bits()
        }
    };
    // Linux chown_common (fs/open.c) + notify_change: for NON-directories it
    // requests ATTR_KILL_SUID | ATTR_KILL_PRIV UNCONDITIONALLY (even a
    // privileged caller, even when uid/gid are unchanged), plus
    // setattr_should_drop_sgid: S_ISGID is killed when the file is
    // group-executable (mode & S_IXGRP) or the caller is neither in the
    // file's group nor CAP_FSETID-capable. The old code skipped the kill for
    // CAP_FSETID holders and required an id to change — current LTP chown02
    // chowns a 06770 root file to (0,0) and expects 0770, while a 0670 file
    // (no group-execute) keeps its setgid.
    if !inode.mode.is_directory() {
        let mut new_mode = mode;
        if new_mode & 0o4000 != 0 {
            new_mode &= !0o4000; // S_ISUID: always killed on chown
        }
        let in_group_or_capable =
            cred.in_group(inode.gid.load(Ordering::Relaxed))
                || crate::security::has_capability(&cred, crate::security::CAP_FSETID);
        if new_mode & 0o2000 != 0 && ((new_mode & 0o010) != 0 || !in_group_or_capable) {
            new_mode &= !0o2000; // S_ISGID
        }
        if new_mode != mode {
            let _ = inode.op_setattr(self::setattr_attr::ATTR_MODE, new_mode as u64, 0);
        }
    }

    let result = inode.op_setattr(self::setattr_attr::ATTR_UID_GID, actual_uid as u64, actual_gid as u64);
    if result == 0 {
        // inotify: owner change → IN_ATTRIB (ISDIR modifier when the
        // subject is a directory, same as chmod above).
        let mut ev_mask = self::ino_events::IN_ATTRIB;
        if inode.mode.is_directory() {
            ev_mask |= self::ino_events::IN_ISDIR;
        }
        let name = vpath.dentry.as_ref().map(|d| d.get_name().into_bytes());
        notify_about(vpath.dentry.as_ref(), Some(inode), ev_mask, name.as_deref(), 0);
        Ok(())
    } else {
        Err(result)
    }
}

/// Truncate file by path (truncate)
///
/// # Arguments
/// - `pathname`: file path
/// - `new_size`: new file size
pub fn vfs_truncate(pathname: &str, new_size: i64) -> Result<(), i32> {
    check_not_readonly(pathname)?;

    if new_size < 0 {
        return Err(errno::Errno::InvalidArgument.as_neg_i32());
    }

    // RLIMIT_FSIZE: growing the file past the soft limit fails EFBIG
    // before any lookup work (Linux do_truncate checks in
    // truncate_setsize's callers; LTP truncate03 sets the limit in
    // setup and expects the 32MiB truncate to fail EFBIG).
    if let Some(task) = crate::sched::current() {
        let (fsz_cur, _) = task.rlimit(crate::process::task::rlimit_res::FSIZE);
        if fsz_cur != u64::MAX && new_size as u64 > fsz_cur {
            return Err(errno::Errno::FileTooLarge.as_neg_i32());
        }
    }

    let vpath = path_lookup(pathname, 0)?;
    let inode = vpath.inode.as_ref()
        .ok_or(errno::Errno::NoSuchFileOrDirectory.as_neg_i32())?;

    if inode.mode.is_directory() {
        return Err(errno::Errno::IsADirectory.as_neg_i32());
    }

    // Permission check: need write access
    let inode_mode = inode.mode.bits() as u16;
    let inode_uid = inode.uid.load(Ordering::Relaxed);
    let inode_gid = inode.gid.load(Ordering::Relaxed);
    let cred = if let Some(task) = crate::sched::current() {
        task.cred().clone()
    } else {
        crate::process::task::Cred::new_init()
    };
    if !self::generic_permission(
        inode_mode, inode_uid, inode_gid,
        self::MAY_WRITE, &cred,
    ) {
        return Err(errno::Errno::PermissionDenied.as_neg_i32());
    }

    // File leases: truncation conflicts with BOTH read and write leases
    // (Linux break_lease on ATTR_SIZE).
    self::lock_hooks_break_lease(inode, true)
        .map_err(|e| e.as_neg_i32())?;

    let result = inode.op_setattr(self::setattr_attr::ATTR_SIZE, new_size as u64, 0);
    if result == 0 {
        // inotify: truncate → IN_MODIFY (Linux reports it for every
        // successful truncate, even a size no-op; never IN_ATTRIB).
        let name = vpath.dentry.as_ref().map(|d| d.get_name().into_bytes());
        notify_about(
            vpath.dentry.as_ref(),
            Some(inode),
            self::ino_events::IN_MODIFY,
            name.as_deref(),
            0,
        );
        Ok(())
    } else {
        Err(result)
    }
}

/// Truncate open file by fd (ftruncate)
pub fn vfs_ftruncate(fd: usize, new_size: i64) -> Result<(), i32> {
    if new_size < 0 {
        return Err(errno::Errno::InvalidArgument.as_neg_i32());
    }

    // RLIMIT_FSIZE parity with vfs_truncate (Linux do_ftruncate path).
    if let Some(task) = crate::sched::current() {
        let (fsz_cur, _) = task.rlimit(crate::process::task::rlimit_res::FSIZE);
        if fsz_cur != u64::MAX && new_size as u64 > fsz_cur {
            return Err(errno::Errno::FileTooLarge.as_neg_i32());
        }
    }

    let file = get_file_fd(fd).ok_or(errno::Errno::BadFileNumber.as_neg_i32())?;

    // EROFS: fd-based truncate on a read-only mount (Linux mnt_want_write).
    if file_on_readonly_mount(&file) {
        return Err(errno::Errno::ReadOnlyFileSystem.as_neg_i32());
    }

    // Linux do_ftruncate: a VALID fd that is not open for writing is
    // EINVAL (man 2 ftruncate: "fd is not open for writing"); EBADF is
    // only for fds that do not exist (LTP ftruncate03: read_fd EINVAL,
    // bad_fd EBADF).
    let file_flags = file.flags();
    if file_flags.is_readonly() {
        return Err(errno::Errno::InvalidArgument.as_neg_i32());
    }

    // Get inode from file
    // SAFETY: file.inode is an UnsafeCell<Option<Arc<Inode>>>; accessing under current task's fd table lock
    let inode_opt = file.get_inode();
    // Sockets and other inode-less files: the fd is valid but the target
    // is not a regular file — EINVAL, not EBADF (LTP ftruncate03 sock_fd).
    let inode = inode_opt.as_ref()
        .ok_or(errno::Errno::InvalidArgument.as_neg_i32())?;

    if inode.mode.is_directory() {
        return Err(errno::Errno::IsADirectory.as_neg_i32());
    }

    // Linux do_ftruncate: only regular files (and dirs, which we already
    // rejected with EISDIR above) are truncatable. A FIFO, socket, or
    // device node must fail with EINVAL instead of running a generic
    // setattr that would fake success.
    if !inode.mode.is_regular_file() {
        return Err(errno::Errno::InvalidArgument.as_neg_i32());
    }

    // File leases: ftruncate conflicts with read AND write leases.
    self::lock_hooks_break_lease(inode, true)
        .map_err(|e| e.as_neg_i32())?;

    let result = inode.op_setattr(self::setattr_attr::ATTR_SIZE, new_size as u64, 0);
    if result == 0 {
        // inotify: ftruncate → IN_MODIFY (through the File so parent
        // watches get the named event; Linux reports it for every
        // successful ftruncate, even a size no-op).
        self::notify_file(&file, self::ino_events::IN_MODIFY);
        Ok(())
    } else {
        Err(result)
    }
}

/// Get file/directory status using inode_operations
pub fn vfs_stat(pathname: &str, stat: &mut Stat) -> Result<(), i32> {
    let vpath = path_lookup(pathname, 0)?;
    let inode = vpath.inode.as_ref()
        .ok_or(errno::Errno::NoSuchFileOrDirectory.as_neg_i32())?;

    // Get inode operations
    if let Some(ops) = inode.ops.as_ref() {
        // INV-VFSOPS-1 dispatcher: getattr when provided, else fall
        // through to the generic fill below (unsupported = 1 forces the
        // fallback, matching the old fn-None fall-through).
        let result = ops.call_getattr(
            inode.as_ref(),
            stat,
            1, // unsupported: not a real errno; the caller falls through
        );
        if result == 0 {
            // st_dev: the filesystem instance's anonymous device
            // (Linux s_dev), stamped centrally over whatever the
            // per-fs getattr wrote — see inode::stat_dev_user.
            stat.st_dev = self::stat_dev_user(inode.fs_id);
            return Ok(());
        } else if ops.getattr.is_some() {
            return Err(result);
        }
    }

    // Fallback: fill in basic info from inode
    stat.st_dev = self::stat_dev_user(inode.fs_id);
    stat.st_ino = inode.ino;
    stat.st_mode = inode.mode.bits();
    stat.st_size = 0;
    stat.st_nlink = 1;
    Ok(())
}

// ==================== inode creation ownership helpers ====================
// Linux counterparts: mode_strip_sgid() + inode_init_owner() in fs/inode.c,
// vfs_prepare_mode() in fs/namei.c (commit 1639a49ccdce, "fs: move S_ISGID
// stripping into the vfs_*() helpers") and the CVE-2018-13405 fix
// 0fa3ecd87848 ("Fix up non-directory creation in SGID Directories").
// LTP creat09 checks all three rules below.

const S_ISGID_BIT: u32 = 0o2000;
const S_IXGRP_BIT: u32 = 0o010;

/// Linux in_group_or_capable(idmap, dir, dir->i_gid): true when the caller
/// may keep S_ISGID on a file it creates in a setgid directory — its fsgid
/// (or a supplementary group) matches the directory's gid, or it holds
/// CAP_FSETID.
fn in_group_or_capable_dir(dir_gid: u32) -> bool {
    match crate::sched::current() {
        Some(task) => {
            let cred = task.cred();
            if cred.fsgid == dir_gid || cred.in_group(dir_gid) {
                return true;
            }
            crate::security::has_capability(cred, crate::security::CAP_FSETID)
        }
        None => false,
    }
}

/// Linux mode_strip_sgid() (fs/inode.c): a NEW non-directory keeps S_ISGID
/// only when the requested mode has S_ISGID|S_IXGRP, the parent directory
/// is itself setgid, and the caller is in the parent's group or privileged
/// (CAP_FSETID). Otherwise the S_ISGID bit is stripped before the mode
/// reaches the filesystem — creating a setgid file one does not belong to
/// would be a privilege escalation (CVE-2018-13405; LTP creat09).
pub fn mode_strip_sgid(dir_mode_bits: u32, dir_gid: u32, mode: u32) -> u32 {
    if mode & (S_ISGID_BIT | S_IXGRP_BIT) != (S_ISGID_BIT | S_IXGRP_BIT) {
        return mode;
    }
    // Directories never come through here (vfs_mkdir has its own S_ISGID
    // propagation); the parent must carry S_ISGID for the strip rule.
    if dir_mode_bits & S_ISGID_BIT == 0 {
        return mode;
    }
    if in_group_or_capable_dir(dir_gid) {
        return mode;
    }
    mode & !S_ISGID_BIT
}

/// Linux vfs_prepare_mode() (fs/namei.c) for non-directory creation:
/// S_ISGID strip FIRST, then umask. The umask must not mask away S_IXGRP
/// before the strip decision, or the mandatory-lock-style setgid file
/// (mode 02777 & ~010) would survive against the caller's interest
/// (LTP creat09's umask(S_IXGRP) round).
fn prepare_create_mode(dir_mode_bits: u32, dir_gid: u32, mode: u32) -> u32 {
    let stripped = mode_strip_sgid(dir_mode_bits, dir_gid, mode & 0o7777);
    let umask = match crate::sched::current() {
        Some(task) => task.get_umask(),
        None => 0o022,
    };
    stripped & !umask
}

/// Linux inode_init_owner() (fs/inode.c) gid rule for a fresh inode: when
/// the parent directory carries S_ISGID, the new entry inherits the
/// directory's gid (directories additionally inherit the S_ISGID bit —
/// handled by vfs_mkdir; non-directories get it STRIPPED by
/// mode_strip_sgid above). Applied post-create through setattr because
/// the per-filesystem create callbacks initialize gid from the caller's
/// fsgid. Mode and gid come from the parent's getattr (a chown'd cached
/// VFS inode keeps its instantiation-time gid — see the vfs_mkdir note).
fn inherit_setgid_dir_gid(parent_inode: &Arc<Inode>, new_inode: &Arc<Inode>) {
    let (parent_mode_bits, parent_gid) = {
        let mut st = super::types::Stat::default();
        if parent_inode.op_getattr(&mut st) == 0 {
            (st.st_mode, st.st_gid as u32)
        } else {
            (
                parent_inode.mode.bits(),
                parent_inode.gid.load(core::sync::atomic::Ordering::Relaxed),
            )
        }
    };
    if parent_mode_bits & S_ISGID_BIT == 0 {
        return;
    }
    let keep_uid = new_inode.uid.load(core::sync::atomic::Ordering::Relaxed) as u64;
    let _ = new_inode.op_setattr(
        self::setattr_attr::ATTR_UID_GID,
        keep_uid,
        parent_gid as u64,
    );
}

///
///
/// # Arguments
/// - filename: file name (must be an absolute path)
/// - flags: O_RDONLY (0), O_WRONLY (1), O_RDWR (2), O_CREAT (0o100), O_EXCL (0o200), O_TRUNC (0o1000)
/// - mode: file permission (used when creating, currently not implemented)
///
/// # Returns
/// Returns file descriptor on success, error code on failure
///
/// # Supported flags
/// - O_RDONLY/O_WRONLY/O_RDWR: read/write mode
/// - O_CREAT: create file if it does not exist
/// - O_EXCL: used with O_CREAT, returns error if file already exists
/// - O_TRUNC: truncate file to empty
/// Open an unnamed temporary file inside `dirpath` (O_TMPFILE semantics).
///
/// Linux creates a fresh inode in the directory with NO directory entry;
/// the descriptor is the only handle until the file is materialized via
/// linkat("/proc/self/fd/N"). Implemented on top of the ordinary create
/// path: create a uniquely-named file, open it, then immediately unlink
/// the name — the descriptor's dentry keeps the inode reachable (POSIX
/// unlink-while-open) and the /proc/[pid]/fd/N magic link resolves to
/// that dentry (see follow_symlink), so linkat re-links it exactly as on
/// Linux (LTP open14 / openat03).
pub fn file_open_tmpfile(dirpath: &str, flags: u32, mode: u32) -> Result<usize, i32> {
    static TMPFILE_SEQ: core::sync::atomic::AtomicU64 =
        core::sync::atomic::AtomicU64::new(0);

    let dir = path_lookup(dirpath, 0)?;
    let dir_inode = dir.inode
        .ok_or(errno::Errno::NoSuchFileOrDirectory.as_neg_i32())?;
    if !dir_inode.mode.is_directory() {
        return Err(errno::Errno::NotADirectory.as_neg_i32());
    }
    // Creating the inode needs write+search on the directory (Linux
    // O_TMPFILE -> MAY_WRITE|MAY_EXEC on the parent).
    if !self::inode_permission(
        &dir_inode,
        self::MAY_WRITE | self::MAY_EXEC,
    ) {
        return Err(errno::Errno::PermissionDenied.as_neg_i32());
    }

    // Strip the directory-shaped bits; add create-exclusive so the name
    // can never collide. Access mode (O_RDWR/O_WRONLY) passes through.
    let open_flags = (flags & !(FileFlags::O_DIRECTORY as u32
        | 0o20000000 /*__O_TMPFILE*/
        | FileFlags::O_TRUNC as u32))
        | FileFlags::O_CREAT as u32
        | FileFlags::O_EXCL as u32;

    let seq = TMPFILE_SEQ.fetch_add(1, core::sync::atomic::Ordering::Relaxed);
    let unique = alloc::format!(
        ".rux-tmpfile-{}-{}",
        crate::process::current_pid(),
        seq
    );
    let full = if dirpath.ends_with('/') {
        alloc::format!("{}{}", dirpath, unique)
    } else {
        alloc::format!("{}/{}", dirpath, unique)
    };

    let fd = file_open(&full, open_flags, mode)?;

    // Remove the name right away: the directory must report empty (the
    // descriptor holds the inode alive). A failed unlink leaks a name —
    // close the descriptor and surface the error instead.
    if let Err(e) = vfs_unlink(&full) {
        // SAFETY: fd was just installed in the current task's table.
        unsafe {
            let _ = self::close_file_fd(fd);
        }
        return Err(e);
    }
    Ok(fd)
}

pub fn file_open(filename: &str, flags: u32, mode: u32) -> Result<usize, i32> {
    // (unsafe-slim r3) the body runs without an unsafe context: every fs
    // callback goes through the INV-VFSOPS-1 dispatchers.
    {
        let o_creat = (flags & FileFlags::O_CREAT) != 0;
        let o_excl = (flags & FileFlags::O_EXCL) != 0;
        let o_trunc = (flags & FileFlags::O_TRUNC) != 0;

        // EROFS before any lookup/write attempt: a write-intent open
        // (O_WRONLY / O_RDWR / O_TRUNC) on a MS_RDONLY mount fails, as does
        // O_CREAT on one (Linux may_open + mnt_want_write; LTP creat06 and
        // the needs_rofs family).
        //
        // NON-REGULAR inodes are exempt from the mount-ro open gate
        // (deferred to below, post-lookup): opening a character device
        // (/dev/null!) O_WRONLY on a read-only MOUNT is legal in the
        // reference — MS_RDONLY on a bind does not make device nodes
        // unwritable at open time. systemd 255's namespace apivfs table
        // binds /dev READ-ONLY into every namespaced service, and the
        // executor's setup_output opens /dev/null O_WRONLY for
        // StandardOutput=null — the open-time EROFS here killed every
        // namespaced service with 209/STDOUT (ub2404 serial evidence).
        let write_intent =
            flags & (FileFlags::O_WRONLY | FileFlags::O_RDWR | FileFlags::O_TRUNC) != 0;
        if o_creat && path_on_readonly_mount(filename) {
            return Err(errno::Errno::ReadOnlyFileSystem.as_neg_i32());
        }
        let mut deferred_rofs_check = false;
        if write_intent && !o_creat && path_on_readonly_mount(filename) {
            deferred_rofs_check = true;
        }

        // O_CREAT atomicity (review 5.1 high): the existence check and the
        // create below must be one atomic step on SMP, or two CPUs racing on
        // the same non-existent name both allocate an inode / directory
        // entry. Bracket the whole sequence with the coarse VFS mutation
        // lock (see VFS_MUTATION_LOCK note for the design choice).
        //
        // KILLABLE (oh-launch round 3): a task SIGKILLed while queued here
        // (de_thread / exit_group teardown of a threading group) unwinds
        // with EINTR instead of parking UNINTERRUPTIBLE forever — the
        // reference's killable namei waits (rwsem/mutex *_killable). The
        // waiter never held the lock, so nothing needs undoing; a healthy
        // caller cannot observe the EINTR (its SIGKILL is delivered at
        // the syscall exit and the task dies), which keeps the ABI clean.
        let _mutation_guard = if o_creat {
            match VFS_MUTATION_LOCK.lock_killable() {
                Some(g) => Some(g),
                None => return Err(errno::Errno::InterruptedSystemCall.as_neg_i32()),
            }
        } else {
            None
        };

        // Step 1: Resolve path through dentry tree
        // O_NOFOLLOW (POSIX): refuse to follow a symlink FINAL component —
        // privileged callers rely on this against symlink tricks, and the
        // flag was previously accepted and silently ignored (the link was
        // followed anyway).
        // O_PATH does NOT change symlink traversal (Linux do_last: only
        // O_NOFOLLOW|O_EXCL stop the follow) — an O_PATH open of a symlink
        // path yields a descriptor for the FOLLOWED TARGET. The old
        // O_PATH-implies-nofollow reading handed back the LINK inode, so
        // systemd's find_executable_full (open(O_PATH) + fstat +
        // S_ISREG on /usr/lib/systemd/systemd-udevd → ../../bin/udevadm)
        // saw mode 0120777, failed fd_verify_regular, and every service
        // whose ExecStart path is a symlink died 203/EXEC (ub2404
        // udevd/journald-chain, flip7 [chain] fstat reg=0, 2026-11-15).
        // readlinkat01's O_PATH|O_NOFOLLOW shape still lands on the link
        // inode — O_NOFOLLOW keeps doing that job alone.
        let lookup_flags = if flags & FileFlags::O_NOFOLLOW != 0 {
            LOOKUP_NOFOLLOW
        } else {
            0
        };
        // inotify: O_TRUNC on a file that already existed fires IN_MODIFY
        // (Linux handle_truncate runs only when the open did NOT create
        // the file — a fresh O_CREAT inode starts empty and stays silent).
        let mut existed_before_trunc = false;
        let (inode, opened_dentry) = match path_lookup(filename, lookup_flags) {
            Ok(vpath) => {
                if o_excl && o_creat {
                    return Err(errno::Errno::FileExists.as_neg_i32());
                }
                let inode = vpath.inode.ok_or(errno::Errno::NoSuchFileOrDirectory.as_neg_i32())?;
                // Deferred mount-ro gate (see the header comment): a
                // write-intent open of an EXISTING file fails EROFS on a
                // read-only mount ONLY for regular files (the LTP
                // needs_rofs contract); character/block/fifo/socket nodes
                // open fine — the device layer is not the mount's data.
                if deferred_rofs_check && inode.mode.is_regular_file() {
                    return Err(errno::Errno::ReadOnlyFileSystem.as_neg_i32());
                }
                if flags & (FileFlags::O_NOFOLLOW | FileFlags::O_PATH) != 0
                    && inode.mode.is_symlink()
                    && flags & FileFlags::O_PATH == 0
                {
                    return Err(errno::Errno::TooManySymbolicLinks.as_neg_i32()); // ELOOP
                }
                // /proc/[pid]/ns/<kind> magic link (followed — plain open):
                // the fd IS the namespace reference (Linux nsfs). The
                // syscall-layer string shortcut only covers non-chrooted
                // tasks; the generic walk (used by jailed/pivoted tasks —
                // OH init after its sandbox pivot) lands here via the
                // terminal follow_symlink rule.
                if inode.fs_id == self::FS_ID_PROCFS
                    && inode.private_data.is_none()
                    && inode.mode.is_symlink()
                {
                    let pid_val = inode.ino / 10000;
                    let rem = inode.ino % 10000;
                    if self::procfs::is_valid_pid(pid_val)
                        && rem >= self::procfs::PROCFS_NS_LINK_INO_OFF
                        && rem < self::procfs::PROCFS_NS_LINK_INO_OFF + 6
                    {
                        if let Some(kind) =
                            crate::process::ns::NsKind::from_index(rem - self::procfs::PROCFS_NS_LINK_INO_OFF)
                        {
                            let file = crate::process::ns::build_ns_file(
                                pid_val as u32,
                                kind,
                                flags,
                            )
                            .map_err(|e| e)?;
                            return match get_file_fd_install(file) {
                                Some(fd) => Ok(fd),
                                None => {
                                    Err(errno::Errno::TooManyOpenFiles.as_neg_i32())
                                }
                            };
                        }
                    }
                }
                // O_PATH on a symlink: install a descriptor-only File on
                // the link inode (no read/write ops — matches Linux, where
                // only fstat/fchdir-ish/readlinkat(fd,"") use it).
                if flags & FileFlags::O_PATH != 0 && inode.mode.is_symlink() {
                    let file = Arc::new(File::new(FileFlags::new(flags)));
                    file.set_inode(Arc::clone(&inode));
                    if let Some(d) = vpath.dentry.clone() {
                        file.set_dentry(d);
                    }
                    match get_file_fd_install(Arc::clone(&file)) {
                        Some(fd) => return Ok(fd),
                        None => return Err(errno::Errno::TooManyOpenFiles.as_neg_i32()),
                    }
                }
                existed_before_trunc = true;
                (inode, vpath.dentry)
            }
            Err(_e) if o_creat => {
                // Only a genuinely ABSENT name may be created (Linux
                // path_openat: O_CREAT proceeds only on ENOENT). Other
                // lookup failures — ELOOP on a self-referential symlink
                // (LTP creat06/open01 ELOOP cases), ENOTDIR, EACCES —
                // propagate to the caller instead of creating through them.
                if _e != -(errno::constants::ENOENT) {
                    return Err(_e);
                }
                let (parent_path, child_name) = path_parent_and_name(filename)?;
                // O_CREAT|O_EXCL is a NOFOLLOW-style existence probe: a
                // dangling symlink at the final component is EEXIST (the
                // name is taken), never "follow it and create the target"
                // (POSIX open; LTP open10/excl cases).
                if o_excl && !child_name.is_empty() {
                    if let Ok(vp) = path_lookup(filename, LOOKUP_NOFOLLOW) {
                        let _ = vp;
                        return Err(errno::Errno::FileExists.as_neg_i32());
                    }
                }
                let parent_vpath = path_lookup(&parent_path, 0)?;
                let parent_inode = parent_vpath.inode
                    .ok_or(errno::Errno::NoSuchFileOrDirectory.as_neg_i32())?;
                // A non-directory in the middle of the create path is
                // ENOTDIR, not a permission error (LTP bind01: unix bind
                // under a regular file must fail ENOTDIR; the ops.create
                // lookup below would otherwise surface EPERM/EACCES).
                if !parent_inode.mode.is_directory() {
                    return Err(errno::Errno::NotADirectory.as_neg_i32());
                }
                // DAC: creating an entry requires write+search on the parent
                if !self::inode_permission(
                    &parent_inode,
                    self::MAY_WRITE | self::MAY_EXEC,
                ) {
                    return Err(errno::Errno::PermissionDenied.as_neg_i32());
                }
                let ops = parent_inode.ops.as_ref()
                    .ok_or(errno::Errno::NotADirectory.as_neg_i32())?;
                let new_inode = {
                    // Linux vfs_prepare_mode() (S_ISGID strip then umask) —
                    // the parent's live mode/gid decide both the strip and
                    // the gid inheritance below (cached fields can lag a
                    // chmod/chown of the parent; see the vfs_mkdir note).
                    let (parent_mode_bits, parent_gid) = {
                        let mut st = super::types::Stat::default();
                        if parent_inode.op_getattr(&mut st) == 0 {
                            (st.st_mode, st.st_gid as u32)
                        } else {
                            (
                                parent_inode.mode.bits(),
                                parent_inode.gid.load(core::sync::atomic::Ordering::Relaxed),
                            )
                        }
                    };
                    let filtered_mode =
                        prepare_create_mode(parent_mode_bits, parent_gid, mode);
                    // INV-VFSOPS-1 dispatcher; unsupported errno is EACCES
                    // (the original fn-None branch).
                    let new_inode = ops.call_create(
                        &*parent_inode,
                        child_name.as_bytes(),
                        super::types::InodeMode::new(filtered_mode),
                        Err(errno::Errno::PermissionDenied),
                    ).map_err(|e| e.as_neg_i32())?;
                    // Linux inode_init_owner(): a setgid parent hands its
                    // gid to everything created inside it (LTP creat09,
                    // CVE-2018-13405 family).
                    inherit_setgid_dir_gid(&parent_inode, &new_inode);
                    vfs_dir_epoch_bump();
                    parent_inode.dir_mut_gen_bump();
                    new_inode
                };
                // Cache new dentry (replace stale/negative dentry)
                let mut new_d = None;
                if let Some(ref parent_dentry) = parent_vpath.dentry {
                    let name = String::from(child_name.as_str());
                    parent_dentry.remove_child(&name);
                    let d = Arc::new(Dentry::new(name.clone()));
                    d.set_inode(Arc::clone(&new_inode));
                    d.set_parent(parent_dentry.clone());
                    parent_dentry.add_child(name, d.clone());
                    new_d = Some(d);
                }
                // inotify: file creation via open(O_CREAT) → IN_CREATE on
                // the parent directory (named).
                self::notify(
                    Some(&parent_inode),
                    None,
                    self::ino_events::IN_CREATE,
                    Some(child_name.as_bytes()),
                    0,
                );
                (new_inode, new_d)
            }
            Err(e) => return Err(e),
        };

        // Directory -> redirect to opendir
        if inode.mode.is_directory() {
            // Linux: opening a directory for WRITING (O_RDWR/O_WRONLY)
            // fails with EISDIR before anything else (LTP open08) — only
            // O_RDONLY (optionally |O_DIRECTORY) is legal on a dir.
            let accmode = flags & FileFlags::O_ACCMODE;
            if accmode != FileFlags::O_RDONLY {
                return Err(errno::Errno::IsADirectory.as_neg_i32());
            }
            return file_opendir(
                filename,
                flags | super::types::FileFlags::O_DIRECTORY,
            );
        }

        // Device nodes with no bound driver: Linux fails the open with
        // ENXIO (no such device or address) — not a silent ops-less File
        // whose read/write would return EBADF.
        if inode.mode.is_char_device() || inode.mode.is_block_device() {
            // INV-VFSOPS-1 dispatcher (None layers identical: no ops).
            let has_ops = match inode.ops {
                Some(o) => o.call_get_file_ops(&*inode).is_some(),
                None => false,
            };
            if !has_ops {
                return Err(errno::Errno::NoSuchDeviceOrAddress.as_neg_i32());
            }
        }

        // DAC: check access mode against the target inode (Linux may_open).
        // O_RDONLY/O_RDWR → MAY_READ; O_WRONLY/O_RDWR/O_TRUNC → MAY_WRITE.
        {
            use self::{inode_permission, MAY_READ, MAY_WRITE};
            let accmode = flags & FileFlags::O_ACCMODE;
            let mut mask = 0;
            if accmode == FileFlags::O_RDONLY || accmode == FileFlags::O_RDWR {
                mask |= MAY_READ;
            }
            if accmode == FileFlags::O_WRONLY || accmode == FileFlags::O_RDWR || o_trunc {
                mask |= MAY_WRITE;
            }
            if mask != 0 && !inode_permission(&inode, mask) {
                return Err(errno::Errno::PermissionDenied.as_neg_i32());
            }
            // ETXTBSY (reference may_open -> get_write_access vs negative
            // i_writecount): a write-mode (or O_TRUNC) open of a regular
            // file some live process still EXECUTES fails with ETXTBSY —
            // the exec side registered its text hold (deny_write_access
            // analogue; LTP creat07's creat of a running child image).
            if mask & MAY_WRITE != 0
                && inode.mode.is_regular_file()
                && self::lock_hooks_inode_text_hold_count(&inode) > 0
            {
                return Err(errno::Errno::TextFileBusy.as_neg_i32());
            }
        }

        // File leases (P3): a conflicting open blocks while the holder is
        // signalled (SIGIO) and the kernel waits up to fs.lease-break-time
        // before breaking the lease by force (LTP fcntl33). Write leases
        // conflict with ANY open; read leases with write-mode opens.
        // Directories never carry leases (set_lease rejects them).
        if inode.mode.is_regular_file() {
            let writer = flags & FileFlags::O_ACCMODE != FileFlags::O_RDONLY;
            self::lock_hooks_break_lease(&inode, writer)
            .map_err(|e| e.as_neg_i32())?;
        }

        // O_NOATIME (Linux): requires the caller to OWN the file or hold
        // CAP_FOWNER — a plain unprivileged reader of another user's file
        // gets EPERM (LTP open02).
        if flags & FileFlags::O_NOATIME != 0 {
            let fsuid = crate::sched::current()
                .map(|t| t.cred().fsuid)
                .unwrap_or(0);
            let owner = inode.uid.load(core::sync::atomic::Ordering::Relaxed);
            if fsuid != owner
                && !crate::security::capable(
                    crate::security::capability::CAP_FOWNER,
                )
            {
                return Err(errno::Errno::OperationNotPermitted.as_neg_i32());
            }
        }

        // FIFO (P1 mknod/mkfifo): named-pipe open semantics — a blocking
        // O_RDONLY waits for a writer, a blocking O_WRONLY waits for a
        // reader, O_NONBLOCK applies per POSIX (ENXIO for a writer with no
        // reader). Dispatch AFTER the DAC check, BEFORE the regular-file
        // path, so the pipe data path (not the inode data) serves I/O.
        if inode.mode.is_fifo() {
            let file = self::fifo_open(inode.fs_id, inode.ino, flags)?;
            file.set_inode(Arc::clone(&inode));
            if let Some(d) = opened_dentry {
                file.set_dentry(d);
            }
            match get_file_fd_install(Arc::clone(&file)) {
                Some(fd) => {
                    self::notify_file(&file, self::ino_events::IN_OPEN);
                    return Ok(fd);
                }
                None => return Err(errno::Errno::TooManyOpenFiles.as_neg_i32()),
            }
        }

        // Create File object
        let file_flags = FileFlags::new(flags);
        let file = Arc::new(File::new(file_flags));
        file.set_inode(Arc::clone(&inode));
        // Track the dentry so /proc/self/fd and dirfd-relative lookups can
        // recover the path (fixes File.dentry never being set).
        if let Some(d) = opened_dentry {
            file.set_dentry(d);
        }

        // Get FileOps from inode callback (INV-VFSOPS-1 dispatchers;
        // absent ops map to no-op, matching the original None branches).
        if let Some(ops) = inode.ops {
            if let Some(file_ops) = ops.call_get_file_ops(&*inode) {
                file.set_ops(file_ops);
            }
            // Call open callback (e.g., procfs pre-read)
            let result = ops.call_open(&*inode, &*file, 0);
            if result != 0 {
                return Err(result);
            }
        }

        // Handle O_TRUNC via setattr
        let mut trunc_modified = false;
        if o_trunc && inode.mode.is_regular_file() {
            let result = inode.op_setattr(
                self::setattr_attr::ATTR_SIZE, 0, 0
            );
            if result != 0 {
                return Err(result);
            }
            // inotify: O_TRUNC of an existing inode → IN_MODIFY (Linux
            // fires it even when the size was already 0; only a file this
            // same open created stays silent — hence the existed flag).
            trunc_modified = existed_before_trunc;
        }

        match get_file_fd_install(Arc::clone(&file)) {
            Some(fd) => {
                // inotify: successful open → IN_OPEN (parent watches get
                // the named event through the File's dentry). Linux emits
                // IN_OPEN before the O_TRUNC IN_MODIFY of the same open.
                self::notify_file(&file, self::ino_events::IN_OPEN);
                if trunc_modified {
                    self::notify_file(&file, self::ino_events::IN_MODIFY);
                }
                Ok(fd)
            }
            None => Err(errno::Errno::TooManyOpenFiles.as_neg_i32()),
        }
    }
}

/// Open `path` read-only through the VFS and return the File WITHOUT
/// installing a descriptor (Linux vm_file semantics for kernel-held
/// references: the Arc outlives any fd number). Unlike `file_open`, this
/// never touches the current task's fdtable, so it also works in early-boot
/// contexts where no fdtable exists yet — the PID-1 exec pins the init and
/// interpreter identities on the exec-time segment VMAs this way, giving
/// /proc/1/maps its path column. A kernel-internal open is also invisible to
/// inotify (no IN_OPEN), matching get_empty_filp-based kernel opens. Dentry
/// and file ops are wired exactly like the fd-installing path so reads
/// through the returned Arc behave as a normal O_RDONLY descriptor.
/// Best-effort: None on lookup failure, a missing inode, or a directory.
pub fn open_file_arc_nofd(path: &str) -> Option<alloc::sync::Arc<File>> {
    // (unsafe-slim r3) plain safe body: path_lookup resolves through the
    // dentry tree and open_file_arc_from_vpath is safe now.
    let vpath = path_lookup(path, 0).ok()?;
    open_file_arc_from_vpath(&vpath)
}

/// Build the kernel-internal read-only File from an ALREADY-RESOLVED
/// VfsPath — the File-construction half of [`open_file_arc_nofd`],
/// split so callers that resolved the path themselves (the exec ladder's
/// single-lookup fast path) do not walk the path a second time. Same
/// semantics: no fdtable slot, invisible to inotify, None on a missing
/// inode or a directory.
///
/// (unsafe-slim r3) un-signed: VfsPath carries Arc'd dentry/inode (the
/// raw `mnt` pointer is never dereferenced here), and every ops call goes
/// through the INV-VFSOPS-1 dispatchers. Hand-verified: safe parameter
/// types, no unsafe ops in the body, no caller contract left to uphold.
pub fn open_file_arc_from_vpath(vpath: &VfsPath) -> Option<alloc::sync::Arc<File>> {
    let inode = vpath.inode.as_ref()?;
    if inode.mode.is_directory() {
        return None;
    }
    let file = alloc::sync::Arc::new(File::new(FileFlags::new(
        FileFlags::O_RDONLY,
    )));
    file.set_inode(alloc::sync::Arc::clone(inode));
    if let Some(d) = vpath.dentry.clone() {
        file.set_dentry(d);
    }
    if let Some(ops) = inode.ops {
        // INV-VFSOPS-1 dispatchers; absent ops map to no-op.
        if let Some(file_ops) = ops.call_get_file_ops(&**inode) {
            file.set_ops(file_ops);
        }
        if ops.call_open(&**inode, &*file, 0) != 0 {
            return None;
        }
    }
    Some(file)
}

///
///
/// # Arguments
/// - fd: file descriptor
///
/// # Returns
/// Returns Ok(()) on success, error code on failure
pub fn file_close(fd: usize) -> Result<(), i32> {
    // (unsafe-slim r3) close_file_fd is a safe fn; the wrapper was vestigial.
    close_file_fd(fd)
}

///
///
/// # Arguments
/// - fd: file descriptor
/// - buf: buffer
/// - count: number of bytes to read
///
/// # Returns
/// Returns number of bytes read on success, error code on failure
pub fn file_read(fd: usize, buf: &mut [u8], count: usize) -> Result<usize, i32> {
    // (unsafe-slim r3) slice-typed dispatch (File::read_slice).
    match get_file_fd(fd) {
        Some(file) => {
            let read_count = count.min(buf.len());
            let result = file.read_slice(&mut buf[..read_count]);
            if result < 0 {
                Err(result as i32)
            } else {
                Ok(result as usize)
            }
        }
        None => {
            Err(errno::Errno::BadFileNumber.as_neg_i32())
        }
    }
}

///
///
/// # Arguments
/// - fd: file descriptor
/// - buf: buffer
/// - count: number of bytes to write
///
/// # Returns
/// Returns number of bytes written on success, error code on failure
pub fn file_write(fd: usize, buf: &[u8], count: usize) -> Result<usize, i32> {
    // (unsafe-slim r3) slice-typed dispatch (File::write_slice).
    match get_file_fd(fd) {
        Some(file) => {
            let write_count = count.min(buf.len());
            let result = file.write_slice(&buf[..write_count]);
            if result < 0 {
                Err(result as i32)
            } else {
                Ok(result as usize)
            }
        }
        None => {
            Err(errno::Errno::BadFileNumber.as_neg_i32())
        }
    }
}

/// Get file status by fd (fstat)
pub fn file_stat(fd: usize, stat: &mut Stat) -> Result<(), i32> {
    // (unsafe-slim r3) the inode cell read goes through File::get_inode
    // (write-once cell, safe accessor).
    {
        let file = match get_file_fd(fd) {
            Some(f) => f,
            None => return Err(errno::Errno::BadFileNumber.as_neg_i32()),
        };
        let inode = match file.get_inode() {
            Some(i) => i,
            None => {
                // Anonymous file description (pipe ends, kernel console):
                // no VFS inode, but fstat(2) must still succeed with a
                // real, distinct identity — Linux stats pipes on pipefs
                // and the console on devfs. Without this, fstat failed
                // with EBADF and userspace same-file checks misbehaved
                // (coreutils cat: "input file is output file" on every
                // `x | cat` pipeline, silently dropping the data).
                if self::pipe_stat(&file, stat).is_some() {
                    return Ok(());
                }
                // Sockets (all families) install inode-less Files too;
                // they must stat as S_IFSOCK or clients that probe the
                // fd shape give up capabilities — sd-bus's
                // sd_is_socket() decides unix-fd NEGOTIATION on it
                // (gdmr71 session-fifo hunt: without this every
                // fd-carrying sd-bus send returned EOPNOTSUPP).
                if crate::api::net::socket_file_stat(&file, stat).is_some() {
                    return Ok(());
                }
                if self::char_dev_stat(&file, stat).is_some() {
                    return Ok(());
                }
                // DRM nodes + exported prime (dma-buf) fds: dma-buf must
                // stat as a regular file with st_size == buffer size (the
                // EGL/gbm importers validate through it).
                if crate::drivers::drm::drm_file_stat(&file, stat).is_some() {
                    return Ok(());
                }
                if mem_file_stat(&file, stat).is_some() {
                    return Ok(());
                }
                return Err(errno::Errno::BadFileNumber.as_neg_i32());
            }
        };
        let result = inode.op_getattr(stat);
        if result == 0 {
            // st_dev: the instance's anonymous device (Linux s_dev) —
            // same stamp as vfs_stat (fstat must agree with stat for
            // libmount's is-mounted probes on open fds).
            stat.st_dev = self::stat_dev_user(inode.fs_id);
            Ok(())
        } else {
            Err(result)
        }
    }
}

/// Get file status by path (for fstatat)
pub fn stat_file_by_path(path: &str, stat: &mut Stat) -> Result<(), i32> {
    vfs_stat(path, stat)
}

/// Get file status by path with lookup flags (for fstatat with AT_SYMLINK_NOFOLLOW)
pub fn stat_file_by_path_with_flags(path: &str, stat: &mut Stat, flags: u32) -> Result<(), i32> {
    let vpath = path_lookup(path, flags)?;
    let inode = vpath.inode.as_ref()
        .ok_or(errno::Errno::NoSuchFileOrDirectory.as_neg_i32())?;

    if let Some(ops) = inode.ops.as_ref() {
        // INV-VFSOPS-1 dispatcher; unsupported = EINVAL (the original
        // fn-None fall-through result below).
        let result = ops.call_getattr(
            inode.as_ref(),
            stat,
            errno::Errno::InvalidArgument.as_neg_i32(),
        );
        if result == 0 {
            // st_dev: the instance's anonymous device (Linux
            // s_dev) — same stamp as vfs_stat.
            stat.st_dev = self::stat_dev_user(inode.fs_id);
            return Ok(());
        } else {
            return Err(result);
        }
    }
    Err(errno::Errno::InvalidArgument.as_neg_i32())
}

/// fcntl command constants
///
pub mod fcntl {
    /// Duplicate file descriptor
    pub const F_DUPFD: usize = 0;

    /// Get close-on-exec flag
    pub const F_GETFD: usize = 1;

    /// Set close-on-exec flag
    pub const F_SETFD: usize = 2;

    /// Get file status flags
    pub const F_GETFL: usize = 3;

    /// Set file status flags
    pub const F_SETFL: usize = 4;

    /// Get record lock info (struct flock *)
    pub const F_GETLK: usize = 5;

    /// Set record lock (non-blocking)
    pub const F_SETLK: usize = 6;

    /// Set record lock (blocking)
    pub const F_SETLKW: usize = 7;

    /// 64-bit aliases — on RV64 off_t is already 64-bit and the struct
    /// layout is identical (glibc may use either number).
    pub const F_GETLK64: usize = 12;
    pub const F_SETLK64: usize = 13;
    pub const F_SETLKW64: usize = 14;

    /// Signal I/O owner commands (asm-generic numbering).
    pub const F_SETOWN: usize = 8;
    pub const F_GETOWN: usize = 9;
    pub const F_SETSIG: usize = 10;
    pub const F_GETSIG: usize = 11;
    pub const F_SETOWN_EX: usize = 15;
    pub const F_GETOWN_EX: usize = 16;

    /// Open-file-description record locks (Linux 3.15+).
    pub const F_OFD_GETLK: usize = 36;
    pub const F_OFD_SETLK: usize = 37;
    pub const F_OFD_SETLKW: usize = 38;

    /// Duplicate file descriptor with close-on-exec
    pub const F_DUPFD_CLOEXEC: usize = 1030;

    /// File leases (asm-generic).
    pub const F_SETLEASE: usize = 1024;
    pub const F_GETLEASE: usize = 1025;

    /// Pipe capacity query/resize.
    pub const F_SETPIPE_SZ: usize = 1031;
    pub const F_GETPIPE_SZ: usize = 1032;

    /// memfd seals (memfd_create(2); asm-generic numbering).
    pub const F_ADD_SEALS: usize = 1033;
    pub const F_GET_SEALS: usize = 1034;

    /// FD_CLOEXEC flag value
    pub const FD_CLOEXEC: usize = 1;
}

/// flock lock types (struct flock::l_type).
mod flock_types {
    pub const F_RDLCK: i16 = 0;
    pub const F_WRLCK: i16 = 1;
    pub const F_UNLCK: i16 = 2;
}

/// Resolve a `struct flock` region (l_whence/l_start/l_len) into an
/// absolute byte range `[start, end)`; `end == u64::MAX` means "to EOF"
/// (and tracks EOF as it grows, per POSIX). Returns negative errno on
/// malformed input.
fn resolve_lock_region(
    file: &File,
    l_whence: i16,
    l_start: i64,
    l_len: i64,
) -> Result<(u64, u64), i32> {
    let base: i64 = match l_whence {
        0 => 0, // SEEK_SET
        1 => file.get_pos() as i64, // SEEK_CUR
        2 => {
            // SAFETY: inode is written once at open time; read-only access.
            let inode_opt = file.get_inode();
            match inode_opt.as_ref() {
                Some(inode) => inode.get_size() as i64, // SEEK_END
                None => return Err(errno::Errno::BadFileNumber.as_neg_i32()),
            }
        }
        _ => return Err(errno::Errno::InvalidArgument.as_neg_i32()),
    };

    let start = match base.checked_add(l_start) {
        Some(s) if s >= 0 => s as u64,
        _ => return Err(errno::Errno::InvalidArgument.as_neg_i32()),
    };

    let end = if l_len == 0 {
        // l_len == 0: lock from start to EOF (and beyond, if it grows).
        u64::MAX
    } else if l_len > 0 {
        match start.checked_add(l_len as u64) {
            Some(e) => e,
            None => return Err(errno::Errno::InvalidArgument.as_neg_i32()),
        }
    } else {
        // Negative l_len: region ends at l_start and extends backwards.
        match (start as i64).checked_add(l_len) {
            Some(s) if s >= 0 => {
                let end = start;
                let start = s as u64;
                if start >= end {
                    return Err(errno::Errno::InvalidArgument.as_neg_i32());
                }
                return Ok((start, end));
            }
            _ => return Err(errno::Errno::InvalidArgument.as_neg_i32()),
        }
    };

    if end <= start {
        return Err(errno::Errno::InvalidArgument.as_neg_i32());
    }
    Ok((start, end))
}

///
///
/// # Arguments
/// - fd: file descriptor
/// - cmd: fcntl command
/// - arg: command argument
///
/// # Returns
/// Returns command-specific value on success, error code on failure
///
/// # Supported commands
/// - F_DUPFD (0) - Duplicate file descriptor, arg specifies minimum fd
/// - F_GETFD (1) - Get close-on-exec flag
/// - F_SETFD (2) - Set close-on-exec flag
/// - F_GETFL (3) - Get file status flags
/// - F_SETFL (4) - Set file status flags
pub fn file_fcntl(fd: usize, cmd: usize, arg: usize) -> Result<usize, i32> {
    use self::{get_file_fd, get_file_fd_install};

    // (unsafe-slim r3) the body runs without an unsafe context.
    {
        match cmd {
            // F_DUPFD: Duplicate file descriptor
            fcntl::F_DUPFD => {
                // Get original file
                let old_file = match get_file_fd(fd) {
                    Some(f) => f,
                    None => return Err(errno::Errno::BadFileNumber.as_neg_i32()),
                };

                // Allocate new file descriptor >= arg
                let fdtable = crate::sched::get_current_fdtable()
                    .ok_or(errno::Errno::BadFileNumber.as_neg_i32())?;
                let new_fd = fdtable.alloc_fd_from(arg)
                    .ok_or(errno::Errno::TooManyOpenFiles.as_neg_i32())?;
                fdtable.install_fd(new_fd, old_file)
                    .map_err(|_| errno::Errno::TooManyOpenFiles.as_neg_i32())?;

                Ok(new_fd)
            }

            // F_DUPFD_CLOEXEC: Duplicate file descriptor with close-on-exec
            fcntl::F_DUPFD_CLOEXEC => {
                // Get original file
                let old_file = match get_file_fd(fd) {
                    Some(f) => f,
                    None => return Err(errno::Errno::BadFileNumber.as_neg_i32()),
                };

                // Allocate new file descriptor >= arg
                let fdtable = crate::sched::get_current_fdtable()
                    .ok_or(errno::Errno::BadFileNumber.as_neg_i32())?;
                let new_fd = fdtable.alloc_fd_from(arg)
                    .ok_or(errno::Errno::TooManyOpenFiles.as_neg_i32())?;
                fdtable.install_fd(new_fd, old_file)
                    .map_err(|_| errno::Errno::TooManyOpenFiles.as_neg_i32())?;

                // Set close-on-exec flag on the new fd (per-descriptor)
                fdtable.set_fd_cloexec(new_fd, true);

                Ok(new_fd)
            }

            // F_GETFD: Get close-on-exec flag
            fcntl::F_GETFD => {
                if get_file_fd(fd).is_none() {
                    return Err(errno::Errno::BadFileNumber.as_neg_i32());
                }
                let ft = crate::sched::get_current_fdtable()
                    .ok_or(errno::Errno::BadFileNumber.as_neg_i32())?;
                Ok(if ft.get_fd_cloexec(fd) { fcntl::FD_CLOEXEC } else { 0 })
            }

            // F_SETFD: Set close-on-exec flag
            fcntl::F_SETFD => {
                if get_file_fd(fd).is_none() {
                    return Err(errno::Errno::BadFileNumber.as_neg_i32());
                }
                let ft = crate::sched::get_current_fdtable()
                    .ok_or(errno::Errno::BadFileNumber.as_neg_i32())?;
                // Bit 0 of arg indicates FD_CLOEXEC (per-descriptor)
                ft.set_fd_cloexec(fd, (arg & fcntl::FD_CLOEXEC) != 0);
                Ok(0)  // Return 0 on success
            }

            // F_GETFL: Get file status flags
            fcntl::F_GETFL => {
                let file = match get_file_fd(fd) {
                    Some(f) => f,
                    None => return Err(errno::Errno::BadFileNumber.as_neg_i32()),
                };

                // Return file status flags (access mode)
                Ok(file.flags().bits() as usize)
            }

            // F_SETFL: Set file status flags
            fcntl::F_SETFL => {
                let file = match get_file_fd(fd) {
                    Some(f) => f,
                    None => return Err(errno::Errno::BadFileNumber.as_neg_i32()),
                };

                // Linux semantics: F_SETFL can only modify O_NONBLOCK,
                // O_APPEND, O_ASYNC and O_DIRECT/O_SYNC. EVERY other flag
                // (access mode, O_DIRECTORY, O_NOFOLLOW, ...) keeps its
                // current value — the old code rebuilt the word from just
                // accmode|arg and cleared O_DIRECTORY et al (review 5.1).
                // P2 O_DIRECT: the flag round-trips through F_SETFL (the
                // I/O path does not differentiate buffered vs direct —
                // flush semantics approximate it; documented limitation).
                const SETFL_FLAGS: u32 = super::types::FileFlags::O_APPEND
                    | super::types::FileFlags::O_NONBLOCK
                    | super::types::FileFlags::O_SYNC
                    | super::types::FileFlags::O_DSYNC
                    | super::types::FileFlags::O_DIRECT
                    | super::types::FileFlags::O_ASYNC;

                let current = file.flags().bits();
                let new_flags = (current & !SETFL_FLAGS) | (arg as u32 & SETFL_FLAGS);

                file.set_flags(super::types::FileFlags::new(new_flags));
                // O_ASYNC bit changed: refresh the pipe fasync registration
                // (registering enables SIGIO delivery, clearing disables).
                self::oasync_register(&file, fd as i32);

                Ok(0)  // Return 0 on success
            }

            // ==================== POSIX record locks (P0-5) ====================
            //
            // struct flock (LP64): { i16 l_type; i16 l_whence; off_t
            // l_start; off_t l_len; pid_t l_pid; } = 32 bytes.
            fcntl::F_GETLK | fcntl::F_GETLK64 | fcntl::F_OFD_GETLK => {
                let file = match get_file_fd(fd) {
                    Some(f) => f,
                    None => return Err(errno::Errno::BadFileNumber.as_neg_i32()),
                };
                if arg == 0 || !crate::arch::uaccess::access_ok(arg, 32) {
                    return Err(errno::Errno::BadAddress.as_neg_i32());
                }
                let mut fl = [0u8; 32];
                if crate::arch::uaccess_safe::copy_in_t(&mut fl, arg) > 0
                {
                    return Err(errno::Errno::BadAddress.as_neg_i32());
                }
                let l_type = i16::from_le_bytes([fl[0], fl[1]]);
                let l_whence = i16::from_le_bytes([fl[2], fl[3]]);
                let l_start = i64::from_le_bytes(fl[8..16].try_into().unwrap());
                let l_len = i64::from_le_bytes(fl[16..24].try_into().unwrap());

                let exclusive = match l_type {
                    flock_types::F_RDLCK => false,
                    flock_types::F_WRLCK => true,
                    _ => return Err(errno::Errno::InvalidArgument.as_neg_i32()),
                };
                // Access-mode check mirrors F_SETLK's (Linux may_setlk).
                if exclusive && file.flags().is_readonly()
                    || !exclusive && file.flags().is_writeonly()
                {
                    return Err(errno::Errno::BadFileNumber.as_neg_i32());
                }

                let (start, end) = resolve_lock_region(&file, l_whence, l_start, l_len)?;
                // OFD variant: the requester's owner token is the open
                // file description, not the process.
                let owner = if cmd == fcntl::F_OFD_GETLK {
                    super::types::LockOwner::Ofd(file.file_id)
                } else {
                    let owner_pid = crate::sched::current()
                        .map(|t| t.tgid())
                        .unwrap_or(0);
                    super::types::LockOwner::Pid(owner_pid)
                };

                let out = {
                    let mut out = fl;
                    match self::posix_test_lock(
                        &file, owner, exclusive, start, end,
                    ) {
                        // First conflicting lock: report it with ABSOLUTE
                        // start (l_whence = SEEK_SET) and l_len = 0 for a
                        // to-EOF tail (POSIX).
                        Some(c) => {
                            let ltype = if c.exclusive {
                                flock_types::F_WRLCK
                            } else {
                                flock_types::F_RDLCK
                            };
                            let len: i64 = if c.end == u64::MAX {
                                0
                            } else {
                                (c.end - c.start) as i64
                            };
                            out[0..2].copy_from_slice(&ltype.to_le_bytes());
                            out[2..4].copy_from_slice(&0i16.to_le_bytes()); // SEEK_SET
                            out[8..16].copy_from_slice(&(c.start as i64).to_le_bytes());
                            out[16..24].copy_from_slice(&len.to_le_bytes());
                            out[24..28].copy_from_slice(&(c.pid as i32).to_le_bytes());
                        }
                        // No conflict: set l_type = F_UNLCK and leave every
                        // other field UNTOUCHED (POSIX; Linux leaves l_pid
                        // at the caller's value — LTP fcntl05 pre-fills
                        // l_pid and expects it preserved).
                        None => {
                            out[0..2].copy_from_slice(&flock_types::F_UNLCK.to_le_bytes());
                        }
                    }
                    out
                };
                if crate::arch::uaccess_safe::copy_out(arg, &out[..32]) > 0
                {
                    return Err(errno::Errno::BadAddress.as_neg_i32());
                }
                Ok(0)
            }

            fcntl::F_SETLK | fcntl::F_SETLK64 | fcntl::F_SETLKW | fcntl::F_SETLKW64
            | fcntl::F_OFD_SETLK | fcntl::F_OFD_SETLKW => {
                let wait = cmd == fcntl::F_SETLKW
                    || cmd == fcntl::F_SETLKW64
                    || cmd == fcntl::F_OFD_SETLKW;
                let file = match get_file_fd(fd) {
                    Some(f) => f,
                    None => return Err(errno::Errno::BadFileNumber.as_neg_i32()),
                };
                if arg == 0 || !crate::arch::uaccess::access_ok(arg, 32) {
                    return Err(errno::Errno::BadAddress.as_neg_i32());
                }
                let mut fl = [0u8; 32];
                if crate::arch::uaccess_safe::copy_in_t(&mut fl, arg) > 0
                {
                    return Err(errno::Errno::BadAddress.as_neg_i32());
                }
                let l_type = i16::from_le_bytes([fl[0], fl[1]]);
                let l_whence = i16::from_le_bytes([fl[2], fl[3]]);
                let l_start = i64::from_le_bytes(fl[8..16].try_into().unwrap());
                let l_len = i64::from_le_bytes(fl[16..24].try_into().unwrap());

                let kind = match l_type {
                    flock_types::F_RDLCK => {
                        // Read lock needs a readable fd.
                        if file.flags().is_writeonly() {
                            return Err(errno::Errno::BadFileNumber.as_neg_i32());
                        }
                        self::F_RDLCK_KIND
                    }
                    flock_types::F_WRLCK => {
                        // Write lock needs a writeable fd.
                        if file.flags().is_readonly() {
                            return Err(errno::Errno::BadFileNumber.as_neg_i32());
                        }
                        self::F_WRLCK_KIND
                    }
                    flock_types::F_UNLCK => self::F_UNLCK_KIND,
                    _ => return Err(errno::Errno::InvalidArgument.as_neg_i32()),
                };

                let (start, end) = resolve_lock_region(&file, l_whence, l_start, l_len)?;
                // Owner token: the process for classic POSIX locks, the
                // open file description for F_OFD_SETLK/W (Linux 3.15+).
                let owner = if cmd == fcntl::F_OFD_SETLK || cmd == fcntl::F_OFD_SETLKW {
                    super::types::LockOwner::Ofd(file.file_id)
                } else {
                    let owner_pid = crate::sched::current()
                        .map(|t| t.tgid())
                        .unwrap_or(0);
                    super::types::LockOwner::Pid(owner_pid)
                };

                self::posix_set_lock(&file, owner, kind, start, end, wait)
                    .map(|_| 0)
                    .map_err(|e| e.as_neg_i32())
            }

            // F_SETOWN (8): set the O_ASYNC signal recipient. arg > 0 is a
            // process id, arg < 0 a process group (-pgid), 0 clears.
            fcntl::F_SETOWN => {
                let file = match get_file_fd(fd) {
                    Some(f) => f,
                    None => return Err(errno::Errno::BadFileNumber.as_neg_i32()),
                };
                let argi = arg as i32;
                if argi != 0 {
                    let (kind, id) = if argi < 0 {
                        (2u8, -argi)
                    } else {
                        (1u8, argi)
                    };
                    // The pid/pgid argument is written in the CALLER's pid
                    // namespace (a container task passes its ns-local pid);
                    // resolve to the global id the O_ASYNC machinery signals
                    // (reference f_setown stores a struct pid resolved in
                    // the caller's ns — LTP pidns13 F_SETOWN(getpid()==1)).
                    let caller_ns = crate::sched::current()
                        .and_then(|t| t.ns_pid.clone());
                    let resolved = if kind == 1 {
                        crate::process::ns::resolve_local_pid_to_global(
                            id as u32,
                            caller_ns.as_ref(),
                        )
                        .map(|g| g as i32)
                    } else {
                        // Process group: the number is the group LEADER's
                        // pid in the caller's ns (pgid convention).
                        // Resolve the leader, store its global pgid.
                        if caller_ns.is_none() {
                            Some(id)
                        } else {
                            crate::process::ns::resolve_local_pid_to_global(
                                id as u32,
                                caller_ns.as_ref(),
                            )
                            .and_then(|leader| {
                                crate::process::find_task_by_pid(leader)
                                    .map(|t| t.pgid() as i32)
                            })
                        }
                    };
                    // Validate the target exists (Linux: ESRCH).
                    let exists = match resolved {
                        Some(gid) if kind == 1 => {
                            crate::process::find_task_by_pid(gid as u32).is_some()
                        }
                        Some(gid) => {
                            let pgid = gid as u32;
                            let found = core::cell::Cell::new(false);
                            crate::process::pid_hash::pid_hash_for_each_task(|task| {
                                if task.pgid() == pgid {
                                    found.set(true);
                                }
                            });
                            found.get()
                        }
                        None => false,
                    };
                    if !exists {
                        return Err(errno::Errno::NoSuchProcess.as_neg_i32());
                    }
                    *file.f_owner.lock() = super::types::FileOwner {
                        kind,
                        id: resolved.unwrap_or(id),
                    };
                } else {
                    *file.f_owner.lock() = super::types::FileOwner::none();
                }
                self::oasync_register(&file, fd as i32);
                Ok(0)
            }

            // F_GETOWN (9): positive pid / negative pgid / 0 (none). The
            // number is reported in the READER's pid namespace.
            fcntl::F_GETOWN => {
                let file = match get_file_fd(fd) {
                    Some(f) => f,
                    None => return Err(errno::Errno::BadFileNumber.as_neg_i32()),
                };
                let o = *file.f_owner.lock();
                let shown = if o.kind == 2 {
                    -(o.id)
                } else if o.id > 0 {
                    crate::sched::current()
                        .and_then(|t| t.ns_pid.clone())
                        .map(|ns| {
                            crate::process::ns::translate_sender_pid_ns(
                                o.id as u32,
                                Some(&ns),
                            ) as i32
                        })
                        .unwrap_or(o.id)
                } else {
                    o.id
                };
                Ok(shown as usize)
            }

            // F_SETSIG (10): O_ASYNC signal number (0 = default SIGIO).
            fcntl::F_SETSIG => {
                let file = match get_file_fd(fd) {
                    Some(f) => f,
                    None => return Err(errno::Errno::BadFileNumber.as_neg_i32()),
                };
                let sig = arg as i32;
                if sig != 0 && !(1..=64).contains(&sig) {
                    return Err(errno::Errno::InvalidArgument.as_neg_i32());
                }
                file.f_signum.store(sig, core::sync::atomic::Ordering::Relaxed);
                self::oasync_register(&file, fd as i32);
                Ok(0)
            }

            // F_GETSIG (11): the O_ASYNC signal number (0 = SIGIO default).
            fcntl::F_GETSIG => {
                let file = match get_file_fd(fd) {
                    Some(f) => f,
                    None => return Err(errno::Errno::BadFileNumber.as_neg_i32()),
                };
                Ok(file.f_signum.load(core::sync::atomic::Ordering::Relaxed) as usize)
            }

            // F_SETOWN_EX (15): struct f_owner_ex { i32 type; i32 pid; }.
            // type: 0 = F_OWNER_TID, 1 = F_OWNER_PID, 2 = F_OWNER_PGRP.
            fcntl::F_SETOWN_EX => {
                let file = match get_file_fd(fd) {
                    Some(f) => f,
                    None => return Err(errno::Errno::BadFileNumber.as_neg_i32()),
                };
                if arg == 0
                    || !crate::arch::uaccess::access_ok(arg, 8)
                {
                    return Err(errno::Errno::BadAddress.as_neg_i32());
                }
                let mut buf = [0u8; 8];
                if crate::arch::uaccess_safe::copy_in_t(&mut buf, arg) > 0
                {
                    return Err(errno::Errno::BadAddress.as_neg_i32());
                }
                let otype = i32::from_le_bytes(buf[0..4].try_into().unwrap());
                let opid = i32::from_le_bytes(buf[4..8].try_into().unwrap());
                // Map f_owner_ex type to our kind: TID→3, PID→1, PGRP→2.
                let kind = match otype {
                    0 => 3u8,
                    1 => 1u8,
                    2 => 2u8,
                    _ => return Err(errno::Errno::InvalidArgument.as_neg_i32()),
                };
                if opid <= 0 {
                    return Err(errno::Errno::InvalidArgument.as_neg_i32());
                }
                // The pid argument is caller-ns-relative; resolve to the
                // global id (same as F_SETOWN above).
                let caller_ns =
                    crate::sched::current().and_then(|t| t.ns_pid.clone());
                let resolved = if caller_ns.is_none() {
                    Some(opid)
                } else if kind == 2 {
                    crate::process::ns::resolve_local_pid_to_global(
                        opid as u32,
                        caller_ns.as_ref(),
                    )
                    .and_then(|leader| {
                        crate::process::find_task_by_pid(leader)
                            .map(|t| t.pgid() as i32)
                    })
                } else {
                    crate::process::ns::resolve_local_pid_to_global(
                        opid as u32,
                        caller_ns.as_ref(),
                    )
                    .map(|g| g as i32)
                };
                // Validate the target exists (Linux: ESRCH).
                let exists = match resolved {
                    Some(gid) if kind == 2 => {
                        let found = core::cell::Cell::new(false);
                        crate::process::pid_hash::pid_hash_for_each_task(|task| {
                            if task.pgid() == gid as u32 {
                                found.set(true);
                            }
                        });
                        found.get()
                    }
                    Some(gid) => {
                        crate::process::find_task_by_pid(gid as u32).is_some()
                    }
                    None => false,
                };
                if !exists {
                    return Err(errno::Errno::NoSuchProcess.as_neg_i32());
                }
                *file.f_owner.lock() = super::types::FileOwner {
                    kind,
                    id: resolved.unwrap_or(opid),
                };
                self::oasync_register(&file, fd as i32);
                Ok(0)
            }

            // F_GETOWN_EX (16): report the current owner.
            fcntl::F_GETOWN_EX => {
                let file = match get_file_fd(fd) {
                    Some(f) => f,
                    None => return Err(errno::Errno::BadFileNumber.as_neg_i32()),
                };
                if arg == 0
                    || !crate::arch::uaccess::access_ok(arg, 8)
                {
                    return Err(errno::Errno::BadAddress.as_neg_i32());
                }
                let o = *file.f_owner.lock();
                let otype = match o.kind {
                    3 => 0i32, // F_OWNER_TID
                    1 => 1i32, // F_OWNER_PID
                    2 => 2i32, // F_OWNER_PGRP
                    _ => 1i32, // no owner set: report own pid, F_OWNER_PID
                };
                let opid = if o.kind == 0 {
                    crate::sched::current().map(|t| t.tgid()).unwrap_or(0) as i32
                } else {
                    o.id
                };
                let mut buf = [0u8; 8];
                buf[0..4].copy_from_slice(&otype.to_le_bytes());
                buf[4..8].copy_from_slice(&opid.to_le_bytes());
                if crate::arch::uaccess_safe::copy_out(arg, &buf[..8]) > 0
                {
                    return Err(errno::Errno::BadAddress.as_neg_i32());
                }
                Ok(0)
            }

            // F_SETLEASE (1024): establish/remove a file lease.
            fcntl::F_SETLEASE => {
                let file = match get_file_fd(fd) {
                    Some(f) => f,
                    None => return Err(errno::Errno::BadFileNumber.as_neg_i32()),
                };
                self::set_lease(&file, arg as i16)
                    .map(|_| 0)
                    .map_err(|e| e.as_neg_i32())
            }

            // F_GETLEASE (1025): the lease held by this description.
            fcntl::F_GETLEASE => {
                let file = match get_file_fd(fd) {
                    Some(f) => f,
                    None => return Err(errno::Errno::BadFileNumber.as_neg_i32()),
                };
                Ok(self::get_lease(&file) as usize)
            }

            // F_GETPIPE_SZ (1032) / F_SETPIPE_SZ (1031): pipe-only (Linux
            // returns EINVAL for any other fd).
            fcntl::F_SETPIPE_SZ => {
                let file = match get_file_fd(fd) {
                    Some(f) => f,
                    None => return Err(errno::Errno::BadFileNumber.as_neg_i32()),
                };
                self::pipe_set_sz(&file, arg)
            }
            fcntl::F_GETPIPE_SZ => {
                let file = match get_file_fd(fd) {
                    Some(f) => f,
                    None => return Err(errno::Errno::BadFileNumber.as_neg_i32()),
                };
                match self::pipe_get_sz(&file) {
                    Some(sz) => Ok(sz),
                    None => Err(errno::Errno::InvalidArgument.as_neg_i32()),
                }
            }

            // F_ADD_SEALS (1033) / F_GET_SEALS (1034): memfd seals
            // (memfd_create(2)). Only memfd files support seals; anything
            // else answers EINVAL (Linux memfd_add_seals/get_seals on a
            // non-shmem file).
            fcntl::F_ADD_SEALS => {
                let file = match get_file_fd(fd) {
                    Some(f) => f,
                    None => return Err(errno::Errno::BadFileNumber.as_neg_i32()),
                };
                match self::memfd_add_seals(&file, arg as u32) {
                    Ok(()) => Ok(0),
                    Err(e) => Err(e),
                }
            }
            fcntl::F_GET_SEALS => {
                let file = match get_file_fd(fd) {
                    Some(f) => f,
                    None => return Err(errno::Errno::BadFileNumber.as_neg_i32()),
                };
                match self::memfd_get_seals(&file) {
                    Ok(seals) => Ok(seals as usize),
                    Err(e) => Err(e),
                }
            }

            // Unsupported command: Linux do_fcntl's default is EINVAL
            // (LTP fcntl13/18 pass a bogus cmd and expect EINVAL; the
            // old ENOSYS failed both).
            _ => {
                Err(errno::Errno::InvalidArgument.as_neg_i32())
            }
        }
    }
}

///
///
/// # Arguments
/// - pathname: directory path
/// - mode: directory permissions
///
/// # Returns
/// Returns Ok(()) on success, error code on failure
///
/// - RISC-V: 77 (mkdirat), but we implement simplified mkdir
pub fn file_mkdir(pathname: &str, mode: u32) -> Result<(), i32> {
    vfs_mkdir(pathname, mode)
}

///
///
/// # Arguments
/// - pathname: directory path
///
/// # Returns
/// Returns Ok(()) on success, error code on failure
///
/// - RISC-V: 79
pub fn file_rmdir(pathname: &str) -> Result<(), i32> {
    vfs_rmdir(pathname)
}

///
///
/// # Arguments
/// - pathname: file path
///
/// # Returns
/// Returns Ok(()) on success, error code on failure
///
/// - RISC-V: 74 (unlinkat), but we implement simplified unlink
