pub fn path_normalize(path: &str) -> alloc::string::String {
    use alloc::vec::Vec;
    use alloc::string::String;

    if path.is_empty() {
        return String::new();
    }

    // Check if absolute path
    let is_absolute = path.starts_with('/');

    // Split path into components
    let components: Vec<&str> = path.split('/')
        .filter(|s| !s.is_empty() && *s != ".")
        .collect();

    // Handle .. and regular components
    let mut result: Vec<&str> = Vec::new();

    for component in components {
        if component == ".." {
            // Handle parent directory reference
            if is_absolute {
                // Absolute path: if at root, ignore ..
                if !result.is_empty() {
                    result.pop();
                }
            } else {
                // Relative path: handle .. normally
                if result.last() == Some(&"..") {
                    // If last one is also .., keep it
                    result.push("..");
                } else if !result.is_empty() {
                    result.pop();
                } else {
                    // Already at top level, add ..
                    result.push("..");
                }
            }
        } else {
            // Regular component
            result.push(component);
        }
    }

    // Rebuild path
    let mut normalized = if is_absolute {
        String::from("/")
    } else {
        String::new()
    };

    for (i, component) in result.iter().enumerate() {
        if i > 0 || !is_absolute {
            if i > 0 {
                normalized.push('/');
            }
            normalized.push_str(component);
        } else if is_absolute && !component.is_empty() {
            normalized.push_str(component);
        }
    }

    // Ensure root returns /
    if normalized.is_empty() && is_absolute {
        normalized.push('/');
    }

    normalized
}


// ════════════════ permission ══════════════════════════
// (was permission.rs)
// File permission checking.
//
// Implements the standard Unix DAC (Discretionary Access Control) check:
// 1. Root (euid==0) bypasses most checks
// 2. If euid matches file uid, use owner permission bits
// 3. If egid matches file gid, use group permission bits
// 4. Otherwise, use other permission bits

/// Permission mask bits
pub const MAY_EXEC: u32 = 0o001;
pub const MAY_WRITE: u32 = 0o002;
pub const MAY_READ: u32 = 0o004;

/// Check generic file permission.
///
/// Returns `true` if access is allowed, `false` if denied.
pub fn generic_permission(
    inode_mode: u16,
    inode_uid: u32,
    inode_gid: u32,
    mask: u32,
    cred: &crate::process::task::Cred,
) -> bool {
    // (perf-gap-hunt) Capability-only fast path: the capability LSM is
    // always registered (order 0) and is the ONLY module on the
    // boot-default chain; its Capable verdict is exactly the
    // effective-set bit test. When it is the sole registered LSM, both
    // capability checks below resolve to inline bit tests — no HookArgs
    // build + dyn dispatch per check. Multi-LSM and pre-init (empty
    // chain) configurations take the original has_capability calls,
    // byte-for-byte the old semantics. The fast path lives HERE (one
    // body) rather than in has_capability (~100 call sites): the .text
    // growth of inlining it there shifted the syscall dispatch
    // neighborhood and cost the null row 3ns (measured, bisected).
    let mode = inode_mode as u32;
    let cap_only = crate::security::lsm::chain_is_capability_only();

    // CAP_DAC_OVERRIDE: root bypasses DAC. Linux grants read/write/search
    // on DIRECTORIES unconditionally; on files, execute still needs at
    // least one x bit (LTP access01 creates files inside 0222 dirs as
    // root — search must be overridden).
    let dac_override = if cap_only {
        cred.cap_effective.has(crate::security::CAP_DAC_OVERRIDE)
    } else {
        crate::security::has_capability(cred, crate::security::CAP_DAC_OVERRIDE)
    };
    if dac_override {
        let is_dir = mode & 0o170000 == 0o040000; // S_IFMT == S_IFDIR
        if mask & MAY_EXEC != 0 && !is_dir {
            // DAC_OVERRIDE: can exec only if at least one x bit is set
            if (mode & 0o111) == 0 {
                return false;
            }
        }
        return true;
    }

    // CAP_DAC_READ_SEARCH (L3 wiring, sec-r1): on DIRECTORIES it overrides
    // read/search when the mask carries no write bit — the reference
    // generic_permission grants CAP_DAC_READ_SEARCH only for
    // `!(mask & MAY_WRITE)` and only for S_ISDIR; plain files never pass
    // through this cap here (a file read needs CAP_DAC_OVERRIDE; the
    // cap's other file use, linkat AT_EMPTY_PATH, is not implemented).
    if mask & MAY_WRITE == 0 && mode & 0o170000 == 0o040000 {
        // S_IFDIR
        let read_search = if cap_only {
            cred.cap_effective.has(crate::security::CAP_DAC_READ_SEARCH)
        } else {
            crate::security::has_capability(cred, crate::security::CAP_DAC_READ_SEARCH)
        };
        if read_search {
            return true;
        }
    }


    // Linux's generic_permission compares against the FILESYSTEM ids
    // (current_fsuid/current_fsgid), not euid/egid — setfsuid/setfsgid
    // change exactly these (LTP setfsuid04: fsuid to nobody then open a
    // 0644 root file O_RDWR must EACCES).
    if cred.fsuid == inode_uid {
        // Owner permission bits (bits 8-6)
        ((mode >> 6) & 0o7) & mask == mask
    } else if cred.fsgid == inode_gid || cred.groups.iter().any(|&g| g == inode_gid) {
        // Group permission bits (bits 5-3) — checks egid + supplementary groups
        ((mode >> 3) & 0o7) & mask == mask
    } else {
        // Other permission bits (bits 2-0)
        (mode & 0o7) & mask == mask
    }
}

/// Check `mask` (MAY_READ/WRITE/EXEC) against `inode` using the current
/// task's credentials.
///
/// Returns `true` when there is no current task (early boot / kernel-thread
/// context) so internal lookups keep working.
pub fn inode_permission(inode: &super::types::Inode, mask: u32) -> bool {
    match crate::sched::current() {
        Some(task) => {
            // SAFETY: `task` is the current task pointer from sched::current();
            // its cred is immutable for the duration of this check.
            let cred = unsafe { (*task).cred() };
            generic_permission(
                inode.mode.bits() as u16,
                inode.uid.load(core::sync::atomic::Ordering::Relaxed),
                inode.gid.load(core::sync::atomic::Ordering::Relaxed),
                mask,
                cred,
            )
        }
        None => true,
    }
}


// ════════════════ superblock ══════════════════════════
// (was superblock.rs)
// Superblock and Filesystem Type Management
//
//
// Core concepts:
// - `struct super_block`: Superblock, represents a mounted filesystem
// - `struct file_system_type`: Filesystem type, used for registration and mounting
// - `struct vfsmount`: Mount point, represents filesystem position in namespace

// (INV-SBTYPE-1: the FileSystemType table ABI — mount/kill_sb are
// raw-pointer extern "C" slots by the table's type; every fs-type
// registration rides this one audited ABI edge.)

impl SuperBlockFlags {
    /// Read-only mount
    pub const SB_RDONLY: u64 = 1;
    /// Don't update atime
    pub const SB_NOATIME: u64 = 1 << 5;
    /// Don't update atime/mtime/ctime
    pub const SB_NODIRATIME: u64 = 1 << 6;
    /// Force synchronous writes
    pub const SB_SYNCHRONOUS: u64 = 1 << 7;
    /// Disallow mandatory locking
    pub const SB_MANDLOCK: u64 = 1 << 8;
    /// Don't write to device
    pub const SB_DIRSYNC: u64 = 1 << 9;
    /// Don't update atime
    pub const SB_NOSEC: u64 = 1 << 10;
    /// Active mount
    pub const SB_ACTIVE: u64 = 1 << 11;
    /// Currently writing
    pub const SB_WRITERS: u64 = 1 << 12;

    pub fn new(flags: u64) -> Self {
        Self(flags)
    }

    pub fn is_readonly(&self) -> bool {
        (self.0 & Self::SB_RDONLY) != 0
    }

    pub fn is_active(&self) -> bool {
        (self.0 & Self::SB_ACTIVE) != 0
    }

    pub fn bits(&self) -> u64 {
        self.0
    }
}

unsafe impl Send for SuperBlock {}
unsafe impl Sync for SuperBlock {}

impl SuperBlock {
    /// Create new superblock
    pub fn new(blocksize: usize, magic: u32) -> Self {
        // Calculate block size bits
        let mut bits = 0u8;
        let mut size = blocksize;
        while size > 1 {
            size >>= 1;
            bits += 1;
        }

        Self {
            s_flags: SuperBlockFlags::new(SuperBlockFlags::SB_RDONLY),
            s_blocksize: blocksize,
            s_blocksize_bits: bits,
            s_magic: magic,
            s_max_links: 0,
            s_root: None,
            s_type: None,
            s_options: None,
            s_fs_info: None,
        }
    }

    /// Set filesystem type
    pub fn set_type(&mut self, fs_type: &'static FileSystemType) {
        self.s_type = Some(fs_type);
    }

    /// Set private data
    pub fn set_fs_info(&mut self, info: *mut u8) {
        self.s_fs_info = Some(info);
    }

    /// Set flags
    pub fn set_flags(&mut self, flags: SuperBlockFlags) {
        self.s_flags = flags;
    }
}

impl<'a> FsContext<'a> {
    /// Create new mount context
    pub fn new(
        source: Option<&'a str>,
        target: Option<&'a str>,
        ms_flags: u64,
    ) -> Self {
        Self {
            source,
            target,
            ms_flags,
            data: None,
        }
    }
}

impl FileSystemType {
    /// Create new filesystem type
    pub const fn new(
        name: &'static str,
        mount: Option<fn(&FsContext<'_>) -> Result<*mut SuperBlock, i32>>,
        kill_sb: Option<fn(*mut SuperBlock)>,
        fs_flags: u64,
    ) -> Self {
        Self {
            name,
            mount,
            kill_sb,
            fs_flags,
        }
    }

    /// Mount filesystem
    ///
    pub fn mount_fs(
        &self,
        source: Option<&str>,
        target: Option<&str>,
        flags: u64,
    ) -> Result<*mut SuperBlock, i32> {
        // Create mount context
        let fc = FsContext::new(source, target, flags);

        // Call filesystem-specific mount function (registration edge)
        if let Some(mount_fn) = self.mount {
            mount_fn(&fc)
        } else {
            Err(errno::Errno::FunctionNotImplemented.as_neg_i32())
        }
    }

    /// Unmount filesystem
    pub fn kill_super(&self, sb: *mut SuperBlock) {
        if let Some(kill_fn) = self.kill_sb {
            kill_fn(sb);
        }
    }
}

unsafe impl Send for FsRegistry {}
unsafe impl Sync for FsRegistry {}

impl FsRegistry {
    pub const fn new() -> Self {
        Self {
            fs_types: Spinlock::new([None; 32]),
        }
    }

    /// Register filesystem type
    ///
    pub fn register(&self, fs_type: &'static FileSystemType) -> Result<(), i32> {
        let mut registry = self.fs_types.lock();

        // Find free slot
        for i in 0..32 {
            if registry[i].is_none() {
                registry[i] = Some(fs_type);
                return Ok(());
            }
        }

        Err(errno::Errno::NoSpaceLeftOnDevice.as_neg_i32())
    }

    /// Unregister filesystem type
    ///
    pub fn unregister(&self, fs_type: &'static FileSystemType) -> Result<(), i32> {
        let mut registry = self.fs_types.lock();

        // Find and remove filesystem type
        for i in 0..32 {
            if let Some(ft) = registry[i] {
                if core::ptr::eq(ft, fs_type) {
                    registry[i] = None;
                    return Ok(());
                }
            }
        }

        Err(errno::Errno::NoSuchFileOrDirectory.as_neg_i32())
    }

    /// Find filesystem type
    ///
    pub fn get(&self, name: &str) -> Option<&'static FileSystemType> {
        let registry = self.fs_types.lock();

        for i in 0..32 {
            if let Some(fs_type) = registry[i] {
                if fs_type.name == name {
                    return Some(fs_type);
                }
            }
        }

        None
    }
}

static FS_REGISTRY: FsRegistry = FsRegistry::new();

pub fn register_filesystem(fs_type: &'static FileSystemType) -> Result<(), i32> {
    FS_REGISTRY.register(fs_type)
}

pub fn unregister_filesystem(fs_type: &'static FileSystemType) -> Result<(), i32> {
    FS_REGISTRY.unregister(fs_type)
}

pub fn get_fs_type(name: &str) -> Option<&'static FileSystemType> {
    FS_REGISTRY.get(name)
}

pub fn superblock_do_mount(
    dev_name: Option<&str>,
    dir_name: Option<&str>,
    type_name: &str,
    flags: u64,
    _data: Option<&str>,
) -> Result<(), i32> {
    // Review 5.1 (低: do_mount 忽略 flags/source、三套 mount 并存): the
    // unified mount path lives in fs::mount (the registry-based path here
    // built a SuperBlock but never linked a mount into the namespace).
    // Keep the registry lookup for type validation, then delegate the
    // actual mount to the one implementation.
    let fs_type = get_fs_type(type_name).ok_or(-2_i32)?;  // ENOENT
    let _ = fs_type; // existence check only — mount::do_mount dispatches by name
    let _ = dev_name;
    let target = dir_name.ok_or(-22_i32)?; // EINVAL

    self::do_mount("none", target, type_name, flags, None)
}

pub fn do_umount(target: &str, _flags: u64) -> Result<(), i32> {

    // Currently only support unmounting ext4 (mounted at root "/")
    let is_root = target == "/" || target.is_empty();

    if is_root && crate::api::ext4::mounted() {
        crate::api::ext4::unmount();
        crate::println!("vfs: unmounted ext4 filesystem from {}", target);
        return Ok(());
    }

    Err(errno::Errno::FunctionNotImplemented.as_neg_i32())
}


// ════════════════ mount ═══════════════════════════════
// (was mount.rs)
// Mount point and namespace management
//
//
// Core concepts:
// - `VfsMount`: Per-mount metadata (used by procfs/rootfs for local state)
// - `MntFlags`: Mount flags (read-only, noexec, etc.)
// - `do_mount()`: Unified mount entry point for sys_mount

/// Global mount registry: (device, mount_point, fs_type, flags_str).
/// U1c: still maintained (boot-time bookkeeping and init-ns seeding) but
/// the AUTHORITATIVE per-namespace view lives in the mount namespace
/// (process::ns::MountNamespace); get_mounts() reads that.
static MOUNT_TABLE: Spinlock<Vec<(String, String, String, String)>> = Spinlock::new(Vec::new());

/// Register a mount in the current mount namespace AND the global registry.
/// U1c: callers in a private (CLONE_NEWNS) namespace only mutate their own
/// table; the global registry stays the init-namespace baseline.
/// sc98: that contract is now ENFORCED — private-namespace mounts (OH
/// appspawn children's ~50 sandbox binds per spawn) used to push a row
/// into the global table too, where the O(rows) retain() per register
/// made every later mount slower while the launcher restart loop pumped
/// thousands of dead rows in.
/// sc115/sc116: the irqsave discipline is dropped for a plain preempt-off
/// lock. Every user is syscall context (mount/umount/procfs reads) — no
/// IRQ-context consumer exists — but the guarded section runs an O(rows)
/// STRING retain (per-byte compare loop) plus four heap allocations, and
/// under allocator contention that section was measured as a >=1 s cli
/// window (WW IRQ-OFF-WINDOW samples landing in atomic_load<u8> string
/// compares; one boot printed 637 >=100 ms inter-tick gaps). The ns.rs
/// namespace tables already use plain .lock(); MOUNT_TABLE now matches.
pub fn register_mount(device: &str, mount_point: &str, fs_type: &str, flags: &str) {
    if crate::process::ns::in_init_mnt_ns() {
        let mut table = MOUNT_TABLE.lock();
        table.retain(|(_, mp, _, _)| mp != mount_point);
        table.push((
            String::from(device),
            String::from(mount_point),
            String::from(fs_type),
            String::from(flags),
        ));
    }
    crate::process::ns::ns_register_mount(device, mount_point, fs_type, flags);
}

/// Is `target` already registered as a mount of filesystem type
/// `fs_type`? (launcher-errno lane: the single-instance filesystems the
/// kernel automounts — debugfs at /sys/kernel/debug — answer EBUSY to a
/// second mount(2) at the same point on the OH reference; a stacked
/// second mount would shadow the kernel's own submounts, e.g. the
/// tracefs instance at /sys/kernel/debug/tracing.)
pub fn mounted_as(fs_type: &str, target: &str) -> bool {
    let table = MOUNT_TABLE.lock();
    table
        .iter()
        .any(|(_, mp, f, _)| f == fs_type && mp == target)
}

/// Raw global registry snapshot + the hardcoded rootfs row (init-namespace
/// seed for process::ns::init_mnt_ns).
pub fn get_global_mounts() -> Vec<(String, String, String, String)> {
    let mut result = Vec::new();
    // Always include rootfs (registered before allocator is fully stable)
    result.push((String::from("rootfs"), String::from("/"), String::from("rootfs"), String::from("rw")));
    // Add dynamically registered mounts
    let table = MOUNT_TABLE.lock();
    for (d, m, f, fl) in table.iter() {
        result.push((d.clone(), m.clone(), f.clone(), fl.clone()));
    }
    result
}

/// Get the mounts visible to the CALLER (U1c: the current mount namespace;
/// the init namespace table is seeded from the boot registry).
pub fn get_mounts() -> Vec<(String, String, String, String)> {
    crate::process::ns::ns_get_mounts()
        .into_iter()
        .map(|e| (e.device, e.mount_point, e.fs_type, e.flags))
        .collect()
}

/// Same view as get_mounts(), keeping the rows' PERMANENT mount ids —
/// /proc/self/mountinfo numbers rows by struct mount.mnt_id, never by
/// output position (registry churn re-pairing positional ids with
/// different mounts made systemd's monitor see phantom changes).
pub fn get_mount_entries() -> Vec<crate::process::ns::MountEntry> {
    crate::process::ns::ns_get_mounts()
}


impl MntFlags {
    pub const MNT_READONLY: u64 = 0x01;
    pub const MNT_NOATIME: u64 = 0x02;
    pub const MNT_NODIRATIME: u64 = 0x04;
    pub const MNT_SYNCHRONOUS: u64 = 0x08;
    pub const MNT_NOEXEC: u64 = 0x10;
    pub const MNT_NOSUID: u64 = 0x20;
    pub const MNT_NODEV: u64 = 0x40;
    pub const MNT_PRIVATE: u64 = 0x80;
    pub const MNT_SHARED: u64 = 0x100;
    pub const MNT_SLAVE: u64 = 0x200;
    pub const MNT_UNBINDABLE: u64 = 0x400;
    pub const MNT_FORCE: u64 = 0x800;
    /// SB_NOSYMFOLLOW (mount_setattr MOUNT_ATTR_NOSYMFOLLOW, 5.10+).
    pub const MNT_NOSYMFOLLOW: u64 = 0x1000;

    pub fn new(flags: u64) -> Self {
        Self(flags)
    }

    pub fn is_readonly(&self) -> bool {
        (self.0 & Self::MNT_READONLY) != 0
    }

    pub fn is_noexec(&self) -> bool {
        (self.0 & Self::MNT_NOEXEC) != 0
    }

    pub fn is_nosuid(&self) -> bool {
        (self.0 & Self::MNT_NOSUID) != 0
    }

    pub fn bits(&self) -> u64 {
        self.0
    }
}

unsafe impl Send for VfsMount {}
unsafe impl Sync for VfsMount {}

impl VfsMount {
    pub fn new(mountpoint: Vec<u8>, root: Vec<u8>, flags: MntFlags, sb: Option<*mut u8>) -> Self {
        Self {
            mnt_id: 0,
            mnt_flags: flags,
            mnt_mountpoint: Some(Arc::new(mountpoint)),
            mnt_root: Some(Arc::new(root)),
            mnt_sb: sb,
            mnt_count: core::sync::atomic::AtomicU64::new(1),
            mnt_expired: core::sync::atomic::AtomicU64::new(0),
        }
    }

    pub fn get_superblock(&self) -> Option<*mut u8> {
        self.mnt_sb
    }

    pub fn set_superblock(&mut self, sb: *mut u8) {
        self.mnt_sb = Some(sb);
    }
}

// ============================================================================
// Unified mount entry point
// ============================================================================

/// Linux MS_* mount flags (UAPI subset).
const MS_RDONLY: u64 = 1;
const MS_NOSUID: u64 = 2;
const MS_NODEV: u64 = 4;
const MS_NOEXEC: u64 = 8;
const MS_SYNCHRONOUS: u64 = 16;
const MS_NOATIME: u64 = 1024;

/// Translate Linux MS_* flags into the internal MntFlags (review 5.1:
/// MNT_* flags 存储 — do_mount used to drop the flags entirely).
fn translate_mnt_flags(ms_flags: u64) -> MntFlags {
    let mut bits = 0u64;
    if ms_flags & MS_RDONLY != 0 { bits |= MntFlags::MNT_READONLY; }
    if ms_flags & MS_NOSUID != 0 { bits |= MntFlags::MNT_NOSUID; }
    if ms_flags & MS_NODEV != 0 { bits |= MntFlags::MNT_NODEV; }
    if ms_flags & MS_NOEXEC != 0 { bits |= MntFlags::MNT_NOEXEC; }
    if ms_flags & MS_SYNCHRONOUS != 0 { bits |= MntFlags::MNT_SYNCHRONOUS; }
    if ms_flags & MS_NOATIME != 0 { bits |= MntFlags::MNT_NOATIME; }
    MntFlags::new(bits)
}

/// Public wrapper for sys_mount's MS_REMOUNT path (flags translation without
/// re-running the filesystem mount callback).
pub fn translate_mnt_flags_public(ms_flags: u64) -> MntFlags {
    translate_mnt_flags(ms_flags)
}

/// Perform a real mount: call the filesystem's mount callback, then build
/// the dentry tree via `vfs_mount()`.
///
/// `data` is the mount(2) options string (may be None). Only tmpfs
/// consumes it today (its `size=` page budget); other filesystems accept
/// and ignore it, like a filesystem with no .parse_monolithic hook.
///
/// This is the single entry point for both boot-time mounts and sys_mount().
pub fn do_mount(
    source: &str,
    target: &str,
    fs_type: &str,
    flags: u64,
    data: Option<&str>,
) -> Result<(), i32> {
    let mnt_flags = translate_mnt_flags(flags);

    // Rung-3 MOUNT SEAM: consult the registration table first; the
    // leaf's mount_instance holds the old arm's body verbatim. The
    // ext family joined at rung 5 (its row carries the loop-device
    // special case, the named-disk resolution and the legacy boot-disk
    // path — the old arms below, crate-side).
    if let Some(mount_fn) = self::lookup(fs_type) {
        return mount_fn(source, target, fs_type, data, mnt_flags);
    }

    match fs_type {
        // POSIX mqueue: no queue semantics in Rux yet (mq_* syscalls
        // answer ENOSYS on their own); an empty tmpfs instance satisfies
        // dev-mqueue.mount so sysinit does not fail. mqueue(7) users that
        // actually open a queue surface the syscall gap unchanged.
        // securityfs: same empty-instance treatment -- sysinit's
        // sys-kernel-security.mount must not fail local-fs.
        // pstore (why-slow lane): OH init.virt.cfg mounts pstore on
        // /sys/fs/pstore every boot; Linux's pstore fs is built-in, so
        // the reference's mount succeeds and ours answered EINVAL — an
        // ours-only error row in the boot error-stream diff. Mount the
        // EXISTING sysfs pstore subtree (pstore-lite already publishes
        // the previous boot's record there, named like the reference's
        // ramoops backends) so content survives the mount-over.
        _ => return Err(errno::Errno::InvalidArgument.as_neg_i32()),
    }

    Ok(())
}


// ════════════════ mount_table ═════════════════════════
// (was mount_table.rs)
// The rung-3 MOUNT SEAM (seed-core-design §4, crate-plan step 3).
//
// The VFS framework (mount.rs) must not reference filesystem leaves by
// name; each leaf's mount logic lives leaf-side as a `mount_instance`
// fn and registers its names here. `register_builtin_handlers()` runs
// once at boot (lib.rs, before any mount syscall) — it is the ONE
// framework-side place that names the leaves, i.e. the exact seam the
// fs crate flip later replaces with each leaf crate's
// self-registration. Behavior-identical to the old match arms.

const MAX_ENTRIES: usize = 32;

static TABLE: crate::sync::spinlock::Spinlock<[Option<Entry>; MAX_ENTRIES]> =
    crate::sync::spinlock::Spinlock::new([const { None }; MAX_ENTRIES]);

/// Register `f` for every `names` alias (idempotent: a name registered
/// twice keeps its first entry — boot inits can run repeatedly).
pub fn register(names: &'static [&'static str], f: MountFn) {
    let mut t = TABLE.lock();
    for slot in t.iter_mut() {
        if slot.is_none() {
            *slot = Some(Entry { names, f });
            return;
        }
        if slot.as_ref().unwrap().names == names {
            return; // idempotent re-registration
        }
    }
    crate::pr_err!("mount_table: full ({} entries)", MAX_ENTRIES);
}

/// The framework's single lookup: O(entries).
pub fn lookup(fs_type: &str) -> Option<MountFn> {
    let t = TABLE.lock();
    for e in t.iter().flatten() {
        if e.names.contains(&fs_type) {
            return Some(e.f);
        }
    }
    None
}

/// The boot-time registration call (the crate-flip seam point). Each
/// leaf's `mount_instance` is the verbatim old match-arm body. EVERY
/// leaf's rows come from the service crates (fs via
/// LeafBootHooks.mount_rows_register, ext4 via its own row) and run
/// at THIS point — never at rust_main time (the mount table/allocator
/// are not up yet there).
pub fn register_builtin_handlers() {
    // The substrate/boot leaves' mount rows (tmpfs, procfs, devfs, sysfs,
    // cgroup, debugfs, tracefs, selinuxfs — fs-substrate tranche): ONE
    // entry from the fs crate, run at THIS boot point.
    (crate::api::fs::boot_hooks().mount_rows_register)();
    // The ext4 service crate's mount rows (rung 5): the SAME boot
    // point as the leaves above — NOT at rust_main registration time
    // (the fs 'R'-loop conviction; the row body self-guards).
    crate::api::ext4::mount_rows_register();
}

