/// The RAM root as the framework sees it: the rootfs superblock's
/// path-shaped API as a framework-owned trait. The cpio unpacker stays
/// framework-side (initrd.rs) and the tests seed/verify through it; the
/// rootfs leaf (fs crate) implements it. Paths are plain strings —
/// no node handles cross the boundary.
pub trait RamfsView {
    fn rfs_mkdir(&self, path: &str) -> Result<(), i32>;
    /// A mount-point directory (with mode).
    fn rfs_create_dir(&self, path: &str, mode: u32) -> Result<(), i32>;
    fn rfs_symlink(&self, target: &str, path: &str) -> Result<(), i32>;
    fn rfs_link(&self, first: &str, path: &str) -> Result<(), i32>;
    fn rfs_create_file(&self, path: &str, data: Vec<u8>) -> Result<(), i32>;
    /// Replace-step for overwrite semantics: drop `base` under `parent`.
    fn rfs_remove_child(&self, parent: &str, base: &str);
    /// Apply permission bits + mtime to the node at `path`.
    fn rfs_set_node_meta(&self, path: &str, mode: u32, mtime: u64);
    /// Presence + kind probe (None = absent; Some(true) = directory).
    fn rfs_lookup_kind(&self, path: &str) -> Option<bool>;
    /// Seed a file (the tests' create_file path).
    fn rfs_seed_file(&self, path: &str, data: Vec<u8>) -> Result<(), i32>;
}

impl InputEventReg {
    /// The Linux `input_dev_uevent()` environment block for the input_dev
    /// kobject (PRODUCT/NAME/PROP/EV/KEY/REL/ABS in kernel emit order).
    pub fn dev_env(&self) -> Vec<(String, String)> {
        let mut env: Vec<(String, String)> = Vec::new();
        env.push((
            String::from("PRODUCT"),
            alloc::format!(
                "{:x}/{:x}/{:x}/{:x}",
                self.bustype,
                self.vendor,
                self.product,
                self.version
            ),
        ));
        // Linux quotes NAME in the uevent environment (NAME="%s").
        env.push((
            String::from("NAME"),
            alloc::format!("\"{}\"", self.dev_name),
        ));
        env.push((String::from("PROP"), String::from("0")));
        env.push((String::from("EV"), self.ev.clone()));
        if !self.key.is_empty() {
            env.push((String::from("KEY"), self.key.clone()));
        }
        if !self.rel.is_empty() {
            env.push((String::from("REL"), self.rel.clone()));
        }
        if !self.abs.is_empty() {
            env.push((String::from("ABS"), self.abs.clone()));
        }
        env
    }
}


// ════════════════ perf_ctr ════════════════════════════
// (was perf_ctr.rs)
// The KERNEL-WIDE ACCOUNTING CELLS (the fs-substrate split, 2026-11-23):
// the counters /proc/{stat,interrupts,loadavg,schedstat,uptime} REPORT
// moved here from the procfs leaf, framework-side — the mutation paths
// (arch trap tick charging, scheduler context-switch/fork notes, the
// loadavg sampler, idle accounting) stay DIRECT framework calls with
// zero indirection (the S1 devirtualization rule: no fn-pointer rows on
// the trap/sched hot paths). The procfs leaf (fs crate) formats
// these cells in its generate() paths. Linux alignment: the reference
// keeps these in kernel/sched + per-cpu irq counters, not in procfs.
//
// Everything here is atomics — no locks, IRQ-context safe.

// ============================================================================
// /proc/interrupts cells
// ============================================================================

const MAX_CPUS: usize = crate::config::MAX_CPUS;

/// Per-CPU timer interrupt counters.
pub static TIMER_COUNT: [AtomicU64; MAX_CPUS] = [const { AtomicU64::new(0) }; MAX_CPUS];

/// Per-CPU software-interrupt (IPI) counters.
pub static SOFT_COUNT: [AtomicU64; MAX_CPUS] = [const { AtomicU64::new(0) }; MAX_CPUS];

/// Charge one timer interrupt to `cpu` (arch trap path).
pub fn timer_inc(cpu: usize) {
    if cpu < MAX_CPUS {
        TIMER_COUNT[cpu].fetch_add(1, Ordering::Relaxed);
    }
}

/// Charge one software interrupt to `cpu` (arch trap path).
pub fn soft_inc(cpu: usize) {
    if cpu < MAX_CPUS {
        SOFT_COUNT[cpu].fetch_add(1, Ordering::Relaxed);
    }
}

/// The per-CPU timer count (procfs generation).
pub fn timer_count(cpu: usize) -> u64 {
    if cpu < MAX_CPUS {
        TIMER_COUNT[cpu].load(Ordering::Relaxed)
    } else {
        0
    }
}

/// The per-CPU softirq count (procfs generation).
pub fn soft_count(cpu: usize) -> u64 {
    if cpu < MAX_CPUS {
        SOFT_COUNT[cpu].load(Ordering::Relaxed)
    } else {
        0
    }
}

// ============================================================================
// /proc/stat cells
// ============================================================================


impl CpuTime {
    const fn new() -> Self {
        Self {
            user: AtomicU64::new(0),
            nice: AtomicU64::new(0),
            system: AtomicU64::new(0),
            idle: AtomicU64::new(0),
            iowait: AtomicU64::new(0),
            irq: AtomicU64::new(0),
            softirq: AtomicU64::new(0),
            steal: AtomicU64::new(0),
            guest: AtomicU64::new(0),
            guest_nice: AtomicU64::new(0),
        }
    }
}

pub static CPU_TIME: [CpuTime; MAX_CPUS] = [const { CpuTime::new() }; MAX_CPUS];

/// Total context switches since boot (Linux /proc/stat "ctxt").
pub static CTXT_SWITCHES: AtomicU64 = AtomicU64::new(0);

/// Total forks since boot (Linux /proc/stat "processes").
pub static FORKS: AtomicU64 = AtomicU64::new(0);

/// Charge one tick to the calling CPU's time accounting.
///
/// `user_mode` is the privilege mode the timer hit. The idle task
/// (pid 0) means the CPU had nothing to run — that is idle time, not
/// system time.
pub fn charge_tick(user_mode: bool) {
    let cpu = crate::arch::cpu_id() as usize;
    if cpu >= MAX_CPUS {
        return;
    }
    let idle = match crate::sched::current() {
        Some(task) => task.pid() == 0,
        None => true,
    };
    if idle {
        CPU_TIME[cpu].idle.fetch_add(1, Ordering::Relaxed);
    } else if user_mode {
        CPU_TIME[cpu].user.fetch_add(1, Ordering::Relaxed);
    } else {
        CPU_TIME[cpu].system.fetch_add(1, Ordering::Relaxed);
    }
}

/// Count one context switch and split it into the per-task voluntary /
/// involuntary buckets (Linux's `__schedule` accounting).
///
/// A task that was still runnable when it was switched out was
/// PREEMPTED — involuntary. A task that had gone to sleep had BLOCKED
/// — voluntary.
pub fn note_switch(prev: &crate::process::task::Task) {
    CTXT_SWITCHES.fetch_add(1, Ordering::Relaxed);
    // perf per-CPU context-switch accounting (PERF_COUNT_SW_CONTEXT_
    // SWITCHES; one relaxed load when no perf event wants it).
    crate::perf::note_ctxsw();
    if prev.pid() == 0 {
        return; // the idle task is not a process
    }
    let state = prev.state().bits();
    let blocked = state & (crate::process::task::TaskState::INTERRUPTIBLE | crate::process::task::TaskState::UNINTERRUPTIBLE) != 0;
    if blocked {
        prev.nvcsw.fetch_add(1, Ordering::Relaxed);
        // NOTE: this is a voluntary context switch (nvcsw), NOT a
        // schedstat yld_count — Linux counts yld_count only in the
        // sched_yield paths (kernel/sched/syscalls.c), so the schedstat
        // counter is bumped from sys_sched_yield, not here.
    } else {
        prev.nivcsw.fetch_add(1, Ordering::Relaxed);
    }
}

/// Count one fork (Linux /proc/stat "processes").
pub fn note_fork() {
    FORKS.fetch_add(1, Ordering::Relaxed);
}

// ============================================================================
// /proc/loadavg cells
// ============================================================================

/// Sample interval in jiffies (5s at HZ=250 — Linux's LOAD_FREQ).
const LOAD_FREQ: u64 = 5 * crate::config::KERNEL_HZ as u64;

/// Fixed-point exponential decay factors (1/5/15 min; 0.32 format).
const EXP_1: u64 = (0.920044414676f64 * (1u64 << 32) as f64) as u64;
const EXP_5: u64 = (0.983471453846f64 * (1u64 << 32) as f64) as u64;
const EXP_15: u64 = (0.994459848005f64 * (1u64 << 32) as f64) as u64;
const EXP_FACTOR: [u64; 3] = [EXP_1, EXP_5, EXP_15];

/// Fixed-point (0.32 format) load average accumulators.
/// To get the float value: avenrun[i] / 2^32 ≈ avenrun[i] >> 16 / 65536.
pub static AVENRUN: [AtomicU64; 3] = [
    AtomicU64::new(0),
    AtomicU64::new(0),
    AtomicU64::new(0),
];

/// Jiffies counter at last load sample.
static LAST_LOAD_JIFFIES: AtomicU64 = AtomicU64::new(0);

/// Running task count at last sample (for /proc/loadavg output).
pub static LAST_RUNNING: AtomicU32 = AtomicU32::new(0);

/// Total task count at last sample (for /proc/loadavg output).
pub static LAST_TOTAL: AtomicU32 = AtomicU32::new(0);

/// Update load average from scheduler_tick().
/// Call this from the timer tick path; it auto-throttles to LOAD_FREQ.
///
/// IRQ-CONTEXT CONSTRAINT (the fbterm-input wedge): scheduler_tick() runs
/// from handle_timer_interrupt() with SIE=0. The old implementation walked
/// the PID hash here (pid_hash_collect_all + find_task_by_pid per pid),
/// taking pid-hash bucket spinlocks. On the single-CPU QEMU virt setup,
/// any task-context holder of a bucket lock (fork insert, wait4/kill
/// lookup, send_signal_to_pgid broadcast — the fbterm boot exercises all
/// of them) that is interrupted by the 5-second sample boundary wedges
/// the whole machine: the tick spins on lock_bucket forever with
/// interrupts off, so the holder can never be resumed — no more timer
/// ticks, no UART RX IRQs, every task frozen (screen stuck on the fbterm
/// banner, serial input dead). GDB proof: pc spinning in lock_bucket,
/// backtrace scheduler_tick -> update_load_avg -> pid_hash_collect_all.
///
/// The sample therefore reads ONLY scheduler-owned atomic state. /proc
/// semantics are unaffected: `running` feeds the EMA and the display
/// field, and generate() re-counts `total`/`last_pid` in the read
/// (task) path, where taking bucket locks is legal.
pub fn update_load_avg() {
    let now = crate::timer::get_jiffies();
    let last = LAST_LOAD_JIFFIES.load(Ordering::Relaxed);
    if now.wrapping_sub(last) < LOAD_FREQ {
        return;
    }

    // Try to claim the update slot. CAS avoids multiple CPUs updating simultaneously.
    if LAST_LOAD_JIFFIES.compare_exchange(last, now, Ordering::Acquire, Ordering::Relaxed).is_err() {
        return;
    }

    // Runnable+running tasks across all scheduling classes — lock-free
    // atomic reads (per-class nr_running counters), safe in IRQ context.
    let running = crate::sched::sched::GlobalRunQueue::grq_nr_running() as u64;

    LAST_RUNNING.store(running as u32, Ordering::Relaxed);
    LAST_TOTAL.store(running as u32, Ordering::Relaxed);

    // Exponential moving average: avenrun = avenrun * exp + nrun * (1 - exp)
    // In fixed-point: avenrun = avenrun * exp >> 32 + nrun * ((1<<32 - exp) >> 32)
    for i in 0..3 {
        let prev = AVENRUN[i].load(Ordering::Relaxed);
        let exp = EXP_FACTOR[i];
        // Fixed-point EMA: (prev*exp)>>32 keeps the full precision — the
        // old (prev>>32)*(exp>>32) truncated both words to ~0, so the
        // averages never moved off zero and increments rounded away
        // (review VFS-M11). The product is computed in u128: with
        // load > 1.0 (prev > 2^32) a u64 multiply would overflow.
        let decayed = (((prev as u128) * (exp as u128)) >> 32) as u64;
        let new_val = decayed + running * ((1u64 << 32) - exp);
        AVENRUN[i].store(new_val, Ordering::Relaxed);
    }
}

// ============================================================================
// /proc/schedstat cells
// ============================================================================

/// Voluntary context switches (yields) per CPU.
pub static YLD_COUNT: [AtomicU64; MAX_CPUS] =
    [const { AtomicU64::new(0) }; MAX_CPUS];

/// Scheduler invocations per CPU.
pub static SCHED_COUNT: [AtomicU64; MAX_CPUS] =
    [const { AtomicU64::new(0) }; MAX_CPUS];

/// Count one sched_yield() served by `cpu` (Linux's rq->yld_count,
/// incremented only in the sched_yield paths — kernel/sched/syscalls.c).
pub fn note_yield(cpu: usize) {
    if cpu < MAX_CPUS {
        YLD_COUNT[cpu].fetch_add(1, Ordering::Relaxed);
    }
}

/// Count one scheduler invocation on `cpu`.
pub fn note_sched_run(cpu: usize) {
    if cpu < MAX_CPUS {
        SCHED_COUNT[cpu].fetch_add(1, Ordering::Relaxed);
    }
}

// ============================================================================
// /proc/uptime cells
// ============================================================================

/// Per-CPU cumulative cycles spent in the idle loop's WFI (P2: real idle
/// accounting for /proc/uptime). Charged by cpu_idle_loop() around each
/// wfi; the sum across CPUs is the second /proc/uptime column.
pub static IDLE_WFI_CYCLES: [AtomicU64; MAX_CPUS] =
    [const { AtomicU64::new(0) }; MAX_CPUS];

/// Charge `cycles` of idle time to the calling CPU (idle loop only).
pub fn account_idle_cycles(cpu: usize, cycles: u64) {
    if cpu < MAX_CPUS {
        IDLE_WFI_CYCLES[cpu].fetch_add(cycles, Ordering::Relaxed);
    }
}

/// Total idle cycles summed across all CPUs.
pub fn total_idle_cycles() -> u64 {
    let mut sum = 0u64;
    for c in IDLE_WFI_CYCLES.iter() {
        sum = sum.saturating_add(c.load(Ordering::Relaxed));
    }
    sum
}


// ════════════════ lock_hooks ══════════════════════════
// (was lock_hooks.rs)
// Rung-3 RELOCATION SEAM (locks family), converted at the fs-rest
// split: the lock/lease LOGIC and its tables live in the fs crate
// (`crate::locks` there), while the framework's fs/locks.rs keeps
// the open/close fast-path gates, the count mirrors and the exec
// text-hold family. The LockOwner enum and lock-kind constants are
// re-exported so vfs.rs/file.rs keep their spellings; the per-open/
// per-close legs and the text-hold census stay DIRECT calls (they hit
// the framework half), and the COLD paths — the fcntl lock arms and
// the slow release bodies the gates arm when locks/leases exist —
// dispatch through the LocksHooks table below (the mount and notify
// seams' model, as this file's original doc predicted).
//
// NOTHING here runs at rust_main time: registration only publishes
// the plain-Copy table; every row body runs when the framework calls
// it. The hot open/close paths never dispatch a row on a default boot
// (the count-mirror gates return first — crate-plan §3a rule 2).

// The table itself lives with the other interface tables (api/fs.rs,
// seed-core-design 2c.4); this file keeps the forwarding wrappers the
// close and write-open paths call. Pass 2 moves those wrappers.


#[inline]
pub fn lock_rows() -> &'static LocksHooks {
    LOCKS_HOOKS.get().unwrap_or(&LocksHooks::EMPTY)
}

/// Register an inode-open for lease tracking (File::open paths).
/// Direct call: the framework half's per-open inode atomics.
pub(crate) fn lock_hooks_inode_open_register(inode: &super::types::Inode, write: bool) {
    self::inode_open_register(inode, write);
}

/// Unregister on close (File::drop path). Direct call: the framework
/// half's atomics + count gate; the lease-release leg rides the row.
pub(crate) fn lock_hooks_inode_open_unregister(file: &super::types::File) {
    self::inode_open_unregister(file);
}

/// Release flock-owned locks on close. Direct call: the framework
/// half's FLOCK_COUNT gate; the table work rides the row.
pub(crate) fn lock_hooks_flock_release_file(file_id: u64) {
    self::flock_release_file(file_id);
}

/// Release OFD-owned locks on close. Same shape as flock_release_file.
pub(crate) fn lock_hooks_ofd_release_file(file_id: u64) {
    self::ofd_release_file(file_id);
}

/// Break a lease on an inode (write-open conflict paths). Direct call:
/// the framework half's LEASE_COUNT gate; the break machinery rides
/// the row.
pub(crate) fn lock_hooks_break_lease(
    inode: &super::types::Inode,
    writer: bool,
) -> Result<(), crate::errno::Errno> {
    self::break_lease(inode, writer)
}

/// Posix fcntl test-lock path (F_GETLK conflict probe). Cold row.
pub(crate) fn posix_test_lock(
    file: &super::types::File,
    owner: LockOwner,
    exclusive: bool,
    start: u64,
    end: u64,
) -> Option<super::types::LockConflict> {
    (lock_rows().posix_test_lock)(file, owner, exclusive, start, end)
}

/// Posix fcntl set-lock path (F_SETLK/W core; kind is a F_*_KIND byte).
/// Cold row.
pub(crate) fn posix_set_lock(
    file: &super::types::File,
    owner: LockOwner,
    kind: u8,
    start: u64,
    end: u64,
    wait: bool,
) -> Result<(), crate::errno::Errno> {
    (lock_rows().posix_set_lock)(file, owner, kind, start, end, wait)
}

/// Lease set/query (F_SETLEASE/F_GETLEASE). Cold rows.
pub(crate) fn set_lease(
    file: &super::types::File,
    lease_type: i16,
) -> Result<(), crate::errno::Errno> {
    (lock_rows().set_lease)(file, lease_type)
}
pub(crate) fn get_lease(file: &super::types::File) -> i16 {
    (lock_rows().get_lease)(file)
}

/// Text-hold census (the write-open conflict check). Direct call: the
/// exec text-hold family never left the framework.
pub(crate) fn lock_hooks_inode_text_hold_count(inode: &super::types::Inode) -> u32 {
    self::inode_text_hold_count(inode)
}


// ════════════════ notify_events ═══════════════════════
// (was notify_events.rs)
// The inotify event constants (IN_*) — FRAMEWORK-side ABI constants
// (rung-3 flip: the inotify leaf moved to fs; the constants
// stay with the framework's notify_hooks so vfs.rs/file.rs keep their
// `ino::IN_*` spellings and the crate re-imports them).

pub mod inotify_events {
    /// File was accessed (read).
    pub const IN_ACCESS: u32 = 0x0000_0001;
    /// File was modified.
    pub const IN_MODIFY: u32 = 0x0000_0002;
    /// Metadata changed.
    pub const IN_ATTRIB: u32 = 0x0000_0004;
    /// Writable file was closed.
    pub const IN_CLOSE_WRITE: u32 = 0x0000_0008;
    /// Unwritable file was closed.
    pub const IN_CLOSE_NOWRITE: u32 = 0x0000_0010;
    /// File was opened.
    pub const IN_OPEN: u32 = 0x0000_0020;
    /// File moved out of watched dir.
    pub const IN_MOVED_FROM: u32 = 0x0000_0040;
    /// File moved into watched dir.
    pub const IN_MOVED_TO: u32 = 0x0000_0080;
    /// File/dir created in watched dir.
    pub const IN_CREATE: u32 = 0x0000_0100;
    /// File/dir deleted from watched dir.
    pub const IN_DELETE: u32 = 0x0000_0200;
    /// Watched file/dir was itself deleted.
    pub const IN_DELETE_SELF: u32 = 0x0000_0400;
    /// Watched file/dir was itself moved.
    pub const IN_MOVE_SELF: u32 = 0x0000_0800;

    /// Watch was removed (explicitly or automatically). Always delivered.
    pub const IN_IGNORED: u32 = 0x0000_8000;
    /// Event queue overflowed.
    pub const IN_Q_OVERFLOW: u32 = 0x0000_4000;
    /// Filesystem containing the watched inode was unmounted.
    pub const IN_UNMOUNT: u32 = 0x0000_2000;

    /// Subject of the event is a directory (modifier, not maskable).
    pub const IN_ISDIR: u32 = 0x4000_0000;
    /// Add to the existing mask instead of replacing it.
    pub const IN_MASK_ADD: u32 = 0x2000_0000;
    /// Don't report events for children after they were unlinked from the
    /// watched directory.
    pub const IN_EXCL_UNLINK: u32 = 0x0400_0000;
    /// Remove the watch after one event.
    pub const IN_ONESHOT: u32 = 0x8000_0000;

    /// Bits a user may ask to watch.
    pub const IN_ALL_EVENTS: u32 = IN_ACCESS
        | IN_MODIFY
        | IN_ATTRIB
        | IN_CLOSE_WRITE
        | IN_CLOSE_NOWRITE
        | IN_OPEN
        | IN_MOVED_FROM
        | IN_MOVED_TO
        | IN_CREATE
        | IN_DELETE
        | IN_DELETE_SELF
        | IN_MOVE_SELF;
}


// ════════════════ stat ════════════════════════════════
// (was stat.rs)
// File Status Information (stat)

impl Stat {
    /// Create default Stat structure
    pub fn new() -> Self {
        Self {
            st_dev: 0,
            st_ino: 0,
            st_mode: 0,
            st_nlink: 0,
            st_uid: 0,
            st_gid: 0,
            st_rdev: 0,
            __pad1: 0,
            st_size: 0,
            st_blksize: 4096,  // Default 4KB
            st_blocks: 0,
            st_atime: 0,
            st_atime_nsec: 0,
            st_mtime: 0,
            st_mtime_nsec: 0,
            st_ctime: 0,
            st_ctime_nsec: 0,
            __unused: [0, 0],
        }
    }

    /// Set as regular file
    pub fn set_regular_file(&mut self) {
        self.st_mode = (self.st_mode & !0o170000) | 0o100000;
    }

    /// Set as directory
    pub fn set_directory(&mut self) {
        self.st_mode = (self.st_mode & !0o170000) | 0o040000;
    }

    /// Set as character device
    pub fn set_char_device(&mut self) {
        self.st_mode = (self.st_mode & !0o170000) | 0o020000;
    }

    /// Set as block device
    pub fn set_block_device(&mut self) {
        self.st_mode = (self.st_mode & !0o170000) | 0o060000;
    }

    /// Set as FIFO
    pub fn set_fifo(&mut self) {
        self.st_mode = (self.st_mode & !0o170000) | 0o010000;
    }

    /// Set as symbolic link
    pub fn set_symlink(&mut self) {
        self.st_mode = (self.st_mode & !0o170000) | 0o120000;
    }

    /// Set as socket
    pub fn set_socket(&mut self) {
        self.st_mode = (self.st_mode & !0o170000) | 0o140000;
    }

    /// Check if regular file
    pub fn is_regular_file(&self) -> bool {
        (self.st_mode & 0o170000) == 0o100000
    }

    /// Check if directory
    pub fn is_directory(&self) -> bool {
        (self.st_mode & 0o170000) == 0o040000
    }

    /// Check if character device
    pub fn is_char_device(&self) -> bool {
        (self.st_mode & 0o170000) == 0o020000
    }

    /// Check if block device
    pub fn is_block_device(&self) -> bool {
        (self.st_mode & 0o170000) == 0o060000
    }

    /// Check if FIFO
    pub fn is_fifo(&self) -> bool {
        (self.st_mode & 0o170000) == 0o010000
    }

    /// Check if symbolic link
    pub fn is_symlink(&self) -> bool {
        (self.st_mode & 0o170000) == 0o120000
    }

    /// Check if socket
    pub fn is_socket(&self) -> bool {
        (self.st_mode & 0o170000) == 0o140000
    }

    /// Set permission bits
    pub fn set_mode(&mut self, mode: u32) {
        // Clear low 9 bits of permissions
        self.st_mode &= 0o170000;
        // Set new permissions
        self.st_mode |= mode & 0o777;
    }

    /// Get permission bits
    pub fn get_mode(&self) -> u32 {
        self.st_mode & 0o777
    }
}

impl Default for Stat {
    fn default() -> Self {
        Self::new()
    }
}

#[cfg(feature = "x86_64")]
impl From<&Stat> for X86Stat {
    fn from(s: &Stat) -> Self {
        X86Stat {
            st_dev: s.st_dev,
            st_ino: s.st_ino,
            st_nlink: s.st_nlink as u64,
            st_mode: s.st_mode,
            st_uid: s.st_uid,
            st_gid: s.st_gid,
            __pad0: 0,
            st_rdev: s.st_rdev,
            st_size: s.st_size,
            st_blksize: s.st_blksize,
            st_blocks: s.st_blocks,
            st_atime: s.st_atime,
            st_atime_nsec: s.st_atime_nsec as i64,
            st_mtime: s.st_mtime,
            st_mtime_nsec: s.st_mtime_nsec as i64,
            st_ctime: s.st_ctime,
            st_ctime_nsec: s.st_ctime_nsec as i64,
            __glibc_reserved: [0; 3],
        }
    }
}

/// Size of the stat struct as the current build target's userspace ABI
/// expects it (access_ok sizing and copy length).
pub fn user_stat_size() -> usize {
    #[cfg(feature = "x86_64")]
    return core::mem::size_of::<X86Stat>();
    #[cfg(not(feature = "x86_64"))]
    core::mem::size_of::<Stat>()
}

/// Copy `stat` to a validated user buffer in the target ABI layout.
/// Returns the number of bytes NOT copied (0 = success), matching
/// arch::uaccess::copy_to_user.
pub fn copy_stat_to_user(buf: *mut u8, stat: &Stat) -> usize {
    #[cfg(feature = "x86_64")]
    {
        let x = X86Stat::from(stat);
        // SAFETY: caller validated buf with access_ok over
        // user_stat_size() bytes; exception-table copy faults safely.
        unsafe {
            crate::arch::uaccess::copy_to_user(
                buf,
                &x as *const X86Stat as *const u8,
                core::mem::size_of::<X86Stat>(),
            )
        }
    }
    #[cfg(not(feature = "x86_64"))]
    // SAFETY: see above.
    unsafe {
        crate::arch::uaccess::copy_to_user(
            buf,
            stat as *const Stat as *const u8,
            core::mem::size_of::<Stat>(),
        )
    }
}

impl Statx {
    /// Create zeroed Statx structure
    pub fn new() -> Self {
        Self {
            stx_mask: 0,
            stx_blksize: 0,
            stx_attributes: 0,
            stx_nlink: 0,
            stx_uid: 0,
            stx_gid: 0,
            stx_mode: 0,
            __spare0: 0,
            stx_ino: 0,
            stx_size: 0,
            stx_blocks: 0,
            stx_attributes_mask: 0,
            stx_atime: StatxTimestamp { tv_sec: 0, tv_nsec: 0, __reserved: 0 },
            stx_btime: StatxTimestamp { tv_sec: 0, tv_nsec: 0, __reserved: 0 },
            stx_ctime: StatxTimestamp { tv_sec: 0, tv_nsec: 0, __reserved: 0 },
            stx_mtime: StatxTimestamp { tv_sec: 0, tv_nsec: 0, __reserved: 0 },
            stx_rdev_major: 0,
            stx_rdev_minor: 0,
            stx_dev_major: 0,
            stx_dev_minor: 0,
            stx_mnt_id: 0,
            __spare2: [0; 13],
        }
    }
}

impl Default for Statx {
    fn default() -> Self {
        Self::new()
    }
}


// ════════════════ dev_t ═══════════════════════════════
// (was dev_t.rs)
// Kernel layer policy (docs/architecture/kernel-layers.md):
// this module must stay Safe Rust.

// Device Number Definitions

/// Number of bits used for minor device number (Linux: MINORBITS = 20)
const DEV_MINOR_BITS: u32 = 20;
/// Mask for minor device number
const DEV_MINOR_MASK: u64 = (1u64 << DEV_MINOR_BITS) - 1;

impl DevNo {
    /// Create new device number
    pub const fn new(major: u32, minor: u32) -> Self {
        Self { major, minor }
    }

    /// Convert from u64 (Linux kernel internal dev_t format)
    pub const fn from_u64(v: u64) -> Self {
        Self {
            major: (v >> DEV_MINOR_BITS) as u32,
            minor: (v & DEV_MINOR_MASK) as u32,
        }
    }

    /// Convert to u64 (Linux kernel internal dev_t format)
    pub const fn to_u64(&self) -> u64 {
        ((self.major as u64) << DEV_MINOR_BITS) | (self.minor as u64 & DEV_MINOR_MASK)
    }

    /// Encode for USERSPACE stat st_rdev / mknod dev_t (Linux
    /// new_encode_dev): major in bits 8-19, minor split across bits 0-7
    /// and 20-31. glibc/busybox major()/minor()/makedev() operate on
    /// exactly this layout — reporting the kernel-internal format broke
    /// every userspace device-number consumer (stat, mdev, udev).
    pub const fn to_user_dev(&self) -> u64 {
        ((self.major as u64 & 0xfff) << 8)
            | (self.minor as u64 & 0xff)
            | ((self.minor as u64 & 0xfffff00) << 12)
    }

    /// Decode a USERSPACE dev_t (new_encode_dev layout: the `dev`
    /// argument of mknod(2) or a node's st_rdev) into a DevNo — Linux
    /// new_decode_dev parity. Needed to look up the CharDev registry from
    /// a device node stored on a non-devfs filesystem (tmpfs-mounted
    /// /dev, OH init's mknod path).
    pub const fn from_user_dev(v: u64) -> Self {
        Self {
            major: ((v >> 8) & 0xfff) as u32,
            minor: ((v & 0xff) | ((v >> 12) & 0xfff00)) as u32,
        }
    }
}

impl Default for DevNo {
    fn default() -> Self {
        Self { major: 0, minor: 0 }
    }
}

// ============================================================================
// Standard major device numbers
// ============================================================================

/// Memory devices (null, zero, random, etc.)
pub const MEM_MAJOR: u32 = 1;

/// TTY devices
pub const TTY_MAJOR: u32 = 4;
/// TTY auxiliary major (/dev/tty = 5:0, /dev/console = 5:1 — Linux layout).
pub const TTYAUX_MAJOR: u32 = 5;
/// The virtio-blk major (the devfs leaf's registration target; lives
/// here — the framework's dev_t block — since the drivers reference it).
pub const VIRTIO_BLK_MAJOR: u32 = 254;

/// Parallel ports
pub const LP_MAJOR: u32 = 6;

/// Loop block devices (/dev/loopN)
pub const LOOP_MAJOR: u32 = 7;

/// Misc char devices (loop-control, ...)
pub const MISC_MAJOR: u32 = 10;

/// SCSI disks
pub const SCSI_DISK_MAJOR: u32 = 8;

/// MTD block devices
pub const MTD_BLOCK_MAJOR: u32 = 31;

/// IDE disks
pub const IDE_DISK_MAJOR: u32 = 33;

/// Framebuffer devices
pub const FB_MAJOR: u32 = 29;

/// Input devices (keyboard, mouse, evdev, etc.)
pub const INPUT_MAJOR: u32 = 13;

/// evdev minor number base
pub const EVDEV_MINOR_BASE: u32 = 64;

/// Mouse devices (mice, mouse0, mouse1, etc.)
pub const MICE_MINOR: u32 = 63;
pub const MOUSE_MINOR_BASE: u32 = 32;

// ============================================================================
// Common devices
// ============================================================================

/// /dev/null
pub const DEV_NULL: DevNo = DevNo::new(MEM_MAJOR, 3);

/// /dev/zero
pub const DEV_ZERO: DevNo = DevNo::new(MEM_MAJOR, 5);

/// /dev/random
pub const DEV_RANDOM: DevNo = DevNo::new(MEM_MAJOR, 8);

/// /dev/urandom
pub const DEV_URANDOM: DevNo = DevNo::new(MEM_MAJOR, 9);

/// /dev/kmsg (kernel message buffer)
pub const DEV_KMSG: DevNo = DevNo::new(MEM_MAJOR, 11);

/// /dev/input/event0 (keyboard)
pub const DEV_FB0: DevNo = DevNo::new(FB_MAJOR, 0);
pub const DEV_EVDEV_KEYBOARD: DevNo = DevNo::new(INPUT_MAJOR, EVDEV_MINOR_BASE);

/// /dev/input/event1 (mouse/pointer)
pub const DEV_EVDEV_POINTER: DevNo = DevNo::new(INPUT_MAJOR, EVDEV_MINOR_BASE + 1);

/// Touchscreen evdev (event2): the pointer device's coordinates
/// re-published with touch protocol (BTN_TOUCH + ABS_MT_POSITION_X/Y)
/// for OH's multimodalinput framework.
pub const DEV_EVDEV_TOUCHSCREEN: DevNo = DevNo::new(INPUT_MAJOR, EVDEV_MINOR_BASE + 2);


// ════════════════ fs_struct ═══════════════════════════
// (was fs_struct.rs)
// Filesystem information structure (fs_struct)
//
// This module implements the fs_struct abstraction for storing
// per-process filesystem context (cwd, root, umask).
//
// When CLONE_FS is used, multiple threads share the same fs_struct.

impl FsStruct {
    /// Create a new FsStruct with default values
    pub fn new() -> Self {
        Self {
            cwd: RwSpinlock::new(alloc::vec::Vec::from(&b"/"[..])),
            root: RwSpinlock::new(alloc::vec::Vec::from(&b"/"[..])),
            cwd_dentry: RwSpinlock::new(None),
            root_dentry: RwSpinlock::new(None),
            pivot_put_old: RwSpinlock::new(None),
            root_is_pivot: RwSpinlock::new(false),
            umask: AtomicU32::new(0o022),  // Default umask
        }
    }

    /// Create a new FsStruct with specified cwd
    pub fn with_cwd(cwd: &[u8]) -> Self {
        let mut fs = Self::new();
        *fs.cwd.write() = alloc::vec::Vec::from(cwd);
        fs
    }

    // ==================== CWD Operations ====================

    /// Get current working directory (global-namespace path).
    ///
    /// When a cwd dentry is recorded it is the source of truth: the
    /// string is rebuilt from the dentry tree so it stays correct
    /// across mount moves (MS_MOVE/pivot-style flows rewrite
    /// mountpoint back-edges, and the rebuild picks the new location
    /// up — Linux derives paths the same way, from (vfsmnt, dentry)).
    pub fn get_cwd(&self) -> alloc::vec::Vec<u8> {
        // preempt-hunt: bind the clone BEFORE the if-let. The scrutinee's
        // read guard is a temporary that lives through the whole block,
        // so build_path() (a walk to the dentry root) used to run with
        // the rwlock guard — and its preempt-disable — held. fs_struct
        // sites were the #1 >2s incumbent family on the ph2 OH boot
        // (46 tick-heal origins at this file's sites).
        let d = self.cwd_dentry.read().clone();
        if let Some(d) = d {
            return d.build_path().into_bytes();
        }
        self.cwd.read().clone()
    }

    /// Set current working directory (string only — clears any
    /// recorded cwd dentry, the string becomes the truth again).
    pub fn set_cwd(&self, path: &[u8]) {
        *self.cwd_dentry.write() = None;
        *self.cwd.write() = alloc::vec::Vec::from(path);
    }

    /// Set the cwd from a resolved lookup: records BOTH the physical
    /// (mount-crossing) path string and the dentry it was built from.
    /// `dentry` None falls back to string-only.
    pub fn set_cwd_with_dentry(&self, path: &[u8], dentry: Option<Arc<Dentry>>) {
        *self.cwd_dentry.write() = dentry;
        *self.cwd.write() = alloc::vec::Vec::from(path);
    }

    /// The recorded cwd dentry, if any (mount-aware: the dentry after
    /// follow_mount crossings).
    pub fn cwd_dentry(&self) -> Option<Arc<Dentry>> {
        self.cwd_dentry.read().clone()
    }

    /// Get cwd as slice (for compatibility)
    pub fn cwd_slice(&self) -> alloc::boxed::Box<[u8]> {
        self.get_cwd().into_boxed_slice()
    }

    // ==================== Root Operations ====================

    /// Get root directory path (real-namespace normalized path; "/"
    /// when not chrooted). Self-heals from the root dentry when one
    /// is recorded (same rationale as get_cwd()).
    pub fn get_root(&self) -> alloc::vec::Vec<u8> {
        // Same if-let temporary-extension fix as get_cwd (preempt-hunt):
        // build_path() runs without the read guard.
        let d = self.root_dentry.read().clone();
        if let Some(d) = d {
            return d.build_path().into_bytes();
        }
        self.root.read().clone()
    }

    /// Whether the task is chrooted somewhere other than the global
    /// root — the ALLOCATION-FREE check path_lookup's fast path needs
    /// (get_root() allocates and, with a recorded root dentry, walks
    /// the parent chain; calling it per lookup cost ~5 heap objects
    /// per open). No allocs: read-lock the two slots and compare.
    pub fn root_is_slash(&self) -> bool {
        if self.root_dentry.read().is_some() {
            return false;
        }
        let r = self.root.read();
        r.as_slice() == b"/"
    }

    /// Set root directory path (chroot), string only — clears any
    /// recorded root dentry.
    pub fn set_root(&self, path: &[u8]) {
        *self.root_dentry.write() = None;
        *self.root.write() = alloc::vec::Vec::from(path);
    }

    /// Set the chroot root from a resolved lookup: records the jail
    /// root dentry (used by getcwd to compute root-relative paths and
    /// to detect a cwd outside the jail) alongside the prefix string
    /// that path_lookup interprets absolute paths against.
    pub fn set_root_with_dentry(&self, path: &[u8], dentry: Option<Arc<Dentry>>) {
        *self.root_dentry.write() = dentry;
        *self.root.write() = alloc::vec::Vec::from(path);
    }

    /// The recorded chroot root dentry, if any.
    pub fn root_dentry(&self) -> Option<Arc<Dentry>> {
        self.root_dentry.read().clone()
    }

    /// Record the put_old of this process's last pivot_root (consumed by
    /// the matching umount2 — see the field doc).
    pub fn set_pivot_put_old(&self, path: &[u8]) {
        *self.pivot_put_old.write() = Some(alloc::vec::Vec::from(path));
    }

    /// The recorded pivot put_old, if any.
    pub fn pivot_put_old(&self) -> Option<alloc::vec::Vec<u8>> {
        self.pivot_put_old.read().clone()
    }

    /// Clear the pivot marker (consumed / context reset).
    pub fn clear_pivot_put_old(&self) {
        *self.pivot_put_old.write() = None;
    }

    /// Whether the current root came from pivot_root(2)/setns (see the
    /// field doc) — drives setns(CLONE_NEWNS) root re-anchoring.
    pub fn root_is_pivot(&self) -> bool {
        *self.root_is_pivot.read()
    }

    /// Set/clear the pivot-root marker (sys_pivot_root, ns::setns).
    pub fn set_root_is_pivot(&self, v: bool) {
        *self.root_is_pivot.write() = v;
    }

    /// Copy the full filesystem context (cwd/root strings, cwd/root
    /// dentries) from `other` — fork()'s non-CLONE_FS duplicate. The
    /// old fork path copied only the cwd STRING, so a forked child of
    /// a chrooted task silently escaped the jail, and children lost
    /// the mount-aware cwd.
    pub fn copy_fs_from(&self, other: &FsStruct) {
        let cwd = other.cwd.read().clone();
        *self.cwd.write() = cwd;
        let root = other.root.read().clone();
        *self.root.write() = root;
        let cd = other.cwd_dentry.read().clone();
        *self.cwd_dentry.write() = cd;
        let rd = other.root_dentry.read().clone();
        *self.root_dentry.write() = rd;
        let rp = *other.root_is_pivot.read();
        *self.root_is_pivot.write() = rp;
    }

    // ==================== Umask Operations ====================

    /// Get current umask
    pub fn get_umask(&self) -> u32 {
        self.umask.load(Ordering::Acquire)
    }

    /// Set umask and return old value
    pub fn set_umask(&self, mask: u32) -> u32 {
        self.umask.swap(mask & 0o777, Ordering::AcqRel)
    }

    /// Apply umask to mode
    pub fn apply_umask(&self, mode: u32) -> u32 {
        mode & !self.umask.load(Ordering::Acquire)
    }
}

impl Default for FsStruct {
    fn default() -> Self {
        Self::new()
    }
}

unsafe impl Send for FsStruct {}
unsafe impl Sync for FsStruct {}


// ════════════════ page_cache ══════════════════════════
// (was page_cache.rs)
// Page Cache — per-inode file data cache layering on top of bio block cache.
//
// Caches 4KB file data pages keyed by ((fs_id, inode_number), page_index).
// The fs_id component (review 5.3: 页缓存键 ino:u32 截断/跨文件系统串页)
// separates inodes of different filesystem instances that would otherwise
// collide on the same small inode number.
// Reduces disk I/O for repeated reads and enables read-ahead population.
//
// Pages are allocated from the zone allocator as physical page frames,
// placed on LRU_INACTIVE_FILE for proper reclaim integration.  Eviction
// walks the LRU list in access-recency order, not BTreeMap key order.
//
// Physical pages are accessed through the linear mapping (phys_to_virt),
// not through identity mapping, since the kernel only identity-maps a
// small region around the kernel image.
//
// LOCKING (pcache Option B stage 1, perf-report 8.10.27/8.10.28 — the
// fdtable lever-B shape, 8.10.22, applied to the inode map). The old
// shape was ONE global `Spinlock<BTreeMap<u64, InodePageCache>>`: every
// fault paid the global lock acquire + two BTreeMap walks, and under the
// cold-start load phase (100MB of libs faulted page-by-page on 4 CPUs,
// thousands of distinct inodes) every fault serialized on that lock.
// Now:
//
// - **Global lookup is lock-free.** The inode map is a fixed-capacity
//   open-addressed slot table (`slots: [PcSlot; PC_TABLE_CAP]`, linear
//   probing on the mixed cache_key). Readers take NO lock: with irqs off
//   they claim their CPU's reader bank (SeqCst RMW), probe the slots
//   (Acquire loads), claim a strong count on the found entry, and drop
//   the bank. CPU ids outside the bank range serialize through
//   `slow_read` (the r8final discipline).
// - **Per-inode lock.** Each `InodePageCache` carries its own
//   `Spinlock<BTreeMap<u64, CachedPage>>` — the guard is the &mut access
//   to the map and every CachedPage field — so cross-INODE fault
//   contention is zero (the load phase faults many files at once; within
//   one inode the faults serialize on the VFS/mm side anyway). The
//   leg-54 locked-plain state-op discipline (86a458f9) transfers
//   verbatim to the per-inode lock: pin/unpin/count/release helpers are
//   plain accesses valid only under the owning entry's lock; read-only
//   scan sites keep atomic loads (`dirty` is always touched through
//   atomic ops and never here).
// - **Writers serialize on `wlock`** (entry insert/remove, eviction,
//   table iteration — rare and unchanged in shape from the old global
//   lock): `wlock → per-inode` nesting ONLY, never the reverse
//   (put-style paths drop the per-inode lock before taking wlock to
//   re-verify emptiness). No allocation ever runs under either lock
//   (R-WRITESTORM-1: the reclaim slowpath reaches shrink → wlock).
// - **Whole-entry removal parks and drains** exactly like
//   FdTable.retired (8.10.22): the slot is tombstoned under wlock, the
//   slot's reference is parked in `retired`, and the drop happens only
//   after a drain observes every reader bank at zero (SeqCst fence +
//   Acquire scans + slow_read held across the take). A reader that
//   already claimed the entry keeps it alive via its strong count; a
//   reader that loads the tombstone sees a miss and re-fills from disk
//   (the pages map was empty — that is WHY the entry was removed).
//   A false miss is always safe: the miss path re-reads the file and
//   `insert` dedups against the live entry.

/// Minimum cached pages across all inodes (8192 x 4KB = 32MB).
///
/// Was the WHOLE cap (a fixed `MAX_CACHED_PAGES = 8192`): smaller than one
/// Ubuntu binary's text+data working set, so every exec/read cycle
/// re-fetched from disk and a 10MB sequential read thrashed the LRU 5x
/// over. It is now the FLOOR of the dynamic cap below.
const MIN_CACHED_PAGES: usize = 8192;

/// Fraction of managed RAM the page cache may occupy before inserts evict
/// (soft cap — see `max_cached_pages`).
///
/// The fixed 32MB cap was the OH `.so`-load thrash: the image's shared
/// libraries alone are gigabytes, so with ~580 tasks faulting libraries
/// EVERY fault was a cache miss + eviction + disk refetch + ext4 big-lock
/// round trip, and measured ~1.5 s per fault (`SA:3002 OpenSo 802166ms`).
/// Linux scales the page cache to reclaimable memory; Rux now caps it at
/// half of managed RAM (reclaim still shrinks it below watermark via
/// `shrink`, so user allocations keep headroom).
const PAGE_CACHE_CAP_RAM_DIVISOR: usize = 2;

/// Cached dynamic cap (0 = not computed yet). Computed lazily on first
/// use; falls back to `MIN_CACHED_PAGES` before zone init.
static PAGE_CACHE_CAP: AtomicUsize = AtomicUsize::new(0);

/// Soft cap on total cached pages: half of managed RAM, at least 32MB.
///
/// Computed once (atomic compare-exchange); before the zone system is up
/// the old fixed floor applies. Reads managed pages from all initialized
/// zones — no allocation, no locks, safe from any insert path.
#[inline]
fn max_cached_pages() -> usize {
    let cached = PAGE_CACHE_CAP.load(Ordering::Relaxed);
    if cached != 0 {
        return cached;
    }
    let mut total = 0usize;
    if let Some(node) = first_online_node() {
        for zt in [ZoneType::ZoneNormal, ZoneType::ZoneDma32, ZoneType::ZoneDma] {
            if let Some(zone) = node.zone(zt) {
                if zone.is_initialized() {
                    total += zone.managed_pages();
                }
            }
        }
    }
    if total == 0 {
        return MIN_CACHED_PAGES; // zones not up yet — old fixed cap
    }
    let cap = core::cmp::max(total / PAGE_CACHE_CAP_RAM_DIVISOR, MIN_CACHED_PAGES);
    let _ = PAGE_CACHE_CAP.compare_exchange(0, cap, Ordering::AcqRel, Ordering::Acquire);
    PAGE_CACHE_CAP.load(Ordering::Relaxed)
}

/// Page-cache observability counters (Rux extension, /proc/meminfo
/// `PageCacheOps:` line). Cheap relaxed atomics on the insert/evict paths;
/// the point is ratio visibility on OH boots (hits vs misses vs evictions
/// under the real service mixture).
static STAT_HITS: AtomicU64 = AtomicU64::new(0);
static STAT_MISSES: AtomicU64 = AtomicU64::new(0);
static STAT_EVICTIONS: AtomicU64 = AtomicU64::new(0);
static STAT_DEMOTIONS: AtomicU64 = AtomicU64::new(0);
/// Re-entrancy gate for shrink_reclaim's dirty-flush I/O (see there).
static WRITEBACK_GUARD: AtomicBool = AtomicBool::new(false);
/// Slot-table degradation counter: inserts refused because the probe
/// found no free slot. Correctness is never affected (the page is simply
/// not cached; the caller re-reads from disk next time); a non-zero count
/// on a standard boot names a workload with more live inodes than
/// PC_TABLE_CAP and is worth resizing the table for.
static PC_TABLE_FULL: AtomicUsize = AtomicUsize::new(0);
/// Drain give-up counter (fdtable parity, 8.10.22): a drain that could
/// not observe all reader banks at zero within its spin budget defers the
/// retired drop to the next writer. Correctness is never affected.
static PC_DRAIN_DEFERS: AtomicUsize = AtomicUsize::new(0);

// ==================== falloc-wedge census (2026-11-16) ====================
//
// The fallocate05/06 wedge census: under the mkfs/fill cache balloon the
// reclaim holder spun minutes in shrink_reclaim with 243k clean-looking
// LRU pages and zero evictions — the SP-7 pattern (count every skip
// reason so the log names the sticking filter, not "reclaim slow").
// Relaxed fetch_adds on the reclaim/evict paths only; standard boots
// accrue a handful of counts and the OOM-FORENSIC block prints them only
// on the doomed path. These are census counters on the existing forensic
// surfaces (SP-5/SP-7 shape), not a new debug switch.
//
// shrink_reclaim faces:
pub(crate) static SR_CALLS: AtomicU64 = AtomicU64::new(0);
/// Pages freed by the clean-evict stage (`shrink`) of shrink_reclaim.
pub(crate) static SR_CLEAN_FREED: AtomicU64 = AtomicU64::new(0);
/// Dirty-inode flushes handed to ext4_flush_dirty_inode.
pub(crate) static SR_FLUSH_INODES: AtomicU64 = AtomicU64::new(0);
/// Rounds that found no flushable dirty inode (collect came back empty).
pub(crate) static SR_NO_DIRTY: AtomicU64 = AtomicU64::new(0);
/// WRITEBACK_GUARD re-entry degradations to clean-only.
pub(crate) static SR_GUARD_HITS: AtomicU64 = AtomicU64::new(0);
/// Loop io-claim degradations (reclaim inside loop I/O context defers
/// its writeback — see the re-entry discipline block in shrink_reclaim).
pub(crate) static SR_LOOP_DEFER: AtomicU64 = AtomicU64::new(0);

// ==================== GLOBAL DIRTY ACCOUNTING (falloc-wedge, 2026-11-16) ====
//
// The number of cache frames whose `dirty` bit is set — the
// dirty-balloon watermark's signal (ext4_buffered_write; the reference
// kernel's dirty-page accounting behind dirty_background_threshold).
// Every transition AND every map removal happens under the owning
// entry's per-inode lock, so a global relaxed counter adjusted at each
// of those points is exact: born-dirty inserts, mark_dirty sets, revive
// rewrites, flush_done clears, and the removal of a still-dirty entry
// (its bit dies with it). No new locking: the entry lock already
// serializes every site.
pub(crate) static DIRTY_PAGES: AtomicUsize = AtomicUsize::new(0);

#[inline]
fn dirty_account_transition(page: &CachedPage, new: bool) {
    let old = page.dirty.swap(new, Ordering::AcqRel);
    if old != new {
        if new {
            DIRTY_PAGES.fetch_add(1, Ordering::Relaxed);
        } else {
            DIRTY_PAGES.fetch_sub(1, Ordering::Relaxed);
        }
    }
}

/// Adjust the global for a page REMOVED from its map (under the entry
/// lock): a still-dirty page's bit dies with the entry.
#[inline]
fn dirty_account_removed(page: &CachedPage) {
    if page.dirty.swap(false, Ordering::AcqRel) {
        DIRTY_PAGES.fetch_sub(1, Ordering::Relaxed);
    }
}

/// Current dirty-frame count (the dirty-balloon watermark signal).
pub fn dirty_pages() -> usize {
    DIRTY_PAGES.load(Ordering::Relaxed)
}


impl<'a> BatchFill<'a> {
    #[inline]
    fn len(&self) -> usize {
        match self {
            BatchFill::Slice(b) => b.len(),
            BatchFill::User { len, .. } => *len,
        }
    }
}

// evict_one skip faces (both the LRU walk and the fallback scan):
/// Candidates skipped: cache pin (ref_count != 0).
pub(crate) static EV_SKIP_PINNED: AtomicU64 = AtomicU64::new(0);
/// Candidates skipped: cache dirty bit set (mmap unflushed stores).
pub(crate) static EV_SKIP_DIRTY: AtomicU64 = AtomicU64::new(0);
/// Candidates skipped: descriptor mapped (PCACHE_RO alias).
pub(crate) static EV_SKIP_MAPPED: AtomicU64 = AtomicU64::new(0);
/// Candidates given their Referenced second chance.
pub(crate) static EV_SECOND_CHANCE: AtomicU64 = AtomicU64::new(0);
/// Pages actually evicted (freed) via the evict paths.
pub(crate) static EV_FREED: AtomicU64 = AtomicU64::new(0);
/// LRU-walk exams that exhausted MAX_SCAN without a verdict.
pub(crate) static EV_SCAN_EXHAUST: AtomicU64 = AtomicU64::new(0);
/// flush_done outcomes: entries whose dirty bit was cleared (written
/// AND at pin 0). The two kept-* faces say why a flushed page stayed
/// dirty — the write failed (kept_fail: the page keeps its only copy)
/// or a mapping still holds the frame (kept_pin: conservative v1).
pub(crate) static FL_CLEARED: AtomicU64 = AtomicU64::new(0);
pub(crate) static FL_KEPT_PIN: AtomicU64 = AtomicU64::new(0);
pub(crate) static FL_KEPT_FAIL: AtomicU64 = AtomicU64::new(0);

/// One compact census line for the OOM-FORENSIC block (same shape as
/// vmscan's VSCAN-CENSUS line).
pub fn pcache_reclaim_census_line() -> alloc::string::String {
    use alloc::format;
    format!(
        "PCACHE-RECLAIM calls={} clean_freed={} flush_inodes={} no_dirty={} guard={} loop_defer={} evict(freed/2nd/pin/dirty/mapped/exhaust)={}/{}/{}/{}/{}/{} fl(clear/pin/fail)={}/{}/{}",
        SR_CALLS.load(Ordering::Relaxed),
        SR_CLEAN_FREED.load(Ordering::Relaxed),
        SR_FLUSH_INODES.load(Ordering::Relaxed),
        SR_NO_DIRTY.load(Ordering::Relaxed),
        SR_GUARD_HITS.load(Ordering::Relaxed),
        SR_LOOP_DEFER.load(Ordering::Relaxed),
        EV_FREED.load(Ordering::Relaxed),
        EV_SECOND_CHANCE.load(Ordering::Relaxed),
        EV_SKIP_PINNED.load(Ordering::Relaxed),
        EV_SKIP_DIRTY.load(Ordering::Relaxed),
        EV_SKIP_MAPPED.load(Ordering::Relaxed),
        EV_SCAN_EXHAUST.load(Ordering::Relaxed),
        FL_CLEARED.load(Ordering::Relaxed),
        FL_KEPT_PIN.load(Ordering::Relaxed),
        FL_KEPT_FAIL.load(Ordering::Relaxed),
    )
}

/// falloc-wedge diagnostic (2026-11-16, bounded — one-shot calls from
/// the WB-WATERMARK print budget only): the top dirty inodes by dirty
/// page count, `fs_id:ino dirty/total`. Identifies WHO owns the dirty
/// balloon when the recovery pass reports shrunk=0. Per-inode iteration
/// capped at 4096 steps (giant inodes report >=4096); full-table slot
/// walk under one wlock — acceptable for a bounded diagnostic, never on
/// a hot path.
pub fn pcache_dirty_histogram() -> alloc::string::String {
    use alloc::format;
    const MAX_INODE_SCAN: usize = 4096;
    const TOP_N: usize = 5;
    let cache = get_page_cache();
    let mut top: [(u64, u64, usize, usize); TOP_N] = [(0, 0, 0, 0); TOP_N];
    let _w = cache.wlock.lock();
    for si in 0..PC_TABLE_CAP {
        let p = cache.slots[si].0.load(Ordering::Acquire);
        if p.is_null() || p as usize == PC_TOMBSTONE_BITS {
            continue;
        }
        // SAFETY: wlock excludes removal; entry alive.
        let entry = unsafe { &*p };
        let g = entry.lock.lock();
        let mut dirty_n = 0usize;
        let mut total_n = 0usize;
        let mut stepped = 0usize;
        for (_idx, page) in g.iter() {
            stepped += 1;
            if stepped > MAX_INODE_SCAN {
                break;
            }
            total_n += 1;
            if page.dirty.load(Ordering::Acquire) {
                dirty_n += 1;
            }
        }
        drop(g);
        if dirty_n == 0 {
            continue;
        }
        // Insert into the top-N array (smallest first).
        for k in 0..TOP_N {
            if top[k].2 < dirty_n {
                // Shift the tail right and place.
                let mut m = TOP_N - 1;
                while m > k {
                    top[m] = top[m - 1];
                    m -= 1;
                }
                top[k] = (entry.fs_id, entry.ino, dirty_n, total_n);
                break;
            }
        }
    }
    let mut s = alloc::string::String::from("PCACHE-DIRTY-TOP");
    for t in top.iter() {
        if t.2 > 0 {
            s.push_str(&format!(" {:x}:{}={}/{}", t.0, t.1, t.2, t.3));
        }
    }
    s
}

impl CachedPage {
    /// Leg-54 item A (perf-report 8.10.24, sampler page 80473000 = 16.2%
    /// of launcher kernel time): every ref_count / released transition
    /// happens under a cache lock — the CAS-loop atomics were machinery
    /// the lock already subsumed. Since pcache Option B stage 1
    /// (8.10.27) that lock is the ENTRY's per-inode Spinlock (the old
    /// global inodes lock covered these same ops through leg-54). The
    /// STORAGE stays atomic for layout stability; these locked helpers
    /// do plain loads/stores through get_mut, which is sound ONLY while
    /// the owning entry's per-inode lock is held — new sites must keep
    /// that invariant (read-only scan sites elsewhere keep atomic loads;
    /// `dirty` is always touched through atomic ops and never here).
    #[inline]
    fn pin_locked(&mut self) {
        *self.ref_count.get_mut() += 1;
    }
    /// R14-16 floor discipline preserved: a put on an already-zero count
    /// (stale put) returns false and never underflows.
    #[inline]
    fn unpin_locked(&mut self) -> bool {
        let c = self.ref_count.get_mut();
        if *c == 0 {
            return false;
        }
        *c -= 1;
        true
    }
    #[inline]
    fn count_locked(&self) -> u32 {
        self.ref_count.load(Ordering::Relaxed)
    }
    /// R14-17 one-shot latch, locked form: true = this caller releases.
    #[inline]
    fn take_released_locked(&mut self) -> bool {
        let r = self.released.get_mut();
        if *r {
            return false;
        }
        *r = true;
        true
    }
}

/// Removal sentinel stored in a vacated slot: non-null (probes keep
/// walking), never dereferenced (every deref site checks the bits first).
const PC_TOMBSTONE_BITS: usize = 1;

/// Bound on a lock-free READER probe walk (slots scanned before giving
/// up). Give-up = a miss, which is always safe (re-read + insert dedup);
/// at the load factors this table runs at, real chains are 1-3 slots and
/// the bound is never approached. Writers probe to the first empty slot
/// with no bound — correctness of the dedup depends on it.
const PC_READER_PROBE_MAX: usize = 64;

impl InodePageCache {
    fn new(key: u64, fs_id: u64, ino: u64) -> Self {
        Self {
            key,
            lock: Spinlock::new(BTreeMap::new()),
            fs_id,
            ino,
            dirty_eof: core::sync::atomic::AtomicU64::new(0),
        }
    }
}

/// Revive an owned `Arc<InodePageCache>` from a slot pointer loaded under
/// a reader claim (INV-PC-CLAIM): the increment happens while the claim
/// (bank counter or slow_read) blocks the drain that would otherwise free
/// the entry, so the strong count cannot transit zero. The round-1
/// Arc-clone-from-raw shape, specialized to this table's claim protocol.
fn claim_entry_arc(p: *mut InodePageCache) -> Arc<InodePageCache> {
    // SAFETY: INV-PC-CLAIM — p was published by a writer from an owned
    // Arc and the caller's claim keeps it alive across the increment.
    unsafe {
        Arc::increment_strong_count(p);
        Arc::from_raw(p)
    }
}

/// Combine (fs_id, ino) into the single u64 map key. Distinct inputs map to
/// distinct keys for all practical purposes (splitmix-style mixing); the
/// fs_id for each filesystem is a stable instance tag (ext4: instance
/// pointer; rootfs/procfs/devfs: their FS_ID_* constants).
#[inline]
fn cache_key(fs_id: u64, ino: u64) -> u64 {
    fs_id.rotate_left(17).wrapping_add(0x9E3779B97F4A7C15) ^ ino.wrapping_mul(0xC2B2AE3D27D4EB4F)
}

/// Convert a physical address to a kernel-virtual pointer via the linear mapping.
#[inline]
fn phys_to_virt_ptr(phys: usize) -> *mut u8 {
    phys_to_virt(PhysAddr::new(phys as u64)).0 as *mut u8
}

impl FrameWindow {
    /// INV-PC-WIN construction (the one raw edge).
    #[inline]
    fn from_phys(phys: usize) -> FrameWindow {
        // SAFETY: INV-PC-WIN — linear-map address of a live frame; the
        // pointer is inert until the fill/copy methods (same INV).
        FrameWindow { ptr: phys_to_virt_ptr(phys) }
    }

    /// Fill from a kernel slice, zero the tail (INV-PC-WIN).
    #[inline]
    fn fill_from(&mut self, src: &[u8]) {
        let copy_len = core::cmp::min(src.len(), crate::mm::PAGE_SIZE);
        // SAFETY: INV-PC-WIN — owned frame, PAGE_SIZE window, bounded copy.
        unsafe {
            core::ptr::copy_nonoverlapping(src.as_ptr(), self.ptr, copy_len);
            if copy_len < crate::mm::PAGE_SIZE {
                core::ptr::write_bytes(self.ptr.add(copy_len), 0, crate::mm::PAGE_SIZE - copy_len);
            }
        }
    }

    /// Copy `copy_len` bytes from another frame, zero the tail
    /// (INV-PC-WIN on both frames).
    #[inline]
    fn copy_frame_from(&mut self, src_phys: usize, copy_len: usize) {
        // SAFETY: INV-PC-WIN — both frames live and owned/locked by the
        /// caller's call (the old INV-PC-PAGECOPY argument).
        unsafe {
            let src = phys_to_virt_ptr(src_phys) as *const u8;
            if copy_len > 0 {
                core::ptr::copy_nonoverlapping(src, self.ptr, copy_len);
            }
            if copy_len < crate::mm::PAGE_SIZE {
                core::ptr::write_bytes(self.ptr.add(copy_len), 0, crate::mm::PAGE_SIZE - copy_len);
            }
        }
    }
}

// ==================== Round-5 named page-fill edges ====================
//
// The insert/writeback family's one shared shape: copying bytes into
// the LINEAR MAP of a physical page frame. INV-PC-PAGECOPY: the frame
// is zone-allocated (the caller owns it exclusively until published)
// and the span stays inside PAGE_SIZE by construction at every caller.

/// Copy `src` into the frame at `phys_addr` and zero the tail (the
/// fill-a-fresh-frame shape: min(src.len(), PAGE_SIZE) bytes land, the
/// rest of the frame zeroes).
#[inline]
fn fill_page_from(phys_addr: usize, src: &[u8]) {
    FrameWindow::from_phys(phys_addr).fill_from(src);
}

/// Copy a whole frame from another frame (frame-to-frame revive/refresh).
#[inline]
fn copy_page_page(dst_phys: usize, src_phys: usize, copy_len: usize) {
    FrameWindow::from_phys(dst_phys).copy_frame_from(src_phys, copy_len);
}

/// Copy `n` bytes at kernel `src` into the frame at `pfn`, offset `off`
/// (the partial-span writeback shape). INV-PC-PAGECOPY: off+n <= PAGE_SIZE.
#[inline]
fn copy_into_page(pfn: u64, off: usize, src: *const u8, n: usize) {
    // SAFETY: INV-PC-PAGECOPY — the span is inside one frame by
    // construction at every caller (the cursor arithmetic asserts it).
    unsafe {
        let dst = phys_to_virt_ptr(pfn_to_phys(pfn as usize));
        core::ptr::copy_nonoverlapping(src, dst.add(off), n);
    }
}

/// Exception-table user->frame copy (the DIO insert path). Returns the
/// uncopied tail on fault. INV-PC-PAGECOPY + the uaccess extable
/// primitive's own contract (any user address is sound to pass).
#[inline]
fn copy_user_into_page(pfn: u64, off: usize, user_addr: usize, n: usize) -> usize {
    // SAFETY: INV-PC-PAGECOPY — the frame is this call's private
    // destination; the user source rides the exception-table primitive.
    unsafe {
        crate::arch::uaccess::copy_from_user(
            phys_to_virt_ptr(pfn_to_phys(pfn as usize)).add(off),
            user_addr as *const u8,
            n,
        )
    }
}

impl PageCache {
    /// Create a new empty page cache.
    pub const fn new() -> Self {
        Self {
            slots: [const { PcSlot(core::sync::atomic::AtomicPtr::new(core::ptr::null_mut())) };
                PC_TABLE_CAP],
            readers: [const { PcReaderBank(core::sync::atomic::AtomicUsize::new(0)) };
                PC_READER_BANKS],
            wlock: Spinlock::new(()),
            retired: Spinlock::new(alloc::vec::Vec::new()),
            slow_read: Spinlock::new(()),
            total_pages: AtomicU32::new(0),
        }
    }

    // ==================== slot-table primitives ====================

    /// Lock-free global lookup of the inode entry for `key` — the pcache
    /// twin of FdTable::get_file (8.10.22), at fault rate instead of
    /// syscall rate.
    ///
    /// With irqs off for the section, bump this CPU's reader bank (a
    /// SeqCst RMW — aqrl AMO on riscv, locked xadd on x86 — so the claim
    /// is globally visible before the slot loads below execute), probe
    /// the table (Acquire loads — pairs the publisher's Release store so
    /// the entry's fields are visible through the reconstructed Arc),
    /// claim the entry via a strong-count increment, and drop the claim.
    /// The per-inode work happens OUTSIDE the bank window, protected by
    /// the strong count alone.
    ///
    /// SAFETY of the increment (the reason the bank exists): a slot's Arc
    /// is owned by the table while published; any writer that removes it
    /// tombstones the slot, parks the Arc in `retired`, and the drain
    /// drops it only after observing EVERY bank at zero with the
    /// slow-path lock held. A reader can therefore only load a pointer
    /// whose reference is provably alive: either the slot still publishes
    /// it (the table's reference), or the removing writer's drain is
    /// waiting for THIS reader's bank to return to zero before its drop.
    /// The reader's SeqCst claim-before-load and the drain's
    /// SeqCst-fence-then-scan close the store-load ordering hole. The
    /// probe's `(*p).key` compare dereferences the entry for the same
    /// reason it is safe: within the claim window the entry cannot be
    /// freed (its allocation outlives the claim by the drain handshake),
    /// and `key` is write-once before publication.
    ///
    /// A probe that exhausts PC_READER_PROBE_MAX slots or hits the first
    /// empty slot reports a miss. Misses are always safe (the caller
    /// re-fills from disk and `insert` dedups against the live entry);
    /// the bound only bounds irqs-off latency.
    fn lookup_claimed(&self, key: u64) -> Option<Arc<InodePageCache>> {
        let flags = crate::arch::cpu::save_and_disable_irq();
        let cpu = crate::arch::cpu_id() as usize;
        let out = if cpu < PC_READER_BANKS {
            let bank = &self.readers[cpu];
            bank.0.fetch_add(1, Ordering::SeqCst);
            let p = self.probe_slot_ptr(key);
            let out = if !p.is_null() {
                // p is kept alive by the slot or by `retired` until a
                // drain observes all banks zero — our bank claim is
                // exactly what that drain waits for (INV-PC-CLAIM).
                Some(claim_entry_arc(p))
            } else {
                None
            };
            bank.0.fetch_sub(1, Ordering::Release);
            out
        } else {
            // r8final family: cpu id outside the bank range. Serialize
            // with drains through slow_read instead of a bank claim.
            let _slow = self.slow_read.lock_irqsave();
            let p = self.probe_slot_ptr(key);
            if !p.is_null() {
                // Drains hold slow_read across the drop of retired Arcs
                // (see drain_retired), so either the slot or a parked
                // reference keeps p alive here (INV-PC-CLAIM).
                Some(claim_entry_arc(p))
            } else {
                None
            }
        };
        crate::arch::cpu::restore_irq(flags);
        out
    }

    /// Probe the slot table for `key`; returns the raw entry pointer or
    /// null. Plain Acquire loads; LIVENESS is the caller's concern (bank
    /// claim window or slow_read). Stops at the first empty slot; walks
    /// over tombstones; bounded for readers, unbounded for writers.
    fn probe_slot_ptr(&self, key: u64) -> *mut InodePageCache {
        let h = (key as usize) & PC_TABLE_MASK;
        for n in 0..PC_READER_PROBE_MAX {
            let i = h.wrapping_add(n) & PC_TABLE_MASK;
            let p = self.slots[i].0.load(Ordering::Acquire);
            if p.is_null() {
                return core::ptr::null_mut();
            }
            if p as usize == PC_TOMBSTONE_BITS {
                continue;
            }
            // SAFETY: p is a published-or-parked live entry (see the
            // liveness contract of the callers); `key` is write-once.
            if unsafe { (*p).key } == key {
                return p;
            }
        }
        core::ptr::null_mut()
    }

    /// WRITER probe (wlock held): find the slot publishing an entry with
    /// this key. Walks to the first empty slot — the dedup invariant
    /// ("never two live entries with one key") depends on seeing the
    /// whole cluster, so no bound here.
    fn table_find(&self, key: u64) -> Option<usize> {
        let h = (key as usize) & PC_TABLE_MASK;
        for n in 0..PC_TABLE_CAP {
            let i = h.wrapping_add(n) & PC_TABLE_MASK;
            let p = self.slots[i].0.load(Ordering::Acquire);
            if p.is_null() {
                return None;
            }
            if p as usize == PC_TOMBSTONE_BITS {
                continue;
            }
            // SAFETY: wlock excludes removal, so the slot's reference is
            // stable and the entry is alive; `key` is write-once.
            if unsafe { (*p).key } == key {
                return Some(i);
            }
        }
        None
    }

    /// WRITER probe (wlock held): find the slot publishing exactly this
    /// entry object. Pointer identity — the entry may have been removed
    /// and re-created under the same key since the caller claimed it.
    fn table_find_ptr(&self, key: u64, want: *const InodePageCache) -> Option<usize> {
        let h = (key as usize) & PC_TABLE_MASK;
        for n in 0..PC_TABLE_CAP {
            let i = h.wrapping_add(n) & PC_TABLE_MASK;
            let p = self.slots[i].0.load(Ordering::Acquire);
            if p.is_null() {
                return None;
            }
            if p as usize == PC_TOMBSTONE_BITS {
                continue;
            }
            if core::ptr::eq(p, want) {
                return Some(i);
            }
        }
        None
    }

    /// WRITER (wlock held): return the live entry for `key`, publishing
    /// the caller's pre-allocated `fresh` entry on first touch.
    ///
    /// The Arc allocation MUST have happened before the caller took
    /// wlock (R-WRITESTORM-1: alloc's reclaim slowpath reaches shrink →
    /// wlock). Returns None only when the table has no free slot (the
    /// insert degrades to no-cache; PC_TABLE_FULL counts it) or `fresh`
    /// was not provided.
    fn table_publish(
        &self,
        _w: &SpinlockGuard<'_, ()>,
        key: u64,
        fresh: &mut Option<Arc<InodePageCache>>,
    ) -> Option<Arc<InodePageCache>> {
        let h = (key as usize) & PC_TABLE_MASK;
        let mut first_tomb: Option<usize> = None;
        for n in 0..PC_TABLE_CAP {
            let i = h.wrapping_add(n) & PC_TABLE_MASK;
            let p = self.slots[i].0.load(Ordering::Acquire);
            if p.is_null() {
                let entry = fresh.take()?;
                // Publish at the first tombstone seen on the way (keeps
                // probe chains compact) or at this empty slot. The entry
                // is fully initialized BEFORE Arc::into_raw; the Release
                // store publishes its fields to lock-free readers.
                let slot = first_tomb.unwrap_or(i);
                let ptr = Arc::into_raw(entry) as *mut InodePageCache;
                // SAFETY: ptr's reference count is transferred to the
                // slot; we re-constitute a second owning Arc for the
                // caller via an increment + from_raw pair.
                unsafe { Arc::increment_strong_count(ptr) };
                self.slots[slot].0.store(ptr, Ordering::Release);
                return Some(unsafe { Arc::from_raw(ptr) });
            }
            if p as usize == PC_TOMBSTONE_BITS {
                if first_tomb.is_none() {
                    first_tomb = Some(i);
                }
                continue;
            }
            // SAFETY: wlock excludes removal (stable slot reference).
            if unsafe { (*p).key } == key {
                // SAFETY: the slot keeps its reference; ours is a new
                // owning claim established while wlock blocks removal.
                unsafe { Arc::increment_strong_count(p) };
                return Some(unsafe { Arc::from_raw(p) });
            }
        }
        PC_TABLE_FULL.fetch_add(1, Ordering::Relaxed);
        None
    }

    /// Remove an EMPTIED entry from the table and park its slot
    /// reference. The emptiness is re-verified under the entry's
    /// per-inode lock WITH wlock held: a concurrent insert may have
    /// re-populated the entry between the claimer's unlock and here —
    /// then the entry stays published (that insert's page would
    /// otherwise be orphaned in a parked entry).
    fn remove_entry(&self, key: u64, claimed: &Arc<InodePageCache>) {
        let w = self.wlock.lock();
        let Some(idx) = self.table_find_ptr(key, Arc::as_ptr(claimed)) else {
            return; // already removed (evict/another put) — our Arc dies with us
        };
        let parked = {
            let g = claimed.lock.lock();
            if !g.is_empty() {
                return; // re-populated — stays published
            }
            self.slots[idx]
                .0
                .store(PC_TOMBSTONE_BITS as *mut InodePageCache, Ordering::Release);
            // SAFETY: the slot's reference is handed over here (the slot
            // no longer owns it); the parking Vec keeps it until the
            // reader-quiescent drain.
            unsafe { Arc::from_raw(Arc::as_ptr(claimed)) }
        };
        drop(w);
        self.park_and_drain(parked);
    }

    /// Park a removed entry and attempt the drain (FdTable.park_and_drain
    /// shape: nothing spins under wlock, so parking happens AFTER it).
    fn park_and_drain(&self, entry: Arc<InodePageCache>) {
        {
            let mut r = self.retired.lock_irqsave();
            r.push(entry);
        }
        self.drain_retired();
    }

    /// Move a wlock section's parked slot references into `retired` and
    /// drain once. Callers run this right AFTER dropping wlock.
    fn flush_parked(&self, parked: &mut PcParkBatch) {
        let mut any = false;
        for p in parked.iter_mut() {
            if let Some(e) = p.take() {
                let mut r = self.retired.lock_irqsave();
                r.push(e);
                any = true;
            }
        }
        if any {
            self.drain_retired();
        }
    }

    /// Drop retired entries once no reader can be mid-claim.
    ///
    /// Quiescence: every bank reads 0 (each scan load Acquire — reading 0
    /// synchronizes with that reader's Release decrement, so its
    /// strong-count increment has completed) AND the slow-path lock is
    /// held across the take (excludes the bank-range fallback readers).
    /// Readers that START after a successful scan cannot load these Arcs:
    /// their slots were tombstoned before the park, the tombstone stores
    /// precede this drain's SeqCst fence, and a fresh reader's slot load
    /// follows its own SeqCst bank claim.
    fn drain_retired(&self) {
        {
            // Cheap emptiness check first: most drains find a previous
            // drain already took the vec.
            let r = self.retired.lock_irqsave();
            if r.is_empty() {
                return;
            }
        }
        let mut scans: usize = 0;
        loop {
            // The fence orders the writer's earlier slot-tombstone stores
            // before the bank reads below (the reader side of the
            // handshake is its SeqCst bank claim before its slot load —
            // see lookup_claimed).
            core::sync::atomic::fence(Ordering::SeqCst);
            let mut all_zero = true;
            for b in self.readers.iter() {
                if b.0.load(Ordering::Acquire) != 0 {
                    all_zero = false;
                    break;
                }
            }
            if all_zero {
                break;
            }
            scans += 1;
            if scans >= 8192 {
                // Defer, never fail: reader sections are irq-off and
                // bounded, so this is practically unreachable; the next
                // writer op retries. Only the removal TIMING can be
                // delayed, never correctness.
                PC_DRAIN_DEFERS.fetch_add(1, Ordering::Relaxed);
                return;
            }
            core::hint::spin_loop();
        }
        let taken = {
            let _slow = self.slow_read.lock_irqsave();
            let mut r = self.retired.lock_irqsave();
            core::mem::take(&mut *r)
        };
        // Drop OUTSIDE all locks: InodePageCache::drop frees BTreeMap
        // nodes (allocator locks only, no pcache locks — same shape as
        // FdTable's retired File drops).
        drop(taken);
    }

    // ==================== fault-side ops (claim + per-inode lock) ====================

    /// Lookup a cached page for ((fs_id, ino), page_index).
    /// On hit: increments ref_count, sets Referenced flag, returns pointer.
    /// On miss: returns None.
    pub fn get(&self, fs_id: u64, ino: u64, page_index: u64) -> Option<*const u8> {
        let key = cache_key(fs_id, ino);
        let entry = self.lookup_claimed(key)?;
        let out = {
            let mut g = entry.lock.lock();
            let page = g.get_mut(&page_index)?;
            if page.invalidated {
                // Stale (a write invalidated it while pinned) — serve a
                // miss so the caller re-reads current data from disk.
                return None;
            }
            STAT_HITS.fetch_add(1, Ordering::Relaxed);
            page.pin_locked();

            // Mark page as recently accessed for LRU rotation
            if let Some(page_desc) = page_desc(page.pfn) {
                    page_desc.set_flag(PageFlag::Referenced);
            }

            let phys = pfn_to_phys(page.pfn);
            Some(phys_to_virt_ptr(phys) as *const u8)
        };
        drop(entry);
        out
    }

    /// Non-pinning residency probe: is ((fs_id, ino), page_index) cached
    /// and NOT invalidated? Takes no pin and touches no LRU state — for
    /// callers that only need the ANSWER (mincore(2)'s page-cache
    /// fallback, the read path's post-fill verification). `get()`/`get_phys()`
    /// each transfer a pin the caller must return via put(); a caller that
    /// drops the returned handle leaks the pin, and a leaked pin is how an
    /// invalidated-but-never-freed entry survives inode free to shadow the
    /// next file that reuses the inode number (the msync01-after-mincore04
    /// order-dependent corruption).
    pub fn resident(&self, fs_id: u64, ino: u64, page_index: u64) -> bool {
        let key = cache_key(fs_id, ino);
        let Some(entry) = self.lookup_claimed(key) else {
            return false;
        };
        let out = {
            let g = entry.lock.lock();
            g.get(&page_index)
                .is_some_and(|page| !page.invalidated)
        };
        drop(entry);
        out
    }

    /// Same as `get` but returns the PHYSICAL address — for mapping the
    /// cached frame directly into a user page table (MAP_SHARED faults).
    /// The returned pin is owned by that PTE mapping for its lifetime.
    pub fn get_phys(&self, fs_id: u64, ino: u64, page_index: u64) -> Option<u64> {
        let key = cache_key(fs_id, ino);
        let entry = self.lookup_claimed(key)?;
        let out = {
            let mut g = entry.lock.lock();
            let page = g.get_mut(&page_index)?;
            if page.invalidated {
                return None;
            }
            STAT_HITS.fetch_add(1, Ordering::Relaxed);
            page.pin_locked();
            if let Some(page_desc) = page_desc(page.pfn) {
                    page_desc.set_flag(PageFlag::Referenced);
            }
            Some(pfn_to_phys(page.pfn) as u64)
        };
        drop(entry);
        out
    }

    /// Tmpfs coherence twin of `get` (fsx-linux FXW family): identical
    /// pinning lookup, but an INVALIDATED entry is served, not refused.
    /// Rux's invalidate never zaps PTEs (documented deviation), so a
    /// tmpfs frame that is invalidated-but-still-mapped/pinned remains a
    /// LIVE face of the file — a mapper's stores land in it directly and
    /// nothing copies them to the node pages, so an fd read that skips
    /// the frame reads stale node bytes (FXW FD-MISMATCH). For ext4 the
    /// refused-on-invalidated contract stays: an invalidated frame there
    /// is retired data the disk supersedes, never a fresher face.
    pub fn get_stale(&self, fs_id: u64, ino: u64, page_index: u64) -> Option<*const u8> {
        let key = cache_key(fs_id, ino);
        let entry = self.lookup_claimed(key)?;
        let out = {
            let mut g = entry.lock.lock();
            let page = g.get_mut(&page_index)?;
            STAT_HITS.fetch_add(1, Ordering::Relaxed);
            page.pin_locked();
            if let Some(page_desc) = page_desc(page.pfn) {
                    page_desc.set_flag(PageFlag::Referenced);
            }
            let phys = pfn_to_phys(page.pfn);
            Some(phys_to_virt_ptr(phys) as *const u8)
        };
        drop(entry);
        out
    }

    /// REVIVE twin of `get_stale` (tmpfs fault path, fsx-linux FXW): same
    /// pinned lookup that serves invalidated entries, but a hit on an
    /// invalidated frame also CLEARS the mark — the frame comes back as a
    /// full citizen of the cache. Why revive: Rux never zaps PTEs, so an
    /// invalidated-but-mapped tmpfs frame remains the page's live face; a
    /// regrow (ftruncate) plus a fresh mapper's write fault must reuse
    /// that frame (mapper stores never reach the node pages), and without
    /// the revive the final put at munmap would remove+free the entry —
    /// evaporating the newly written data (FXW regression, truncate-evict
    /// family). The caller faults only at offsets inside the current file
    /// size (the fault-path EOF gate), so reviving cannot resurrect
    /// past-EOF data: truncate's force-zero pass already blanked the
    /// frame's cut range. ext4 keeps the strict contract — it never calls
    /// this.
    pub fn get_stale_revive(&self, fs_id: u64, ino: u64, page_index: u64) -> Option<u64> {
        let key = cache_key(fs_id, ino);
        let entry = self.lookup_claimed(key)?;
        let out = {
            let mut g = entry.lock.lock();
            let page = g.get_mut(&page_index)?;
            if page.invalidated {
                page.invalidated = false;
            }
            STAT_HITS.fetch_add(1, Ordering::Relaxed);
            page.pin_locked();
            if let Some(page_desc) = page_desc(page.pfn) {
                    page_desc.set_flag(PageFlag::Referenced);
            }
            Some(pfn_to_phys(page.pfn) as u64)
        };
        drop(entry);
        out
    }

    /// Pin up to `out.len()` consecutive cached pages starting at
    /// `page_index`, filling `out` with (index, pointer) pairs.
    ///
    /// Stops at the first missing/invalidated page — the caller re-fills and
    /// retries. One claim + one per-inode lock + one BTreeMap range walk
    /// replaces a get()/put() pair PER PAGE: for a 1 MiB sequential read that
    /// is 2 map round trips instead of 512 (the dominant warm-read cost under
    /// TCG). The out-array API avoids a heap allocation per call (a Vec here
    /// measurably regressed the 4 KiB-read hot path). Returns the run
    /// length; 0 when `page_index` itself is not cached.
    ///
    /// CONTIGUITY CONTRACT: out[i] is exactly `page_index + i` for i < n.
    /// The caller (ext4_file_read_cached_dst) consumes the run POSITIONALLY
    /// — it ignores the returned index and serves run[i] as page_index+i.
    /// BTreeMap::range() iterates only EXISTING keys, silently stepping
    /// over missing ones, so a bare range walk violates that contract
    /// whenever a page inside the window is absent:
    ///   - eviction removed page_index itself while its neighbours stayed:
    ///     the run started at page_index+1 and its content was served as
    ///     page_index's; or
    ///   - eviction removed a middle page (or fill_page_cache_batch skipped
    ///     a hole): every later entry shifted one page early — VALID file
    ///     data delivered at the WRONG offset.
    /// That was the AC-2 CKSUM-MISMATCH family (300 MB read-only window
    /// returning wrong bytes with a pristine disk and boot-deterministic
    /// wrong content). The `expected` walk below stops at the first gap so
    /// the caller re-fills from the missing page instead.
    pub fn get_range_into(
        &self,
        fs_id: u64,
        ino: u64,
        page_index: u64,
        out: &mut [(u64, *const u8)],
    ) -> usize {
        self.get_range_with_entry(fs_id, ino, page_index, out)
            .0
    }

    /// `get_range_into` that also hands the caller the CLAIMED entry the
    /// pins live in (oc-rc read-path cut): a release through
    /// `put_range_with_entry` then skips the second bank-claim + probe +
    /// strong-count round trip `put_range` would pay — on the 1-page hit
    /// that repeat lookup was ~half the pin+unpin pair's cost. The
    /// returned Arc keeps the entry (and the pinned pages' map entries)
    /// alive across the caller's copy window; `None` only when the whole
    /// lookup missed (caller re-fills).
    pub fn get_range_with_entry(
        &self,
        fs_id: u64,
        ino: u64,
        page_index: u64,
        out: &mut [(u64, *const u8)],
    ) -> (usize, Option<alloc::sync::Arc<InodePageCache>>) {
        let key = cache_key(fs_id, ino);
        if out.is_empty() {
            return (0, None);
        }
        let count = out.len();
        let Some(entry) = self.lookup_claimed(key) else {
            return (0, None);
        };
        let n = {
            let mut g = entry.lock.lock();
            let mut expected = page_index;
            let mut n = 0usize;
            for (&idx, page) in g.range_mut(page_index..page_index + count as u64) {
                if idx != expected {
                    break; // gap: page `expected` is not cached — stop here
                }
                if page.invalidated {
                    break;
                }
                page.pin_locked();
                if let Some(page_desc) = page_desc(page.pfn) {
                        page_desc.set_flag(PageFlag::Referenced);
                }
                let phys = pfn_to_phys(page.pfn);
                out[n] = (idx, phys_to_virt_ptr(phys) as *const u8);
                n += 1;
                expected += 1;
            }
            n
        };
        // oc-rc: one counter RMW per call instead of one per page — the
        // per-page fetch_add on this shared line was pure cacheline
        // ping on SMP for multi-page runs, and STAT_HITS semantics
        // ("pages served from cache") are preserved exactly (n pages).
        STAT_HITS.fetch_add(n as u64, Ordering::Relaxed);
        (n, Some(entry))
    }

    /// Contiguous-run release fast path shared by `put_range` /
    /// `put_range_by_key` (perf-gap-hunt, pagefault 2x push): both
    /// callers' release lists are consecutive file indices in practice
    /// (the fault arm's chunk tails release every page of the chunk;
    /// the unmap pin batches walk a contiguous VA range of one inode),
    /// so ONE BTreeMap range iterator in lockstep replaces a per-page
    /// tree descent (get_mut, O(log n) each).
    ///
    /// Handles only pages that are NOT invalidated: an invalidated page
    /// whose final pin drops here must also leave the map and free its
    /// frame, which cannot happen while the iterator borrows the map.
    /// The first invalidated page stops the fast path; the caller runs
    /// its per-page fallback for the REST. (invalidated is only ever
    /// set by invalidate_inode, under this same entry lock, for the
    /// whole entry at once — the fast path's untouched-prefix contract
    /// holds: every page it released was un-pinned exactly once and
    /// needs no further action.)
    ///
    /// Returns None when every page was released, or Some(k) meaning
    /// pages[k..] still need the per-page path.
    #[inline]
    fn unpin_contiguous_locked<T, F: Fn(&T) -> u64>(
        g: &mut BTreeMap<u64, CachedPage>,
        pages: &[T],
        idx_of: F,
    ) -> Option<usize> {
        if pages.is_empty() {
            return None;
        }
        // Contiguity gate (defensive: callers build consecutive runs,
        // but a W-form chunk tail skips its installed leaves).
        for w in pages.windows(2) {
            if idx_of(&w[0]).wrapping_add(1) != idx_of(&w[1]) {
                return Some(0);
            }
        }
        let start = idx_of(&pages[0]);
        let end = start + pages.len() as u64;
        let mut it = g.range_mut(start..end);
        let mut cur = it.next();
        for (pi, p) in pages.iter().enumerate() {
            let want = idx_of(p);
            // Advance the iterator to the first entry >= want.
            while let Some((idx, _)) = cur.as_ref() {
                if **idx >= want {
                    break;
                }
                cur = it.next();
            }
            match cur.take() {
                Some(pair) => {
                    if *pair.0 == want {
                        let page = pair.1;
                        if page.invalidated {
                            // Hand this page and the rest to the
                            // per-page path (its unpin may need remove
                            // + free).
                            return Some(pi);
                        }
                        page.unpin_locked();
                        cur = it.next();
                    } else {
                        // Map hole at `want` (idx > want): unreachable
                        // under the pin protocol, but hand the rest to
                        // the per-page path rather than skip silently.
                        drop(pair);
                        return Some(pi);
                    }
                }
                // Iterator exhausted before our last index: the pin
                // protocol guarantees every pinned page has its map
                // entry, so this cannot happen for a run WE pinned —
                // treat as desync and hand the rest to the per-page
                // path for safety.
                None => return Some(pi),
            }
        }
        None
    }

    /// Release a run of pages pinned by `get_range` (one claim + one
    /// per-inode lock for all).
    pub fn put_range(&self, fs_id: u64, ino: u64, pages: &[(u64, *const u8)]) {
        let key = cache_key(fs_id, ino);
        let Some(entry) = self.lookup_claimed(key) else {
            return;
        };
        let emptied = {
            let mut g = entry.lock.lock();
            // Contiguous-run fast path (perf-gap-hunt, pagefault 2x
            // push): one range iterator instead of a per-page tree
            // descent; the per-page loop below stays as the fallback
            // for the non-contiguous / invalidated remainder.
            let idx = match Self::unpin_contiguous_locked(&mut g, pages, |p| p.0) {
                Some(k) => k,
                None => pages.len(),
            };
            for &(page_index, _) in &pages[idx..] {
                if let Some(page) = g.get_mut(&page_index) {
                    // Same release discipline as put(): only a put that
                    // actually decremented may release an invalidated
                    // page's frame.
                    let decremented = page.unpin_locked();
                    if decremented
                        && page.count_locked() == 0
                        && page.invalidated
                        && page.take_released_locked()
                    {
                        let pfn = page.pfn;
                        dirty_account_removed(page);
                        g.remove(&page_index);
                        if let Some(page_desc) = page_desc(pfn) {
                                crate::api::mm::page_remove_lru(page_desc);
                        }
                        release_page_frame(pfn);
                        self.total_pages.fetch_sub(1, Ordering::Relaxed);
                    }
                }
            }
            g.is_empty()
        };
        if emptied {
            self.remove_entry(key, &entry);
        }
        drop(entry);
    }

    /// `put_range` on an entry the caller already holds from
    /// `get_range_with_entry` (oc-rc read-path cut): skips the second
    /// bank-claim + probe + strong-count round trip. Passing the entry
    /// is MORE precise than re-probing by key: the pins live in THIS
    /// entry's map even if the slot was vacated and a new generation
    /// re-inserted under the same key between the get and this put
    /// (invalidate marks pinned pages `invalidated`; this same-entry
    /// release path then frees the frame at the final unpin exactly as
    /// the re-probed form would have for the old generation — and a
    /// re-probe would have un-pinned the WRONG generation's page).
    pub fn put_range_with_entry(
        &self,
        fs_id: u64,
        ino: u64,
        entry: &Arc<InodePageCache>,
        pages: &[(u64, *const u8)],
    ) {
        if pages.is_empty() {
            return;
        }
        let key = cache_key(fs_id, ino);
        let emptied = {
            let mut g = entry.lock.lock();
            let idx = match Self::unpin_contiguous_locked(&mut g, pages, |p| p.0) {
                Some(k) => k,
                None => pages.len(),
            };
            for &(page_index, _) in &pages[idx..] {
                if let Some(page) = g.get_mut(&page_index) {
                    let decremented = page.unpin_locked();
                    if decremented
                        && page.count_locked() == 0
                        && page.invalidated
                        && page.take_released_locked()
                    {
                        let pfn = page.pfn;
                        dirty_account_removed(page);
                        g.remove(&page_index);
                        if let Some(page_desc) = page_desc(pfn) {
                                crate::api::mm::page_remove_lru(page_desc);
                        }
                        release_page_frame(pfn);
                        self.total_pages.fetch_sub(1, Ordering::Relaxed);
                    }
                }
            }
            g.is_empty()
        };
        if emptied {
            self.remove_entry(key, entry);
        }
    }
    pub fn put(&self, fs_id: u64, ino: u64, page_index: u64) {
        let key = cache_key(fs_id, ino);
        let Some(entry) = self.lookup_claimed(key) else {
            return;
        };
        let emptied = {
            let mut g = entry.lock.lock();
            if let Some(page) = g.get_mut(&page_index) {
                // Floor at 0: a get() miss (invalidated page) never
                // incremented, so a stale put must not underflow.
                // R14-16 (the dblfree engine): only a put that ACTUALLY
                // decremented (prev >= 1) may release — the old code
                // released whenever the count was seen 0+invalidated, so
                // two stale puts (or a stale put after the real one) each
                // released the SAME frame: the zone double-free stream
                // (pfn 544551/2/5...) behind the surviving corruption.
                let decremented = page.unpin_locked();
                // R7-C2: invalidate_inode left this page in place because a
                // reader held a pin — now that the pin is gone, free it.
                if decremented
                    && page.count_locked() == 0
                    && page.invalidated
                    && page.take_released_locked()
                {
                    let pfn = page.pfn;
                    dirty_account_removed(page);
                    g.remove(&page_index);
                    if let Some(page_desc) = page_desc(pfn) {
                            crate::api::mm::page_remove_lru(page_desc);
                    }
                    release_page_frame(pfn);
                    self.total_pages.fetch_sub(1, Ordering::Relaxed);
                }
            }
            g.is_empty()
        };
        if emptied {
            self.remove_entry(key, &entry);
        }
        drop(entry);
    }

    /// mm-side release for a mapping-owned pin (x86_64 filemap_fault).
    ///
    /// The combined key and page_index come from the page DESCRIPTOR's
    /// mapping/index fields, which insert/insert_batch maintain as the
    /// eviction keys — the unmap/COW/fork paths only have the frame. Same
    /// release discipline as `put()` (R14-16: only a put that actually
    /// decremented may release an invalidated entry's frame).
    pub fn put_by_key(&self, key: u64, page_index: u64) {
        let Some(entry) = self.lookup_claimed(key) else {
            return;
        };
        let emptied = {
            let mut g = entry.lock.lock();
            if let Some(page) = g.get_mut(&page_index) {
                let decremented = page.unpin_locked();
                if decremented
                    && page.count_locked() == 0
                    && page.invalidated
                    && page.take_released_locked()
                {
                    let pfn = page.pfn;
                    dirty_account_removed(page);
                    g.remove(&page_index);
                    if let Some(page_desc) = page_desc(pfn) {
                            crate::api::mm::page_remove_lru(page_desc);
                    }
                    release_page_frame(pfn);
                    self.total_pages.fetch_sub(1, Ordering::Relaxed);
                }
            }
            g.is_empty()
        };
        if emptied {
            self.remove_entry(key, &entry);
        }
        drop(entry);
    }

    /// Batched form of `put_by_key` for the unmap fast path
    /// (perf-gap-hunt 2026-11-04): release the pins of every listed page
    /// index under ONE claim + ONE inode lock, instead of a hash probe +
    /// claim + lock + BTreeMap get PER PAGE (which measured ~40ns/page —
    /// the dominant teardown cost of large PCACHE-mapped munmaps; the
    /// fault-around windows make such runs the common shape). Same
    /// release discipline as put_range, keyed by cache key like
    /// put_by_key (the mm side only has the descriptor's mapping key).
    pub fn put_range_by_key(&self, key: u64, pages: &[u64]) {
        if pages.is_empty() {
            return;
        }
        let Some(entry) = self.lookup_claimed(key) else {
            return;
        };
        let emptied = {
            let mut g = entry.lock.lock();
            // Contiguous-run fast path (same shape as put_range): the
            // unmap pin batches are consecutive indices of one inode.
            let idx = match Self::unpin_contiguous_locked(&mut g, pages, |p| *p) {
                Some(k) => k,
                None => pages.len(),
            };
            for &page_index in &pages[idx..] {
                if let Some(page) = g.get_mut(&page_index) {
                    let decremented = page.unpin_locked();
                    if decremented
                        && page.count_locked() == 0
                        && page.invalidated
                        && page.take_released_locked()
                    {
                        let pfn = page.pfn;
                        dirty_account_removed(page);
                        g.remove(&page_index);
                        if let Some(page_desc) = page_desc(pfn) {
                                crate::api::mm::page_remove_lru(page_desc);
                        }
                        release_page_frame(pfn);
                        self.total_pages.fetch_sub(1, Ordering::Relaxed);
                    }
                }
            }
            g.is_empty()
        };
        if emptied {
            self.remove_entry(key, &entry);
        }
        drop(entry);
    }

    /// mm-side pin acquisition for a frame the page tables are about to
    /// share (fork's COW walk copying a cache-mapped PTE into the child).
    ///
    /// Private cache mappings own exactly one pin per PTE (taken by
    /// `get_phys` at fault time, released by `put_by_key` at unmap/COW);
    /// the fork walk copies the PTE, so it must copy the pin ownership
    /// too — otherwise the parent's unmap would drop the last pin and
    /// eviction could free a frame the child still maps. Pins are also
    /// taken on `invalidated` entries (the R7-C2/R8-3 release accounting
    /// counts every holder; a refused pin would let a later put release
    /// another mapping's frame). Returns false when the entry is gone
    /// entirely (no pin possible; the frame is no longer cache-owned).
    pub fn pin_by_key(&self, key: u64, page_index: u64) -> bool {
        let Some(entry) = self.lookup_claimed(key) else {
            return false;
        };
        let out = {
            let mut g = entry.lock.lock();
            if let Some(page) = g.get_mut(&page_index) {
                // QUARANTINE guard (mmforensics lane): a poisoned frame
                // (ever double-tracked) must not be mapped as file data —
                // its other owners' contents would alias the mapping.
                // Serve a miss instead: callers read from disk into a
                // fresh frame; the stale entry dies at its next eviction
                // (release refused, entry removed — self-healing).
                if crate::arch::mm::mmu_init::alloc_stage_is_late()
                    && crate::arch::mm::mmu_init::PtLedger::is_poisoned(page.pfn as u64)
                {
                    false
                } else {
                    page.pin_locked();
                    if let Some(page_desc) = page_desc(page.pfn) {
                            page_desc.set_flag(PageFlag::Referenced);
                    }
                    true
                }
            } else {
                false
            }
        };
        drop(entry);
        out
    }

    // ==================== MAP_SHARED writeback (session 25) ====================
    //
    // Writable shared mappings alias the cache frame with W, so their
    // stores land DIRECTLY in the frame (mapper coherence by construction).
    // Persistence is then the cache's problem: the frame is marked dirty
    // at W-map install (conservative v1), write(2) writes THROUGH pinned
    // frames instead of invalidating them, and msync/fsync flush dirty
    // frames back to the file. NO pcache lock (wlock or per-inode) is
    // EVER held across the block I/O of a flush (R-WRITESTORM-1):
    // collection and completion are separate locked passes, the flush
    // itself runs pinned but unlocked.

    /// Mark one cached page dirty (a writable shared mapping was just
    /// installed on it). Conservative: a writable mapping MAY write, and
    /// flushing an unwritten page is harmless I/O. Missing/invalidated
    /// entries are ignored (nothing to persist).
    pub fn mark_dirty(&self, fs_id: u64, ino: u64, page_index: u64) {
        self.mark_dirty_by_key(cache_key(fs_id, ino), page_index);
    }

    /// `mark_dirty` by combined cache key — for callers that only hold the
    /// descriptor's eviction keys (mapping/index).
    pub fn mark_dirty_by_key(&self, key: u64, page_index: u64) {
        let Some(entry) = self.lookup_claimed(key) else {
            return;
        };
        {
            let g = entry.lock.lock();
            if let Some(page) = g.get(&page_index) {
                if !page.invalidated {
                    dirty_account_transition(page, true);
                }
            }
        }
        drop(entry);
    }

    /// `mark_dirty` by frame PFN — for PTE-rewrite sites (mprotect
    /// W-upgrades on SHARED cache leaves) that hold the leaf's PPN but not
    /// the file identity. Resolves the cache entry through the page
    /// descriptor's eviction keys (set by insert). No-op for non-cache
    /// frames (mapping() == 0) and foreign descriptors.
    pub fn mark_dirty_pfn(&self, pfn: usize) {
        let Some(page) = page_desc(pfn) else {
            return;
        };
        // INV-FRAME-1: descriptor of a live frame; mapping/index are
        // written only by the cache's insert/release paths.
        let key = page.mapping() as u64;
        if key == 0 {
            return;
        }
        let index = page.index() as u64;
        self.mark_dirty_by_key(key, index);
    }

    /// Post-write(2) cache update: copy the written bytes INTO every fresh
    /// cached frame overlapping [file_off, file_off+data.len()) and leave
    /// the entries in place. This replaces the old whole-inode invalidate
    /// on the write path:
    /// - PINNED entries (shared or private mappings alias them) MUST be
    ///   updated, never invalidated — a pinned-but-invalidated entry serves
    ///   misses, so the next fault would re-read from disk into a SECOND
    ///   frame while live mappings keep writing the old one: permanent
    ///   mapper divergence. Updating the frame keeps every alias coherent
    ///   (Linux writes into the page cache the same way).
    /// - Unpinned entries stay cached and clean: the bytes just reached
    ///   the file, so the frame matches disk — cache stays hot instead of
    ///   being dropped (the old behavior re-fetched the whole inode on
    ///   every write).
    /// The dirty bit is deliberately untouched: a page holding UNFLUSHED
    /// shared-mapping stores outside the written range stays dirty (its
    /// data still exists only in the frame); a clean page written by
    /// write(2) is now on disk, hence clean.
    ///
    /// `skip_pfn`: the writeback path itself calls this with the FLUSH
    /// SOURCE frame (a dirty cache frame being written to disk) — copying
    /// it onto itself is a self-overlap (UB via copy_nonoverlapping, and
    /// pointless); passing its PFN skips exactly that entry.
    ///
    /// memcpy only — no I/O, safe under the per-inode lock.
    pub fn writeback_update_range(
        &self,
        fs_id: u64,
        ino: u64,
        file_off: u64,
        data: &[u8],
        skip_pfn: u64,
    ) {
        self.writeback_update_range_impl(fs_id, ino, file_off, data, &[skip_pfn], false);
    }

    /// Multi-source twin of `writeback_update_range` (the run-batched
    /// flush): EVERY pfn of the run's flush-source frames is skipped —
    /// the staged bytes came FROM those frames, so copying any of them
    /// back would revert a mapper store that raced the staging copy
    /// (POSIX leaves unsynchronized stores vs writeback unordered; the
    /// kernel must not actively undo them). Runs are chunk-bounded
    /// (<= 16 pages), so the membership scan is trivially cheap.
    pub fn writeback_update_range_multi(
        &self,
        fs_id: u64,
        ino: u64,
        file_off: u64,
        data: &[u8],
        skip_pfns: &[u64],
    ) {
        self.writeback_update_range_impl(fs_id, ino, file_off, data, skip_pfns, false);
    }

    /// GUP-DIO twin of `writeback_update_range_multi`: the written
    /// bytes live in PINNED user frames (request offset 0 = the pin's
    /// first byte), not a staging slice. Same walk, same skip discipline;
    /// the copy reads the frames' direct-map aliases (the caller
    /// guarantees the pin covers the whole written range). Only
    /// existing entries are updated — the DIO fast arm leaves no cache
    /// residents to populate.
    pub fn writeback_update_range_pinned(
        &self,
        fs_id: u64,
        ino: u64,
        file_off: u64,
        pins: &crate::mm::gup::PinnedUserPages,
        written: usize,
        skip_pfns: &[u64],
    ) {
        if written == 0 {
            return;
        }
        let key = cache_key(fs_id, ino);
        let first_index = file_off / crate::mm::PAGE_SIZE as u64;
        let last_index = (file_off + written as u64 - 1) / crate::mm::PAGE_SIZE as u64;
        let Some(entry) = self.lookup_claimed(key) else {
            return;
        };
        {
            let g = entry.lock.lock();
            for idx in first_index..=last_index {
                let Some(page) = g.get(&idx) else {
                    continue;
                };
                if page.invalidated {
                    continue; // stale-pinned: same policy as the impl twin
                }
                if page.pfn as u64 != 0 && skip_pfns.contains(&(page.pfn as u64)) {
                    continue;
                }
                let page_off = (idx * crate::mm::PAGE_SIZE as u64).max(file_off);
                let page_end = ((idx + 1) * crate::mm::PAGE_SIZE as u64).min(file_off + written as u64);
                if page_off >= page_end {
                    continue;
                }
                let src_skip = (page_off - file_off) as usize;
                let n = (page_end - page_off) as usize;
                let page_in_frame = (page_off % crate::mm::PAGE_SIZE as u64) as usize;
                let dst = phys_to_virt_ptr(pfn_to_phys(page.pfn));
                // Copy the pin's [src_skip, src_skip+n) into the entry's
                // frame. The user frames are PINNED — no fault possible;
                // the write entry guarantees a full pin, so the pieces
                // cover every byte (the cursor asserts it).
                let mut done = 0usize;
                pins.for_each_piece(src_skip, n, |src, l| {
                    copy_into_page(page.pfn as u64, (page_in_frame + done) as usize, src as *const u8, l);
                    done += l;
                    true
                });
                debug_assert_eq!(done, n, "gup writeback crossed a pin hole");
            }
        }
        drop(entry);
    }

    /// Authoritative-repopulation twin of `writeback_update_range` (tmpfs
    /// truncate coherence): identical body except STALE-BUT-MAPPED frames
    /// are updated too. An invalidated entry whose frame still backs a
    /// live PTE is normally untouchable (a write "resurrects" data the
    /// invalidation promised to retire), but a truncate's zero-fill is
    /// exactly the promise-keeper: [old_size, new_size) must read as
    /// zeros on EVERY face of the file, including a mapper's still-live
    /// alias of a page an earlier shrink marked. Reachable only from
    /// TmpfsNode::truncate (single authoritative writer of that range).
    pub fn writeback_update_range_stale(
        &self,
        fs_id: u64,
        ino: u64,
        file_off: u64,
        data: &[u8],
    ) {
        self.writeback_update_range_impl(fs_id, ino, file_off, data, &[], true);
    }

    fn writeback_update_range_impl(
        &self,
        fs_id: u64,
        ino: u64,
        file_off: u64,
        data: &[u8],
        skip_pfns: &[u64],
        force_stale: bool,
    ) {
        if data.is_empty() {
            return;
        }
        let key = cache_key(fs_id, ino);
        let first_index = file_off / crate::mm::PAGE_SIZE as u64;
        let last_index = (file_off + data.len() as u64 - 1) / crate::mm::PAGE_SIZE as u64;
        let Some(entry) = self.lookup_claimed(key) else {
            return;
        };
        {
            let g = entry.lock.lock();
            for idx in first_index..=last_index {
                let Some(page) = g.get(&idx) else {
                    continue;
                };
                if page.invalidated && !force_stale {
                    // Stale-pinned entry: serves misses, dies on its last put —
                    // leave it alone (its frame is invisible to new faults).
                    // (force_stale: tmpfs truncate zero-fill — see
                    // writeback_update_range_stale.)
                    continue;
                }
                if page.pfn as u64 != 0 && skip_pfns.contains(&(page.pfn as u64)) {
                    // A flush source frame itself (see the doc comment) —
                    // copying a frame onto itself is a self-overlap.
                    continue;
                }
                let page_off = (idx * crate::mm::PAGE_SIZE as u64).max(file_off);
                let page_end = ((idx + 1) * crate::mm::PAGE_SIZE as u64).min(file_off + data.len() as u64);
                if page_off >= page_end {
                    continue;
                }
                let src_skip = (page_off - file_off) as usize;
                let n = (page_end - page_off) as usize;
                copy_into_page(
                    page.pfn as u64,
                    (page_off % crate::mm::PAGE_SIZE as u64) as usize,
                    data[src_skip..src_skip + n].as_ptr(),
                    n,
                );
            }
        }
        drop(entry);
    }

    /// Write-through populate (perf-mm lane, 2026-10-31): the write path's
    /// coherence twin of `writeback_update_range`. First updates every
    /// EXISTING entry in the written range (identical semantics), then
    /// INSERTS the run of pages the write FULLY covers as clean cache
    /// frames — the reference kernel's buffered-write shape: a file that
    /// was just written then mmap'd/read faults from the cache instead of
    /// repopulating through the read machinery on first touch (measured
    /// pmm-decomp: cold fault 14.1 us/page vs warm 0.94 us/page — a 20x
    /// class gap on the p3c shape; the reference kernel populates its
    /// cache at write time, so its "cold" shape is our warm one).
    ///
    /// Partially covered pages (the head/tail of an unaligned write) are
    /// NOT inserted — the uncovered bytes are unknown here; their first
    /// fault populates through the read path as before. Inserted frames
    /// are CLEAN (the write already committed these bytes through the
    /// buffer cache), so the dirty-flush and eviction paths treat them
    /// exactly like read-cached pages.
    ///
    /// The full-page run is contiguous in `data` by construction, so the
    /// insert goes through `insert_batch` (ONE wlock + ONE per-inode lock
    /// + power-of-two buddy allocations for the whole run) instead of a
    /// per-page `insert` — the append/copy rows must not pay a lock round
    /// trip per page.
    pub fn writeback_populate_range(
        &self,
        fs_id: u64,
        ino: u64,
        file_off: u64,
        data: &[u8],
        skip_pfn: u64,
    ) {
        self.writeback_populate_range_multi(fs_id, ino, file_off, data, &[skip_pfn]);
    }

    /// Multi-source twin (the run-batched flush passes every source
    /// frame's PFN — see writeback_update_range_multi).
    pub fn writeback_populate_range_multi(
        &self,
        fs_id: u64,
        ino: u64,
        file_off: u64,
        data: &[u8],
        skip_pfns: &[u64],
    ) {
        if data.is_empty() {
            return;
        }
        // Existing entries first — same-body update (an inserted page
        // below carries exactly its slice of `data`, so there is no
        // second copy for fresh frames).
        self.writeback_update_range_multi(fs_id, ino, file_off, data, skip_pfns);

        let len = data.len() as u64;
        let first_index = file_off / crate::mm::PAGE_SIZE as u64;
        let last_index = (file_off + len - 1) / crate::mm::PAGE_SIZE as u64;

        // The fully covered run is the interior of [first, last]: drop a
        // partial head and a partial tail.
        let mut run_first = first_index;
        if file_off % crate::mm::PAGE_SIZE as u64 != 0 {
            run_first += 1;
        }
        let mut run_last = last_index;
        if (file_off + len) % crate::mm::PAGE_SIZE as u64 != 0 {
            run_last = run_last.saturating_sub(1);
        }
        if run_first > run_last {
            return;
        }
        let src = (run_first * crate::mm::PAGE_SIZE as u64 - file_off) as usize;
        let n = ((run_last - run_first + 1) * crate::mm::PAGE_SIZE as u64) as usize;
        // Bounds are exact: run pages are fully inside [file_off,
        // file_off+len), so src+n <= data.len().
        if src + n > data.len() {
            return;
        }
        self.insert_batch(fs_id, ino, run_first, crate::mm::PAGE_SIZE, &data[src..src + n]);
    }

    /// Collect up to `out.len()` dirty pages in [first_index, last_index]
    /// (inclusive), PINNING each (ref++) so its frame cannot be freed
    /// while the caller flushes it OUTSIDE all pcache locks. Fills `out`
    /// with (page_index, pfn) pairs; returns the count collected. Callers
    /// MUST balance every collected entry with `flush_done`.
    ///
    /// PROGRESS RULE (session 26): a collected-and-flushed page whose
    /// mapping is still up STAYS dirty (flush_done clears the bit only at
    /// pin count zero), so a caller looping "collect until empty" would
    /// re-collect the same leading pages forever — the first msync of any
    /// file with >out.len() live-mapped dirty pages hung in an unbounded
    /// write loop. Callers therefore resume from the LAST COLLECTED index:
    /// pass `first_index = last_collected + 1` on the next call within one
    /// flush operation (the entries collected but not yet flushed keep
    /// their pins, and are skipped naturally by the advanced range).
    pub fn collect_dirty_range(
        &self,
        fs_id: u64,
        ino: u64,
        first_index: u64,
        last_index: u64,
        out: &mut [(u64, u64)],
    ) -> usize {
        let key = cache_key(fs_id, ino);
        if out.is_empty() {
            return 0;
        }
        let Some(entry) = self.lookup_claimed(key) else {
            return 0;
        };
        let n = {
            let mut g = entry.lock.lock();
            let mut n = 0usize;
            for (&idx, page) in g.range_mut(first_index..=last_index) {
                if n == out.len() {
                    break;
                }
                if page.invalidated || !page.dirty.load(Ordering::Acquire) {
                    continue;
                }
                page.pin_locked();
                out[n] = (idx, page.pfn as u64);
                n += 1;
            }
            n
        };
        drop(entry);
        n
    }

    /// Highest byte offset covered by a DIRTY entry of this (fs, inode):
    /// `(max dirty page index + 1) * PAGE_SIZE`. None when no dirty pages.
    ///
    /// Buffered-write revival guard (delayed allocation, 2026-11): a VFS
    /// inode re-instantiated from disk (icache evicted it between a
    /// buffered write and its writeback) carries the ON-DISK size, which
    /// lags the dirty frames still living in the cache — reads clamp at
    /// the stale size and the written bytes vanish until writeback.
    /// `create_vfs_inode_in` lifts the fresh cached size to at least this
    /// bound so the frames stay readable (the reference kernel pins a
    /// dirty inode in its own cache until writeback completes — same
    /// contract, different mechanism).
    pub fn dirty_extent_hint(&self, fs_id: u64, ino: u64) -> Option<u64> {
        let key = cache_key(fs_id, ino);
        let entry = self.lookup_claimed(key)?;
        let out = {
            let g = entry.lock.lock();
            // BTreeMap iterates in key order: the LAST dirty entry has the
            // highest index.
            let last = g
                .iter()
                .rev()
                .find(|(_, p)| !p.invalidated && p.dirty.load(Ordering::Acquire))?;
            Some((last.0 + 1) * crate::mm::PAGE_SIZE as u64)
        };
        drop(entry);
        out
    }

    /// Exact EOF of the surviving dirty tail of (fs, inode): None when no
    /// dirty pages, else `min(dirty_eof, rounded extent of the surviving
    /// dirty pages)`. The min() makes a stale-high watermark (writeback
    /// already cleaned the highest pages) safe: the lift never exceeds
    /// what the surviving frames cover, and any written-back prefix is
    /// covered by the on-disk size the caller already has.
    pub fn dirty_tail_eof(&self, fs_id: u64, ino: u64) -> Option<u64> {
        let key = cache_key(fs_id, ino);
        let entry = self.lookup_claimed(key)?;
        let out = {
            let g = entry.lock.lock();
            let last = g
                .iter()
                .rev()
                .find(|(_, p)| !p.invalidated && p.dirty.load(Ordering::Acquire))?;
            let extent = (last.0 + 1) * crate::mm::PAGE_SIZE as u64;
            Some(core::cmp::min(
                entry.dirty_eof.load(Ordering::Acquire),
                extent,
            ))
        };
        drop(entry);
        out
    }

    /// Record a buffered-write published EOF (delayed allocation): the
    /// CAS-max watermark consulted by `dirty_tail_eof` when a VFS inode
    /// is revived with dirty frames beyond the on-disk size. No-op when
    /// the inode has no cache entry (nothing dirty to lift later).
    pub fn note_dirty_eof(&self, fs_id: u64, ino: u64, eof: u64) {
        let key = cache_key(fs_id, ino);
        if let Some(entry) = self.lookup_claimed(key) {
            let mut cur = entry.dirty_eof.load(Ordering::Relaxed);
            while eof > cur {
                match entry.dirty_eof.compare_exchange(
                    cur,
                    eof,
                    Ordering::AcqRel,
                    Ordering::Acquire,
                ) {
                    Ok(_) => break,
                    Err(c) => cur = c,
                }
            }
            drop(entry);
        }
    }

    /// sync(2)/syncfs(2)/shutdown writeback (delayed allocation,
    /// 2026-11): flush EVERY dirty (fs, inode) entry through the ext4
    /// write machinery — the buffered-write counterpart of
    /// `bio::sync_buffers`. Buffered write(2) leaves data ONLY in dirty
    /// page-cache frames; draining the buffer cache alone would persist
    /// nothing of them.
    ///
    /// Shape: chunked slot-table scan (fixed arrays — no allocation under
    /// wlock), NO pcache lock held across the flush I/O (R-WRITESTORM-1),
    /// live inodes resolved via the ext4 writeback resolver (the icache
    /// first, then a fresh inode materialized from the on-disk inode — a
    /// cache miss may cost performance, never data: the old "miss = skip"
    /// contract silently DROPPED every dirty frame of an inode the
    /// bounded icache had evicted — the sync(2) data-loss bug),
    /// single pass — pages dirtied by a racing writer after their slot
    /// was scanned remain for the next sync (the reference kernel's
    /// sync(2) is not a quiescent point either).
    ///
    /// Returns the (fs_id, ino) targets whose dirty pages were flushed —
    /// the caller persists their data blocks first and their inode-table
    /// blocks afterwards (the ordered-data discipline: data first,
    /// metadata last).
    pub fn flush_all_dirty(&self) -> alloc::vec::Vec<(u64, u64)> {
        const PASS: usize = 32;
        let mut flushed_targets: alloc::vec::Vec<(u64, u64)> = alloc::vec::Vec::new();
        let mut work: [(u64, u64); PASS] = [(0, 0); PASS];
        let mut resume: usize = 0;
        loop {
            let mut n = 0usize;
            {
                let _w = self.wlock.lock();
                // SAFETY: wlock excludes removal, so each claimed slot's
                // reference is stable and the entry is alive.
                'outer: for si in resume..PC_TABLE_CAP {
                    let p = self.slots[si].0.load(Ordering::Acquire);
                    if p.is_null() || p as usize == PC_TOMBSTONE_BITS {
                        continue;
                    }
                    let entry = unsafe { &*p };
                    let has_dirty = {
                        let g = entry.lock.lock();
                        g.iter()
                            .any(|(_, pg)| !pg.invalidated && pg.dirty.load(Ordering::Acquire))
                    };
                    if has_dirty {
                        work[n] = (entry.fs_id, entry.ino);
                        n += 1;
                        if n == PASS {
                            resume = si + 1;
                            break 'outer;
                        }
                    }
                }
            }
            // Best-effort re-entrancy gate (same one shrink_reclaim
            // uses): a concurrent reclaim inside our flush's allocations
            // degrades to clean-only instead of piling a second flush.
            let guarded = WRITEBACK_GUARD
                .compare_exchange(false, true, Ordering::AcqRel, Ordering::Acquire)
                .is_ok();
            for i in 0..n {
                let (fs_id, ino) = work[i];
                // Liveness: the writeback resolver NEVER gives up on a
                // collected dirty inode — the icache is a bounded cache
                // and a miss must not cost the file its dirty frames
                // (the fi-lane sync(2) data loss: an 8 MB file's 2048
                // dirty pages were collected and then skipped because
                // the icache had evicted the inode).
                let flushed =
                    crate::api::ext4::writeback_flush(fs_id, ino, 0, u64::MAX);
                if flushed > 0 {
                    flushed_targets.push((fs_id, ino));
                }
            }
            if guarded {
                WRITEBACK_GUARD.store(false, Ordering::Release);
            }
            if n < PASS {
                break; // table exhausted
            }
        }
        flushed_targets
    }

    /// Complete a flush cycle for entries collected by `collect_dirty_range`:
    /// drop the flush pin and clear the dirty bit ONLY when the count reached
    /// zero AND the flush's write verifiably reached the file (`ok`) — no live
    /// mapping remains that could store into the frame again (every mapping
    /// holds a pin). Concurrent mapper stores racing the flush are
    /// last-writer-wins (POSIX accepted for unsynchronized msync); while a
    /// mapping is up the bit stays set and the next sync rewrites the
    /// page — the conservative v1 substitute for hardware dirty tracking.
    /// An entry invalidated meanwhile (truncate/unlink raced the flush) has
    /// its data discarded instead.
    ///
    /// `entries`: (page_index, pfn, write_ok) — a FAILED or short write
    /// keeps the page dirty for the next sync even at pin count 0: the
    /// frame may be the only surviving copy (mapping already unmapped),
    /// and marking it clean would make it evictable and its data silently
    /// losable.
    pub fn flush_done(&self, fs_id: u64, ino: u64, entries: &[(u64, u64, bool)]) {
        if entries.is_empty() {
            return;
        }
        let key = cache_key(fs_id, ino);
        let Some(entry) = self.lookup_claimed(key) else {
            return;
        };
        let emptied = {
            let mut g = entry.lock.lock();
            for &(page_index, _pfn, write_ok) in entries {
                if let Some(page) = g.get_mut(&page_index) {
                    // Clear dirty ONLY when the flush put brought the pin
                    // count to zero — i.e. NO live mapping remains (every
                    // PCACHE mapping holds a pin) — AND the write succeeded.
                    // While any mapping is up, the page MAY receive new stores
                    // the flush did not see; keeping the dirty bit makes the
                    // next sync rewrite it (the conservative v1 substitute for
                    // hardware dirty tracking). The same rule keeps the
                    // entry dirty after the LAST unmap of an unsynced page:
                    // bounded, unevictable until the next sync on the file,
                    // and coherent for every reader through the frame (POSIX
                    // deferred-writeback latitude).
                    let mut clear_dirty = false;
                    let decremented = page.unpin_locked();
                    if decremented {
                        clear_dirty = page.count_locked() == 0 && !page.invalidated && write_ok;
                    }
                    if clear_dirty {
                        dirty_account_transition(page, false);
                        FL_CLEARED.fetch_add(1, Ordering::Relaxed);
                    } else if !write_ok {
                        FL_KEPT_FAIL.fetch_add(1, Ordering::Relaxed);
                    } else {
                        FL_KEPT_PIN.fetch_add(1, Ordering::Relaxed);
                    }
                    if decremented
                        && page.count_locked() == 0
                        && page.invalidated
                        && page.take_released_locked()
                    {
                        let pfn = page.pfn;
                        dirty_account_removed(page);
                        g.remove(&page_index);
                        if let Some(page_desc) = page_desc(pfn) {
                                crate::api::mm::page_remove_lru(page_desc);
                        }
                        release_page_frame(pfn);
                        self.total_pages.fetch_sub(1, Ordering::Relaxed);
                    }
                }
            }
            // An inode whose last entry was an invalidated frame released
            // here must not leave a permanent empty InodePageCache behind.
            g.is_empty()
        };
        if emptied {
            self.remove_entry(key, &entry);
        }
        drop(entry);
    }

    /// Invalidate all cached pages for a given inode.
    /// Called after writes or truncates to prevent stale data.
    ///
    /// R7-C2: pages with an active reader pin (ref_count > 0) are marked
    /// `invalidated` instead of being freed under the reader's feet —
    /// the final put() releases them, and get() serves a miss meanwhile
    /// so no stale data is ever returned.
    ///
    /// The per-pass doom list is a FIXED array: no allocation may run
    /// under the per-inode lock (R-WRITESTORM-1 — the reclaim slowpath
    /// could reach evict_one → the same entry's per-inode lock). A full
    /// pass loops until an under-full pass proves everything is done;
    /// every full pass frees 64 pages, so this terminates.
    pub fn invalidate_inode(&self, fs_id: u64, ino: u64) {
        let key = cache_key(fs_id, ino);
        let Some(entry) = self.lookup_claimed(key) else {
            return;
        };
        const PASS_MAX: usize = 64;
        loop {
            let mut doomed: [(u64, usize); PASS_MAX] = [(0, 0); PASS_MAX];
            let mut n = 0usize;
            let emptied = {
                let mut g = entry.lock.lock();
                for (&idx, page) in g.iter_mut() {
                    if n == PASS_MAX {
                        break;
                    }
                    // PCACHE_RO alias guard (perf-gap-hunt): a MAPPED frame
                    // with no pin must die exactly like a PINNED one —
                    // invalidated now, reclaimed by the eviction walk's
                    // mapcount check once the last mapping drops.
                    let mapped = {
                        // INV-FRAME-1: read-only is_mapped under the inode
                        // lock.
                        page_desc(page.pfn).is_some_and(|pd| pd.is_mapped())
                    };
                    if page.ref_count.load(Ordering::Acquire) == 0 && !mapped {
                        page.invalidated = true; // marker; removed below
                        doomed[n] = (idx, page.pfn);
                        n += 1;
                    } else {
                        page.invalidated = true; // pinned/mapped: dies on its final put/eviction
                    }
                }
                // Remove the doomed entries while the lock still covers
                // the map; the frames are freed right here (release does
                // not allocate — it ran under the old global lock too).
                for &(idx, pfn) in &doomed[..n] {
                    if let Some(removed) = g.remove(&idx) {
                        dirty_account_removed(&removed);
                    }
                    if let Some(page_desc) = page_desc(pfn) {
                            crate::api::mm::page_remove_lru(page_desc);
                    }
                    release_page_frame(pfn);
                }
                if n > 0 {
                    self.total_pages.fetch_sub(n as u32, Ordering::Relaxed);
                }
                g.is_empty()
            };
            if emptied {
                self.remove_entry(key, &entry);
            }
            if n < PASS_MAX {
                break;
            }
            // Full pass — more unreferenced pages may remain. Loop.
        }
        drop(entry);
    }

    /// Range-bounded twin of `invalidate_inode` (tmpfs truncate, fsx-linux
    /// family): identical doom/invalidation discipline, but only pages at
    /// index >= `from_page` are touched — a byte-granular ftruncate keeps
    /// every page index < ceil(new_size/PAGE) (its partial last page's
    /// tail is zeroed in-frame by the caller via
    /// `writeback_update_range_stale`, mirroring the node-side tail zero).
    pub fn invalidate_inode_range(&self, fs_id: u64, ino: u64, from_page: u64) {
        self.invalidate_inode_span(fs_id, ino, from_page, u64::MAX);
    }

    /// Span-bounded twin of `invalidate_inode` (falloc-wedge lane,
    /// 2026-11-16): only pages at index in [from_page, to_page_excl) are
    /// touched — ext4 PUNCH_HOLE kills exactly its fully-covered pages
    /// with this (the reference truncate_pagecache_range shape); the
    /// punch's partial EDGE pages must survive (they hold live bytes
    /// outside the punched range) and are zero-sliced by the caller via
    /// `writeback_update_range_stale`. The whole-inode form must NOT be
    /// used for range deletions: it drops STILL-DIRTY delayed-allocation
    /// pages too, and outside the deleted range those frames are the
    /// ONLY copy of already-acknowledged writes (the fallocate05/06
    /// data-loss face).
    /// Same invariants as the whole-entry form: unreferenced frames are
    /// freed here; pinned/mapped ones are marked and die on their final
    /// put/eviction; no allocation under any lock (fixed 64-entry doom
    /// list, multi-pass loop).
    pub fn invalidate_inode_span(
        &self,
        fs_id: u64,
        ino: u64,
        from_page: u64,
        to_page_excl: u64,
    ) {
        let key = cache_key(fs_id, ino);
        let Some(entry) = self.lookup_claimed(key) else {
            return;
        };
        const PASS_MAX: usize = 64;
        loop {
            let mut doomed: [(u64, usize); PASS_MAX] = [(0, 0); PASS_MAX];
            let mut n = 0usize;
            let emptied = {
                let mut g = entry.lock.lock();
                for (&idx, page) in g.iter_mut() {
                    if idx < from_page || idx >= to_page_excl {
                        continue; // outside the doomed span: not this call's business
                    }
                    if n == PASS_MAX {
                        break;
                    }
                    // PCACHE_RO alias guard (perf-gap-hunt): a MAPPED frame
                    // with no pin must die exactly like a PINNED one —
                    // invalidated now, reclaimed by the eviction walk's
                    // mapcount check once the last mapping drops.
                    let mapped = {
                        // INV-FRAME-1: read-only is_mapped under the inode
                        // lock.
                        page_desc(page.pfn).is_some_and(|pd| pd.is_mapped())
                    };
                    if page.ref_count.load(Ordering::Acquire) == 0 && !mapped {
                        page.invalidated = true; // marker; removed below
                        doomed[n] = (idx, page.pfn);
                        n += 1;
                    } else {
                        page.invalidated = true; // pinned/mapped: dies on its final put/eviction
                    }
                }
                for &(idx, pfn) in &doomed[..n] {
                    if let Some(removed) = g.remove(&idx) {
                        dirty_account_removed(&removed);
                    }
                    if let Some(page_desc) = page_desc(pfn) {
                            crate::api::mm::page_remove_lru(page_desc);
                    }
                    release_page_frame(pfn);
                }
                if n > 0 {
                    self.total_pages.fetch_sub(n as u32, Ordering::Relaxed);
                }
                g.is_empty()
            };
            if emptied {
                self.remove_entry(key, &entry);
            }
            if n < PASS_MAX {
                break;
            }
            // Full pass — more unreferenced pages may remain. Loop.
        }
        drop(entry);
    }

    // ==================== writer-side ops (wlock) ====================

    /// Insert a newly-read page into the cache.
    /// If the page already exists, just leaves it alone (its pin is the
    /// caller's next get).
    pub fn insert(&self, fs_id: u64, ino: u64, page_index: u64, _block_nr: u64, data: &[u8]) {
        self.insert_ext(fs_id, ino, page_index, _block_nr, data, false);
    }

    /// Buffered-write insert (delayed allocation, 2026-11): the SAME body
    /// as `insert` but the entry is born DIRTY. A clean-then-mark_dirty
    /// sequence has a window where an eviction (another CPU's insert or
    /// shrink) could reclaim the just-inserted unreferenced clean page
    /// before the dirty bit lands — silently dropping a write(2) that
    /// already returned success. Dirty-at-insert removes the window:
    /// evict_one_locked skips dirty pages by design.
    ///
    /// `data` may be EMPTY (zero-fill the whole frame — a fresh tail page
    /// whose uncovered bytes are hole/beyond-EOF zeros); as with `insert`,
    /// bytes past `data.len()` are zeroed, so a partial head page is
    /// materialized by passing only its known prefix... callers that need
    /// scattered coverage copy through a pinned frame instead (get → copy
    /// → put, see the buffered-write path).
    ///
    /// Returns TRUE when this call installed the frame, FALSE when the
    /// page was already cached (the caller's data did NOT land — a racing
    /// writer won the insert; re-loop through get/copy to publish it).
    pub fn insert_dirty(&self, fs_id: u64, ino: u64, page_index: u64, data: &[u8]) -> bool {
        self.insert_ext(fs_id, ino, page_index, 0, data, true)
    }

    /// USER-memory twin of [`Self::insert_dirty`] (BUFW-2X): the frame is
    /// filled by the ONE user→frame copy OUTSIDE every lock (a usercopy
    /// under the per-inode spinlock would be unsound — its fault path can
    /// sleep), then installed born-dirty through `insert_ext`'s verdict
    /// discipline (duplicate / lazy-reap / revive-in-place, R8-3 and
    /// FXW-SQUAT included). A faulting page is never installed: its
    /// zero-filled tail would tear the page's base content beyond the
    /// landed prefix — the frame is freed and FAULT is reported so the
    /// caller ends the write with short-write/EFAULT semantics.
    /// Mapped-but-not-resident user pages do NOT fault here (the uaccess
    /// trap handler demand-fills them).
    pub fn insert_dirty_user(
        &self,
        fs_id: u64,
        ino: u64,
        page_index: u64,
        user_src: usize,
        len: usize,
    ) -> DirtyUserOutcome {
        let key = cache_key(fs_id, ino);

        // R-WRITESTORM-1: allocate + fill BEFORE any pcache lock (the
        // alloc slowpath self-deadlock rule; see insert_ext).
        let phys_addr = alloc_page(GfpFlags::GFP_KERNEL);
        if phys_addr == 0 {
            return DirtyUserOutcome::Contention;
        }
        let copy_len = core::cmp::min(len, crate::mm::PAGE_SIZE);
        // The named user->frame edge (INV-PC-PAGECOPY + the extable
        // primitive's contract: faults return the uncopied tail).
        let uncopied = copy_user_into_page((phys_addr >> 12) as u64, 0, user_src, copy_len);
        if uncopied > 0 {
            // No byte of this page becomes visible; the frame was never
            // stamped or published, so a plain free suffices.
            free_page(phys_addr);
            return DirtyUserOutcome::Fault;
        }

        STAT_MISSES.fetch_add(1, Ordering::Relaxed);

        // First-touch Arc allocation outside wlock (same rule).
        let mut fresh = Some(Arc::new(InodePageCache::new(key, fs_id, ino)));
        let mut parked: PcParkBatch = [const { None }; PC_PARK_BATCH];

        let verdict;
        {
            let w = self.wlock.lock();

            // Eviction headroom (same progress-bounded shape as insert_ext).
            while self.total_pages.load(Ordering::Relaxed) as usize >= max_cached_pages() {
                if !self.evict_one_locked(&w, &mut parked) {
                    break;
                }
            }

            let Some(entry) = self.table_publish(&w, key, &mut fresh) else {
                drop(w);
                self.flush_parked(&mut parked);
                free_page(phys_addr);
                return DirtyUserOutcome::Contention;
            };

            // Dedup verdict + install in ONE per-inode hold; the in-lock
            // data hop for the duplicate/revive arms is a frame→frame
            // memcpy from the pre-filled fresh frame (never a usercopy).
            let mut outcome = DirtyUserOutcome::Installed;
            let mut fresh_unused = false;
            {
                let mut g = entry.lock.lock();

                if g.contains_key(&page_index) {
                    let reap = {
                        let stale = g.get(&page_index).expect("contains_key");
                        if !stale.invalidated {
                            false
                        } else {
                            let mapped =
                                page_desc(stale.pfn).is_some_and(|pd| pd.is_mapped());
                            stale.ref_count.load(Ordering::Acquire) == 0 && !mapped
                        }
                    };
                    if reap {
                        let stale = g.remove(&page_index).expect("contains_key");
                        dirty_account_removed(&stale);
                        if let Some(page_desc) = page_desc(stale.pfn) {
                                crate::api::mm::page_remove_lru(page_desc);
                        }
                        release_page_frame(stale.pfn);
                        self.total_pages.fetch_sub(1, Ordering::Relaxed);
                        // fall through: the fresh frame installs below
                    } else if g.get(&page_index).expect("contains_key").invalidated {
                        // REVIVE-IN-PLACE with the pre-filled frame's
                        // bytes (insert_ext's twin; the data hop is
                        // frame→frame, kernel memory only).
                        let stale = g.get_mut(&page_index).expect("contains_key");
                        stale.invalidated = false;
                        let pfn = stale.pfn;
                        // Frame-to-frame revive (the named edge owns the copy).
                        copy_page_page(pfn_to_phys(pfn), phys_addr as usize, copy_len);
                        dirty_account_transition(stale, true);
                        fresh_unused = true; // data landed; frame freed below
                    } else {
                        // Duplicate fresh entry — the caller re-loops
                        // through pin-and-copy (same contract as
                        // insert_dirty returning false).
                        outcome = DirtyUserOutcome::Contention;
                        fresh_unused = true;
                    }
                }
                if !fresh_unused {
                    let pfn = phys_addr / crate::mm::PAGE_SIZE;
                    if let Some(pd) = page_desc(pfn) {
                        pd.set_page_type(PageType::PageCache);
                        pd.set_flag(PageFlag::UpToDate);
                        pd.set_mapping(key as usize as *mut core::ffi::c_void);
                        pd.set_index(page_index as usize);
                        crate::api::mm::page_add_file_lru_young(pd);
                    }
                    g.insert(
                        page_index,
                        CachedPage {
                            pfn,
                            ref_count: AtomicU32::new(0),
                            invalidated: false,
                            released: core::sync::atomic::AtomicBool::new(false),
                            dirty: core::sync::atomic::AtomicBool::new(true),
                        },
                    );
                    DIRTY_PAGES.fetch_add(1, Ordering::Relaxed);
                    self.total_pages.fetch_add(1, Ordering::Relaxed);
                }
            }
            drop(w);
            self.flush_parked(&mut parked);
            drop(entry);
            if fresh_unused {
                free_page(phys_addr);
            }
            verdict = outcome;
        }
        verdict
    }

    fn insert_ext(
        &self,
        fs_id: u64,
        ino: u64,
        page_index: u64,
        _block_nr: u64,
        data: &[u8],
        dirty: bool,
    ) -> bool {
        let key = cache_key(fs_id, ino);

        // R-WRITESTORM-1: allocate the frame BEFORE taking any pcache
        // lock. alloc_page(GFP_KERNEL) can enter synchronous direct
        // reclaim (page_alloc.rs slowpath), which reaches
        // vmscan::try_to_free_pages -> PageCache::shrink -> wlock —
        // allocating under the lock self-deadlocks the CPU on its own
        // spinlock. Under the OH /data write storm (memory pressure makes
        // the zone slowpath routine) that wedged BOTH CPUs spinning on
        // PAGE_CACHE while the ext4 big-lock holder sat inside insert()
        // (oh b120/b121 deadlock watchdog: lock=...page_cache::PAGE_CACHE,
        // preceded by EXT4-BIGLOCK-STALL).
        let phys_addr = alloc_page(GfpFlags::GFP_KERNEL);
        if phys_addr == 0 {
            return false;
        }

        STAT_MISSES.fetch_add(1, Ordering::Relaxed);

        // The first-touch Arc allocation ALSO stays outside wlock for the
        // same reason. Pre-allocated speculatively; dropped unused when
        // the entry already exists.
        let mut fresh = Some(Arc::new(InodePageCache::new(key, fs_id, ino)));
        let mut parked: PcParkBatch = [const { None }; PC_PARK_BATCH];

        {
            let w = self.wlock.lock();

            // Evict if needed (with progress check to prevent infinite loop
            // when all cached pages have ref_count > 0). The frame is already
            // in hand, so exceeding the soft cap by a page here is harmless —
            // the next insert evicts. The parked batch bounds the loop too
            // (emptied entries park there; they are drained right after the
            // wlock drops — the overshoot is the old soft-cap latitude).
            while self.total_pages.load(Ordering::Relaxed) as usize >= max_cached_pages() {
                if !self.evict_one_locked(&w, &mut parked) {
                    break; // Cannot evict — all pages in use
                }
            }

            let Some(entry) = self.table_publish(&w, key, &mut fresh) else {
                // Table full (or no fresh entry): degrade to no-cache —
                // the page is simply not cached; correctness unaffected.
                drop(w);
                self.flush_parked(&mut parked);
                free_page(phys_addr);
                return false;
            };

            // Dedup verdict + install in ONE per-inode hold. A duplicate
            // never returns from inside the guards — the frame return is
            // scheduled here and executed after all locks drop.
            let mut duplicate = false;
            // Revive-in-place of a retired-but-live squatter (see the
            // REVIVE-IN-PLACE block below): the caller's data landed in
            // the existing frame, so the call reports success while the
            // pre-allocated frame is still freed like a duplicate's.
            let mut revived = false;
            {
                let mut g = entry.lock.lock();

                // If already cached and fresh, nothing to do. (R7-C2:
                // insert used to bump ref_count with no matching put — a
                // permanent pin leak that defeated eviction and pinned
                // stale data forever.) R8-3: an invalidated-but-still-
                // pinned entry — the final put() owns the old frame; the
                // previous code freed the new frame HERE regardless of
                // ref_count, handing the pinned reader a freed physical
                // page (exactly what invalidate_inode promises not to
                // do). Skip caching this read; the old entry dies via
                // its refcount. The pre-allocated frame is unused on
                // all paths — returned below.
                //
                // LAZY REAP (FXW-SQUAT, fsx-linux ext4 face): an entry
                // retired by an earlier invalidate whose frame was
                // pinned/mapped BACK THEN can outlive its last
                // reference — put()'s per-page fallback removes such an
                // entry only when a put actually runs, and a frame whose
                // pins all evaporated through entry-replacement paths
                // never sees one. The retired entry then squats the page
                // index: every later insert (fd write populate, fault
                // bounce, zero fill) dedups against it and frees its own
                // fresh frame — the page can NEVER be cached again, and
                // the fault path falls to the private-copy arm (mapper
                // data invisible to every other face of the file). Two
                // resolutions live here: a retired entry with NO pin and
                // NO live mapping is REAPED (frame freed exactly like
                // invalidate's doomed path) so this insert installs the
                // new frame; a retired-but-LIVE one (pin or mapcount
                // held — the d37643abb KNOWN LIMIT) is REVIVED IN PLACE
                // with this insert's data (see the REVIVE-IN-PLACE arm
                // below) so the index resolves to current data and the
                // frame's every alias stays coherent.
                if g.contains_key(&page_index) {
                    let reap = {
                        let stale = g.get(&page_index).expect("contains_key");
                        if !stale.invalidated {
                            false
                        } else {
                            let mapped = {
                                page_desc(stale.pfn).is_some_and(|pd| pd.is_mapped())
                            };
                            stale.ref_count.load(Ordering::Acquire) == 0 && !mapped
                        }
                    };
                    if reap {
                        let stale = g.remove(&page_index).expect("contains_key");
                        dirty_account_removed(&stale);
                        if let Some(page_desc) = page_desc(stale.pfn) {
                                crate::api::mm::page_remove_lru(page_desc);
                        }
                        release_page_frame(stale.pfn);
                        self.total_pages.fetch_sub(1, Ordering::Relaxed);
                        // fall through: the fresh frame installs below
                    } else if g.get(&page_index).expect("contains_key").invalidated {
                        // REVIVE-IN-PLACE (fsx-linux ext4 face, the
                        // d37643abb KNOWN LIMIT): the squatter is
                        // retired-but-LIVE (pinned or still mapped — Rux
                        // never zaps PTEs), so it cannot be reaped, and
                        // failing this insert (the old `duplicate` arm)
                        // left the page PERMANENTLY uncachable: every
                        // populate deduped against the squatter and
                        // filemap faults bounced to the private-copy
                        // arm — mapper stores invisible to every other
                        // face of the file. Instead the entry is revived
                        // WITH THIS INSERT'S DATA: the frame is
                        // overwritten with exactly what a fresh install
                        // would carry (disk content on the read path,
                        // the written span for insert_dirty) and
                        // un-retired, so the index resolves to the
                        // current entry again and every alias — the old
                        // mapper's PTE included — is coherent through
                        // the ONE frame (the reference kernel's
                        // single-page-per-index shape; stores racing the
                        // revive are last-writer-wins, POSIX latitude).
                        // Pins, mapcount and LRU membership are
                        // untouched: their owners put exactly as before,
                        // into an entry that is a full citizen again.
                        // The pre-allocated frame is unused — freed
                        // below like a duplicate's.
                        let stale = g.get_mut(&page_index).expect("contains_key");
                        stale.invalidated = false;
                        let pfn = stale.pfn;
                        // Fill the revived frame (the named edge).
                        fill_page_from(pfn_to_phys(pfn), data);
                        // `dirty` is always touched through atomic ops
                        // (leg-54 note): the revived frame carries
                        // exactly this insert's content — clean for a
                        // read install (frame == disk), dirty for
                        // insert_dirty (bytes not yet persisted).
                        dirty_account_transition(stale, dirty);
                        revived = true;
                    } else {
                        duplicate = true;
                    }
                }
                if g.contains_key(&page_index) {
                    duplicate = true;
                } else {
                    let pfn = phys_addr / crate::mm::PAGE_SIZE;

                    // Mark page descriptor and add to LRU
                    if let Some(pd) = page_desc(pfn) {
                        pd.set_page_type(PageType::PageCache);
                        pd.set_flag(PageFlag::UpToDate);
                        // Store reverse-lookup info for eviction (the combined key)
                        pd.set_mapping(key as usize as *mut core::ffi::c_void);
                        pd.set_index(page_index as usize);
                        // Add to LRU_INACTIVE_FILE at the YOUNG end — must happen after
                        // setting flags. (Two-tier policy: young at head, reclaim from
                        // tail; linking at the tail made the eviction scan see the
                        // freshest page first.)
                        crate::api::mm::page_add_file_lru_young(pd);
                    }

                    // Fill the fresh frame (the named edge).
                    fill_page_from(phys_addr as usize, data);

                    g.insert(
                        page_index,
                        CachedPage {
                            pfn,
                            ref_count: AtomicU32::new(0),
                            invalidated: false,
                            released: core::sync::atomic::AtomicBool::new(false),
                            dirty: core::sync::atomic::AtomicBool::new(dirty),
                        },
                    );
                    if dirty {
                        DIRTY_PAGES.fetch_add(1, Ordering::Relaxed);
                    }
                    self.total_pages.fetch_add(1, Ordering::Relaxed);
                }
            }
            drop(w);
            self.flush_parked(&mut parked);
            drop(entry);
            if duplicate || revived {
                free_page(phys_addr);
            }
            !duplicate
        }
    }

    /// Bulk-insert a run of consecutive pages whose data lives in ONE
    /// contiguous buffer (`buf`, `block_size` bytes per page).
    ///
    /// The read-ahead path used to call `insert` per 4 KiB page: each call
    /// took the global lock, ran the eviction check, did a BTreeMap
    /// lookup+insert, allocated one order-0 frame, and copied 4 KiB —
    /// ~90µs/page under TCG, which was ~4x the cost of the underlying disk
    /// I/O (measured: 181ms insert vs 12ms device wait for an 8 MiB fill).
    /// This path amortizes all of it:
    /// - ONE wlock + ONE per-inode lock acquisition and ONE eviction pass
    ///   for the whole run;
    /// - power-of-two buddy allocations (up to 64 pages) instead of per-page
    ///   order-0 allocations;
    /// - ONE memcpy per buddy chunk instead of per page;
    /// - direct per-page inserts into the pre-resolved entry. Duplicate
    ///   frames never leak: a key already cached (or invalidated-but-pinned,
    ///   R8-3) is skipped and its freshly popped frame released right away.
    pub fn insert_batch(
        &self,
        fs_id: u64,
        ino: u64,
        first_index: u64,
        block_size: usize,
        buf: &[u8],
    ) {
        let _ = self.insert_batch_ext(fs_id, ino, first_index, block_size, BatchFill::Slice(buf), false);
    }

    /// Dirty-write twin of [`Self::insert_batch`] (DIO-CONC): installs the
    /// run's frames BORN DIRTY and returns how many leading pages were
    /// consumed (installed or overwritten). A page already cached when the
    /// batch reaches it is OVERWRITTEN with this batch's bytes and turned
    /// dirty — the read batch's skip-duplicate arm would silently drop the
    /// writer's data — and an early stop (OOM / table full) reports the
    /// consumed prefix so the caller falls back to its per-page path for
    /// the tail. This is the buffered-write(2) fast path: one wlock pass
    /// per 64 pages, order-0 batched allocations, unlocked memcpys (the
    /// per-page insert_dirty loop cost ~0.6 µs/page on the pair rig).
    pub fn insert_dirty_batch(
        &self,
        fs_id: u64,
        ino: u64,
        first_index: u64,
        block_size: usize,
        buf: &[u8],
    ) -> usize {
        self.insert_batch_ext(fs_id, ino, first_index, block_size, BatchFill::Slice(buf), true)
            .0
    }

    /// USER-memory twin of [`Self::insert_dirty_batch`] (BUFW-2X): the
    /// batch's frames are filled straight from user memory — ONE copy
    /// per page, user→frame, outside every lock (the reference kernel's
    /// copy_page_from_iter shape; the syscall staging buffer and its
    /// second copy are skipped). Returns (pages consumed from the front,
    /// user-fault flag). A user page that FAULTS the copy stops the
    /// batch at the previous page — the faulting page's bytes are never
    /// installed (its partially-copied frame is discarded: a zero-padded
    /// born-dirty install would tear the page's base content beyond the
    /// landed prefix); the caller's per-page path then meets the same
    /// fault head-on and applies the short-write/EFAULT semantics.
    /// Mapped-but-not-resident user pages do NOT fault here — the
    /// uaccess trap handler demand-fills them (exception-table copy).
    pub fn insert_dirty_batch_user(
        &self,
        fs_id: u64,
        ino: u64,
        first_index: u64,
        block_size: usize,
        user_src: usize,
        len: usize,
    ) -> (usize, bool) {
        self.insert_batch_ext(
            fs_id,
            ino,
            first_index,
            block_size,
            BatchFill::User { ptr: user_src, len },
            true,
        )
    }

    /// Shared body of the batch inserters. `mark_dirty` selects the write
    /// semantics (born-dirty installs, duplicate OVERWRITE — see
    /// insert_dirty_batch); the read shape keeps skip-duplicate.
    /// Returns (pages consumed from the front, user-fault flag); read
    /// callers ignore both.
    fn insert_batch_ext(
        &self,
        fs_id: u64,
        ino: u64,
        first_index: u64,
        block_size: usize,
        fill: BatchFill<'_>,
        mark_dirty: bool,
    ) -> (usize, bool) {
        // Early-return arms below (table-full, duplicate, revive-in-place)
        // free frames that the unlocked pre-stage ALREADY described as
        // cache pages (type/UpToDate/mapping/index — the perf-review
        // pre-marking). The zone's alloc path clears flags+refcount but
        // NOT type/mapping/index, so a frame discarded with its pre-mark
        // keeps claiming to be a LIVE cache entry for the rest of its
        // recycling life: free-side guards misfire (mmforensics' 2026-11-15
        // boot: 29 refused frees from insert_batch's own stack) and every
        // identity-consulting path misjudges the frame. Strip the identity
        // before every discard free — same stores release_page_frame does.
        #[inline]
        fn discard_prepared_frame(phys: usize) {
            if let Some(pd) = page_desc(phys / crate::mm::PAGE_SIZE) {
                // Frame was allocated by this batch's pre-stage (exclusive
                // ownership) and is being discarded.
                pd.set_page_type(PageType::Normal);
                pd.clear_flag(PageFlag::UpToDate);
                pd.set_mapping(core::ptr::null_mut());
                pd.set_index(0);
            }
            free_page(phys);
        }

        if block_size == 0 || fill.len() < block_size {
            return (0, false);
        }
        let npages = fill.len() / block_size;
        if npages <= 1 || block_size != crate::mm::PAGE_SIZE {
            if let BatchFill::User { .. } = fill {
                // A user batch of a single page (or a sub-frame block
                // size) saves nothing — report the whole span unconsumed
                // so the caller's per-page path (with its fault
                // semantics) serves it.
                return (0, false);
            }
            // Single page, or a block size that does not fill a frame (the
            // packed contiguous copy below would pack blocks without their
            // per-page zero padding) — per-page inserts keep that layout.
            let BatchFill::Slice(buf) = fill else { unreachable!() };
            let mut consumed = 0usize;
            for k in 0..npages {
                let end = core::cmp::min((k + 1) * block_size, buf.len());
                if mark_dirty {
                    if self.insert_dirty(fs_id, ino, first_index + k as u64, &buf[k * block_size..end]) {
                        consumed += 1;
                    } else {
                        // Duplicate cached page the per-page write path
                        // never got to pin-copy: still consumed for the
                        // caller's accounting only when the bytes landed
                        // — insert_dirty returns false on duplicates, so
                        // stop here and let the per-page caller serve it.
                        break;
                    }
                } else {
                    self.insert(
                        fs_id,
                        ino,
                        first_index + k as u64,
                        0,
                        &buf[k * block_size..end],
                    );
                    consumed += 1;
                }
            }
            return (consumed, false);
        }
        let key = cache_key(fs_id, ino);

        // R-WRITESTORM-1 (the insert twin): allocate EVERY frame BEFORE
        // taking any pcache lock. The old loop called
        // alloc_page_batch(GFP_KERNEL) under the lock; under memory
        // pressure that enters the page-allocator slowpath →
        // vmscan::try_to_free_pages → PageCache::shrink → wlock — the
        // SAME lock the caller already holds: a spinlock self-deadlock
        // with one CPU spinning forever (the OH b120/b121 wedge insert()
        // was fixed for, resurrected here at RAM-scale cache pressure —
        // every insert batch wedged a CPU, SA .so loads never completed).
        // Chunked 64 frames at a time: each chunk allocates unlocked, then
        // one locked section does eviction headroom + inserts for the
        // chunk. (A 256-chunk was measured neutral on the 1 MiB row — the
        // cost is per-page free-list surgery, not per-chunk lock overhead
        // — while quadrupling the zone-lock hold; keep the small holds.)
        const ALLOC_CHUNK: usize = 64;
        let mut phys_buf: [usize; ALLOC_CHUNK] = [0; ALLOC_CHUNK];

        let mut done: usize = 0;
        while done < npages {
            let want = core::cmp::min(ALLOC_CHUNK, npages - done);
            let got = alloc_page_batch(GfpFlags::GFP_KERNEL, want, &mut phys_buf[..want]);
            if got == 0 {
                // Out of memory entirely: stop the batch here; the caller's
                // per-page fallback covers the tail.
                break;
            }

            // Fill and describe every frame BEFORE any pcache lock (perf
            // review 2026-10-31): the chunk's memcpy used to run under
            // wlock + the per-inode lock — up to 64x4 KiB of copying with
            // both serialization points held, stalling every reader and
            // every other inserter for the duration. The frames are still
            // private here (allocated above, not yet published), so the
            // copy and the descriptor stamping need no lock. A frame whose
            // index turns out to be a duplicate at insert time pays one
            // wasted copy (the rare dedup path) and is freed exactly as
            // the old in-lock order did.
            //
            // BUFW-2X: the USER fill copies each page straight from user
            // memory — the ONE user→frame copy, still outside every lock
            // (a usercopy under a spinlock is unsound: its fault path can
            // sleep). A mapped-but-not-resident user page does NOT stop
            // the batch — the uaccess trap handler demand-fills it and
            // the copy re-executes; only an unmapped page reports the
            // uncopied tail, and that page must never become visible.
            let mut faulted_at: Option<usize> = None;
            for k in 0..got {
                let phys = phys_buf[k];
                let pfn = phys / crate::mm::PAGE_SIZE;
                let page_index = first_index + done as u64 + k as u64;
                let src_off = (done + k) * block_size;
                let copy_len = core::cmp::min(crate::mm::PAGE_SIZE, fill.len() - src_off);
                match fill {
                    BatchFill::Slice(buf) => {
                        copy_into_page((phys >> 12) as u64, 0, buf[src_off..src_off + copy_len].as_ptr(), copy_len);
                    }
                    BatchFill::User { ptr, .. } => {
                        // SAFETY: dst is the fresh zone frame (a valid
                        // PAGE_SIZE kernel destination); the user side is
                        // access_ok-checked and faults through the
                        // exception table inside the primitive — any
                        // address is sound to pass, and the uncopied tail
                        // of dst is zero-filled by the primitive.
                        // (A movnti non-temporal variant measured 10x
                        // WORSE under this KVM rig — see BUFW-2X.md — so
                        // the regular rep movsb stays — now inside the
                        // named user->frame edge.)
                        let uncopied = copy_user_into_page((phys >> 12) as u64, 0, ptr + src_off, copy_len);
                        if uncopied > 0 {
                            // FAULT: the page's bytes must not become
                            // visible — a partially-copied frame installed
                            // born-dirty would zero-overwrite the page's
                            // base content beyond the landed prefix (a
                            // torn frame). Discard this frame and the
                            // chunk's not-yet-filled tail; the batch stops
                            // at the previous page and the caller's
                            // per-page path meets the fault head-on.
                            faulted_at = Some(k);
                            break;
                        }
                    }
                }
                if let Some(pd) = page_desc(pfn) {
                    // pfn came from the zone allocator; its page descriptor
                    // is valid for the frame's lifetime (INV-FRAME-1).
                    pd.set_page_type(PageType::PageCache);
                    pd.set_flag(PageFlag::UpToDate);
                    pd.set_mapping(key as usize as *mut core::ffi::c_void);
                    pd.set_index(page_index as usize);
                }
            }

            // USER FAULT (BUFW-2X): install the successfully-filled prefix
            // of this chunk, discard the faulted page and the unfilled
            // tail, and stop the batch. The prefix's frames are private
            // (not yet published), so nothing partial is ever visible.
            let n_install = match faulted_at {
                Some(k) => k,
                None => got,
            };
            if n_install == 0 {
                for j in 0..got {
                    discard_prepared_frame(phys_buf[j]);
                }
                return (done, true);
            }

            // The first-touch Arc allocation stays outside wlock (same
            // R-WRITESTORM-1 rule as insert); dropped unused when the
            // entry already exists.
            let mut fresh = Some(Arc::new(InodePageCache::new(key, fs_id, ino)));
            let mut parked: PcParkBatch = [const { None }; PC_PARK_BATCH];
            let mut appended: u32 = 0;

            {
                let w = self.wlock.lock();

                // Eviction headroom for this chunk (soft cap — bounded
                // loop, the batch may proceed slightly over if everything
                // is pinned or the park batch fills).
                let mut evict_tries = 0u32;
                while self.total_pages.load(Ordering::Relaxed) as usize + n_install > max_cached_pages() {
                    if !self.evict_one_locked(&w, &mut parked) {
                        evict_tries += 1;
                        if evict_tries >= 32 {
                            break;
                        }
                    }
                    if parked.iter().all(|p| p.is_some()) {
                        break;
                    }
                }

                STAT_MISSES.fetch_add(1, Ordering::Relaxed);

                let Some(entry) = self.table_publish(&w, key, &mut fresh) else {
                    // Table full: drop this chunk's frames, stop the batch.
                    drop(w);
                    for j in 0..got {
                        discard_prepared_frame(phys_buf[j]);
                    }
                    self.flush_parked(&mut parked);
                    break;
                };

                // Copy per page (order-0 frames are not contiguous), describe,
                // link to the LRU in one locked batch, and insert into the
                // inode map directly. Order-0 deliberately: eviction frees
                // page-cache frames one page at a time, higher-order buddy
                // chunks failed expensively (reclaim + compaction slowpaths).
                let mut lru_batch: [*mut crate::mm::page_desc::Page; ALLOC_CHUNK] = [core::ptr::null_mut(); ALLOC_CHUNK];
                let mut lru_n: usize = 0;
                {
                    let mut g = entry.lock.lock();
                    // BUFW-2X: ONE map traversal per page via entry() —
                    // the old shape paid contains_key + a second
                    // contains_key + insert (three descents of a 12k-entry
                    // tree at the 48 MiB mark, ~400c/page under this lock;
                    // the measured lock pass was 94-113k cycles per 1 MiB
                    // op, the row's second-largest term after the copies).
                    use alloc::collections::btree_map::Entry;
                    for k in 0..n_install {
                        let phys = phys_buf[k];
                        let pfn = phys / crate::mm::PAGE_SIZE;
                        let page_index = first_index + done as u64 + k as u64;
                        let src_off = (done + k) * block_size;
                        let copy_len =
                            core::cmp::min(crate::mm::PAGE_SIZE, fill.len().saturating_sub(src_off));
                        // Duplicate-key discipline of insert(): an existing
                        // fresh entry is left alone (no frame clobber/leak);
                        // an invalidated-but-pinned one (R8-3) is skipped
                        // too. LAZY REAP (FXW-SQUAT, see insert_ext): a
                        // retired entry with no pin and no live mapping is
                        // removed here so the batch's frame installs
                        // instead of being dropped against a squatter.
                        match g.entry(page_index) {
                            Entry::Vacant(v) => {
                                // Install the pre-filled fresh frame (born
                                // dirty on the write shape).
                                if let Some(pd) = page_desc(pfn) {
                                    // pfn came from the zone allocator;
                                    // descriptor valid (INV-FRAME-1).
                                    pd.set_page_type(PageType::PageCache);
                                    pd.set_flag(PageFlag::UpToDate);
                                    pd.set_mapping(
                                        key as usize as *mut core::ffi::c_void,
                                    );
                                    pd.set_index(page_index as usize);
                                    lru_batch[lru_n] = pd as *const crate::mm::page_desc::Page as *mut crate::mm::page_desc::Page;
                                    lru_n += 1;
                                }
                                v.insert(CachedPage {
                                    pfn,
                                    ref_count: AtomicU32::new(0),
                                    invalidated: false,
                                    released: core::sync::atomic::AtomicBool::new(false),
                                    dirty: core::sync::atomic::AtomicBool::new(mark_dirty),
                                });
                                appended += 1;
                            }
                            Entry::Occupied(mut e) => {
                                if !e.get().invalidated {
                                    // Duplicate index. READ shape: the frame
                                    // was already filled and described in the
                                    // unlocked stage above — release it exactly
                                    // as the old in-lock order did (no
                                    // clobber, no leak). WRITE shape: the
                                    // cached page must RECEIVE this batch's
                                    // bytes (the per-page path's pin-and-copy
                                    // outcome, last-writer-wins) and turn
                                    // dirty — the skip arm would drop the
                                    // write silently.
                                    //
                                    // BUFW-2X: the bytes ride the PRE-FILLED
                                    // FRESH FRAME — the user fast path's one
                                    // user→frame copy already landed them
                                    // outside every lock, and a usercopy
                                    // under this spinlock would be unsound
                                    // (its fault path can sleep). The fresh
                                    // frame holds exactly what the slice
                                    // source would (the pre-stage filled it
                                    // from the same offset), so the
                                    // kernel-slice batch is byte-identical
                                    // through this hop.
                                    if mark_dirty {
                                        let stale = e.get_mut();
                                        let dup_pfn = stale.pfn;
                                        // SAFETY: dup_pfn is this entry's
                                        // zone frame; the linear map covers
                                        // PAGE_SIZE bytes and copy_len <=
                                        // it; phys is this batch's private
                                        // pre-filled frame.
                                        copy_page_page(pfn_to_phys(dup_pfn), phys as usize, copy_len);
                                        dirty_account_transition(stale, true);
                                    }
                                    // The pre-marked cache identity is
                                    // stripped first (see
                                    // discard_prepared_frame above).
                                    discard_prepared_frame(phys);
                                    continue;
                                }
                                let reap = {
                                    let stale = e.get();
                                    let mapped = page_desc(stale.pfn)
                                        .is_some_and(|pd| pd.is_mapped());
                                    stale.ref_count.load(Ordering::Acquire) == 0 && !mapped
                                };
                                if reap {
                                    let stale = e.remove();
                                    dirty_account_removed(&stale);
                                    if let Some(pd) = page_desc(stale.pfn) {
                                            crate::api::mm::page_remove_lru(pd);
                                    }
                                    release_page_frame(stale.pfn);
                                    self.total_pages.fetch_sub(1, Ordering::Relaxed);
                                    // Squatter gone: install the batch frame.
                                    if let Some(pd) = page_desc(pfn) {
                                        // As the Vacant arm.
                                        pd.set_page_type(PageType::PageCache);
                                        pd.set_flag(PageFlag::UpToDate);
                                        pd.set_mapping(
                                            key as usize as *mut core::ffi::c_void,
                                        );
                                        pd.set_index(page_index as usize);
                                        lru_batch[lru_n] = pd as *const crate::mm::page_desc::Page as *mut crate::mm::page_desc::Page;
                                        lru_n += 1;
                                    }
                                    g.insert(
                                        page_index,
                                        CachedPage {
                                            pfn,
                                            ref_count: AtomicU32::new(0),
                                            invalidated: false,
                                            released: core::sync::atomic::AtomicBool::new(
                                                false,
                                            ),
                                            dirty: core::sync::atomic::AtomicBool::new(
                                                mark_dirty,
                                            ),
                                        },
                                    );
                                    appended += 1;
                                    continue;
                                }
                                // REVIVE-IN-PLACE (see insert_ext's twin):
                                // a retired-but-live squatter (pinned or
                                // still mapped) is revived WITH THIS
                                // BATCH PAGE'S DATA instead of blocking
                                // the install — the index resolves to
                                // current data and every alias of the
                                // frame stays coherent. The batch frame
                                // is released exactly like a duplicate's.
                                // (Bytes ride the pre-filled fresh frame —
                                // see the duplicate arm above.)
                                let stale = e.get_mut();
                                stale.invalidated = false;
                                let revive_pfn = stale.pfn;
                                // Frame revive (the named edge).
                                copy_page_page(pfn_to_phys(revive_pfn), phys as usize, copy_len);
                                // Read-path batch: the revived frame now
                                // matches disk — clean; the dirty batch's
                                // revive carries this batch's bytes, so it
                                // transitions dirty (atomic-op rule either
                                // way).
                                dirty_account_transition(stale, mark_dirty);
                                discard_prepared_frame(phys);
                                continue;
                            }
                        }
                    }
                    if lru_n > 0 {
                        crate::api::mm::page_add_file_lru_young_batch(&lru_batch[..lru_n]);
                    }
                    if mark_dirty && appended > 0 {
                        DIRTY_PAGES.fetch_add(appended as usize, Ordering::Relaxed);
                    }
                    self.total_pages.fetch_add(appended, Ordering::Relaxed);
                }
            }
            self.flush_parked(&mut parked);
            done += n_install;
            if faulted_at.is_some() {
                // USER FAULT: discard the faulted page and the unfilled
                // tail (frames are private — nothing partial is visible),
                // stop the batch with the installed prefix.
                for j in n_install..got {
                    discard_prepared_frame(phys_buf[j]);
                }
                return (done, true);
            }
        }
        (done, false)
    }

    /// Shrink the page cache by evicting up to `nr_to_scan` unreferenced pages.
    ///
    /// Called by the page reclaim engine (kswapd / direct reclaim) when zone
    /// free pages drop below watermarks.  Only pages with ref_count == 0 are
    /// evicted — pages actively being read are left alone.
    ///
    /// Returns the number of pages actually freed.
    pub fn shrink(&self, nr_to_scan: usize) -> usize {
        let mut freed = 0usize;
        while freed < nr_to_scan {
            if self.total_pages.load(Ordering::Relaxed) == 0 {
                break;
            }
            let mut parked: PcParkBatch = [const { None }; PC_PARK_BATCH];
            let evicted = {
                let w = self.wlock.lock();
                self.evict_one_locked(&w, &mut parked)
            };
            self.flush_parked(&mut parked);
            if !evicted {
                break;
            }
            freed += 1;
        }
        freed
    }

    /// Dirty-work collect, shared by [`shrink_reclaim`] and
    /// [`writeback_recover`] (falloc-wedge lane, 2026-11-16).
    ///
    /// Fills `work` with up to `work.len()` (fs_id, ino, first_idx,
    /// last_idx) dirty windows. FULL-TABLE WALK with a rotating start
    /// and EARLY EXIT (falloc-wedge round 2): the first cut scanned a
    /// rotating 512-slot window per call, which covers the 32768-slot
    /// table only once per 64 calls — under the fill balloon (a handful
    /// of dirty inodes among 32k slots) the recovery pass found the
    /// balloon inode once per ~64 watermark trips and the mark never
    /// un-tripped (every 4 KiB write then paid a synchronous flush of
    /// itself; measured on the fallocate05 fill, run/f05e). The walk
    /// now scans slots until the work array is full; the rotating start
    /// spreads WHICH dirty inodes are found first across calls. The
    /// monopolist bound from the pcachewedge lane is kept where it
    /// matters: the per-inode iteration stays capped (MAX_INODE_SCAN
    /// BTree steps — a giant inode cannot monopolize the wlock), and an
    /// empty/clean slot costs one atomic load, so the worst-case walk
    /// (nothing dirty anywhere) is 32768 atomic loads plus a bounded
    /// per-dirty-inode peek, not a BTree marathon.
    fn collect_wb_work(
        &self,
        work: &mut [(u64, u64, u64, u64)],
        window_pages: u64,
    ) -> usize {
        const MAX_INODE_SCAN: usize = 2048;
        static COLLECT_CURSOR: AtomicUsize = AtomicUsize::new(0);
        let mut n_work = 0usize;
        let _w = self.wlock.lock();
        let start = COLLECT_CURSOR.fetch_add(1, Ordering::Relaxed) % PC_TABLE_CAP;
        'outer: for k in 0..PC_TABLE_CAP {
            let si = (start + k) % PC_TABLE_CAP;
            let p = self.slots[si].0.load(Ordering::Acquire);
            if p.is_null() || p as usize == PC_TOMBSTONE_BITS {
                continue;
            }
            // SAFETY: wlock excludes removal, so the slot's reference is
            // stable and the entry is alive.
            let entry = unsafe { &*p };
            let g = entry.lock.lock();
            let mut first: Option<u64> = None;
            let mut last: u64 = 0;
            let mut stepped = 0usize;
            for (&idx, page) in g.iter() {
                stepped += 1;
                if stepped > MAX_INODE_SCAN {
                    break; // giant inode — the flush below takes the whole range
                }
                if page.invalidated
                    || page.count_locked() != 0
                    || !page.dirty.load(Ordering::Acquire)
                {
                    continue;
                }
                if first.is_none() {
                    first = Some(idx);
                }
                last = idx;
                if idx - first.unwrap_or(idx) + 1 >= window_pages {
                    break;
                }
            }
            if let Some(first) = first {
                work[n_work] = (entry.fs_id, entry.ino, first, last);
                n_work += 1;
                if n_work == work.len() {
                    break 'outer;
                }
            }
        }
        n_work
    }

    /// Targeted clean eviction for ONE inode (falloc-wedge lane,
    /// 2026-11-16): frees up to `want` clean, unpinned, unmapped pages
    /// of (fs_id, ino) directly from its map. The writer-side watermark
    /// recovery needs the pages it just flushed to actually RETURN to
    /// the zone — the generic shrink walks the LRU tail, and while a
    /// dirty balloon dominates the tail (the fill: 120k dirty parent
    /// backing pages, measured run/f05e) the freshly-cleaned pages
    /// behind it are unreachable (EV_SCAN_EXHAUST treadmill, 0-41 pages
    /// freed per recovery). Same candidate rule as every evict path:
    /// pinned (cache pin), dirty, or mapped (PCACHE_RO alias) pages
    /// stay; removal under the entry lock, LRU/frame release after it
    /// drops (the standing lock order). An emptied map is left in place
    /// — the insert path revives it (the balloon inodes are written
    /// again within the same phase).
    pub fn evict_clean_inode(&self, fs_id: u64, ino: u64, want: usize) -> usize {
        if want == 0 {
            return 0;
        }
        let key = cache_key(fs_id, ino);
        let Some(entry) = self.lookup_claimed(key) else {
            return 0;
        };
        const BATCH: usize = 128;
        let mut freed = 0usize;
        while freed < want {
            // Pass 1 (entry lock): collect up to min(BATCH, want-freed)
            // victim indices and remove them from the map — removal
            // under the lock is what keeps a concurrent get() from
            // pinning a victim. The want bound holds for the RETURN
            // value (callers budget by it), so the batch must not
            // overshoot the remainder.
            let limit = core::cmp::min(BATCH, want - freed);
            let mut victims: [(u64, usize); BATCH] = [(0, 0); BATCH];
            let mut n = 0usize;
            {
                let mut g = entry.lock.lock();
                let mut it = g.iter();
                while n < limit {
                    let Some((&idx, page)) = it.next() else {
                        break;
                    };
                    if page.count_locked() != 0 || page.dirty.load(Ordering::Acquire) {
                        continue;
                    }
                    if page_desc(page.pfn).is_some_and(|pd| pd.is_mapped()) {
                        continue;
                    }
                    victims[n] = (idx, page.pfn);
                    n += 1;
                }
                for k in 0..n {
                    if let Some(removed) = g.remove(&victims[k].0) {
                        dirty_account_removed(&removed);
                    }
                }
            }
            if n == 0 {
                break;
            }
            // Pass 2 (locks dropped): LRU unlink + frame release — no
            // allocation, same funnel as every eviction arm.
            for k in 0..n {
                let pfn = victims[k].1;
                if let Some(pd) = page_desc(pfn) {
                        crate::api::mm::page_remove_lru(pd);
                }
                release_page_frame(pfn);
                self.total_pages.fetch_sub(1, Ordering::Relaxed);
                STAT_EVICTIONS.fetch_add(1, Ordering::Relaxed);
                EV_FREED.fetch_add(1, Ordering::Relaxed);
                freed += 1;
            }
        }
        drop(entry);
        freed
    }

    /// Writer-side dirty-writeback recovery (falloc-wedge lane,
    /// 2026-11-16) — the duty-cycle back end of ext4_buffered_write's
    /// dirty-balloon watermark. Flushing the WRITER's own inode is not
    /// enough to recover the mark: the balloon's bulk is the backing
    /// file of a loop device fed by every flushed page of the stacked
    /// fs (a different inode entirely), and until IT is flushed nothing
    /// becomes evictable and the mark stays tripped (measured: every
    /// 4 KiB fill write then paid a synchronous flush of itself). This
    /// pass first frees ALREADY-clean pages (reference order — free
    /// clean before writing back), then collects dirty inodes
    /// system-wide (full-table walk, monopolist-bounded per inode) and
    /// flushes each WHOLE through the run-batched engine (the fast
    /// class: 23890 pages in ~3.8 s on the repro rig), evicting each
    /// flushed inode's now-clean pages directly (evict_clean_inode) —
    /// which is what actually raises nr_free and un-trips the
    /// watermark.
    ///
    /// Re-entry discipline: identical to shrink_reclaim — degrades to
    /// clean-only when the current task holds a loop io claim (a loop
    /// backing write must not nest writeback for fses stacked on the
    /// same loop) or when another writeback engine is mid-flight.
    /// Returns pages freed by the clean-evict stages.
    pub fn writeback_recover(&self, want: usize) -> usize {
        const MAX_WB_INODES: usize = 4;
        SR_CALLS.fetch_add(1, Ordering::Relaxed);
        if crate::sched::current_is_dying() {
            return self.shrink(want);
        }
        if crate::drivers::loop_dev::loop_io_claim_held_by_current() {
            SR_LOOP_DEFER.fetch_add(1, Ordering::Relaxed);
            return self.shrink(want);
        }
        if WRITEBACK_GUARD
            .compare_exchange(false, true, Ordering::AcqRel, Ordering::Acquire)
            .is_err()
        {
            SR_GUARD_HITS.fetch_add(1, Ordering::Relaxed);
            return self.shrink(want);
        }
        // Stage 1: already-clean pages, generic paths (LRU tail, then
        // the windowed fallback). Cheap when the tail is clean; cheap
        // to fail when a dirty balloon owns the tail.
        let mut freed = self.shrink(want);
        let mut remaining = want.saturating_sub(freed);
        if remaining > 0 {
            let mut work: [(u64, u64, u64, u64); MAX_WB_INODES] = [(0, 0, 0, 0); MAX_WB_INODES];
            // window_pages=1: the collect only IDENTIFIES dirty inodes
            // (one dirty page is enough); the flush below hands the
            // WHOLE inode range to ext4_flush_dirty_inode, whose chunked
            // collect/write/complete cycles already bound every
            // per-inode lock hold.
            let n_work = self.collect_wb_work(&mut work, 1);
            for i in 0..n_work {
                if remaining == 0 {
                    break;
                }
                let (fs_id, ino, _first, _last) = work[i];
                SR_FLUSH_INODES.fetch_add(1, Ordering::Relaxed);
                // Liveness: the same writeback resolver shrink_reclaim
                // uses (icache first, then a fresh inode from the
                // live-instance registry) — a cache miss may cost
                // performance, never data.
                crate::api::ext4::writeback_flush(fs_id, ino, 0, u64::MAX);
                // The pages this flush cleaned are THIS inode's — evict
                // them directly instead of hoping the LRU tail reaches
                // them past the rest of the balloon.
                let f2 = self.evict_clean_inode(fs_id, ino, remaining);
                freed += f2;
                remaining -= f2;
            }
        }
        WRITEBACK_GUARD.store(false, Ordering::Release);
        SR_CLEAN_FREED.fetch_add(freed as u64, Ordering::Relaxed);
        freed
    }

    /// Reclaim-time dirty writeback (the session-24 "v2" item). Direct
    /// reclaim ONLY: the plain shrink() evicts clean pages alone — a
    /// DIRTY entry (unflushed MAP_SHARED stores of a mapping that has
    /// since unmapped without msync) is skipped by evict_one by design,
    /// because evicting it would lose the only copy of that data. When
    /// nothing clean is left, such pages are a permanent, unevictable
    /// drain (the abandonment shape of the fake-OOM family). This
    /// variant makes progress where shrink() cannot: flush the dirty
    /// entries to their file first, then let the clean pass evict them.
    ///
    /// Safety shape (each point verified against the callers):
    /// - Runs from vmscan direct reclaim (page_alloc slowpath), which is
    ///   task context, holds no spinlocks, and is globally serialized by
    ///   IN_DIRECT_RECLAIM — never from the mmu_init PT-alloc retry,
    ///   which holds the per-mm PteLock (sleeping on I/O there is the
    ///   deadlock the session-19 comment documents; that caller keeps
    ///   plain shrink()).
    /// - NO pcache lock is EVER held across the flush I/O
    ///   (R-WRITESTORM-1): candidates are collected under wlock (+ the
    ///   per-inode locks), the locks are dropped, then
    ///   ext4_flush_dirty_inode does its own chunked collect → write →
    ///   complete cycle.
    /// - The filesystem is reached through a LIVE VFS Inode resolved by
    ///   the ext4 writeback resolver (icache first, then a fresh inode
    ///   materialized from the on-disk inode; fs_id of an ext4 Inode IS
    ///   the fs pointer, ext4 mod.rs inode setup, validated against the
    ///   live-instance registry) — the same liveness contract sys_fsync
    ///   uses. A resolver failure skips the entry: its dirty pages stay
    ///   as they were (bounded, coherent to every reader through the
    ///   frame); a later retry can flush them.
    /// - WRITEBACK_GUARD stops re-entry: ext4's write path allocates
    ///   memory, and a nested reclaim arriving inside our own flush
    ///   must not start another flush (it degrades to clean-only).
    /// - A page whose mapping re-pinned during the flush stays dirty
    ///   (flush_done keeps the bit while pinned) and is simply picked
    ///   again by a later round — the bounded round count below keeps
    ///   one call from spinning on it.
    pub fn shrink_reclaim(&self, nr_to_scan: usize) -> usize {
        /// Max inode ranges flushed per round, and rounds per call. One
        /// shrink_reclaim thus performs at most 2*16 chunked flushes of
        /// I/O before returning — reclaim stays responsive while always
        /// making progress (each flushed-and-now-clean page is evicted
        /// by the follow-up clean pass).
        const MAX_WB_INODES: usize = 2;
        const MAX_WB_ROUNDS: usize = 4;
        /// Dirty-page window per flush: matches ext4_flush_dirty_inode's
        /// internal CHUNK (one collect/write/complete cycle).
        const WB_WINDOW: u64 = 16;

        let mut freed = 0usize;
        SR_CALLS.fetch_add(1, Ordering::Relaxed);
        for _round in 0..MAX_WB_ROUNDS {
            // Reference fatal_signal_pending discipline (falloc-wedge):
            // a task killed mid-reclaim (the OOM killer selected the gate
            // holder, or LTP's timeout SIGKILL) must unwind through here
            // instead of carrying the gate through more flush I/O — the
            // wedge boots held the gate for minutes after the kill.
            if crate::sched::current_is_dying() {
                break;
            }
            let remaining = nr_to_scan.saturating_sub(freed);
            if remaining == 0 {
                break;
            }
            let before = freed;
            freed += self.shrink(remaining);
            SR_CLEAN_FREED.fetch_add((freed - before) as u64, Ordering::Relaxed);

            if freed >= nr_to_scan {
                break;
            }
            // Shortfall: reclaim demand exceeds what clean eviction
            // supplied. Flush dirty, unreferenced entries NOW — while
            // clean pages may still exist elsewhere — rather than at
            // the exhausted wall: the flush's own ext4/bio allocations
            // (journal buffers, block mapping) must be able to allocate
            // while it runs, or every write fails and the pages stay
            // dirty forever (the Linux dirty-threshold insight: writeback
            // starts far below the memory wall).
            let mut work: [(u64, u64, u64, u64); MAX_WB_INODES] = [(0, 0, 0, 0); MAX_WB_INODES];
            let n_work = self.collect_wb_work(&mut work, WB_WINDOW);
            if n_work == 0 {
                SR_NO_DIRTY.fetch_add(1, Ordering::Relaxed);
                break; // no flushable dirty pages anywhere
            }
            // RE-ENTRY DISCIPLINE (falloc-wedge lane, 2026-11-16): no
            // synchronous writeback under a held io lock. If the current
            // task is inside a loop device's backing-file I/O (the io
            // claim is held), flushing a dirty inode whose fs is stacked
            // on that same loop would re-enter loop_request_fn with the
            // claim already ours — the EDEADLK arm, pages stay dirty,
            // and this loop burns I/O budget re-deriving that. The
            // reference kernel never runs loop writeback in the I/O
            // submitter's context (loop I/O is dispatched from the
            // device's own worker); our degrade is the same discipline:
            // clean-only here, the deferred pages are flushed by the
            // writer-side dirty-balloon watermark or a later reclaim
            // outside any io claim.
            if crate::drivers::loop_dev::loop_io_claim_held_by_current() {
                SR_LOOP_DEFER.fetch_add(1, Ordering::Relaxed);
                break;
            }
            // Re-entrancy gate: nested reclaim (from inside ext4 write's
            // own allocations) degrades to clean-only.
            if WRITEBACK_GUARD
                .compare_exchange(false, true, Ordering::AcqRel, Ordering::Acquire)
                .is_err()
            {
                SR_GUARD_HITS.fetch_add(1, Ordering::Relaxed);
                break;
            }
            for i in 0..n_work {
                let (fs_id, ino, first, last) = work[i];
                // Liveness: the same writeback resolver flush_all_dirty
                // uses (icache first, then a fresh inode materialized
                // from the on-disk inode via the live-instance registry).
                // The old "miss = skip" contract silently dropped the
                // dirty frames of any inode the bounded icache had
                // evicted — a cache miss may cost performance, never
                // data.
                SR_FLUSH_INODES.fetch_add(1, Ordering::Relaxed);
                crate::api::ext4::writeback_flush(
                    fs_id,
                    ino,
                    first,
                    last.min(first + WB_WINDOW - 1),
                );
            }
            WRITEBACK_GUARD.store(false, Ordering::Release);
            // Loop: the clean pass at the top of the next round evicts
            // what the flush cleaned.
        }
        freed
    }

    /// Evict one unreferenced page, two-tier (Linux file-LRU shape).
    ///
    /// 1. Walk LRU_INACTIVE_FILE from the TAIL — the oldest end, walking
    ///    `lru_prev` toward younger pages. Pinned pages (ref_count > 0)
    ///    are skipped. Referenced pages get the flag cleared and are
    ///    activated onto the young end of LRU_ACTIVE_FILE. The first
    ///    clean unreferenced page is evicted.
    /// 2. If the inactive walk found nothing, demote the OLDEST active
    ///    pages back onto the young end of inactive (second chance) and
    ///    re-walk once. Without demotion every page that was ever served
    ///    accumulated on the active list forever (`lru_deactivate` had no
    ///    callers), eviction could not make progress, and inserts fell
    ///    through to the map-order fallback — semantically RANDOM
    ///    eviction, the OH multi-loader thrash amplifier.
    /// 3. Safety net: slot-table scan (hash-key order) for pages the LRU
    ///    walk cannot reach (descriptor-less frames, list corruption).
    ///
    /// History: the pre-two-tier walk started at the tail and followed
    /// `lru_next` — the terminator direction — so it examined exactly ONE
    /// page per call: the newest (fresh pages linked at the tail back
    /// then), i.e. "evict the page most likely to be needed next".
    ///
    /// `wlock` MUST be held by the caller (the guard parameter is the
    /// proof — it nests per-inode locks of VICTIMS inside it; the caller's
    /// own target entry, if any, is locked only AFTER this returns).
    /// Entries emptied by the eviction have their slot tombstoned and the
    /// slot's Arc parked into `parked` (the caller flushes after dropping
    /// wlock); the function refuses to evict when `parked` is full.
    ///
    /// Returns true when a page was actually evicted.
    fn evict_one_locked(&self, _w: &SpinlockGuard<'_, ()>, parked: &mut PcParkBatch) -> bool {
        const MAX_SCAN: usize = 64; // bound scan to limit latency
        const DEMOTE_BATCH: usize = 32;

        if parked.iter().all(|p| p.is_some()) {
            return false; // caller must flush first
        }

        for _round in 0..2 {
            let mut pfn = crate::api::mm::lru_tail(LRU_INACTIVE_FILE);
            let mut scanned = 0usize;

            while pfn != 0 && scanned < MAX_SCAN {
                scanned += 1;
                let Some(page) = page_desc(pfn) else {
                    break;
                };

                {
                    // Tail = oldest end; lru_prev walks toward the head
                    // (younger). Capture BEFORE any move of this page.
                    let next_pfn = page.lru_prev();

                    // Only evict PageCache pages
                    if page.page_type() != PageType::PageCache {
                        pfn = next_pfn;
                        continue;
                    }

                    // Check ref_count — pages being read are not evictable.
                    // Use mapping (inode key) and index (page_index) for the
                    // lookup. Verdict AND removal share ONE per-inode hold:
                    // dropping the lock between check and remove would let a
                    // concurrent get() pin the page and the eviction free a
                    // pinned frame.
                    let key = page.mapping() as u64;
                    let page_index = page.index() as u64;

                    enum Victim {
                        Skip,
                        SecondChance,
                        Evict,
                    }

                    let verdict = match self.table_find(key) {
                        Some(i) => {
                            let ptr = self.slots[i].0.load(Ordering::Acquire);
                            // SAFETY: wlock excludes removal; the entry is
                            // alive and keyed (write-once `key` checked by
                            // table_find).
                            let entry = unsafe { &*ptr };
                            let mut g = entry.lock.lock();
                            let verdict = match g.get(&page_index) {
                                Some(cached) => {
                                    // Session 25: dirty frames hold unflushed
                                    // shared-mapping stores — evicting one
                                    // would lose the only copy of that data.
                                    // PCACHE_RO aliases (perf-gap-hunt): a
                                    // frame with mapcount > 0 is mapped by
                                    // pin-free leaves — with no cache pin to
                                    // stop us, the MAPCOUNT is the only
                                    // eviction guard (the reference kernel's
                                    // page_mapped() shape).
                                    let pinned = cached.count_locked() != 0;
                                    let dirty = cached.dirty.load(Ordering::Acquire);
                                    let mapped = page_desc(cached.pfn)
                                        .is_some_and(|pd| pd.is_mapped());
                                    if pinned {
                                        EV_SKIP_PINNED.fetch_add(1, Ordering::Relaxed);
                                    }
                                    if dirty {
                                        EV_SKIP_DIRTY.fetch_add(1, Ordering::Relaxed);
                                    }
                                    if mapped {
                                        EV_SKIP_MAPPED.fetch_add(1, Ordering::Relaxed);
                                    }
                                    let evictable = !pinned && !dirty && !mapped;
                                    if !evictable {
                                        Victim::Skip
                                    } else {
                                        let referenced = page_desc(cached.pfn)
                                            .is_some_and(|pd| {
                                                pd.test_flag(PageFlag::Referenced)
                                            });
                                        if referenced {
                                            Victim::SecondChance
                                        } else {
                                            g.remove(&page_index);
                                            if g.is_empty() {
                                                // Whole entry gone: tombstone the
                                                // slot and park its reference
                                                // (drained by the caller after
                                                // wlock drops — never spin under
                                                // wlock). `parked` had a free
                                                // slot (checked up front).
                                                self.slots[i].0.store(
                                                    PC_TOMBSTONE_BITS as *mut InodePageCache,
                                                    Ordering::Release,
                                                );
                                                if let Some(slot) =
                                                    parked.iter_mut().find(|p| p.is_none())
                                                {
                                                    // SAFETY: the slot's
                                                    // reference is handed over
                                                    // here (see remove_entry).
                                                    *slot = Some(unsafe { Arc::from_raw(ptr) });
                                                }
                                            }
                                            Victim::Evict
                                        }
                                    }
                                }
                                // Page not in the map — stale descriptor, clean up
                                None => Victim::Evict,
                            };
                            verdict
                        }
                        // Entry gone entirely — stale descriptor, clean up
                        None => Victim::Evict,
                    };

                    match verdict {
                        Victim::Skip => {
                            pfn = next_pfn;
                            continue;
                        }
                        Victim::SecondChance => {
                            // Referenced: clear the flag, promote to the young
                            // end of the active list, keep scanning.
                            EV_SECOND_CHANCE.fetch_add(1, Ordering::Relaxed);
                            page.clear_flag(PageFlag::Referenced);
                            crate::api::mm::lru_activate_young(page);
                            pfn = next_pfn;
                            continue;
                        }
                        Victim::Evict => {
                            crate::api::mm::page_remove_lru(page);
                            release_page_frame(pfn);
                            self.total_pages.fetch_sub(1, Ordering::Relaxed);
                            STAT_EVICTIONS.fetch_add(1, Ordering::Relaxed);
                            EV_FREED.fetch_add(1, Ordering::Relaxed);
                            return true;
                        }
                    }
                }
            }

            // Inactive walk made no progress — demote the oldest ACTIVE
            // pages to the young end of inactive and retry once. An empty
            // active list (or nothing demotable) falls to the map scan.
            EV_SCAN_EXHAUST.fetch_add(1, Ordering::Relaxed);
            let demoted = crate::api::mm::lru_demote_active_file_oldest(DEMOTE_BATCH);
            if demoted == 0 {
                break;
            }
            STAT_DEMOTIONS.fetch_add(demoted as u64, Ordering::Relaxed);
        }

        // LRU walk exhausted — fall back to slot-table scan (safety net).
        // WINDOWED (pcachewedge lane, 2026-11-15): the whole-table scan
        // (32768 slots, each a per-inode lock + map iteration) ran inside
        // ONE wlock section with preemption disabled — under the fammm
        // churn (everything pinned/mapped, nothing evictable) that was a
        // MULTI-SECOND preempt-off monopolist window: RCU quiescent
        // rounds stalled, fdreapd (waiting on the grace period to close
        // dead tasks' fds) starved for 179 s+, and every task piling
        // behind the pcache locks spun. The net is a safety valve, not a
        // correctness requirement — a rotating window of slots per call
        // keeps the coverage (successive calls continue where the last
        // stopped) while bounding any single wlock hold.
        const FALLBACK_WINDOW: usize = 512;
        static FALLBACK_CURSOR: AtomicUsize = AtomicUsize::new(0);
        let start = FALLBACK_CURSOR.fetch_add(FALLBACK_WINDOW, Ordering::Relaxed) % PC_TABLE_CAP;
        for k in 0..FALLBACK_WINDOW {
            let si = (start + k) % PC_TABLE_CAP;
            let ptr = self.slots[si].0.load(Ordering::Acquire);
            if ptr.is_null() || ptr as usize == PC_TOMBSTONE_BITS {
                continue;
            }
            // SAFETY: wlock excludes removal; the entry is alive.
            let entry = unsafe { &*ptr };
            let mut g = entry.lock.lock();
            // Same candidate rule as the LRU walk: skip pinned and dirty,
            // give Referenced pages their second chance (activated, scan
            // continues), evict the first clean unreferenced page.
            let mut victim: Option<(u64, usize)> = None;
            for (&page_idx, page) in g.iter() {
                if page.count_locked() != 0 || page.dirty.load(Ordering::Acquire) {
                    continue;
                }
                // PCACHE_RO alias guard (see the LRU-walk twin): a mapped
                // frame is not evictable.
                if let Some(p) = page_desc(page.pfn) {
                    if p.is_mapped() {
                        continue;
                    }
                    if p.test_flag(PageFlag::Referenced) {
                        p.clear_flag(PageFlag::Referenced);
                        crate::api::mm::lru_activate_young(p);
                        continue; // second chance — keep scanning
                    }
                }
                victim = Some((page_idx, page.pfn));
                break;
            }
            if let Some((page_idx, pfn)) = victim {
                g.remove(&page_idx);
                if g.is_empty() {
                    self.slots[si]
                        .0
                        .store(PC_TOMBSTONE_BITS as *mut InodePageCache, Ordering::Release);
                    if let Some(slot) = parked.iter_mut().find(|p| p.is_none()) {
                        // SAFETY: the slot's reference is handed over here.
                        *slot = Some(unsafe { Arc::from_raw(ptr) });
                    }
                }
                drop(g);
                if let Some(page_desc) = page_desc(pfn) {
                        crate::api::mm::page_remove_lru(page_desc);
                }
                release_page_frame(pfn);
                self.total_pages.fetch_sub(1, Ordering::Relaxed);
                STAT_EVICTIONS.fetch_add(1, Ordering::Relaxed);
                EV_FREED.fetch_add(1, Ordering::Relaxed);
                return true;
            }
        }
        false
    }
}

/// Release a physical page frame back to the zone allocator.
///
/// PT-ledger refusal (pcachewedge lane, 2026-11-15): the single funnel
/// for every cache-side frame free (eviction, invalidate, final put,
/// lazy reap). A frame the page-table ledger still stamps LIVE must
/// never re-enter the zone from here: it is simultaneously a live page
/// table (its PT allocation grabbed it after a premature free left the
/// frame on the cache LRU with a stale PageCache-typed descriptor) and
/// a cache entry — freeing it RAW-FREEs the live table (the corruption
/// cascade: PTLEDGER DOUBLE-ALLOC, PTE values in recycled task memory,
/// oops-killed lock holders). REFUSE the free — the frame is leaked
/// (bounded, one per corrupted entry) and the evidence names it. Same
/// tripwire shape as zone.rs's RAW-FREE-OF-LIVE-TABLE watchpoint, but
/// as a refusal at the producer.
fn release_page_frame(pfn: usize) {
    let phys_addr = pfn_to_phys(pfn);

    // QUARANTINED frames (ever double-tracked) are never released: their
    // stale references make every re-allocation a collision. Leak.
    if crate::arch::mm::mmu_init::alloc_stage_is_late()
        && crate::arch::mm::mmu_init::PtLedger::is_poisoned(pfn as u64)
    {
        use core::sync::atomic::Ordering::Relaxed;
        crate::debug::driftwatch::MM_POISON_FREES.fetch_add(1, Relaxed);
        return;
    }

    if crate::arch::mm::mmu_init::alloc_stage_is_late()
        && crate::arch::mm::mmu_init::PtLedger::is_live_table(pfn as u64)
    {
        use core::sync::atomic::Ordering::Relaxed;
        crate::debug::driftwatch::PCACHE_LIVE_PT_REFUSED
            .fetch_add(1, Relaxed);
        static REPORTS: core::sync::atomic::AtomicUsize =
            core::sync::atomic::AtomicUsize::new(0);
        let n = REPORTS.fetch_add(1, Relaxed);
        if n < 8 {
            crate::pr_err!(
                "page-cache release of LIVE PT frame pfn={:#x} REFUSED — leaking (double-owned cache entry; RAW-FREE cascade guard)",
                pfn
            );
            crate::debug::backtrace::dump_stack();
        }
        // mmforensics: deep capture at the producer-side refusal (the
        // capture takes no page-cache locks — it only reads descriptors,
        // rings and foreign trees — so running it from this lock-held
        // context is safe).
        crate::debug::mmforensics::capture_frame(pfn, "pcache-live-pt-refused");
        // QUARANTINE the frame (mmforensics lane): the capture evidence
        // showed such frames keep colliding with re-allocation for the
        // rest of the boot (one frame re-stamped by five trees); the
        // poison bit makes every later free of it impossible, so the
        // surviving references dangle inertly.
        crate::arch::mm::mmu_init::PtLedger::poison_table(pfn as u64);
        crate::debug::driftwatch::MM_POISONED.fetch_add(1, Relaxed);
        // The caller has already removed the map entry and unlinked the
        // LRU member; the leaked frame is an untracked orphan. Its
        // stale PageCache descriptor is unreachable from the LRU walk,
        // so it cannot be re-picked here.
        return;
    }

    // Clear page cache metadata
    if let Some(pd) = page_desc(pfn) {
        pd.set_index(0);
    }

    free_page(phys_addr);
}

/// Global page cache instance.
static PAGE_CACHE: PageCache = PageCache::new();

/// Get a reference to the global page cache.
pub fn get_page_cache() -> &'static PageCache {
    &PAGE_CACHE
}

/// Get the total number of cached pages (for /proc/meminfo).
pub fn page_cache_total_pages() -> u32 {
    PAGE_CACHE.total_pages.load(Ordering::Relaxed)
}

/// Page-cache op counters (hits, misses, evictions, active demotions) for
/// the /proc/meminfo `PageCacheOps:` Rux-extension line. Under the OH
/// service mixture the hit/miss ratio is the direct read on whether the
/// cache still thrashes (miss ≈ every fault pays the ext4 big lock).
pub fn page_cache_stats() -> (u64, u64, u64, u64) {
    (
        STAT_HITS.load(Ordering::Relaxed),
        STAT_MISSES.load(Ordering::Relaxed),
        STAT_EVICTIONS.load(Ordering::Relaxed),
        STAT_DEMOTIONS.load(Ordering::Relaxed),
    )
}

/// Effective page-cache cap (dynamic: half of managed RAM, min 32MB).
/// Exposed for the meminfo observability line.
pub fn page_cache_cap_pages() -> usize {
    max_cached_pages()
}

/// Resolve a MAP_SHARED file-mapping fault to the page-cache frame for
/// (inode, file_offset/PAGE), populating the cache from the file on miss.
///
/// Returns the pinned physical address that the caller maps into the user
/// page table. Aliasing the cache frame (instead of a private copy) is
/// what makes the mapping genuinely shared: every mapper of the file —
/// across fork AND across a fresh mmap after exec — faults onto the same
/// physical page and observes the others' stores (LTP's IPC results file;
/// the execl01..execveat02 family used to TBROK "Test haven't reported
/// results" when each mapper got a private copy).
///
/// The `get_phys` pin is owned by the user PTE mapping for its lifetime;
/// there is deliberately no put() at unmap time, so a shared-mapped page
/// stays unevictable until its inode cache is dropped. Bounded in practice
/// by the number of simultaneously shared-mapped files (LTP: one 4KB page
/// per test). Known deviation from Linux, documented here: write(2) on the
/// file invalidates the inode cache, after which the mapped frame and new
/// disk reads can diverge — Linux keeps them coherent by writing through
/// the page cache; ext4 here writes disk-direct. Files used as shared
/// mappings (the POSIX shm-over-mmap pattern) are written via the mapping
/// itself, which stays coherent.
pub fn shared_file_fault_page(file: &super::types::File, file_offset: u64) -> Option<u64> {
    // SAFETY: inode is written once at open time and read-only afterwards.
    let inode = unsafe { &*file.inode.get() }.as_ref()?;
    let (fs_id, ino) = (inode.fs_id, inode.ino as u64);
    let cache = get_page_cache();
    let page_index = file_offset / crate::mm::PAGE_SIZE as u64;

    // REVIVE lookup (tmpfs-only caller): an invalidated-but-mapped frame
    // is still the page's live face — reuse it (and un-invalidate it) so
    // regrow-then-remap keeps serving the same frame instead of falling
    // to the private-copy fallback (FXW squat family).
    if let Some(phys) = cache.get_stale_revive(fs_id, ino, page_index) {
        return Some(phys);
    }

    // Miss: read the page from the file into a bounce frame, insert it
    // into the cache, then take the pinning lookup path.
    let bounce_phys = alloc_page(GfpFlags::GFP_KERNEL);
    if bounce_phys == 0 {
        return None;
    }
    // SAFETY: bounce_phys is a freshly allocated page frame owned here.
    let bounce = unsafe {
        core::ptr::write_bytes(
            phys_to_virt(PhysAddr::new(bounce_phys as u64)).0 as *mut u8,
            0,
            crate::mm::PAGE_SIZE,
        );
        phys_to_virt(PhysAddr::new(bounce_phys as u64)).0 as *mut u8
    };
    // SAFETY: read_at validates its own file references; bounce is a full
    // page of writable kernel memory.
    let got = unsafe { file.read_at(file_offset, bounce, crate::mm::PAGE_SIZE) };
    if got < 0 {
        free_page(bounce_phys);
        return None;
    }
    // SAFETY: bounce holds PAGE_SIZE readable bytes (zero-filled tail).
    unsafe {
        cache.insert(
            fs_id,
            ino,
            page_index,
            0,
            core::slice::from_raw_parts(bounce, crate::mm::PAGE_SIZE),
        );
    }
    free_page(bounce_phys);
    cache.get_phys(fs_id, ino, page_index)
}


// ════════════════ readahead ═══════════════════════════
// (was readahead.rs)
// Read-Ahead — detect sequential access patterns and prefetch file data.
//
// Each open file descriptor gets a `ReadAheadState` stored in `File.private_data`.
// After detecting consecutive sequential reads, prefetches upcoming blocks
// into the page cache to reduce VirtIO round-trips.

// Kernel layer policy (docs/architecture/kernel-layers.md):
// this module must stay Safe Rust.

/// Maximum number of blocks to read ahead per trigger.
///
/// 512 blocks = 2 MiB per batch: one sleep/wake cycle covers a whole
/// window, so sequential read throughput is (window / cycle-latency)
/// instead of (4 KiB / cycle-latency). The ext4 read path batches the demand
/// range and this window together through the async block layer; the
/// virtqueue in-flight limit (queue_size/3 chains) naturally pipelines
/// larger windows in sub-batches.
pub const MAX_READAHEAD_BLOCKS: u32 = 512;

/// Fault-around cluster for mmap demand-fault misses (Linux parity:
/// fault_around_bytes = 64 KiB / 4 KiB = 16 pages).
///
/// The fault path issues single page-aligned one-page preads; dynamic
/// linker fault order interleaves segments, which defeats the sequential
/// detector. A miss fills this cluster around the faulting page so
/// interleaved and ascending faults hit the page cache instead of paying
/// one synchronous fill each (sc105 launcher stime burn).
pub const FAULT_AROUND_BLOCKS: u32 = 16;

/// Number of consecutive sequential reads before activating read-ahead.
const ACTIVATION_THRESHOLD: u32 = 2;


impl ReadAheadState {
    pub fn new(block_size: u64) -> Self {
        Self {
            last_read_end: 0,
            sequential_count: 0,
            active: false,
            ra_until: 0,
            block_size,
        }
    }

    /// Update state after a read at `offset` that produced `length` bytes.
    /// Returns `(should_ra, ra_start_page, ra_count)` if read-ahead should be issued.
    pub fn on_read(&mut self, offset: u64, length: u64) -> (bool, u64, u32) {
        if length == 0 {
            return (false, 0, 0);
        }

        // Detect sequential access: this read starts where the last one ended
        let is_sequential = offset == self.last_read_end;

        if is_sequential {
            self.sequential_count += 1;
        } else {
            // Seek or random access — reset
            self.sequential_count = 0;
            self.active = false;
        }

        self.last_read_end = offset + length;

        // Activate after threshold
        if self.sequential_count >= ACTIVATION_THRESHOLD && !self.active {
            self.active = true;
        }

        if !self.active {
            return (false, 0, 0);
        }

        // Check if we need to issue new read-ahead
        let current_end_page = (offset + length + self.block_size - 1) / self.block_size;

        if current_end_page >= self.ra_until {
            let ra_start = self.ra_until;
            let ra_count = MAX_READAHEAD_BLOCKS;
            self.ra_until = ra_start + ra_count as u64;
            return (true, ra_start, ra_count);
        }

        (false, 0, 0)
    }
}


// ════════════════ io_completion ═══════════════════════
// (was io_completion.rs)
// I/O Completion — lightweight completion signal for async block I/O.
//
// Provides a wait/wakeup primitive for I/O completion notification.
// extended with an I/O status code. Used to decouple I/O submission
// from completion: the submitter creates an IoCompletion, passes it to
// an async I/O function, then calls `wait()` later (or never, if polling).

// Kernel layer policy (docs/architecture/kernel-layers.md):
// this module must stay Safe Rust.

/// Status returned by [`IoCompletion::wait`] when the bounded wait deadline
/// expired without the device signaling completion (-ETIMEDOUT).
///
/// Distinct from -EIO: a real device error means the chain COMPLETED (its
/// DMA writes are done); a timeout means the chain may STILL be in flight
/// on the device. Callers must therefore (a) rely on wait() itself having
/// retired the device-side pending entry (it calls
/// virtio::abandon_pending_completion, converting the entry into a
/// tombstone) so its late completion cannot fire into memory they are
/// about to stop owning, and (b) never free the request's DMA target
/// buffer — leak it instead.
pub const WAIT_TIMED_OUT: i32 = -110; // -ETIMEDOUT


impl IoCompletion {
    /// Create a new, not-done completion.
    pub const fn new() -> Self {
        Self {
            done: AtomicBool::new(false),
            status: AtomicI32::new(0),
            delivering: AtomicUsize::new(0),
            token: AtomicUsize::new(0),
            wait_queue: WaitQueueHead::new(),
        }
    }

    /// Delivery-protocol arm: called by a completion walker under the
    /// device pending-table lock, before the entry leaves the table.
    ///
    /// probe-slow: the increment is Relaxed. The ordering the protocol
    /// needs against `abandon_pending_completion` ("if the entry is gone
    /// from the table, the increment is already visible") is carried by
    /// the pending-table lock itself: the walker increments while holding
    /// the table lock, and abandon scans the table under the same lock —
    /// its lock ACQUIRE synchronizes with the walker's lock RELEASE, so
    /// the increment is ordered ahead of abandon's read without a fence
    /// in the RMW. Both call sites (PCI and MMIO walkers) hold the table
    /// lock across this call.
    pub fn begin_delivery(&self) {
        self.delivering.fetch_add(1, Ordering::Relaxed);
    }

    /// Delivery-protocol release: called after `complete()` returned.
    ///
    /// Release (kept from the original): `wait_deliveries` loads the
    /// count with Acquire, so observing the decrement must make
    /// `complete()`'s status store (Release, before this call) visible —
    /// a Relaxed decrement could publish "delivered" ahead of the status.
    pub fn end_delivery(&self) {
        self.delivering.fetch_sub(1, Ordering::Release);
    }

    /// Spin until every in-flight delivery of this completion has called
    /// `complete()` and released it. Returns false only if the bounded
    /// spin expired (a walker wedged mid-delivery) — callers log loudly;
    /// correctness no longer depends on the bound under the fixed wake
    /// discipline, but the residual case must stay visible.
    pub fn wait_deliveries(&self) -> bool {
        let mut spins = 0u64;
        while self.delivering.load(Ordering::Acquire) != 0 {
            core::hint::spin_loop();
            spins += 1;
            if spins >= 800_000_000 {
                return false;
            }
        }
        true
    }

    /// Mark completion as done with the given status (internal signal:
    /// not attributed to a device chain).
    ///
    /// Wakes all waiters. Safe to call from interrupt context
    /// (no allocation, no BKL).
    ///
    /// VIRTIO-WQ-1 (virtio-blk ABBA fix): callers must NOT hold a virtio
    /// driver lock — wake_up_all takes the wait-queue lock across
    /// wake_up_process for every waiter, and nesting that inside
    /// VIRTIO_PCI_BLK_LOCK (or the MMIO virtqueue lock) is the final6
    /// GNOME deadlock family. Debug builds panic at the violation point
    /// instead of wedging the machine.
    pub fn complete(&self, status: i32) {
        self.complete_with_token(status, 0);
    }

    /// Mark completion as done with the given status, stamped with the
    /// device-truth token of the chain whose completion is being
    /// delivered (the pending entry's DMA data-buffer pointer).
    ///
    /// Called by the completion walkers (PCI and MMIO) with the pending
    /// entry's data pointer. `bread_wait` compares [`Self::delivered_token`]
    /// against its own buffer and refuses to publish data whose DMA the
    /// delivery did not prove — a misattributed delivery (wrong pending
    /// entry fired by another chain's used-ring entry) must surface as a
    /// loud EIO, never as silent zeros (the no-journal ext4 root-lookup
    /// zero-serve family).
    pub fn complete_with_token(&self, status: i32, token: usize) {
        #[cfg(debug_assertions)]
        crate::drivers::virtio::assert_no_virtio_lock("IoCompletion::complete");
        self.status.store(status, Ordering::Release);
        self.token.store(token, Ordering::Release);
        self.done.store(true, Ordering::Release);
        self.wait_queue.wake_up_all();
    }

    /// Device-truth token of the delivery that set `done`. Only meaningful
    /// after `wait()` returned: the delivery-drain handshake guarantees the
    /// delivering walker finished, so the load is stable.
    pub fn delivered_token(&self) -> usize {
        self.token.load(Ordering::Acquire)
    }

    /// Block until completion is signaled. Returns the status code, or
    /// [`WAIT_TIMED_OUT`] if the bounded deadline expires first.
    ///
    /// Follows the standard BKL discipline: release BKL, schedule,
    /// re-acquire BKL.
    pub fn wait(&self) -> i32 {
        // SUBMIT-2X (lever E): bounded poll-before-sleep. A synchronous
        // depth-1 waiter has nothing else to run; the device completes
        // under KVM in the ~10-25 us the sleep/wake machinery itself
        // costs (schedule-out, IRQ wake on another CPU, schedule-in,
        // wait-queue teardown). Polling the done flag for a bounded
        // window first trades idle CPU for that whole path — the same
        // trade the reference kernel's polled / HIPRI modes make, here
        // applied to every sync I/O wait with a small fixed budget.
        // Budget: 1536 pause iterations ~= 14 us on the 3.7 GHz KVM rig
        // (each PAUSE ~35 cycles); completions slower than the budget
        // fall through to the sleeping loop unchanged. Preemption and
        // IRQs stay on: the completion IRQ itself interrupts the loop,
        // retires the chain, and the next load observes done.
        {
            const POLL_BUDGET: u32 = 1536;
            let mut i = 0u32;
            while i < POLL_BUDGET {
                if self.done.load(Ordering::Acquire) {
                    return self.status.load(Ordering::Acquire);
                }
                core::hint::spin_loop();
                i += 1;
            }
        }
        let mut deadline_timer = 0u64; // 0 = not armed (or arm failed)
        let mut deadline_armed = false;
        let mut poll_fallback = false; // timer budget exhausted: 1-jiffy re-arms
        let mut deadline = 0u64;
        let result;
        loop {
            if self.done.load(Ordering::Acquire) {
                result = self.status.load(Ordering::Acquire);
                break;
            }

            let current = match crate::sched::current() {
                Some(task) => task,
                None => {
                    core::hint::spin_loop();
                    continue;
                }
            };

            // WEDGE fix (LTP inode02/ftest family): an unbounded
            // kernel-side wait is unkillable — signals are delivered only
            // on the return to userspace, so a lost completion wedged the
            // whole sweep. Bound the wait (10s of jiffies); a lost
            // completion then reports ETIMEDOUT and the syscall unwinds.
            //
            // GSD fix (10s-deadline UAF): returning with the I/O still
            // queued left the virtio pending tables holding a raw pointer
            // to this (usually stack-allocated) completion; later
            // completion walkers called complete() through freed stack
            // memory (wild wake_up_all -> KERNPANIC under gnome-session).
            // Before unwinding (see the deadline check below): (1) kick +
            // drain one last time — recovers lost-kick stalls; (2) abandon
            // our pending-table entries so nothing dereferences this
            // memory after we return. Callers must likewise NOT free the
            // I/O's DMA buffers on ETIMEDOUT.
            if !deadline_armed && !poll_fallback {
                deadline = crate::timer::get_jiffies()
                    .saturating_add(msecs_to_jiffies(10_000));
                // Arm a wakeup AT THE DEADLINE itself. The deadline check
                // below only runs after schedule() returns, so without this
                // timer a completion that never arrives (and no other wake)
                // would sleep forever — unkillable, and with no timeout
                // print: exactly the silent-strand shape behind the freed
                // kernel-stack completion fires (the r2/r4 rounds).
                let pid = crate::sched::get_current_pid();
                deadline_timer = crate::timer::add_timer_wakeup(deadline, pid);
                if deadline_timer != 0 {
                    deadline_armed = true;
                } else {
                    // Timer table full: degrade to per-iteration 1-jiffy
                    // re-arms (wait_buffer_io_done discipline) so the
                    // deadline check still runs.
                    poll_fallback = true;
                }
            }

            // Use prepare_to_wait to atomically set INTERRUPTIBLE and
            // add to queue, preventing lost-wakeup race.
            // might_sleep parity: a softirq-context caller parking here
            // is the count-migration leak's producer class (schedule()
            // now refuses the switch and names it).
            crate::interrupt::preempt::might_sleep_check("IoCompletion::wait");
            self.wait_queue.prepare_to_wait(current, false, true);

            // Recheck after setting state (waker may have fired)
            if self.done.load(Ordering::Acquire) {
                self.wait_queue.finish_wait(current);
                // R36-B2 (R8-5 NEW-C2 discipline, missed here): a complete()
                // that raced between prepare_to_wait and this recheck woke
                // and enqueued us while we never slept — take ourselves
                // back off the GRQ (no-op via on_rq guards otherwise) or
                // nr_running stays inflated until our next context switch.
                crate::sched::dequeue_task(&*current);
                result = self.status.load(Ordering::Acquire);
                break;
            }

            // Deadline check AFTER prepare_to_wait: we are about to sleep,
            // so this is the last point the deadline can abort without a
            // wake. A concurrent complete() between the recheck above and
            // here is caught by the loop-top check on the next iteration
            // only if we get woken — the deadline timer covers that too.
            if (deadline_armed || poll_fallback)
                && crate::timer::get_jiffies() >= deadline
            {
                self.wait_queue.finish_wait(current);
                // Same R36-B2 compensation as the recheck exit: a racing
                // fire may have enqueued us between prepare and finish.
                crate::sched::dequeue_task(&*current);
                // Final chance (GSD fix): kick the queue and drain
                // completions once — recovers lost-kick stalls.
                crate::drivers::virtio::vw_report("async-deadline");
                crate::drivers::blkdev::kick_all_pending_disks();
                crate::drivers::virtio::pci_process_async_completions();
                if self.done.load(Ordering::Acquire) {
                    crate::pr_err!("io_completion: recovered by final kick/drain");
                    result = self.status.load(Ordering::Acquire);
                    break;
                }
                crate::pr_err!(
                    "io_completion: lost completion — reporting ETIMEDOUT (wedge fix)"
                );
                // Abandon our pending-table entries so nothing
                // dereferences this memory after we return (GSD fix).
                // This also waits out any walker delivery of OUR entries
                // that is still in flight (see `delivering`).
                crate::drivers::virtio::abandon_pending_completion(
                    self as *const _ as *mut _,
                );
                // The drained delivery may have completed us after the
                // re-check above — prefer the real status if so.
                if self.done.load(Ordering::Acquire) {
                    result = self.status.load(Ordering::Acquire);
                } else {
                    result = WAIT_TIMED_OUT;
                }
                break;
            }

            if poll_fallback {
                // Re-arm a 1-jiffy wake so the deadline check above runs
                // every jiffy even without a completion wake.
                let pid = crate::sched::get_current_pid();
                let dl = crate::timer::get_jiffies().saturating_add(1);
                let id = crate::timer::add_timer_wakeup(dl, pid);
                if id != 0 {
                    // R54: schedule() now restores the caller's SIE state;
                    // wait-path callers re-arm explicitly (semaphore.rs
                    // discipline) so ticks/IPIs reach this CPU across the
                    // wait loop.
                    crate::arch::cpu::restore_irq(true);
                    crate::sched::schedule();
                    crate::timer::del_timer(id);
                } else {
                    // Timer table STILL exhausted: never schedule() without
                    // a wake source — that is exactly the silent forever-
                    // sleep the deadline timer exists to prevent. Spin one
                    // bounded interval with interrupts enabled (so the
                    // completion walker can run) and re-check.
                    self.wait_queue.finish_wait(current);
                    crate::arch::cpu::restore_irq(true);
                    for _ in 0..100_000 {
                        core::hint::spin_loop();
                    }
                    continue;
                }
            } else {
                // Sleep-path recover wake + waiter-side rescue (the
                // VW-EXT4LOCK wedge lesson; mirrors the sync path's
                // SLEEP_RECOVER_MS discipline in virtio/queue.rs): with
                // ONLY the wait queue as a wake source, a lost interrupt
                // engine meant schedule() never returned until the 10 s
                // deadline — every async batch then cost 10 s while its
                // completions sat harvested-by-nobody in the used ring.
                // Arm a short one-shot wakeup so the rescue drain below
                // runs every 250 ms even with no interrupt at all; the
                // timer is deleted on wake (a healthy completion in
                // µs/ms never observes it). Timer-table exhaustion
                // degrades to the old wake-dependent behavior.
                const ASYNC_RECOVER_MS: u64 = 250;
                let rid = {
                    let pid = crate::sched::get_current_pid();
                    let at = crate::timer::get_jiffies()
                        .saturating_add(msecs_to_jiffies(ASYNC_RECOVER_MS));
                    crate::timer::add_timer_wakeup(at, pid)
                };
                // R54: schedule() now restores the caller's SIE state;
                // wait-path callers re-arm explicitly (semaphore.rs
                // discipline) so ticks/IPIs reach this CPU across the wait
                // loop.
                crate::arch::cpu::restore_irq(true);
                crate::sched::schedule();
                if rid != 0 {
                    crate::timer::del_timer(rid);
                }
            }

            self.wait_queue.finish_wait(current);

            // Waiter-side rescue (VW-EXT4LOCK wedge lesson, the sync
            // path's ftest01 fix applied to async): a wake whose data is
            // still pending can mean the used ring is ahead of the
            // completion walker AND no interrupt is coming (device idle,
            // softirq bits clear). Drain the lag ourselves before
            // re-sleeping — cheap when caught up, and it converts any
            // lost-IRQ engine into at most one extra 250 ms poll round
            // instead of a 10 s deadline batch stall.
            crate::drivers::virtio::pci_rescue_all_lagged();
        }
        if deadline_armed && deadline_timer != 0 {
            crate::timer::del_timer(deadline_timer);
        }
        // Frame-safety handshake on EVERY return path: a walker may be
        // between complete() and end_delivery() right now — it still owns
        // a reference to `self`, which usually lives on THIS stack frame.
        // Drain before the frame dies (see `delivering`).
        if !self.wait_deliveries() {
            crate::pr_err!("io_completion: delivery handoff overran spin budget");
        }
        result
    }

    /// Non-blocking check: returns Some(status) if done, None otherwise.
    pub fn try_wait(&self) -> Option<i32> {
        if self.done.load(Ordering::Acquire) {
            Some(self.status.load(Ordering::Acquire))
        } else {
            None
        }
    }

    /// Check if completion is done without returning status.
    pub fn is_done(&self) -> bool {
        self.done.load(Ordering::Acquire)
    }

    /// Reset to initial (not-done) state for reuse.
    pub fn reset(&self) {
        self.done.store(false, Ordering::Release);
        self.status.store(0, Ordering::Release);
        self.token.store(0, Ordering::Release);
    }
}

/// Wait for all completions in a slice. Returns 0 if all succeeded,
/// or the first error encountered.
pub fn wait_for_all(completions: &[&IoCompletion]) -> i32 {
    let mut first_error = 0;
    for comp in completions {
        let status = comp.wait();
        if status < 0 && first_error == 0 {
            first_error = status;
        }
    }
    first_error
}


// ════════════════ locks ═══════════════════════════════
// (was locks.rs)
// File locks: BSD flock(2) + POSIX fcntl(2) record locks
// (P0-5 — sqlite / package-manager data safety).
//
// ## The fs-rest split: THIS file is the framework half
//
// The flock/POSIX/lease LOGIC and its tables live in the fs crate
// (`kernel/fs/src/locks.rs`, under crate-level forbid); THIS
// module keeps everything the kernel's open/close/exec paths touch
// directly, so the hot legs pay zero indirection (crate-plan §3a
// rule 2 — no fn-pointer rows on data paths):
//
// - the live-entry count mirrors (`FLOCK_COUNT` / `RECORD_LOCK_COUNT`
//   / `LEASE_COUNT`), read by the per-open/per-close fast-path gates;
//   the crate's table critical sections STORE them (they are `pub`
//   for exactly that);
// - the open/close bookkeeping: `inode_open_register` (per-open inode
//   atomics), `inode_open_unregister` / `flock_release_file` /
//   `ofd_release_file` / `posix_release_for_file` (the close-path
//   legs: fast gate here, table work through a COLD row that only
//   fires when locks/leases are actually held);
// - `break_lease`'s no-lease fast gate (every write-mode open);
// - the exec text-hold family (`TEXT_HOLDS` + acquire/release/count —
//   mm_struct and the exec path call these directly);
// - the shared owner/type vocabulary (`LockOwner`, `LockConflict`,
//   `F_*_KIND`) the VFS fcntl arms construct and the crate consumes.
//
// The cold rows live in `lock_hooks::LocksHooks` (the registration
// slot model this file's seam predicted at rung 3); the crate
// registers them at boot alongside the other tables.
//
// ## Ownership model (mirrors Linux)
//
// **flock(2)** locks are owned by the OPEN FILE DESCRIPTION
// (`File::file_id`, the R36-B1 never-repeating generation) and keyed by
// the file's `(fs_id, ino)` identity:
// - two separate open()s of the same path hold SEPARATE locks that
//   conflict with each other (flock is not per-process);
// - dup'd fds (and fork's fd-table copies) share the description and
//   therefore the lock;
// - the lock is released when the description dies — hooked from
//   `File::drop`, which covers close(2), dup2(2) displacement and
//   process exit in one place;
// - a re-lock through the same description CONVERTS the lock (SH<->EX),
//   possibly blocking/EWOULDBLOCKing against the other holders.
//
// **POSIX record locks** (F_SETLK/F_SETLKW/F_GETLK) are owned by the
// PROCESS (tgid) and keyed by `(fs_id, ino)`:
// - locks of one process never conflict with each other; a set request
//   REPLACES the owner's overlapping locks (split/merge per POSIX);
// - read locks are shared, write locks exclusive, across processes;
// - closing ANY fd referring to the file releases ALL of the closing
//   process's record locks on that file — the classic POSIX semantic —
//   hooked from `FdTable::close_fd`/`dup2_fd`/`Drop`;
// - as belt-and-braces against a missed hook, a conflicting lock whose
//   owner process no longer exists is treated as stale and reaped
//   (no permanent EAGAIN / F_SETLKW hang from dead owners).
//
// Both halves' tables are global `Spinlock<Vec<..>>`s (crate side):
// lock counts are small (sqlite uses a handful per database), O(n)
// scans are fine, and a global wait queue per lock class keeps the
// wake-all-and-recheck discipline simple (thundering herd at worst).

// (INV-LOCKS-KEY-1: the file-lock family — lock keys and the open/
// lease registries live in locked maps; the raw file/inode words in
// the release/lease rows are identity keys into those maps (never
// dereferenced), read under INV-FILE-CELL-1's cell discipline.)

impl LockOwner {
    /// PID reported by F_GETLK for a conflicting lock: the process for
    /// Pid-owned locks; 0 for OFD locks (they have no process owner —
    /// POSIX/linux behavior, LTP fcntl34/36 expect 0).
    pub fn report_pid(&self) -> u32 {
        match *self {
            LockOwner::Pid(p) => p,
            LockOwner::Ofd(_) => 0,
        }
    }
}

/// Lock type for requests: 0 = unlock, 1 = read (shared), 2 = write (exclusive).
pub const F_UNLCK_KIND: u8 = 0;
pub const F_RDLCK_KIND: u8 = 1;
pub const F_WRLCK_KIND: u8 = 2;

// ============================================================================
// The live-entry count mirrors (framework-side: the open/close fast-path
// gates read them; the crate's critical sections store them)
// ============================================================================

/// Live-entry mirror of the flock table, stored inside every critical
/// section that mutates it (the crate side does the storing). File::drop's
/// release path reads this first and skips the slow row + table scan when
/// it is 0 — no process holds flocks on a default boot, so every close
/// saves one row dispatch + irqsave lock pair + O(table) scan. Soundness
/// of the 0-read against a racing FIRST-ever insert: an insert runs inside
/// flock_lock(&File) which holds a File reference; File::drop (the gate
/// reader) only runs after the LAST reference died, and the Arc refcount's
/// Release/Acquire chain orders the dropping CPU's Acquire load of this
/// counter after the inserter's Release store of the new length.
pub static FLOCK_COUNT: AtomicUsize = AtomicUsize::new(0);

/// Live-entry mirror of the POSIX record-lock table (same protocol as
/// FLOCK_COUNT). The two per-CLOSE release paths (posix_release_for_file
/// via fdreap::retire_complete, ofd_release_file via File::drop) read
/// this first and skip the slow row when it is 0 — the overwhelmingly
/// common case (no process on the box holds record locks), and one row
/// dispatch + irqsave lock pair + O(table) scan off every close (the
/// close side of lat_syscall,open; perf-path lane measured the whole
/// close at 300-400 ns). Exactness: 0 proves the table was empty at the
/// storing critical section; a concurrent FIRST-ever insert racing the
/// read can leave one lock unreleased by that close — a window that
/// needs a task inserting the box's first record lock in the exact
/// interval another thread of the same process closes a same-inode
/// file; the stale entry is still reaped by reap_stale_locked
/// (belt-and-braces, crate side) and by that owner's next release path.
pub static RECORD_LOCK_COUNT: AtomicUsize = AtomicUsize::new(0);

/// Live-entry mirror of the lease table (same protocol). Every
/// regular-file open runs break_lease's conflict probe and every close
/// runs the unregister lease leg; with no leases on the box (the
/// default) both collapse to one Acquire load. Soundness against a
/// racing FIRST-ever set_lease: the setter runs inside fcntl on a held
/// File reference; File::drop only runs after the last reference died,
/// and the Arc refcount Release/Acquire chain orders the dropping CPU's
/// Acquire read after the setter's Release length store.
pub static LEASE_COUNT: AtomicUsize = AtomicUsize::new(0);

/// Lock identity key of an Inode (shared by both halves).
pub fn inode_lock_key(inode: &Inode) -> (u64, u64) {
    (inode.fs_id, inode.ino)
}

// ============================================================================
// Open/close bookkeeping (the hot legs — direct calls; the table work
// rides COLD rows that only fire when the count mirrors are non-zero)
// ============================================================================

/// Register a new open file description on `inode` (File::set_inode).
/// `write_access` is the description's access mode.
pub fn inode_open_register(inode: &Inode, write_access: bool) {
    inode
        .open_total
        .fetch_add(1, Ordering::AcqRel);
    if write_access {
        inode
            .open_write
            .fetch_add(1, Ordering::AcqRel);
    }
}

/// Unregister a dying open file description (File::drop) and release its
/// lease (if any), waking blocked lease breakers.
pub fn inode_open_unregister(file: &File) {
    // SAFETY: inode is written once at open time; read-only access.
    let inode_opt = crate::fs::r#unsafe::file_inode_arc(file);
    let inode = match inode_opt.as_ref() {
        Some(inode) => inode,
        None => return,
    };
    // O_ACCMODE = 3; O_WRONLY(1) and O_RDWR(2) count as write access.
    let write_open = file.flags().bits() & 0o3 != 0;
    inode
        .open_total
        .fetch_sub(1, Ordering::AcqRel);
    if write_open {
        inode
            .open_write
            .fetch_sub(1, Ordering::AcqRel);
    }
    // Release the dying description's lease and wake lease breakers.
    // closegap: empty-table fast path — see LEASE_COUNT. The table work
    // rides the COLD row: a box with zero leases (the default boot)
    // never crosses the crate boundary here.
    if LEASE_COUNT.load(Ordering::Acquire) == 0 {
        return;
    }
    (self::lock_rows().lease_release_slow)(file.file_id);
}

/// Release every flock held by a dying open file description. Called from
/// `File::drop` — the exact moment the last fd (possibly across fork
/// copies and in-flight syscall clones) goes away.
pub fn flock_release_file(file_id: u64) {
    // closegap: empty-table fast path — see FLOCK_COUNT. One Acquire
    // load replaces the row dispatch + lock pair + retain scan on every
    // File::drop.
    if FLOCK_COUNT.load(Ordering::Acquire) == 0 {
        return;
    }
    (self::lock_rows().flock_release_slow)(file_id);
}

/// Release every OFD record lock held by a dying open file description
/// (F_OFD_SETLK locks live and die with the description, like flock).
/// Called from `File::drop`.
pub fn ofd_release_file(file_id: u64) {
    // closegap: empty-table fast path — see RECORD_LOCK_COUNT.
    if RECORD_LOCK_COUNT.load(Ordering::Acquire) == 0 {
        return;
    }
    (self::lock_rows().ofd_release_slow)(file_id);
}

/// FdTable close-hook wrapper: releases the closing task's record locks
/// on the inode behind `file` (no-op for inode-less files such as pipes).
pub fn posix_release_for_file(file: &File) {
    // closegap: empty-table fast path — see RECORD_LOCK_COUNT. The gate
    // runs before the inode fetch (the old body paid the cell read
    // first; with no record locks on the box — the default — close(2)
    // now skips it).
    if RECORD_LOCK_COUNT.load(Ordering::Acquire) == 0 {
        return;
    }
    // SAFETY: inode is written once at open time and never mutated;
    // read-only access.
    let inode_opt = crate::fs::r#unsafe::file_inode_arc(file);
    if let Some(inode) = inode_opt.as_ref() {
        (self::lock_rows().posix_release_slow)(inode_lock_key(inode));
    }
}

// ============================================================================
// File leases (fcntl F_SETLEASE / F_GETLEASE — Linux file leases)
// ============================================================================
//
// The lease TABLE, the grant checks and the break machinery live
// crate-side; this side keeps the per-write-open fast gate. The model
// (documented divergence): a lease is remembered per open file
// description and keyed by the inode; F_SETLEASE grant checks mirror
// Linux's (fcntl_setlease → generic_add_lease):
//   - read lease (F_RDLCK): refused with EAGAIN if ANY open description
//     of the inode (including the caller's own) has write access —
//     Linux's i_writecount test (LTP fcntl27);
//   - write lease (F_WRLCK): refused with EAGAIN if ANY OTHER open
//     description of the inode exists, whatever its mode (LTP fcntl32),
//     or another description already holds a lease;
//   - two read leases from different descriptions coexist (readers do
//     not conflict with each other).
// Lease BREAK: a conflicting open/truncate blocks on the crate-side
// LEASE_WAIT, the holder is signalled (SIGIO), and after
// fs.lease-break-time seconds the kernel force-breaks the lease and
// lets the opener through — Linux's break_lease discipline in miniature
// (LTP fcntl33).

/// Break leases on `inode` conflicting with the pending operation
/// (`writer` = write-mode open / truncate). Framework half: the
/// no-lease fast gate every write-mode open pays (one Acquire load —
/// the old lease_conflicts probe collapsed to exactly this when the
/// table was empty); the signal/wait machinery rides the COLD row.
pub fn break_lease(inode: &Inode, writer: bool) -> Result<(), crate::errno::Errno> {
    if LEASE_COUNT.load(Ordering::Acquire) == 0 {
        return Ok(());
    }
    (self::lock_rows().break_lease_slow)(inode, writer)
}

/// Number of open file descriptions holding `inode` for write access
/// (the i_writecount analogue). execve's ETXTBSY gate reads this
/// (Linux deny_write_access in do_open_execat; LTP execve04): executing
/// a file some open description still writes would alias the text
/// against a concurrent writer's bytes.
pub fn inode_write_open_count(inode: &Inode) -> u32 {
    inode.open_write.load(Ordering::Acquire)
}

// ============================================================================
// Exec text holds (the ETXTBSY negative i_writecount — mm_struct and
// the exec path call these directly; never crosses the crate boundary)
// ============================================================================

/// Live exec text holds per inode key — the NEGATIVE half of the
/// reference i_writecount. deny_write_access() at exec commit takes one
/// hold for the image; allow_write_access() drops it when the last mm of
/// that exec lineage dies (our MmStruct::drop stand-in for the
/// mm->exe_file fput). While any hold is live, a write-mode (or
/// O_TRUNC) open of the file fails ETXTBSY (reference may_open ->
/// get_write_access; LTP creat07).
static TEXT_HOLDS: Spinlock<BTreeMap<(u64, u64), u32>> =
    Spinlock::new(BTreeMap::new());

/// Text-hold key of `inode` (same identity as the lease/open tables).
pub fn inode_text_hold_key(inode: &Inode) -> (u64, u64) {
    inode_lock_key(inode)
}

/// Take one text hold on `key` (exec commit / fork's exe_file dup).
pub fn inode_text_hold_acquire_key(key: (u64, u64)) {
    let mut m = TEXT_HOLDS.lock();
    let c = m.entry(key).or_insert(0);
    *c = c.saturating_add(1);
}

/// Drop one text hold on `key` (last-mm death).
pub fn inode_text_hold_release(key: (u64, u64)) {
    let mut m = TEXT_HOLDS.lock();
    if let Some(c) = m.get_mut(&key) {
        *c = c.saturating_sub(1);
        if *c == 0 {
            m.remove(&key);
        }
    }
}

/// Number of live exec text holds on `inode`. may_open's write leg
/// reads this and fails ETXTBSY while any process still executes the
/// file.
pub fn inode_text_hold_count(inode: &Inode) -> u32 {
    let key = inode_lock_key(inode);
    TEXT_HOLDS.lock().get(&key).copied().unwrap_or(0)
}


// ════════════════ vt ══════════════════════════════════
// (was vt.rs)
// VT (virtual terminal) layer — /dev/tty0 master + /dev/tty1..ttyN
// console devices, Linux `include/uapi/linux/vt.h` / `kd.h` ABI.
//
// The gdm chain's display-switch protocol runs entirely over these:
// - gdm-session-worker `set_up_for_new_vt()`: open("/dev/tty1") (the
//   "open console of initial fd" step — ENOENT killed every greeter
//   session at SESSION_OPENED until these nodes existed), VT_OPENQRY
//   on it, then open("/dev/ttyN") for the returned VT.
// - `jump_to_vt()`: open("/dev/tty0"), VT_GETSTATE, VT_ACTIVATE,
//   VT_WAITACTIVE; `fix_terminal_vt_mode()`: VT_SETMODE/VT_GETMODE
//   (VT_PROCESS + relsig/acqsig).
// - Xorg on the session VT: VT_ACTIVATE/VT_WAITACTIVE, VT_SETMODE,
//   KDSETMODE(KD_GRAPHICS), KDGKBTYPE/KDGKBMODE/KDSKBMODE.
// - logind TakeControl: same ioctls on /dev/tty0.
//
// Rux has one display (virtio-gpu fb + UART text console), so the VT
// layer is a single active-VT register with in-use refcounts per VT:
// VT_ACTIVATE moves the active VT and wakes VT_WAITACTIVE sleepers;
// the switch never blocks on a VT_PROCESS handshake (a release/acquire
// signal round-trip) because there is no competing console owner. The
// read/write/poll semantics delegate to the shared console TtyDevice
// (same sink as /dev/console).
//
// dev_t layout (Linux): tty0..ttyN are (4, 0..N); /dev/tty is (5, 0)
// and /dev/console is (5, 1) (TTYAUX_MAJOR). ttyS0 remains (4, 64).

// (INV-VT-PRIV-1: the VT device fd family — private_data holds the
// Box<DevNo> leaked by devfs_open; close is the single reclaim; the
// ioctl rows read the cell under INV-FS-FILEPRIV-1's write-once
// discipline.)

/// Highest VT number this kernel provides (/dev/tty1..=tty7).
pub const NR_VT: u32 = 7;

/// vt ioctl commands (include/uapi/linux/vt.h).
const VT_OPENQRY: u32 = 0x5600;
const VT_GETMODE: u32 = 0x5601;
const VT_SETMODE: u32 = 0x5602;
const VT_GETSTATE: u32 = 0x5603;
const VT_SENDSIG: u32 = 0x5604;
const VT_RELDISP: u32 = 0x5605;
const VT_ACTIVATE: u32 = 0x5606;
const VT_WAITACTIVE: u32 = 0x5607;
const VT_DISALLOCATE: u32 = 0x5608;
const VT_RESIZE: u32 = 0x5609;
const VT_RESIZEX: u32 = 0x560A;
const VT_LOCKSWITCH: u32 = 0x560B;
const VT_UNLOCKSWITCH: u32 = 0x560C;

/// kd ioctl commands (include/uapi/linux/kd.h) — the subset gdm, Xorg
/// and logind issue on VT fds.
const KIOCSOUND: u32 = 0x4B2F;
const KDGETLED: u32 = 0x4B31;
const KDSETLED: u32 = 0x4B32;
const KDGKBTYPE: u32 = 0x4B33;
const KDSETMODE: u32 = 0x4B3A;
const KDGETMODE: u32 = 0x4B3B;
const KDGKBMODE: u32 = 0x4B44;
const KDSKBMODE: u32 = 0x4B45;

pub(crate) const VT_AUTO: u8 = 0x00;
pub(crate) const VT_PROCESS: u8 = 0x01;

const KD_TEXT: u32 = 0x00;
const KD_GRAPHICS: u32 = 0x01;

/// Keyboard type answer for KDGKBTYPE: 101-key PC (Xorg's probe).
const KB_101: u8 = 0x02;


// ============================================================================
// Global VT state
// ============================================================================

/// The active VT (starts at 1: gdm's GDM_INITIAL_VT).
static ACTIVE_VT: AtomicU32 = AtomicU32::new(1);

/// Open-fd refcount per VT number (index 0 = /dev/tty0 master view, not
/// itself allocatable by VT_OPENQRY). VT_OPENQRY skips in-use VTs so
/// two displays never share a VT.
pub(crate) static VT_REFS: [AtomicU32; (NR_VT as usize) + 1] =
    [const { AtomicU32::new(0) }; (NR_VT as usize) + 1];

/// Active-console vt_mode (single display → single mode register).
pub(crate) static VT_MODE: Spinlock<VtMode> = Spinlock::new(VtMode {
    mode: VT_AUTO,
    waitv: 0,
    relsig: 0,
    acqsig: 0,
    frsig: 0,
});

/// KD text/graphics mode of the active console.
static KD_MODE: AtomicU32 = AtomicU32::new(KD_TEXT);

/// Keyboard mode (K_XLATE=0 default; Xorg sets K_RAW=1 via KDSKBMODE).
static KB_MODE: AtomicU32 = AtomicU32::new(0);

/// VT switch lock (VT_LOCKSWITCH) — accepted, never consulted (single
/// owner protocol only).
static VT_LOCKED: AtomicBool = AtomicBool::new(false);

/// Waiters for VT_WAITACTIVE (woken on every ACTIVATE).
static SWITCH_WAITQ: WaitQueueHead = WaitQueueHead::new();

/// Is `devno` one of this layer's devices (major 4, minor 0..=NR_VT)?
pub fn is_vt_devno(devno: &super::types::DevNo) -> bool {
    devno.major == self::TTY_MAJOR && devno.minor <= NR_VT
}

/// open(): count the VT as in use (devfs_open calls this when the file's
/// device is a VT node).
pub fn vt_opened(devno: &super::types::DevNo) {
    VT_REFS[devno.minor as usize].fetch_add(1, Ordering::Relaxed);
}

/// close(): release the in-use count.
pub fn vt_closed(devno: &super::types::DevNo) {
    VT_REFS[devno.minor as usize].fetch_sub(1, Ordering::Relaxed);
}

/// The active VT number (sysfs /sys/class/tty/tty0/active content).
pub fn active_vt() -> u32 {
    ACTIVE_VT.load(Ordering::Acquire)
}

/// Wake every VT_WAITACTIVE sleeper (an ACTIVATE happened).
fn wake_switch_waiters() {
    SWITCH_WAITQ.wake_up_all();
}

/// One interruptible wait round for a VT switch. Returns Ok(()) when the
/// predicate already holds (caller re-checks), Err(EINTR) on a pending
/// signal. Same discipline as netlink_wait_round.
fn wait_switch_round() -> Result<(), i32> {
    let current = match crate::sched::current() {
        Some(t) => t,
        None => return Err(-11),
    };
    SWITCH_WAITQ.prepare_to_wait(current, false, true);
    if crate::signal::signal_pending() {
        SWITCH_WAITQ.finish_wait(current);
        crate::sched::dequeue_task(&*current);
        return Err(-4); // EINTR
    }
    crate::arch::cpu::restore_irq(true);
    crate::sched::schedule();
    SWITCH_WAITQ.finish_wait(current);
    if crate::signal::signal_pending() {
        return Err(-4);
    }
    Ok(())
}

// ============================================================================
// File operations (delegate to the shared console tty, like /dev/console)
// ============================================================================

fn vtdev_read(file: &super::types::File, buf: &mut [u8]) -> isize {
    self::devfs::condev_read(file, buf)
}

fn vtdev_write(file: &super::types::File, buf: &[u8]) -> isize {
    self::devfs::condev_write(file, buf)
}

fn vtdev_poll(file: &super::types::File, events: u16) -> u16 {
    self::devfs::condev_poll(file, events)
}

/// Last fd closed: release the VT in-use slot and free the stashed
/// DevNo (devfs_open boxed it; File::close runs exactly once per open
/// file description — the fput discipline in fs/file.rs).
// SAFETY: private_data holds a leaked Box<DevNo> installed by devfs_open.
fn vtdev_close(file: &super::types::File) -> i32 {
    // SAFETY: the Box was leaked for this File; close runs once.
    let ptr = match unsafe { *file.private_data.get() } {
        Some(p) => p,
        None => return 0,
    };
    let devno = unsafe { alloc::boxed::Box::from_raw(ptr as *mut super::types::DevNo) };
    vt_closed(&devno);
    unsafe { *file.private_data.get() = None };
    0
}

/// VT device file operations.
pub static VTDEV_OPS: super::types::FileOps = super::types::FileOps::builder()
    .read(vtdev_read)
    .write(vtdev_write)
    .poll(vtdev_poll)
    .close(vtdev_close)
    .build();

// ============================================================================
// ioctl
// ============================================================================

/// VT/KD ioctl dispatch on the File's ops identity (evdev/pty pattern).
/// Returns None for non-VT files so sys_ioctl falls through.
pub fn vt_file_ioctl(file: &super::types::File, request: u32, arg: usize) -> Option<i64> {
    if !file
        .get_ops()
        .map_or(false, |ops| core::ptr::eq(ops as *const _, &VTDEV_OPS as *const _))
    {
        return None;
    }

    // The VT number this fd was opened against (devfs_open stashed the
    // DevNo; minor 0 = the tty0 master view, which addresses the ACTIVE
    // VT — exactly Linux's semantics for /dev/tty0).
    let vt = unsafe {
        match *(file.private_data.get()) {
            Some(p) => (*(p as *const super::types::DevNo)).minor,
            None => 1,
        }
    };
    let _ = vt;

    use crate::errno::constants;
    let is_vt_cmd = matches!(request, VT_OPENQRY..=VT_UNLOCKSWITCH)
        || matches!(request, KIOCSOUND | KDGETLED | KDSETLED | KDGKBTYPE | KDSETMODE | KDGETMODE | KDGKBMODE | KDSKBMODE);
    if !is_vt_cmd {
        return None;
    }

    Some(match request {
        VT_OPENQRY => {
            // First VT with no open fd, skipping VT 1 when gdm holds it
            // (the caller opened tty1 precisely to mark it in use).
            let mut found: i32 = -1;
            for n in 1..=(NR_VT as usize) {
                if VT_REFS[n].load(Ordering::Relaxed) == 0 {
                    found = n as i32;
                    break;
                }
            }
            if found < 0 {
                return Some(-(constants::EBUSY as i64));
            }
            if arg == 0 || !crate::arch::uaccess::access_ok(arg, 4) {
                return Some(-(constants::EFAULT as i64));
            }
            // SAFETY: arg validated with access_ok(4) above.
            if !unsafe { crate::arch::uaccess::put_user(arg as *mut i32, found) } {
                return Some(-(constants::EFAULT as i64));
            }
            0
        }
        VT_GETMODE => {
            if arg == 0 || !crate::arch::uaccess::access_ok(arg, 8) {
                return Some(-(constants::EFAULT as i64));
            }
            let mut buf = [0u8; 8];
            {
                let m = VT_MODE.lock_irqsave();
                buf[0] = m.mode;
                buf[1] = m.waitv;
                buf[2..4].copy_from_slice(&m.relsig.to_le_bytes());
                buf[4..6].copy_from_slice(&m.acqsig.to_le_bytes());
                buf[6..8].copy_from_slice(&m.frsig.to_le_bytes());
            }
            // SAFETY: arg validated with access_ok(8) above.
            if unsafe { crate::arch::uaccess::copy_to_user(arg as *mut u8, buf.as_ptr(), 8) } > 0 {
                return Some(-(constants::EFAULT as i64));
            }
            0
        }
        VT_SETMODE => {
            if arg == 0 || !crate::arch::uaccess::access_ok(arg, 8) {
                return Some(-(constants::EFAULT as i64));
            }
            let mut buf = [0u8; 8];
            // SAFETY: arg validated with access_ok(8) above.
            if unsafe { crate::arch::uaccess::copy_from_user(buf.as_mut_ptr(), arg as *const u8, 8) }
                > 0
            {
                return Some(-(constants::EFAULT as i64));
            }
            let mut m = VT_MODE.lock_irqsave();
            m.mode = if buf[0] == VT_PROCESS { VT_PROCESS } else { VT_AUTO };
            m.waitv = buf[1];
            m.relsig = u16::from_le_bytes([buf[2], buf[3]]);
            m.acqsig = u16::from_le_bytes([buf[4], buf[5]]);
            m.frsig = u16::from_le_bytes([buf[6], buf[7]]);
            drop(m);
            0
        }
        VT_GETSTATE => {
            if arg == 0 || !crate::arch::uaccess::access_ok(arg, 6) {
                return Some(-(constants::EFAULT as i64));
            }
            let active = ACTIVE_VT.load(Ordering::Acquire);
            // Allocated-console bitmask: bit n-1 set for VT n (all are
            // statically allocated here).
            let mut mask: u16 = 0;
            for n in 1..=NR_VT {
                mask |= 1 << (n - 1);
            }
            // struct vt_stat fields are unsigned short (u16) — v_active
            // must be narrowed before to_le_bytes or copy_from_slice
            // panics (gdmr31: the worker's jump_to_vt VT_GETSTATE hit
            // "source slice length (4) does not match destination slice
            // length (2)" and took the box down).
            let active16 = active as u16;
            let mut buf = [0u8; 6];
            buf[0..2].copy_from_slice(&active16.to_le_bytes());
            buf[2..4].copy_from_slice(&0u16.to_le_bytes()); // v_signal
            buf[4..6].copy_from_slice(&mask.to_le_bytes());
            // SAFETY: arg validated with access_ok(6) above.
            if unsafe { crate::arch::uaccess::copy_to_user(arg as *mut u8, buf.as_ptr(), 6) } > 0 {
                return Some(-(constants::EFAULT as i64));
            }
            0
        }
        VT_SENDSIG | VT_RELDISP => {
            // No competing VT_PROCESS owner exists to handshake with;
            // acknowledge (the arg is VT_ACKACQ/1 and is ignored).
            0
        }
        VT_ACTIVATE => {
            let n = arg as u32;
            if n == 0 || n > NR_VT {
                return Some(-(constants::EINVAL as i64));
            }
            ACTIVE_VT.store(n, Ordering::Release);
            wake_switch_waiters();
            0
        }
        VT_WAITACTIVE => {
            let n = arg as u32;
            if n == 0 || n > NR_VT {
                return Some(-(constants::EINVAL as i64));
            }
            loop {
                if ACTIVE_VT.load(Ordering::Acquire) == n {
                    return Some(0);
                }
                match wait_switch_round() {
                    Ok(()) => continue,
                    Err(e) => return Some(e as i64),
                }
            }
        }
        VT_DISALLOCATE => {
            // Static VT set: nothing to free. A VT that is open stays.
            0
        }
        VT_RESIZE | VT_RESIZEX => {
            // struct winsz/conssize from user — accept the size report
            // without splitting it per-VT (single console).
            0
        }
        VT_LOCKSWITCH => {
            VT_LOCKED.store(true, Ordering::Release);
            0
        }
        VT_UNLOCKSWITCH => {
            VT_LOCKED.store(false, Ordering::Release);
            0
        }
        KIOCSOUND => 0, // no PC speaker
        KDGETLED => {
            if arg == 0 || !crate::arch::uaccess::access_ok(arg, 1) {
                return Some(-(constants::EFAULT as i64));
            }
            // SAFETY: arg validated with access_ok(1) above.
            if !unsafe { crate::arch::uaccess::put_user(arg as *mut u8, 0u8) } {
                return Some(-(constants::EFAULT as i64));
            }
            0
        }
        KDSETLED => 0,
        KDGKBTYPE => {
            if arg == 0 || !crate::arch::uaccess::access_ok(arg, 1) {
                return Some(-(constants::EFAULT as i64));
            }
            // SAFETY: arg validated with access_ok(1) above.
            if !unsafe { crate::arch::uaccess::put_user(arg as *mut u8, KB_101) } {
                return Some(-(constants::EFAULT as i64));
            }
            0
        }
        KDSETMODE => {
            if arg as u32 > KD_GRAPHICS {
                return Some(-(constants::EINVAL as i64));
            }
            KD_MODE.store(arg as u32, Ordering::Release);
            0
        }
        KDGETMODE => {
            if arg == 0 || !crate::arch::uaccess::access_ok(arg, 4) {
                return Some(-(constants::EFAULT as i64));
            }
            // SAFETY: arg validated with access_ok(4) above.
            if !unsafe { crate::arch::uaccess::put_user(arg as *mut i32, KD_MODE.load(Ordering::Acquire) as i32) } {
                return Some(-(constants::EFAULT as i64));
            }
            0
        }
        KDGKBMODE => {
            if arg == 0 || !crate::arch::uaccess::access_ok(arg, 4) {
                return Some(-(constants::EFAULT as i64));
            }
            // SAFETY: arg validated with access_ok(4) above.
            if !unsafe { crate::arch::uaccess::put_user(arg as *mut i32, KB_MODE.load(Ordering::Acquire) as i32) } {
                return Some(-(constants::EFAULT as i64));
            }
            0
        }
        KDSKBMODE => {
            // K_XLATE=0 / K_RAW=1 / K_MEDIUMRAW=2 / K_UNICODE=4 — store
            // the scancode-vs-translation choice (no keymap engine yet).
            KB_MODE.store(arg as u32, Ordering::Release);
            0
        }
        _ => return Some(-(constants::ENOTTY as i64)),
    })
}

